-- auto-apply
-- Repair article_cache.translation strings that reached the DB with a broken
-- character (U+FFFD) in 52 articles — e.g. the snake article's "... 밑에 ?주 숨어요"
-- no longer matched the article text, so tapping that sentence said "No analysis
-- for this sentence" (tester report 2026-10-30). Each broken string is restored from
-- the article body or by hand (labels / explanations / arrows). Guarded by md5 of the
-- current value, so a re-run or a later edit is never overwritten.

update public.article_cache set translation = $t${"sentences": [{"text": "최근 틱톡(TikTok)에서 '미니 킨들 팟(Mini Kindle Pods)'이라는 제품이 인기를 끌고 있어요.", "idx": 0, "translation": "Recently, a product called 'Mini Kindle Pods' has been gaining popularity on TikTok.", "vocab": [{"ko": "최근", "en": "recently", "note": ""}, {"ko": "제품", "en": "product", "note": ""}, {"ko": "인기", "en": "popularity", "note": ""}, {"ko": "끌다", "en": "to draw, pull", "note": "인기를 끌다 = to gain popularity"}], "analysis": [{"type": "grammar", "label": "~에서", "exp": "at/in (location of action) or from (source)", "example_in_sentence": "틱톡(TikTok)에서"}, {"type": "grammar", "label": "~(이)라는 (called)", "exp": "links a name to a noun: N(이)라는 + noun = \"a noun called N\". Use 이라는 after a consonant.", "example_in_sentence": "'미니 킨들 팟(Mini Kindle Pods)'이라는"}, {"type": "grammar", "label": "~이/가", "exp": "subject particle", "example_in_sentence": "제품이"}, {"type": "grammar", "label": "~을/를", "exp": "direct object particle", "example_in_sentence": "인기를"}, {"type": "grammar", "label": "~고 있다", "exp": "progressive aspect, is V-ing", "example_in_sentence": "끌고 있어요"}, {"type": "grammar", "label": "~아/어/여요", "exp": "present polite informal ending", "example_in_sentence": "있어요"}, {"type": "expression", "label": "인기를 끌다", "exp": "to gain popularity, become popular", "example_in_sentence": "인기를 끌고 있어요"}]}, {"text": "많은 사람들이 이 제품에 관심을 보이고 있습니다.", "idx": 1, "translation": "Many people are showing interest in this product.", "vocab": [{"ko": "많다", "en": "many, much", "note": ""}, {"ko": "사람", "en": "person", "note": ""}, {"ko": "관심", "en": "interest", "note": ""}, {"ko": "보이다", "en": "to show, appear", "note": ""}], "analysis": [{"type": "grammar", "label": "~ㄴ/은", "exp": "past verb OR present adjective modifying a noun", "example_in_sentence": "많은"}, {"type": "grammar", "label": "~이/가", "exp": "subject particle", "example_in_sentence": "사람들이"}, {"type": "grammar", "label": "~에", "exp": "static location/time/direction", "example_in_sentence": "제품에"}, {"type": "grammar", "label": "~을/를", "exp": "direct object particle", "example_in_sentence": "관심을"}, {"type": "grammar", "label": "~고 있다", "exp": "progressive aspect, is V-ing", "example_in_sentence": "보이고 있습니다"}, {"type": "expression", "label": "관심을 보이다", "exp": "to show interest", "example_in_sentence": "관심을 보이고 있습니다"}]}, {"text": "하지만 이 제품들은 사람들이 생각하는 것과 다른 제품이에요.", "idx": 2, "translation": "However, these products are different from what people think.", "vocab": [{"ko": "하지만", "en": "however, but", "note": ""}, {"ko": "생각하다", "en": "to think", "note": ""}, {"ko": "다르다", "en": "to be different", "note": ""}], "analysis": [{"type": "grammar", "label": "~은/는", "exp": "topic particle", "example_in_sentence": "제품들은"}, {"type": "grammar", "label": "~이/가", "exp": "subject particle", "example_in_sentence": "사람들이"}, {"type": "grammar", "label": "~는", "exp": "present verb modifier", "example_in_sentence": "생각하는"}, {"type": "grammar", "label": "~과/와", "exp": "with/and (formal)", "example_in_sentence": "것과"}, {"type": "grammar", "label": "~ㄴ/은", "exp": "past verb OR present adjective modifying a noun", "example_in_sentence": "다른"}]}, {"text": "킨들(Kindle)은 아마존에서 만든 전자책 리더기예요.", "idx": 3, "translation": "Kindle is an e-book reader made by Amazon.", "vocab": [{"ko": "전자책", "en": "e-book", "note": "electronic book"}, {"ko": "리더기", "en": "reader device", "note": ""}, {"ko": "만들다", "en": "to make", "note": ""}], "analysis": [{"type": "grammar", "label": "~에서", "exp": "at/in (location of action) or from (source)", "example_in_sentence": "아마존에서"}, {"type": "grammar", "label": "~ㄴ/은", "exp": "past verb OR present adjective modifying a noun", "example_in_sentence": "만든"}]}, {"text": "틱톡에서 판매되는 '미니 킨들 팟'은 실제 킨들 제품이 아니라고 해요.", "idx": 4, "translation": "It is said that the 'Mini Kindle Pods' sold on TikTok are not actual Kindle products.", "vocab": [{"ko": "판매되다", "en": "to be sold", "note": "passive form of 판매하다"}, {"ko": "실제", "en": "actual, real", "note": ""}], "analysis": [{"type": "grammar", "label": "~에서", "exp": "at/in (location of action) or from (source)", "example_in_sentence": "틱톡에서"}, {"type": "grammar", "label": "~는", "exp": "present verb modifier", "example_in_sentence": "판매되는"}, {"type": "grammar", "label": "~은/는", "exp": "topic particle", "example_in_sentence": "미니 킨들 팟'은"}, {"type": "grammar", "label": "~이/가", "exp": "subject particle", "example_in_sentence": "제품이"}, {"type": "grammar", "label": "~이/가 아니라고 하다 (they say it is not)", "exp": "reported speech. 아니다 → 아니라고 해요 = \"they say it is not ~\".", "example_in_sentence": "아니라고 해요"}]}, {"text": "온라인에서 물건을 살 때는 정확한 정보를 확인하는 것이 중요해요.", "idx": 5, "translation": "When buying things online, it's important to check accurate information.", "vocab": [{"ko": "온라인", "en": "online", "note": ""}, {"ko": "물건", "en": "thing, item", "note": ""}, {"ko": "정확하다", "en": "to be accurate", "note": ""}, {"ko": "확인하다", "en": "to check, confirm", "note": ""}], "analysis": [{"type": "grammar", "label": "~에서", "exp": "at/in (location of action) or from (source)", "example_in_sentence": "온라인에서"}, {"type": "grammar", "label": "~을/를", "exp": "direct object particle", "example_in_sentence": "물건을"}, {"type": "grammar", "label": "~(으)ㄹ 때 (when)", "exp": "when something happens. 사다 → 살 때 = \"when buying\".", "example_in_sentence": "살 때는"}, {"type": "grammar", "label": "~은/는", "exp": "topic particle", "example_in_sentence": "때는"}, {"type": "grammar", "label": "~ㄴ/은", "exp": "past verb OR present adjective modifying a noun", "example_in_sentence": "정확한"}, {"type": "grammar", "label": "~는 것", "exp": "nominalizing present action", "example_in_sentence": "확인하는 것이"}, {"type": "grammar", "label": "~이/가", "exp": "subject particle", "example_in_sentence": "것이"}]}, {"text": "소셜미디어(SNS)에서 인기인 제품을 살 때는 더욱 조심해야 합니다.", "idx": 6, "translation": "When buying products that are popular on social media, you need to be even more careful.", "vocab": [{"ko": "소셜미디어", "en": "social media", "note": "SNS abbreviation also used"}, {"ko": "조심하다", "en": "to be careful", "note": ""}], "analysis": [{"type": "grammar", "label": "~에서", "exp": "at/in (location of action) or from (source)", "example_in_sentence": "소셜미디어(SNS)에서"}, {"type": "grammar", "label": "~인 (that is N)", "exp": "noun-modifying form of 이다. 인기이다 → 인기인 제품 = \"a product that is popular\".", "example_in_sentence": "인기인 제품"}, {"type": "grammar", "label": "~을/를", "exp": "direct object particle", "example_in_sentence": "제품을"}, {"type": "grammar", "label": "~(으)ㄹ 때 (when)", "exp": "when something happens. 사다 → 살 때 = \"when buying\".", "example_in_sentence": "살 때는"}, {"type": "grammar", "label": "~은/는", "exp": "topic particle", "example_in_sentence": "때는"}, {"type": "grammar", "label": "~아/어야 하다", "exp": "must, have to", "example_in_sentence": "조심해야 합니다"}]}, {"text": "제품 정보를 꼼꼼히 확인하고 구매하세요.", "idx": 7, "translation": "Check the product information thoroughly and make your purchase.", "vocab": [{"ko": "정보", "en": "information", "note": ""}, {"ko": "꼼꼼히", "en": "thoroughly, carefully", "note": ""}, {"ko": "구매하다", "en": "to purchase", "note": ""}], "analysis": [{"type": "grammar", "label": "~을/를", "exp": "direct object particle", "example_in_sentence": "정보를"}, {"type": "grammar", "label": "~히", "exp": "adverb suffix (Sino-Korean)", "example_in_sentence": "꼼꼼히"}, {"type": "grammar", "label": "~고 (and then)", "exp": "links actions in order. 확인하다 → 확인하고 = \"check and (then)\".", "example_in_sentence": "확인하고"}, {"type": "grammar", "label": "~(으)세요", "exp": "polite imperative/request", "example_in_sentence": "구매하세요"}]}], "version": "s5"}$t$, qa_at = now()
 where article_id = 'mniwzglxp014' and md5(translation) = 'fe8c9738ca5eb3d89a41e5aa33b1d34c';
update public.article_cache set translation = $t${"texts": ["A special fact has been discovered in the United States. There are more households that keep pets than households with children.", "These days, American people are getting married later or having fewer children. However, they continue to keep animals like dogs and cats.", "Korea is in a similar situation. The birth rate is decreasing. Instead, the number of people who think of pets as family members is increasing.", "This change seems like it will have a big impact on society. Pet-related businesses will also grow larger."], "sentences": [{"text": "미국에서 특별한 사실이 발견되었어요.", "translation": "A special fact has been discovered in the United States.", "vocab": [{"ko": "특별하다", "en": "special; particular"}, {"ko": "사실", "en": "fact"}, {"ko": "발견되다", "en": "to be discovered"}], "analysis": [{"type": "grammar", "label": "~았/었어요 (past)", "exp": "past polite. 발견되다 → 발견되었어요 = \"was discovered\".", "example_in_sentence": "발견되었어요"}, {"type": "grammar", "label": "~이 (subject particle)", "exp": "Marks the subject of the sentence; used after noun ending in consonant.", "example_in_sentence": "사실이"}]}, {"text": "아이가 있는 가정보다 애완동물을 키우는 가정이 더 많다고 해요.", "translation": "It is said that there are more households raising pets than households with children.", "vocab": [{"ko": "아이", "en": "child"}, {"ko": "가정", "en": "household; family"}, {"ko": "애완동물", "en": "pet"}, {"ko": "키우다", "en": "to raise; to keep (an animal)"}], "analysis": [{"type": "grammar", "label": "~는 (verb modifier)", "exp": "present-tense modifier before a noun. 키우다 → 키우는 가정 = \"households that raise (pets)\".", "example_in_sentence": "키우는 가정"}, {"type": "grammar", "label": "~보다 (comparison particle)", "exp": "Marks the standard of comparison; means 'than' or 'more than'.", "example_in_sentence": "가정보다"}, {"type": "grammar", "label": "~다고 하다", "exp": "Reported speech pattern. Converts direct statement to indirect report; 많다 + 고 + 하다 = 'it is said that'.", "example_in_sentence": "많다고 해요"}]}, {"text": "요즘 미국 사람들은 결혼을 늦게 하거나 아이를 적게 낳아요.", "translation": "These days, Americans marry late or have few children.", "vocab": [{"ko": "요즘", "en": "these days; nowadays"}, {"ko": "결혼", "en": "marriage"}, {"ko": "늦다", "en": "to be late"}, {"ko": "낳다", "en": "to give birth; to have (a child)"}], "analysis": [{"type": "grammar", "label": "~거나 (alternative connective)", "exp": "Connects two alternative clauses; 하 + 거나 = 'or' (one option or another).", "example_in_sentence": "하거나"}, {"type": "grammar", "label": "~아/어요", "exp": "Present tense polite ending. 낳 + 아 + 요 = have (present habitual).", "example_in_sentence": "낳아요"}]}, {"text": "하지만 강아지나 고양이 같은 동물은 계속 키우고 있어요.", "translation": "However, they continue to raise animals like dogs and cats.", "vocab": [{"ko": "하지만", "en": "however; but"}, {"ko": "강아지", "en": "dog"}, {"ko": "고양이", "en": "cat"}, {"ko": "계속", "en": "continuously; continually"}], "analysis": [{"type": "grammar", "label": "~나 (alternative particle with nouns)", "exp": "Joins items as alternatives; 강아지 + 나 = 'dogs or/and [such things]'.", "example_in_sentence": "강아지나"}, {"type": "grammar", "label": "~같은 (similarity marker)", "exp": "Means 'like; such as'; attaches to noun to modify following noun.", "example_in_sentence": "같은 동물은"}, {"type": "grammar", "label": "~고 있다 (be V-ing)", "exp": "ongoing action. 키우다 → 키우고 있어요 = \"are raising\".", "example_in_sentence": "키우고 있어요"}]}, {"text": "한국도 비슷한 상황이에요.", "translation": "Korea is in a similar situation.", "vocab": [{"ko": "비슷하다", "en": "similar; alike"}, {"ko": "상황", "en": "situation; circumstance"}], "analysis": [{"type": "grammar", "label": "이다 (copula)", "exp": "Links subject to predicate noun. 상황 + 이 + 어요 = 'is a situation'.", "example_in_sentence": "상황이에요"}]}, {"text": "출산율이 낮아지고 있어요.", "translation": "The birth rate is decreasing.", "vocab": [{"ko": "출산율", "en": "birth rate"}, {"ko": "낮아지다", "en": "to become low; to decrease"}], "analysis": [{"type": "grammar", "label": "~아/어지다 (change of state)", "exp": "becoming. 낮다 → 낮아지다 = \"to become low\".", "example_in_sentence": "낮아지고"}, {"type": "grammar", "label": "~고 있다", "exp": "Progressive aspect showing ongoing action or state. Indicates the process is currently happening.", "example_in_sentence": "낮아지고 있어요"}]}, {"text": "대신 반려동물(pet)을 가족처럼 생각하는 사람들이 늘어나고 있어요.", "translation": "Instead, people who think of pets as family are increasing.", "vocab": [{"ko": "대신", "en": "instead; in place of"}, {"ko": "반려동물", "en": "companion animal; pet"}, {"ko": "가족", "en": "family"}, {"ko": "늘어나다", "en": "to increase; to grow"}], "analysis": [{"type": "grammar", "label": "~처럼 (similarity/manner)", "exp": "Means 'like; as if'; indicates manner or comparison. 가족 + 처럼 = 'like family'.", "example_in_sentence": "가족처럼"}, {"type": "grammar", "label": "~는 (verb modifier)", "exp": "present-tense modifier before a noun. 생각하다 → 생각하는 사람들 = \"people who think\".", "example_in_sentence": "생각하는 사람들이"}, {"type": "grammar", "label": "~고 있다 (be V-ing)", "exp": "ongoing action. 늘어나다 → 늘어나고 있어요 = \"are increasing\".", "example_in_sentence": "늘어나고 있어요"}]}, {"text": "이런 변화는 사회에 큰 영향을 줄 것 같아요.", "translation": "Changes like this seem to have a big impact on society.", "vocab": [{"ko": "변화", "en": "change"}, {"ko": "사회", "en": "society"}, {"ko": "영향", "en": "influence; impact"}], "analysis": [{"type": "expression", "label": "영향을 주다 (have an impact)", "exp": "to influence or affect something. 사회에 큰 영향을 주다 = \"to have a big impact on society\".", "example_in_sentence": "영향을 줄"}, {"type": "grammar", "label": "~(으)ㄹ 것 같다 (I think it will)", "exp": "a guess about the future. 주다 → 줄 것 같아요 = \"it seems (it) will give\".", "example_in_sentence": "줄 것 같아요"}]}, {"text": "애완동물 관련 사업도 더 커질 거예요.", "translation": "Pet-related businesses will also grow larger.", "vocab": [{"ko": "관련", "en": "relation; connection"}, {"ko": "사업", "en": "business"}, {"ko": "커지다", "en": "to grow bigger"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 거예요 (will)", "exp": "future. 커지다 (to grow bigger) → 커질 거예요 = \"will grow bigger\".", "example_in_sentence": "커질 거예요"}, {"type": "grammar", "label": "~도 (inclusive particle, 'also')", "exp": "Adds the current item to a series; 사업 + 도 = 'business also'.", "example_in_sentence": "사업도"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mofayuusefil' and md5(translation) = '023c13d692204f59ff9d7d2299dfb408';
update public.article_cache set translation = $t${"texts": ["This is a story that happened in America long ago. In 1930, 600 beavers were released in Oregon. It was to prevent soil from being washed away by water.", "One beaver cost 5 dollars. But what the beaver did was worth 300 dollars. This is because the beaver built a dam and protected the soil.", "Beavers build dams with wood. The dam blocks the water so the soil doesn't get washed away. If people do it, it costs a lot of money.", "Animals can also help us greatly. The power of nature is truly amazing."], "sentences": [{"text": "옛날 미국에서 일어난 일이에요.", "translation": "It's something that happened in the United States long ago.", "vocab": [{"ko": "옛날", "en": "long ago; the old days"}, {"ko": "일어나다", "en": "to happen; to occur"}, {"ko": "일", "en": "thing; matter; event"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (past verb modifier)", "exp": "describes a noun with a past action. 일어나다 → 일어난 일 = \"something that happened\".", "example_in_sentence": "일어난 일"}, {"type": "grammar", "label": "이에요 (copula)", "exp": "Combines 이다 (to be) + ~어요 (polite present ending). Connects subject to descriptive predicate.", "example_in_sentence": "일이에요"}]}, {"text": "1930년에 오리건 주에서 비버 600마리를 풀어놨어요.", "translation": "In 1930, they released 600 beavers in Oregon.", "vocab": [{"ko": "풀어놓다", "en": "to release; to let loose"}, {"ko": "마리", "en": "counter for animals"}], "analysis": [{"type": "grammar", "label": "~았/었어요 (past tense)", "exp": "past polite. 풀어놓다 → 풀어놓았어요, shortened to 풀어놨어요 = \"released\".", "example_in_sentence": "풀어놨어요"}, {"type": "grammar", "label": "을/를 (object particle)", "exp": "Marks 비버 600마리 as the direct object of the action 풀어놓다.", "example_in_sentence": "비버 600마리를"}]}, {"text": "흙이 물에 쓸려가는 것을 막기 위해서였어요.", "translation": "It was in order to prevent soil from being washed away by water.", "vocab": [{"ko": "흙", "en": "soil; earth"}, {"ko": "쓸려가다", "en": "to be washed away; to be swept away"}, {"ko": "막다", "en": "to prevent; to block"}], "analysis": [{"type": "grammar", "label": "~는 것 (V-ing)", "exp": "turns a verb into a noun. 쓸려가다 → 쓸려가는 것 = \"(soil) being washed away\".", "example_in_sentence": "쓸려가는 것"}, {"type": "grammar", "label": "~기 위해서 (in order to)", "exp": "purpose. 막다 → 막기 위해서 = \"in order to prevent\".", "example_in_sentence": "막기 위해서"}, {"type": "grammar", "label": "였어요 (past copula)", "exp": "이다 + 었어요 forms past tense of copula. Describes a past state or reason.", "example_in_sentence": "였어요"}]}, {"text": "비버 한 마리는 5달러였어요.", "translation": "One beaver was 5 dollars.", "vocab": [{"ko": "달러", "en": "dollar"}], "analysis": [{"type": "grammar", "label": "는 (contrastive particle)", "exp": "Marks 비버 한 마리 as the topic, suggesting contrast or focus on this specific item.", "example_in_sentence": "비버 한 마리는"}, {"type": "grammar", "label": "였어요 (past copula)", "exp": "이다 + 었어요 forms past tense of copula. Connects subject to its value/price.", "example_in_sentence": "였어요"}]}, {"text": "하지만 비버가 한 일은 300달러 값어치였어요.", "translation": "However, the work that beavers did was worth 300 dollars.", "vocab": [{"ko": "하지만", "en": "however; but"}, {"ko": "값어치", "en": "value; worth"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (past verb modifier)", "exp": "describes a noun with a past action. 하다 → 한 일 = \"the work (they) did\".", "example_in_sentence": "한 일"}, {"type": "grammar", "label": "은 (contrastive particle)", "exp": "Marks 비버가 한 일 as the topic, contrasting with the previous statement about individual beaver cost.", "example_in_sentence": "일은"}, {"type": "grammar", "label": "였어요 (past copula)", "exp": "이다 + 었어요 forms past tense of copula. Indicates the worth in a past context.", "example_in_sentence": "였어요"}]}, {"text": "비버가 댐을 만들어서 흙을 지켜줬거든요.", "translation": "Because beavers built a dam and protected the soil for us.", "vocab": [{"ko": "댐", "en": "dam"}, {"ko": "만들다", "en": "to make; to build"}, {"ko": "지키다", "en": "to protect; to keep"}], "analysis": [{"type": "grammar", "label": "~어서 (sequential connective)", "exp": "만들다 (build) + 어서 connects two actions in sequence. Shows that building the dam led to protecting soil.", "example_in_sentence": "만들어서"}, {"type": "expression", "label": "~아/어 주다 (do for someone)", "exp": "doing something that helps someone else. 지키다 → 지켜 주다 = \"to protect (for us)\".", "example_in_sentence": "지켜줬"}, {"type": "grammar", "label": "~았/었거든요 (reason/explanation in past)", "exp": "Combines past tense 았/었 + 거든요 to give a reason or explanation. Emphasizes the reason for the previous statement.", "example_in_sentence": "지켜줬거든요"}]}, {"text": "비버는 나무로 댐을 만들어요.", "translation": "Beavers make dams with wood.", "vocab": [{"ko": "나무", "en": "wood; tree"}], "analysis": [{"type": "grammar", "label": "~(으)로 (instrumental particle)", "exp": "나무 (wood) + 로 marks the material or means used to make the dam. Shows what something is made from.", "example_in_sentence": "나무로"}, {"type": "grammar", "label": "~어요 (polite present tense)", "exp": "만들다 (make) + 어요 forms polite present tense. Describes a habitual or general action.", "example_in_sentence": "만들어요"}]}, {"text": "댐이 물을 막아줘서 흙이 안 쓸려가요.", "translation": "Because the dam blocks water for us, soil doesn't get washed away.", "vocab": [{"ko": "막다", "en": "to block; to prevent"}], "analysis": [{"type": "expression", "label": "~아/어주다 (benefactive auxiliary verb)", "exp": "막다 (block) + 아/어주다 expresses doing an action as a benefit. The dam blocks water in a way that helps.", "example_in_sentence": "막아줘서"}, {"type": "grammar", "label": "~아/어서 (sequential connective)", "exp": "막아주다 + 어서 connects the blocking action as the reason for the following result.", "example_in_sentence": "막아줘서"}, {"type": "grammar", "label": "안 (negation adverb)", "exp": "안 (not) negates the following verb 쓸려가다. Indicates that soil does not get washed away.", "example_in_sentence": "안 쓸려가요"}]}, {"text": "사람이 하면 돈이 많이 들어요.", "translation": "If people do it, it costs a lot of money.", "vocab": [{"ko": "들다", "en": "to cost; to take (time/money)"}, {"ko": "많이", "en": "much; a lot"}], "analysis": [{"type": "grammar", "label": "~(으)면 (if)", "exp": "condition. 하다 → 하면 = \"if (people) do it\".", "example_in_sentence": "하면"}, {"type": "grammar", "label": "~어요 (polite present tense)", "exp": "들다 (cost) + 어요 forms polite present tense. Describes a general fact or habitual situation.", "example_in_sentence": "들어요"}]}, {"text": "동물도 우리에게 큰 도움을 줄 수 있어요.", "translation": "Animals can also give great help to us.", "vocab": [{"ko": "도움", "en": "help; assistance"}, {"ko": "주다", "en": "to give"}], "analysis": [{"type": "grammar", "label": "~도 (also particle)", "exp": "동물 (animals) + 도 means 'also' or 'too', suggesting animals in addition to other subjects can help.", "example_in_sentence": "동물도"}, {"type": "grammar", "label": "~을/를 (object particle)", "exp": "도움 (help) + 을 marks the direct object of 주다 (give). Indicates what is being given.", "example_in_sentence": "도움을"}, {"type": "grammar", "label": "~ㄹ 수 있다 (possibility/ability)", "exp": "주다 (give) + ㄹ + 수 + 있어요 expresses possibility or ability. Indicates that something can happen.", "example_in_sentence": "줄 수 있어요"}]}, {"text": "자연의 힘은 정말 대단해요.", "translation": "The power of nature is really amazing.", "vocab": [{"ko": "자연", "en": "nature"}, {"ko": "힘", "en": "power; strength"}, {"ko": "대단하다", "en": "to be amazing; to be great"}, {"ko": "정말", "en": "really; truly"}], "analysis": [{"type": "grammar", "label": "의 (possessive particle)", "exp": "자연 (nature) + 의 marks possession or attribution. Shows that 힘 (power) belongs to or comes from nature.", "example_in_sentence": "자연의"}, {"type": "grammar", "label": "~어요 (polite present tense)", "exp": "대단하다 (be amazing) + 어요 forms polite present tense. Expresses a state or quality in present time.", "example_in_sentence": "대단해요"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mofb0jl5y7ag' and md5(translation) = '2b32bcf122a3a7eb3c824de4d8fa6ad2';
update public.article_cache set translation = $t${"texts": ["A funny video has recently become a hot topic online. It contains people's reactions when a remote control falls off a sofa.", "Many people are relating to this situation. When a remote control falls under a sofa, it becomes really difficult to find. Especially if it gets stuck in a narrow gap, it's even more frustrating.", "Netizens are leaving funny comments saying 'I do the same thing.' Some people said they use a smartphone app instead of a remote control.", "This everyday experience is drawing the attention of many people. It's a small inconvenience, but it's a common experience that everyone goes through."], "sentences": [{"text": "최근 온라인에서 재미있는 영상이 화제가 되고 있어요.", "translation": "Recently, an entertaining video has become a hot topic online.", "vocab": [{"ko": "최근", "en": "recently"}, {"ko": "화제", "en": "hot topic; issue"}], "analysis": [{"type": "grammar", "label": "~고 있어요", "exp": "Progressive aspect marker indicating an ongoing action or state. Verb stem + 고 있다 conjugated to present polite form.", "example_in_sentence": "화제가 되고 있어요"}]}, {"text": "소파에서 리모컨이 떨어졌을 때 사람들의 반응을 담은 내용입니다.", "translation": "It is content that captures people's reactions when a remote control falls from a sofa.", "vocab": [{"ko": "리모컨", "en": "remote control"}, {"ko": "떨어지다", "en": "to fall; to drop"}, {"ko": "반응", "en": "reaction; response"}, {"ko": "담다", "en": "to contain; to capture"}], "analysis": [{"type": "grammar", "label": "~았/었을 때 (when ~ happened)", "exp": "when, for a completed event. 떨어지다 → 떨어졌을 때 = \"when (it) fell\".", "example_in_sentence": "떨어졌을 때"}]}, {"text": "많은 사람들이 이 상황에 공감하고 있어요.", "translation": "Many people are empathizing with this situation.", "vocab": [{"ko": "공감하다", "en": "to relate to; to sympathize"}], "analysis": [{"type": "grammar", "label": "~고 있어요", "exp": "Progressive aspect marking an ongoing action. Verb stem + 고 있다 in present polite form.", "example_in_sentence": "공감하고 있어요"}]}, {"text": "리모컨이 소파 아래로 떨어지면 찾기가 정말 어려워져요.", "translation": "When a remote control falls under a sofa, finding it becomes really difficult.", "vocab": [{"ko": "아래", "en": "under; below"}, {"ko": "어렵다", "en": "to be difficult"}], "analysis": [{"type": "grammar", "label": "~(으)면 (if/when)", "exp": "condition. 떨어지다 → 떨어지면 = \"if/when (it) falls\".", "example_in_sentence": "떨어지면"}, {"type": "expression", "label": "~ 아래로 (down under)", "exp": "아래 (below) + 로 (direction). 소파 → 소파 아래로 = \"(down) under the sofa\".", "example_in_sentence": "소파 아래로"}, {"type": "grammar", "label": "~아/어지다 (become)", "exp": "change of state. 어렵다 → 어려워지다 (ㅂ-irregular) → 어려워져요 = \"becomes difficult\".", "example_in_sentence": "어려워져요"}]}, {"text": "특히 좁은 틈 사이에 끼면 더욱 답답합니다.", "translation": "It is especially frustrating when it gets stuck in a narrow gap.", "vocab": [{"ko": "특히", "en": "especially; particularly"}, {"ko": "틈", "en": "gap; crack; crevice"}, {"ko": "끼다", "en": "to be stuck; to wedge"}, {"ko": "답답하다", "en": "to be frustrating; to be stuffy"}], "analysis": [{"type": "expression", "label": "~ 사이에", "exp": "Locational expression marking space between two things. 사이 (between) + 에 (locative particle).", "example_in_sentence": "틈 사이에"}, {"type": "grammar", "label": "~(으)면 (if/when)", "exp": "condition. 끼다 → 끼면 = \"if/when (it) gets stuck\".", "example_in_sentence": "끼면"}]}, {"text": "네티즌들은 \"나도 똑같다\"며 재미있는 댓글을 남기고 있어요.", "translation": "Netizens are leaving funny comments, saying \"Same here.\"", "vocab": [{"ko": "네티즌", "en": "netizen; internet user"}, {"ko": "똑같다", "en": "to be identical; to be the same"}, {"ko": "댓글", "en": "comment"}, {"ko": "남기다", "en": "to leave; to post"}], "analysis": [{"type": "grammar", "label": "~다며 (saying that)", "exp": "quotes what people say while doing something else. 똑같다 → 똑같다며 = \"saying (it's) the same\".", "example_in_sentence": "\"나도 똑같다\"며"}, {"type": "grammar", "label": "~고 있어요", "exp": "Progressive aspect marking ongoing action. Verb stem + 고 있다 in present polite form.", "example_in_sentence": "남기고 있어요"}]}, {"text": "어떤 사람은 리모컨 대신 스마트폰 앱을 사용한다고 했습니다.", "translation": "One person said they use a smartphone app instead of a remote control.", "vocab": [{"ko": "대신", "en": "instead of; in place of"}, {"ko": "앱", "en": "app; application"}, {"ko": "사용하다", "en": "to use"}], "analysis": [{"type": "grammar", "label": "~ㄴ다고 하다", "exp": "Reported speech pattern. Verb in present declarative ~ㄴ다 + 고 하다 (say that). Reports what someone says.", "example_in_sentence": "사용한다고 했습니다"}]}, {"text": "이런 일상적인 경험이 많은 사람들의 관심을 끌고 있어요.", "translation": "Such everyday experiences are drawing the attention of many people.", "vocab": [{"ko": "일상적", "en": "everyday; ordinary"}, {"ko": "경험", "en": "experience"}, {"ko": "관심", "en": "interest; attention"}, {"ko": "끌다", "en": "to draw; to attract"}], "analysis": [{"type": "expression", "label": "관심을 끌다", "exp": "Verb+object collocation meaning 'to attract attention/interest'. 끌다 (draw) takes 관심 (interest) as its direct object.", "example_in_sentence": "관심을 끌고 있어요"}, {"type": "grammar", "label": "~고 있어요", "exp": "Progressive aspect marking an ongoing action. Verb stem + 고 있다 in present polite form.", "example_in_sentence": "끌고 있어요"}]}, {"text": "작은 불편함이지만 모든 사람이 겪는 공통된 경험이기 때문입니다.", "translation": "It's because, although it's a small inconvenience, it's a common experience that everyone goes through.", "vocab": [{"ko": "불편함", "en": "inconvenience; discomfort"}, {"ko": "겪다", "en": "to experience; to go through"}, {"ko": "공통되다", "en": "to be common; to be shared"}], "analysis": [{"type": "grammar", "label": "~지만", "exp": "Concessive conjunction connecting contrasting clauses. Stem + 지만 (but; although). Links 'small inconvenience' with 'common experience'.", "example_in_sentence": "불편함이지만"}, {"type": "grammar", "label": "~기 때문이다", "exp": "Causal expression. Nominalizer 기 + 때문 (reason/cause) + 이다. Explains the reason: 'because [everyone experiences it]'.", "example_in_sentence": "겪는 공통된 경험이기 때문입니다"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mofqpcmxshdf' and md5(translation) = '5040ed687be59288bd5b31365e0f1e5a';
update public.article_cache set translation = $t${"texts": ["In Namibia, Africa, a desert-adapted elephant was captured sliding down a sand dune. This special scene has become a big topic of discussion on the internet.", "Desert elephants in Namibia, unlike regular elephants, have adapted to dry environments. They travel long distances to find water and can move skillfully even on sand.", "The behavior of an elephant sliding down a sand dune is a very rare sight. Experts analyze that this is likely a play behavior. It's an interesting case that shows animals, like humans, engage in activities for fun.", "This scene makes us feel the mystery of nature once again. We can see that even in harsh desert environments, animals enjoy life in their own way."], "sentences": [{"text": "아프리카 나미비아에서 사막에 적응한 코끼리가 모래언덕을 미끄러져 내려가는 모습이 포착되었어요.", "translation": "In Namibia, Africa, a desert-adapted elephant was spotted sliding down a sand dune.", "vocab": [{"ko": "적응하다", "en": "adapt; adjust"}, {"ko": "모래언덕", "en": "sand dune"}, {"ko": "미끄러지다", "en": "slide; slip"}, {"ko": "포착되다", "en": "be spotted; be caught"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (past verb modifier)", "exp": "describes a noun with a past action. 적응하다 → 적응한 코끼리 = \"an elephant that has adapted\".", "example_in_sentence": "사막에 적응한 코끼리"}, {"type": "grammar", "label": "~는 (modification: present participle)", "exp": "Marks a present participle modifying a noun. '미끄러져 내려가는' = ongoing action describing the manner of the sight being captured.", "example_in_sentence": "미끄러져 내려가는 모습"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense ending with polite/casual tone. '포착되었어요' = '포착되다' + -었어요, indicating a completed action.", "example_in_sentence": "포착되었어요"}]}, {"text": "이 특별한 장면은 인터넷에서 큰 화제가 되고 있습니다.", "translation": "This remarkable scene is becoming a major topic on the internet.", "vocab": [{"ko": "특별하다", "en": "special; remarkable"}, {"ko": "화제", "en": "topic; subject"}], "analysis": [{"type": "grammar", "label": "~고 있다 (progressive aspect)", "exp": "Indicates ongoing/progressive action. '되고 있습니다' = '되다' + -고 있다, showing continuous becoming a topic.", "example_in_sentence": "화제가 되고 있습니다"}]}, {"text": "나미비아의 사막 코끼리는 일반 코끼리와 달리 건조한 환경에 적응했어요.", "translation": "Unlike ordinary elephants, Namibia's desert elephants have adapted to dry environments.", "vocab": [{"ko": "건조하다", "en": "dry; arid"}, {"ko": "적응하다", "en": "adapt; adjust"}], "analysis": [{"type": "expression", "label": "~와/과 달리 (unlike)", "exp": "shows a contrast. 일반 코끼리 → 일반 코끼리와 달리 = \"unlike ordinary elephants\".", "example_in_sentence": "일반 코끼리와 달리"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense with polite tone. '적응했어요' = '적응하다' + -았어요, indicating completed adaptation.", "example_in_sentence": "적응했어요"}]}, {"text": "이들은 물을 찾아 먼 거리를 이동하며, 모래 위에서도 능숙하게 움직일 수 있습니다.", "translation": "They move long distances searching for water, and can skillfully move on sand as well.", "vocab": [{"ko": "이동하다", "en": "move; relocate"}, {"ko": "능숙하다", "en": "skillful; adept"}], "analysis": [{"type": "grammar", "label": "~(으)며 (and, while)", "exp": "links two actions, mostly in writing. 이동하다 → 이동하며 = \"move (long distances), and\".", "example_in_sentence": "이동하며"}, {"type": "grammar", "label": "~(으)ㄹ 수 있다 (can)", "exp": "ability. 움직이다 → 움직일 수 있습니다 = \"can move\".", "example_in_sentence": "움직일 수 있습니다"}]}, {"text": "코끼리가 모래언덕을 미끄러져 내려가는 행동은 매우 드문 광경이에요.", "translation": "The behavior of an elephant sliding down a sand dune is a very rare sight.", "vocab": [{"ko": "미끄러지다", "en": "slide; slip"}, {"ko": "행동", "en": "behavior; action"}, {"ko": "드물다", "en": "rare; uncommon"}], "analysis": [{"type": "grammar", "label": "~는 (modification: present participle)", "exp": "Marks present participle modifying a noun. '미끄러져 내려가는' describes the ongoing behavior being characterized.", "example_in_sentence": "미끄러져 내려가는 행동"}]}, {"text": "전문가들은 이것이 놀이 행동일 가능성이 높다고 분석하고 있습니다.", "translation": "Experts believe this is most likely play behavior.", "vocab": [{"ko": "전문가", "en": "expert; specialist"}, {"ko": "놀이", "en": "play; game"}, {"ko": "가능성", "en": "possibility; likelihood"}, {"ko": "분석하다", "en": "analyze"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 가능성이 높다 (likely)", "exp": "probability. 놀이 행동이다 → 놀이 행동일 가능성이 높다 = \"is likely to be play behavior\".", "example_in_sentence": "놀이 행동일 가능성이 높다"}, {"type": "grammar", "label": "~고 있다 (progressive aspect)", "exp": "Ongoing action. '분석하고 있습니다' = '분석하다' + -고 있다, indicating experts are currently analyzing.", "example_in_sentence": "분석하고 있습니다"}]}, {"text": "동물들도 사람처럼 재미를 위한 활동을 한다는 것을 보여주는 흥미로운 사례예요.", "translation": "It is an interesting case showing that animals, like humans, engage in activities for fun.", "vocab": [{"ko": "재미", "en": "fun; enjoyment"}, {"ko": "활동", "en": "activity"}, {"ko": "사례", "en": "case; example"}], "analysis": [{"type": "expression", "label": "~처럼 (like; as; similar to)", "exp": "Comparison/similarity marker. '사람처럼' = comparing animals to humans.", "example_in_sentence": "사람처럼"}, {"type": "grammar", "label": "~ㄴ/는다는 것 (the fact that)", "exp": "turns a statement into a noun. 활동을 한다 → 한다는 것 = \"the fact that (they) do (activities)\".", "example_in_sentence": "한다는 것"}, {"type": "grammar", "label": "~는 (modification: present participle)", "exp": "Present participle modifying noun. '보여주는' = '보여주다' + -는, describing the case/example.", "example_in_sentence": "보여주는 흥미로운 사례"}]}, {"text": "이런 모습은 자연의 신비로움을 다시 한번 느끼게 해줘요.", "translation": "Such sights make us feel the mystery of nature once again.", "vocab": [{"ko": "신비로움", "en": "mystery; wonder"}, {"ko": "느끼다", "en": "feel; sense"}], "analysis": [{"type": "grammar", "label": "~게 하다 (causative)", "exp": "Causative auxiliary meaning 'make/let/cause.' '느끼게 해줘요' = '느끼다' + -게 하다, causing someone to feel.", "example_in_sentence": "느끼게 해줘요"}]}, {"text": "혹독한 사막 환경에서도 동물들은 자신만의 방식으로 삶을 즐기고 있다는 것을 알 수 있습니다.", "translation": "We can understand that even in harsh desert environments, animals enjoy life in their own way.", "vocab": [{"ko": "혹독하다", "en": "harsh; severe"}, {"ko": "환경", "en": "environment"}, {"ko": "방식", "en": "way; method"}, {"ko": "즐기다", "en": "enjoy"}], "analysis": [{"type": "grammar", "label": "~다는 것 (the fact that)", "exp": "turns a statement into a noun. 즐기고 있다 → 즐기고 있다는 것 = \"the fact that (they) are enjoying\".", "example_in_sentence": "즐기고 있다는 것"}, {"type": "grammar", "label": "~(으)ㄹ 수 있다 (can)", "exp": "possibility. 알다 → 알 수 있습니다 (ㄹ-stem: no extra ㄹ) = \"can see, can tell\".", "example_in_sentence": "알 수 있습니다"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mogejm0r2t3z' and md5(translation) = 'c059b429ccc7161d5f898630bdf366ad';
update public.article_cache set translation = $t${"texts": ["You shouldn't make eye contact with a gorilla. Gorillas perceive eye contact as a threat. Especially large male gorillas get even angrier. They can even attack people. At zoos, they make special glasses. When you wear these glasses, your eyes don't meet the gorilla's eyes. This way, the gorilla doesn't experience stress. Both the gorilla and people become safe.", "Korean Teacher Shortage Becomes Serious, School Classes Disrupted", "What is an \"anxiety bag\"? A Popular Trend", "The United States and China Resume Talks Over Trade Issues", "\"Talking Pig\" Becomes SNS Star", "Apple Greatly Improves iPhone Speed with New AI Chip"], "sentences": [{"text": "고릴라와 눈을 마주치면 안 돼요.", "translation": "You must not make eye contact with a gorilla.", "vocab": [{"ko": "고릴라", "en": "gorilla"}, {"ko": "눈", "en": "eye"}, {"ko": "마주치다", "en": "to meet; to make eye contact"}], "analysis": [{"type": "grammar", "label": "~(으)면 안 되다 (must not)", "exp": "prohibition. 마주치다 → 마주치면 안 돼요 = \"must not meet (its eyes)\".", "example_in_sentence": "마주치면 안 돼요"}, {"type": "grammar", "label": "~와/과 (particle)", "exp": "Particle indicating 'with' or 'and' in the sense of accompaniment/association. Attached to noun 고릴라.", "example_in_sentence": "고릴라와"}]}, {"text": "고릴라는 눈을 마주치는 것을 위협으로 느껴요.", "translation": "Gorillas perceive eye contact as a threat.", "vocab": [{"ko": "위협", "en": "threat"}, {"ko": "느끼다", "en": "to feel; to perceive"}], "analysis": [{"type": "grammar", "label": "~는 것 (V-ing)", "exp": "turns a verb into a noun. 마주치다 → 마주치는 것 = \"making (eye contact)\"; 을 marks it as the object.", "example_in_sentence": "눈을 마주치는 것을"}, {"type": "expression", "label": "~을/를 위협으로 느끼다", "exp": "Verb expression meaning 'to perceive/feel ~ as a threat.' Combines object particle 을 + 위협(threat) + 으로(as) + 느끼다(to feel).", "example_in_sentence": "눈을 마주치는 것을 위협으로 느껴요"}]}, {"text": "특히 큰 수컷 고릴라는 더 화를 내요.", "translation": "Large male gorillas in particular get angrier.", "vocab": [{"ko": "특히", "en": "especially; particularly"}, {"ko": "수컷", "en": "male"}, {"ko": "화", "en": "anger"}], "analysis": [{"type": "expression", "label": "화를 내다", "exp": "Verb expression meaning 'to get angry; to become upset.' Combines noun 화(anger) + object particle 를 + 내다(to express/show). An idiom rather than literal composition.", "example_in_sentence": "더 화를 내요"}]}, {"text": "사람을 공격할 수도 있어요.", "translation": "They may even attack people.", "vocab": [{"ko": "사람", "en": "person"}, {"ko": "공격하다", "en": "to attack"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 수도 있다 (may, might)", "exp": "possibility; 도 adds \"even\". 공격하다 → 공격할 수도 있어요 = \"may (even) attack\".", "example_in_sentence": "공격할 수도 있어요"}]}, {"text": "동물원에서는 특별한 안경을 만들어요.", "translation": "In zoos, they make special glasses.", "vocab": [{"ko": "동물원", "en": "zoo"}, {"ko": "특별하다", "en": "to be special"}, {"ko": "안경", "en": "glasses; spectacles"}, {"ko": "만들다", "en": "to make; to create"}], "analysis": [{"type": "grammar", "label": "~에서는", "exp": "Locative particle ~에서 (in/at) + topic particle ~는. Indicates location with topical emphasis. Here: 'in zoos [particularly]'.", "example_in_sentence": "동물원에서는"}]}, {"text": "이 안경을 쓰면 고릴라와 눈이 마주치지 않아요.", "translation": "If you wear these glasses, you don't make eye contact with the gorillas.", "vocab": [{"ko": "쓰다", "en": "to wear (on head)"}, {"ko": "마주치다", "en": "to meet; to make contact"}], "analysis": [{"type": "grammar", "label": "~(으)면 (if/when)", "exp": "condition. 쓰다 → 쓰면 = \"if (you) wear\".", "example_in_sentence": "쓰면"}, {"type": "grammar", "label": "~지 않다 (not)", "exp": "negation. 마주치다 → 마주치지 않아요 = \"(eyes) don't meet\".", "example_in_sentence": "마주치지 않아요"}]}, {"text": "이렇게 하면 고릴라가 스트레스를 받지 않아요.", "translation": "If you do this, the gorillas don't get stressed.", "vocab": [{"ko": "스트레스", "en": "stress"}, {"ko": "받다", "en": "to receive; to experience"}], "analysis": [{"type": "expression", "label": "스트레스를 받다", "exp": "Verb expression meaning 'to experience/receive stress.' Combines noun 스트레스 + object particle 를 + 받다(to receive).", "example_in_sentence": "스트레스를 받지 않아요"}]}, {"text": "고릴라도 사람도 안전해져요.", "translation": "Both gorillas and people become safe.", "vocab": [{"ko": "안전하다", "en": "to be safe; to be secure"}], "analysis": [{"type": "grammar", "label": "도 (particle, repeated)", "exp": "Particle meaning 'also; too' or when repeated (X도 Y도), 'both X and Y.' Here: 'both gorillas and people'.", "example_in_sentence": "고릴라도 사람도"}, {"type": "grammar", "label": "~어/아지다", "exp": "Auxiliary verb indicating state change or becoming. 안전하다 (adjective) + 어지다 → 안전해지다 → 안전해져요. Expresses transition to a state: 'become safe'.", "example_in_sentence": "안전해져요"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mogek69w51r7' and md5(translation) = 'bc7c630a5302ce62308c716975d6fa25';
update public.article_cache set translation = $t${"texts": ["In 2013, NASA in the United States launched a lunar exploration rocket. However, an unexpected event occurred when the rocket was launched.", "A small frog near the rocket launch pad was blown into the sky by the rocket's strong wind. This moment was captured directly by NASA's camera.", "The frog was floating in the air along with the rocket smoke. This photograph became a big topic of discussion on the internet.", "Experts said that the frog was likely living in a pond near the launch pad. They explained that this happened because of the strong force of the rocket launch."], "sentences": [{"text": "2013년 미국 NASA에서 달 탐사 로켓을 발사했어요.", "translation": "In 2013, NASA in the United States launched a moon exploration rocket.", "vocab": [{"ko": "달 탐사", "en": "moon exploration"}, {"ko": "로켓", "en": "rocket"}, {"ko": "발사하다", "en": "to launch"}], "analysis": [{"type": "grammar", "label": "~았/었어요", "exp": "Past tense ending for narrative. 발사(하다) + 았 → 발사했어요 marks completed action in informal polite style.", "example_in_sentence": "발사했어요"}]}, {"text": "그런데 로켓이 발사될 때 예상하지 못한 일이 일어났습니다.", "translation": "However, an unexpected event occurred when the rocket was being launched.", "vocab": [{"ko": "예상하다", "en": "to anticipate; to expect"}, {"ko": "일어나다", "en": "to happen; to occur"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 때 (when)", "exp": "when something happens. 발사되다 → 발사될 때 = \"when (the rocket) was launched\".", "example_in_sentence": "발사될 때"}, {"type": "grammar", "label": "~지 못하다 (could not)", "exp": "inability. 예상하다 → 예상하지 못한 일 = \"something (no one) could foresee\".", "example_in_sentence": "예상하지 못한"}]}, {"text": "로켓 발사대 근처에 있던 작은 개구리가 로켓의 강한 바람에 하늘로 날아갔어요.", "translation": "A small frog that was near the launch pad was blown into the sky by the rocket's strong blast.", "vocab": [{"ko": "발사대", "en": "launch pad"}, {"ko": "개구리", "en": "frog"}, {"ko": "바람", "en": "wind"}, {"ko": "날아가다", "en": "to fly away"}], "analysis": [{"type": "grammar", "label": "~던", "exp": "Past participle for incomplete/habitual state. 있다 + 던 → 있던 'that was (in the state of being)' modifies 개구리.", "example_in_sentence": "있던"}, {"type": "grammar", "label": "~에 (because of)", "exp": "cause, after a noun. 바람 → 강한 바람에 = \"because of the strong wind\".", "example_in_sentence": "바람에"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense. 날아가다 + 았 → 날아갔어요 marks completed action.", "example_in_sentence": "날아갔어요"}]}, {"text": "이 순간이 NASA의 카메라에 그대로 찍혔습니다.", "translation": "This moment was captured on NASA's camera just as it happened.", "vocab": [{"ko": "순간", "en": "moment; instant"}, {"ko": "그대로", "en": "exactly; as is"}, {"ko": "찍히다", "en": "to be captured; to be photographed"}], "analysis": [{"type": "grammar", "label": "~았/었습니다", "exp": "Past tense in formal/written style. 찍히다 + 었 → 찍혔습니다 marks completed passive action.", "example_in_sentence": "찍혔습니다"}]}, {"text": "개구리는 로켓 연기와 함께 공중에 떠 있는 모습이었어요.", "translation": "The frog could be seen floating in the air along with the rocket smoke.", "vocab": [{"ko": "연기", "en": "smoke"}, {"ko": "함께", "en": "together"}, {"ko": "공중", "en": "air; sky"}, {"ko": "뜨다", "en": "to float"}], "analysis": [{"type": "grammar", "label": "~와/과 함께", "exp": "Coordinating particle + adverbial noun = 'together with.' 연기 + 와 + 함께 marks accompaniment.", "example_in_sentence": "연기와 함께"}, {"type": "grammar", "label": "~는 모습", "exp": "Present participle + noun 'appearance/sight.' 떠 있다 + 는 → 떠 있는 모습 'the sight of floating.'", "example_in_sentence": "떠 있는 모습"}]}, {"text": "이 사진은 인터넷에서 큰 화제가 되었습니다.", "translation": "This photograph became a major topic on the internet.", "vocab": [{"ko": "사진", "en": "photograph"}, {"ko": "인터넷", "en": "internet"}, {"ko": "화제", "en": "topic; subject of discussion"}], "analysis": [{"type": "expression", "label": "~이/가 화제가 되다", "exp": "Idiomatic expression 'to become a topic/subject of discussion.' 화제 (topic) + 되다 (to become).", "example_in_sentence": "화제가 되었습니다"}]}, {"text": "전문가들은 개구리가 발사대 주변 연못에서 살고 있었을 것이라고 말했어요.", "translation": "Experts said that the frog was likely living in a pond near the launch pad.", "vocab": [{"ko": "전문가", "en": "expert"}, {"ko": "주변", "en": "vicinity; surrounding area"}, {"ko": "연못", "en": "pond"}, {"ko": "살다", "en": "to live"}], "analysis": [{"type": "grammar", "label": "~았/었을 것이다 (probably was)", "exp": "a guess about the past. 살고 있다 → 살고 있었을 것이다 = \"(it) was probably living\".", "example_in_sentence": "살고 있었을 것이라고"}, {"type": "grammar", "label": "~(이)라고 말하다 (said that)", "exp": "reported speech. 것이다 → 것이라고 말했어요 = \"said that (it) probably ~\".", "example_in_sentence": "것이라고 말했어요"}]}, {"text": "로켓 발사의 강한 힘 때문에 이런 일이 생겼다고 설명했습니다.", "translation": "They explained that this happened because of the rocket launch's strong force.", "vocab": [{"ko": "발사", "en": "launch"}, {"ko": "힘", "en": "force; power"}, {"ko": "생기다", "en": "to happen; to occur"}], "analysis": [{"type": "grammar", "label": "~ 때문에 (because of N)", "exp": "reason, after a noun. 힘 → 강한 힘 때문에 = \"because of the strong force\".", "example_in_sentence": "강한 힘 때문에"}, {"type": "grammar", "label": "~다고 설명하다 (explain that)", "exp": "reported speech. 생겼다 → 생겼다고 설명했습니다 = \"explained that (it) happened\".", "example_in_sentence": "생겼다고 설명했습니다"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mogeoe04bzt8' and md5(translation) = 'f94fab57dba0b932f6ce2e7f27dcc386';
update public.article_cache set translation = $t${"texts": ["An Iranian court sentenced 3 women to death for participating in protests in January this year. They were arrested after participating in protest activities against government policies.", "The Iranian government announced that the protest participants are 'criminals who threaten national security.' However, international human rights organizations are strongly criticizing this ruling.", "The United Nations (UN) and several countries have demanded that the Iranian government stop the execution. In particular, they emphasized that women's freedom of expression (the right to speak opinions freely) should be guaranteed.", "The Korean government also expressed its concern about the human rights situation in Iran. It is expected that the international community will continue to pressure the Iranian government."], "sentences": [{"text": "이란 법원이 올해 1월 시위에 참여한 여성 3명에게 사형을 선고했어요.", "translation": "Iran's court sentenced three women who participated in a protest in January this year to death.", "vocab": [{"ko": "법원", "en": "court"}, {"ko": "시위", "en": "protest"}, {"ko": "사형", "en": "death sentence"}, {"ko": "선고하다", "en": "to sentence"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (past noun modifier)", "exp": "Describes the noun with a completed action. 참여하다 → 참여한 여성 = women who took part.", "example_in_sentence": "시위에 참여한 여성"}]}, {"text": "이들은 정부 정책에 반대하는 시위 활동에 참여했다가 체포되었습니다.", "translation": "They participated in protest activities opposing government policies and were then arrested.", "vocab": [{"ko": "정책", "en": "policy"}, {"ko": "반대하다", "en": "to oppose"}, {"ko": "체포되다", "en": "to be arrested"}], "analysis": [{"type": "grammar", "label": "~는 (present noun modifier)", "exp": "Describes the noun with an action or ongoing fact. 반대하다 → 반대하는 시위 활동 = protest activities opposing (policies).", "example_in_sentence": "반대하는 시위 활동"}, {"type": "grammar", "label": "~았/었다가 (did ~ and then)", "exp": "Shows that one action was followed by a different, often unexpected one. 참여했다가 체포되었다 = took part and then were arrested.", "example_in_sentence": "참여했다가 체포되었습니다"}]}, {"text": "이란 정부는 시위 참여자들을 '국가 안보를 위협하는 범죄자'라고 발표했어요.", "translation": "The Iranian government announced that protest participants are 'criminals threatening national security.'", "vocab": [{"ko": "안보", "en": "security"}, {"ko": "위협하다", "en": "to threaten"}, {"ko": "범죄자", "en": "criminal"}, {"ko": "발표하다", "en": "to announce"}], "analysis": [{"type": "grammar", "label": "~는 (present relative clause modifier)", "exp": "Modifies the noun 범죄자. 위협하다 → 위협하는.", "example_in_sentence": "국가 안보를 위협하는 범죄자"}, {"type": "grammar", "label": "~(이)라고 (quoting: 'as / that')", "exp": "Quotes a description or label someone gives. 범죄자라고 발표했어요 = announced (them) as criminals.", "example_in_sentence": "'국가 안보를 위협하는 범죄자'라고 발표했어요"}]}, {"text": "하지만 국제 인권 단체들은 이번 판결을 강하게 비판하고 있습니다.", "translation": "However, international human rights organizations are strongly criticizing this verdict.", "vocab": [{"ko": "인권", "en": "human rights"}, {"ko": "단체", "en": "organization"}, {"ko": "판결", "en": "verdict / judgment"}, {"ko": "비판하다", "en": "to criticize"}], "analysis": [{"type": "grammar", "label": "~고 있다 (progressive aspect)", "exp": "Indicates an ongoing or continuous action. 비판하다 → 비판하고 있습니다.", "example_in_sentence": "비판하고 있습니다"}]}, {"text": "유엔(UN)과 여러 나라들이 이란 정부에 사형 집행을 중단하라고 요구했어요.", "translation": "The UN and several countries demanded that the Iranian government stop carrying out the executions.", "vocab": [{"ko": "유엔", "en": "UN / United Nations"}, {"ko": "여러", "en": "several / various"}, {"ko": "사형", "en": "death sentence"}, {"ko": "집행하다", "en": "to execute / to carry out"}], "analysis": [{"type": "grammar", "label": "~에 (to — with groups and institutions)", "exp": "Marks who a demand is made to. With organizations like a government, 에 is used instead of 에게. 정부에 요구하다 = to demand of the government.", "example_in_sentence": "정부에"}, {"type": "grammar", "label": "~(으)라고 (quoting a command)", "exp": "Quotes an order or demand. 중단하다 → 중단하라고 요구하다 = to demand that (they) stop.", "example_in_sentence": "중단하라고 요구했어요"}]}, {"text": "특히 여성의 표현의 자유(의견을 자유롭게 말할 권리)를 보장해야 한다고 강조했습니다.", "translation": "They especially emphasized that the freedom of expression for women (the right to speak opinions freely) must be guaranteed.", "vocab": [{"ko": "표현", "en": "expression"}, {"ko": "자유", "en": "freedom"}, {"ko": "권리", "en": "right"}, {"ko": "보장하다", "en": "to guarantee"}], "analysis": [{"type": "grammar", "label": "~아/어야 하다 (must)", "exp": "Expresses necessity or obligation. 보장하다 → 보장해야 한다 = must guarantee.", "example_in_sentence": "보장해야 한다"}, {"type": "grammar", "label": "~다고 (quotative: reported speech/content)", "exp": "Marks the content of speech or emphasis. 보장해야 한다고 강조 = emphasized that [it] must be guaranteed.", "example_in_sentence": "보장해야 한다고 강조했습니다"}]}, {"text": "한국 정부도 이란의 인권 상황을 우려한다는 입장을 밝혔어요.", "translation": "The Korean government also expressed its position of concern about Iran's human rights situation.", "vocab": [{"ko": "인권", "en": "human rights"}, {"ko": "상황", "en": "situation"}, {"ko": "우려하다", "en": "to be concerned / to worry"}, {"ko": "입장", "en": "position / stance"}], "analysis": [{"type": "grammar", "label": "~ㄴ/는다는 + noun (the ~ that ...)", "exp": "Turns a statement into a description of the noun that follows. 우려한다 → 우려한다는 입장 = a position that it is concerned.", "example_in_sentence": "우려한다는 입장"}, {"type": "expression", "label": "~에 대해 우려하다 / ~을/를 우려하다 (to express concern about ~)", "exp": "Collocational expression indicating worry or concern about a matter.", "example_in_sentence": "인권 상황을 우려한다"}]}, {"text": "국제사회가 이란 정부에 지속적으로 압력을 가할 것으로 예상됩니다.", "translation": "It is expected that the international community will continuously apply pressure to the Iranian government.", "vocab": [{"ko": "국제사회", "en": "international community"}, {"ko": "지속적", "en": "continuous / sustained"}, {"ko": "압력", "en": "pressure"}, {"ko": "예상되다", "en": "to be expected"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 것으로 예상되다 (is expected to ~)", "exp": "A formal way to state a prediction. 가하다 → 가할 것으로 예상됩니다 = (it) is expected to apply.", "example_in_sentence": "가할 것으로 예상됩니다"}, {"type": "expression", "label": "~에 압력을 가하다 (to put pressure on ~)", "exp": "Collocational expression meaning to exert pressure or influence on someone/something.", "example_in_sentence": "정부에 지속적으로 압력을 가할"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'moh0g4bsfk23' and md5(translation) = '52d46a5a6757afcdb9e243076ff0ab12';
update public.article_cache set translation = $t${"texts": ["In 1945, there was a Japanese man named Yamaguchi Tsutomu. He experienced a nuclear bomb explosion in Hiroshima. However, he survived. He took shelter in an air raid shelter (a place to escape air raids). He spent the night there. The next morning, he took a train. He was trying to get to work on time. His workplace was in Nagasaki. But a nuclear bomb also exploded in Nagasaki. Surprisingly, he survived the second nuclear bomb as well. He is a person who had a very unique experience in the world. This kind of thing is truly rare.", "Korean Teacher Shortage Becomes Serious, School Classes Disrupted", "What is an \"anxiety bag\"? A Popular Trend", "The United States and China Resume Talks Over Trade Issues", "\"Talking Pig\" Becomes SNS Star", "Apple Greatly Improves iPhone Speed with New AI Chip"], "sentences": [{"text": "1945년 야마구치 츠토무라는 일본 사람이 있었어요.", "translation": "In 1945, there was a Japanese person named Yamaguchi Tsutomu.", "vocab": [{"ko": "야마구치", "en": "Yamaguchi (surname)"}, {"ko": "일본 사람", "en": "Japanese person"}, {"ko": "있다", "en": "to exist; to be"}], "analysis": [{"type": "grammar", "label": "~(이)라는 (named ~, called ~)", "exp": "Comes after a name to describe the noun that follows. 야마구치 츠토무라는 일본 사람 = a Japanese man named Yamaguchi Tsutomu.", "example_in_sentence": "야마구치 츠토무라는 일본 사람"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense suffix. Indicates the action or state occurred in the past. 있다 → 있었어요.", "example_in_sentence": "있었어요"}]}, {"text": "그는 히로시마에서 핵폭탄(원자폭탄) 폭발을 당했어요.", "translation": "He experienced a nuclear bomb (atomic bomb) explosion in Hiroshima.", "vocab": [{"ko": "히로시마", "en": "Hiroshima"}, {"ko": "핵폭탄", "en": "nuclear bomb"}, {"ko": "폭발", "en": "explosion"}, {"ko": "당하다", "en": "to experience; to suffer; to undergo"}], "analysis": [{"type": "grammar", "label": "~에서", "exp": "Locative particle indicating the location where an action takes place.", "example_in_sentence": "히로시마에서"}, {"type": "grammar", "label": "~을/를", "exp": "Object particle marking the direct object of the verb. 폭발 is what is experienced.", "example_in_sentence": "폭발을"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense suffix. 당하다 → 당했어요.", "example_in_sentence": "당했어요"}]}, {"text": "하지만 살아남았어요.", "translation": "However, he survived.", "vocab": [{"ko": "하지만", "en": "however; but"}, {"ko": "살아남다", "en": "to survive"}], "analysis": [{"type": "grammar", "label": "~았/었어요", "exp": "Past tense suffix. 살아남다 → 살아남았어요.", "example_in_sentence": "살아남았어요"}]}, {"text": "그는 방공호(공습을 피하는 곳)로 피했어요.", "translation": "He fled to a bunker (a place to avoid air raids).", "vocab": [{"ko": "방공호", "en": "bunker; air-raid shelter"}, {"ko": "공습", "en": "air raid"}, {"ko": "피하다", "en": "to escape; to flee; to avoid"}], "analysis": [{"type": "grammar", "label": "~(으)로", "exp": "Particle indicating direction or destination of movement. Where he fled to.", "example_in_sentence": "방공호(공습을 피하는 곳)로"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense suffix. 피하다 → 피했어요.", "example_in_sentence": "피했어요"}]}, {"text": "하룻밤을 그곳에서 보냈어요.", "translation": "He spent one night there.", "vocab": [{"ko": "하룻밤", "en": "one night"}, {"ko": "보내다", "en": "to spend (time); to pass"}], "analysis": [{"type": "grammar", "label": "~을/를", "exp": "Object particle marking the direct object. 하룻밤 is the time period being spent.", "example_in_sentence": "하룻밤을"}, {"type": "grammar", "label": "~에서", "exp": "Locative particle indicating where the action takes place.", "example_in_sentence": "그곳에서"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense suffix. 보내다 → 보냈어요.", "example_in_sentence": "보냈어요"}]}, {"text": "다음 날 아침 기차를 탔어요.", "translation": "The next morning, he boarded a train.", "vocab": [{"ko": "다음", "en": "next; following"}, {"ko": "기차", "en": "train"}, {"ko": "타다", "en": "to ride; to board"}], "analysis": [{"type": "grammar", "label": "~을/를", "exp": "Object particle marking the direct object of the verb. 기차 is what is boarded.", "example_in_sentence": "기차를"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense suffix. 타다 → 탔어요.", "example_in_sentence": "탔어요"}]}, {"text": "그는 시간에 맞춰 직장에 가려고 했어요.", "translation": "He intended to go to work on time.", "vocab": [{"ko": "시간", "en": "time"}, {"ko": "맞추다", "en": "to match; to fit (a time)"}, {"ko": "직장", "en": "workplace; job"}, {"ko": "가다", "en": "to go"}], "analysis": [{"type": "grammar", "label": "~에 맞춰 (on time for, in line with)", "exp": "Means doing something so it fits a time or standard. 시간에 맞춰 = on time.", "example_in_sentence": "시간에 맞춰"}, {"type": "grammar", "label": "~(으)려고 하다", "exp": "Auxiliary construction expressing intention or plan. 가다 → 가려고 했어요 (intended to go).", "example_in_sentence": "가려고 했어요"}]}, {"text": "그의 직장은 나가사키에 있었어요.", "translation": "His workplace was in Nagasaki.", "vocab": [{"ko": "나가사키", "en": "Nagasaki"}, {"ko": "있다", "en": "to be; to exist"}], "analysis": [{"type": "grammar", "label": "~은/는", "exp": "Topic particle marking the subject of the sentence.", "example_in_sentence": "그의 직장은"}, {"type": "grammar", "label": "~에", "exp": "Locative particle indicating where something is located.", "example_in_sentence": "나가사키에"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense suffix. 있다 → 있었어요.", "example_in_sentence": "있었어요"}]}, {"text": "그런데 나가사키에서도 핵폭탄이 터졌어요.", "translation": "However, a nuclear bomb also exploded in Nagasaki.", "vocab": [{"ko": "그런데", "en": "however; but; nevertheless"}, {"ko": "터지다", "en": "to burst; to explode"}], "analysis": [{"type": "grammar", "label": "~도", "exp": "Particle meaning 'also' or 'too,' adding emphasis to the location where the action occurs.", "example_in_sentence": "나가사키에서도"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense suffix. 터지다 → 터졌어요.", "example_in_sentence": "터졌어요"}]}, {"text": "놀랍게도 그는 두 번째 핵폭탄에서도 살아남았어요.", "translation": "Surprisingly, he also survived the second nuclear bomb.", "vocab": [{"ko": "놀랍다", "en": "to be surprising; to be amazing"}, {"ko": "두 번째", "en": "second (time); second"}, {"ko": "살아남다", "en": "to survive"}], "analysis": [{"type": "grammar", "label": "~게도 (to one's ~)", "exp": "Turns a feeling word into a comment on the whole sentence. 놀랍다 → 놀랍게도 = surprisingly.", "example_in_sentence": "놀랍게도"}, {"type": "grammar", "label": "~도 (also, too)", "exp": "Adds 'also' to the word before it. 두 번째 핵폭탄에서도 = from the second nuclear bomb too.", "example_in_sentence": "두 번째 핵폭탄에서도"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense suffix. 살아남다 → 살아남았어요.", "example_in_sentence": "살아남았어요"}]}, {"text": "그는 세계에서 매우 특별한 경험을 한 사람이에요.", "translation": "He is a person who has had a very special experience in the world.", "vocab": [{"ko": "세계", "en": "world"}, {"ko": "매우", "en": "very; extremely"}, {"ko": "특별하다", "en": "special; exceptional; unique"}, {"ko": "경험", "en": "experience"}], "analysis": [{"type": "grammar", "label": "~에서", "exp": "Locative particle indicating the scope or range within which something is remarkable.", "example_in_sentence": "세계에서"}, {"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Turns a describing word into a noun modifier. 특별하다 → 특별한 경험 = a special experience.", "example_in_sentence": "특별한 경험"}, {"type": "grammar", "label": "~을/를", "exp": "Object particle marking the direct object of the verb 하다.", "example_in_sentence": "경험을"}]}, {"text": "이런 일은 정말 드문 일이에요.", "translation": "Such an occurrence is truly rare.", "vocab": [{"ko": "이런", "en": "such; like this"}, {"ko": "드물다", "en": "rare; uncommon; scarce"}], "analysis": [{"type": "grammar", "label": "~은/는", "exp": "Topic particle marking the subject of the sentence.", "example_in_sentence": "이런 일은"}, {"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Turns a describing word into a noun modifier. ㄹ drops before ㄴ: 드물다 → 드문 일 = a rare thing.", "example_in_sentence": "드문 일"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'moi5kzqf9w90' and md5(translation) = '660c27d48939e4d46301551970427b4f';
update public.article_cache set translation = $t${"texts": ["In July 1976, something special happened in Philadelphia, USA. An American Legion convention was held at the Bellevue-Stratford Hotel.", "However, people who attended the convention suddenly got pneumonia. Many people got sick with the same symptoms. Doctors worked hard to find the cause of this disease.", "Later, scientists discovered a new bacterium. People got sick because of this bacterium. So this disease came to be called 'Legionnaires' disease'.", "Legionnaires' disease still occurs occasionally today. Bacteria can grow in air conditioners or hot water facilities. That's why building management is very important."], "sentences": [{"text": "1976년 7월, 미국 필라델피아에서 특별한 일이 일어났어요.", "translation": "In July 1976, something special happened in Philadelphia, United States.", "vocab": [{"ko": "특별하다", "en": "to be special"}, {"ko": "일", "en": "event; thing"}, {"ko": "일어나다", "en": "to happen; to occur"}], "analysis": [{"type": "grammar", "label": "~았/었어요 (past tense)", "exp": "Marks a completed past action. 일어나다 → 일어났어요 = happened.", "example_in_sentence": "일어났어요"}]}, {"text": "벨뷰-스트래트포드 호텔에서 재향군인회(American Legion) 대회가 열렸어요.", "translation": "An American Legion conference was held at the Bellevue-Stratford Hotel.", "vocab": [{"ko": "호텔", "en": "hotel"}, {"ko": "대회", "en": "conference; convention"}, {"ko": "열리다", "en": "to be held; to open"}], "analysis": [{"type": "grammar", "label": "~았/었어요 (past tense)", "exp": "Marks a completed past action. 열리다 → 열렸어요 = was held.", "example_in_sentence": "열렸어요"}]}, {"text": "그런데 대회에 참석한 사람들이 갑자기 폐렴에 걸렸어요.", "translation": "However, people who attended the conference suddenly got pneumonia.", "vocab": [{"ko": "참석하다", "en": "to attend"}, {"ko": "갑자기", "en": "suddenly"}, {"ko": "폐렴", "en": "pneumonia"}, {"ko": "걸리다", "en": "to catch; to contract (a disease)"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (past noun modifier)", "exp": "Describes the noun with a past action. 참석하다 → 참석한 사람들 = people who attended.", "example_in_sentence": "참석한"}, {"type": "grammar", "label": "~았/었어요 (past tense)", "exp": "Marks a completed past action. 걸리다 → 걸렸어요 = caught (an illness).", "example_in_sentence": "걸렸어요"}]}, {"text": "많은 사람들이 같은 증상으로 아팠어요.", "translation": "Many people were sick with the same symptoms.", "vocab": [{"ko": "많다", "en": "to be many; to be a lot"}, {"ko": "같다", "en": "to be the same"}, {"ko": "증상", "en": "symptom"}, {"ko": "아프다", "en": "to be sick; to be ill"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Describing words take ~(으)ㄴ before a noun. 같다 → 같은 증상 = the same symptoms.", "example_in_sentence": "같은"}, {"type": "grammar", "label": "~(으)로 (because of, with)", "exp": "Here (으)로 marks the cause. 같은 증상으로 아팠어요 = were sick with the same symptoms.", "example_in_sentence": "증상으로"}, {"type": "grammar", "label": "~았/었어요 (past tense)", "exp": "Marks a past state. 아프다 → 아팠어요 = were sick (the 으 drops).", "example_in_sentence": "아팠어요"}]}, {"text": "의사들은 이 병의 원인을 찾기 위해 노력했어요.", "translation": "Doctors tried to find the cause of this disease.", "vocab": [{"ko": "의사", "en": "doctor"}, {"ko": "병", "en": "disease; illness"}, {"ko": "원인", "en": "cause"}, {"ko": "찾다", "en": "to find; to search"}], "analysis": [{"type": "grammar", "label": "~기 위해 (in order to)", "exp": "Shows purpose. 찾다 → 찾기 위해 = in order to find.", "example_in_sentence": "찾기 위해"}, {"type": "grammar", "label": "~았/었어요 (past tense)", "exp": "Marks a completed past action. 노력하다 → 노력했어요 = tried hard.", "example_in_sentence": "노력했어요"}]}, {"text": "나중에 과학자들이 새로운 세균을 발견했어요.", "translation": "Later, scientists discovered a new bacterium.", "vocab": [{"ko": "나중에", "en": "later"}, {"ko": "과학자", "en": "scientist"}, {"ko": "새롭다", "en": "to be new"}, {"ko": "세균", "en": "bacterium; germ"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Describing words take ~(으)ㄴ before a noun. 새롭다 (ㅂ irregular) → 새로운 세균 = a new bacterium.", "example_in_sentence": "새로운"}, {"type": "grammar", "label": "~았/었어요 (past tense)", "exp": "Marks a completed past action. 발견하다 → 발견했어요 = discovered.", "example_in_sentence": "발견했어요"}]}, {"text": "이 세균 때문에 사람들이 아팠던 거예요.", "translation": "It was because of this bacterium that people got sick.", "vocab": [{"ko": "세균", "en": "bacterium; germ"}, {"ko": "때문에", "en": "because of; due to"}, {"ko": "아프다", "en": "to be sick; to be ill"}], "analysis": [{"type": "grammar", "label": "~았/었던 거예요 (that's why ~ was)", "exp": "Explains the real reason behind a past situation. 아프다 → 아팠던 거예요 = (that's why) people were sick.", "example_in_sentence": "아팠던 거예요"}]}, {"text": "그래서 이 병을 '레지오넬라병(Legionnaires' disease)'이라고 부르게 되었어요.", "translation": "So this disease came to be called 'Legionnaires' disease.'", "vocab": [{"ko": "그래서", "en": "so; therefore"}, {"ko": "병", "en": "disease; illness"}, {"ko": "부르다", "en": "to call; to name"}], "analysis": [{"type": "grammar", "label": "~(이)라고 부르다 (to call it ~)", "exp": "Gives the name people use for something. 레지오넬라병이라고 부르다 = to call it Legionnaires' disease.", "example_in_sentence": "이라고 부르게"}, {"type": "grammar", "label": "~게 되다", "exp": "Auxiliary construction indicating 'come to; begin to'. Verb stem 부르 + ~게 되다 → 부르게 되었어요.", "example_in_sentence": "부르게 되었어요"}]}, {"text": "레지오넬라병은 지금도 가끔 발생해요.", "translation": "Legionnaires' disease still occurs occasionally even now.", "vocab": [{"ko": "지금", "en": "now"}, {"ko": "가끔", "en": "occasionally; sometimes"}, {"ko": "발생하다", "en": "to occur; to happen"}], "analysis": [{"type": "grammar", "label": "~도", "exp": "Additive particle meaning 'also; even'. Attaches to 지금.", "example_in_sentence": "지금도"}]}, {"text": "에어컨이나 온수 시설에서 세균이 자랄 수 있어요.", "translation": "Bacteria can grow in air conditioning or hot water facilities.", "vocab": [{"ko": "에어컨", "en": "air conditioner"}, {"ko": "온수", "en": "hot water"}, {"ko": "시설", "en": "facility"}, {"ko": "세균", "en": "bacterium; germ"}], "analysis": [{"type": "grammar", "label": "~이나", "exp": "Alternative particle meaning 'or; or else'. Connects 에어컨 and 온수 시설.", "example_in_sentence": "에어컨이나"}, {"type": "grammar", "label": "~(으)ㄹ 수 있다 (can)", "exp": "Expresses possibility. 자라다 → 자랄 수 있어요 = can grow.", "example_in_sentence": "자랄 수 있어요"}]}, {"text": "그래서 건물 관리가 매우 중요해요.", "translation": "Therefore, building management is very important.", "vocab": [{"ko": "그래서", "en": "so; therefore"}, {"ko": "건물", "en": "building"}, {"ko": "관리", "en": "management"}, {"ko": "매우", "en": "very; greatly"}], "analysis": []}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mok1001q8h4x' and md5(translation) = '6b48192099cba55925c9b9650c43dc43';
update public.article_cache set translation = $t${"texts": ["An Italian woman is facing opposition from her fiancé's family due to her blood type. The woman was preparing to marry a local man.", "The fiancé's family opposed the marriage, saying the woman's blood type was not good. In some cultures, people believe that blood type influences personality and destiny.", "This incident shows that even in modern society, traditional beliefs can have a significant impact on people's lives. Many people are showing critical reactions to such discrimination.", "In Korea, blood type personality theory was also popular in the past. However, recently, individual character and values are being considered more important than such beliefs."], "sentences": [{"text": "이탈리아의 한 여성이 혈액형을 이유로 약혼자 가족의 반대를 받고 있어요.", "translation": "A woman from Italy is facing opposition from her fiancé's family because of her blood type.", "vocab": [{"ko": "혈액형", "en": "blood type"}, {"ko": "약혼자", "en": "fiancé(e)"}, {"ko": "반대를 받다", "en": "to face opposition; to be opposed"}], "analysis": [{"type": "grammar", "label": "~을/를 이유로 (on the grounds of ~)", "exp": "Gives the reason for an action. 혈액형을 이유로 = because of (her) blood type.", "example_in_sentence": "혈액형을 이유로"}, {"type": "grammar", "label": "~고 있어요", "exp": "Progressive aspect indicating an ongoing action or state. Formed with ~고 있- + ~어요.", "example_in_sentence": "반대를 받고 있어요"}]}, {"text": "이 여성은 현지 남성과 결혼을 준비하고 있었습니다.", "translation": "This woman was preparing for marriage with a local man.", "vocab": [{"ko": "현지", "en": "local; native"}, {"ko": "결혼을 준비하다", "en": "to prepare for marriage"}], "analysis": [{"type": "grammar", "label": "~고 있었습니다", "exp": "Past progressive aspect. ~고 있- (ongoing action) + ~었- (past) + ~습니다 (formal past).", "example_in_sentence": "준비하고 있었습니다"}]}, {"text": "약혼자의 가족은 여성의 혈액형이 좋지 않다며 결혼을 반대했어요.", "translation": "The fiancé's family opposed the marriage, saying that the woman's blood type was not good.", "vocab": [{"ko": "반대하다", "en": "to oppose"}], "analysis": [{"type": "grammar", "label": "~다며 (saying that ~)", "exp": "Reports what someone said while doing the main action. 좋지 않다 → 좋지 않다며 반대했어요 = opposed (it), saying it was not good.", "example_in_sentence": "좋지 않다며"}]}, {"text": "일부 문화권에서는 혈액형이 성격이나 운명에 영향을 준다고 믿습니다.", "translation": "In some cultures, people believe that blood type influences personality and destiny.", "vocab": [{"ko": "일부", "en": "some; a part of"}, {"ko": "문화권", "en": "cultural sphere; culture"}, {"ko": "운명", "en": "destiny; fate"}, {"ko": "영향을 주다", "en": "to influence; to have an effect on"}], "analysis": [{"type": "expression", "label": "~에 영향을 주다", "exp": "Collocation meaning 'to have an influence/effect on'. 영향 (influence) + 을 (object particle) + 주다 (give).", "example_in_sentence": "영향을 준다"}, {"type": "grammar", "label": "~다고 믿다", "exp": "Quotative construction. ~다고 marks reported speech/belief, and 믿다 means 'to believe'. Full pattern: V + ~다고 믿다.", "example_in_sentence": "영향을 준다고 믿습니다"}]}, {"text": "이 사건은 현대 사회에서도 전통적인 믿음이 개인의 삶에 큰 영향을 미칠 수 있음을 보여줘요.", "translation": "This case shows that even in modern society, traditional beliefs can have a significant impact on individuals' lives.", "vocab": [{"ko": "사건", "en": "incident; case; event"}, {"ko": "현대", "en": "modern times; modernity"}, {"ko": "전통적", "en": "traditional"}, {"ko": "미치다", "en": "to have (an effect); to exert"}], "analysis": [{"type": "expression", "label": "~에 영향을 미치다", "exp": "Collocation meaning 'to have an influence/effect on'. Similar to 영향을 주다 but with 미치다 (reach/exert).", "example_in_sentence": "영향을 미칠"}, {"type": "grammar", "label": "~(으)ㄹ 수 있다 (can, may)", "exp": "Expresses possibility. 미치다 → 미칠 수 있다 = can have (an effect).", "example_in_sentence": "미칠 수 있음"}, {"type": "grammar", "label": "~(으)ㅁ을 보여주다 (to show that ~)", "exp": "~(으)ㅁ turns a clause into a noun, often in formal writing. 있다 → 있음을 보여줘요 = shows that (it) can ...", "example_in_sentence": "미칠 수 있음을 보여줘요"}]}, {"text": "많은 사람들이 이런 차별에 대해 비판적인 반응을 보이고 있습니다.", "translation": "Many people are showing critical reactions to such discrimination.", "vocab": [{"ko": "차별", "en": "discrimination"}, {"ko": "비판적", "en": "critical"}, {"ko": "반응", "en": "reaction; response"}], "analysis": [{"type": "grammar", "label": "~고 있습니다", "exp": "Progressive aspect in formal polite form. ~고 있- (ongoing) + ~습니다 (formal present).", "example_in_sentence": "보이고 있습니다"}]}, {"text": "한국에서도 과거 혈액형 성격론이 인기를 끌었던 적이 있어요.", "translation": "In Korea too, there was a time when blood type personality theory was popular in the past.", "vocab": [{"ko": "혈액형 성격론", "en": "blood type personality theory"}, {"ko": "인기를 끌다", "en": "to become popular; to gain popularity"}], "analysis": [{"type": "expression", "label": "인기를 끌다", "exp": "Collocation meaning 'to become/gain popularity' or 'to attract attention'. 인기 (popularity) + 를 (object) + 끌다 (draw/attract).", "example_in_sentence": "인기를 끌었던"}, {"type": "grammar", "label": "~았/었던 적이 있다 (there was a time when ~)", "exp": "Talks about a past experience or period. 끌다 → 끌었던 적이 있어요 = there was a time when (it) was popular.", "example_in_sentence": "끌었던 적이 있어요"}]}, {"text": "하지만 최근에는 이런 믿음보다 개인의 인격과 가치관이 더 중요하게 여겨지고 있습니다.", "translation": "However, recently, individual character and values are being considered more important than such beliefs.", "vocab": [{"ko": "인격", "en": "character; personality"}, {"ko": "가치관", "en": "values; value system"}, {"ko": "여겨지다", "en": "to be considered; to be regarded"}], "analysis": [{"type": "grammar", "label": "~게 여겨지다", "exp": "Passive construction with adverbial modifier. ~게 (manner adverbializer) + 여겨지다 (passive of 여기다, to regard). Shows how something is regarded.", "example_in_sentence": "중요하게 여겨지고"}, {"type": "grammar", "label": "~고 있습니다", "exp": "Progressive aspect in formal form indicating an ongoing state or trend. ~고 있- + ~습니다.", "example_in_sentence": "여겨지고 있습니다"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mok11yba0nrd' and md5(translation) = '24e1b5df931c7e98e04a3d900b4d8263';
update public.article_cache set translation = $t${"texts": ["A liger is an animal born between a male lion and a female tiger. They have special genetic characteristics.", "Ligers receive growth-promoting genes from their father, the lion. However, their mother, the tiger, does not have the growth-inhibiting gene that female lions possess.", "Because of these genetic traits, ligers continue to grow. This is called genetic gigantism. A liger's body weight can reach a maximum of 500 kilograms (approximately 1,100 pounds).", "This is a much larger size than typical lions or tigers. This is a unique phenomenon that appears when the two species are mixed."], "sentences": [{"text": "라이거(Liger)는 수사자와 암호랑이 사이에서 태어난 동물입니다.", "translation": "A liger is an animal born from a male lion and a female tiger.", "vocab": [{"ko": "수사자", "en": "male lion"}, {"ko": "암호랑이", "en": "female tiger"}, {"ko": "태어나다", "en": "to be born"}], "analysis": [{"type": "expression", "label": "~ 사이에서", "exp": "Indicates a location or context between two entities. Used with nouns to show the space/relationship in which an action occurs.", "example_in_sentence": "수사자와 암호랑이 사이에서"}, {"type": "grammar", "label": "~(으)ㄴ (past noun modifier)", "exp": "Describes the noun with a past event. 태어나다 → 태어난 동물 = an animal that was born.", "example_in_sentence": "태어난 동물"}]}, {"text": "이들은 특별한 유전적 특징을 가지고 있어요.", "translation": "They have special genetic characteristics.", "vocab": [{"ko": "특별하다", "en": "to be special"}, {"ko": "유전적", "en": "genetic"}, {"ko": "특징", "en": "characteristic"}], "analysis": [{"type": "expression", "label": "~을/를 가지고 있다", "exp": "Expresses possession or having a quality. Object particle ~을/를 marks what is possessed, and 있다 indicates the state of possession.", "example_in_sentence": "특별한 유전적 특징을 가지고 있어요"}]}, {"text": "라이거는 아버지인 사자로부터 성장을 촉진하는 유전자를 받습니다.", "translation": "Ligers receive genes that promote growth from their father, the lion.", "vocab": [{"ko": "아버지", "en": "father"}, {"ko": "성장", "en": "growth"}, {"ko": "촉진하다", "en": "to promote; to accelerate"}, {"ko": "유전자", "en": "gene"}], "analysis": [{"type": "grammar", "label": "~인 (attributive copula)", "exp": "The copula ~인 functions as an attributive marker connecting 아버지 to 사자, meaning 'father who is a lion'. Shows apposition or identification.", "example_in_sentence": "아버지인 사자"}, {"type": "grammar", "label": "~는 (present noun modifier)", "exp": "Describes what the noun does. 촉진하다 → 성장을 촉진하는 유전자 = genes that promote growth.", "example_in_sentence": "성장을 촉진하는 유전자"}, {"type": "grammar", "label": "~로부터 (source particle)", "exp": "Marks the source or origin of an action. Indicates where something comes from or originates.", "example_in_sentence": "아버지인 사자로부터"}]}, {"text": "하지만 어머니인 호랑이에게는 암사자가 가진 성장 억제 유전자가 없어요.", "translation": "However, the mother, the tiger, does not have the growth-suppressing genes that female lions have.", "vocab": [{"ko": "어머니", "en": "mother"}, {"ko": "암사자", "en": "female lion"}, {"ko": "억제", "en": "suppression; inhibition"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (noun modifier)", "exp": "Describes the noun that follows. 가지다 → 암사자가 가진 유전자 = the genes that female lions have.", "example_in_sentence": "암사자가 가진 성장 억제 유전자"}, {"type": "grammar", "label": "~에게는 (as for ~, has)", "exp": "With 있다/없다, 에게 marks who has something; 는 adds contrast. 호랑이에게는 ... 없어요 = the tiger does not have ...", "example_in_sentence": "어머니인 호랑이에게는"}]}, {"text": "이런 유전적 특성 때문에 라이거는 계속해서 자랍니다.", "translation": "Because of these genetic characteristics, ligers continue to grow.", "vocab": [{"ko": "특성", "en": "characteristic; trait"}, {"ko": "계속하다", "en": "to continue"}, {"ko": "자라다", "en": "to grow"}], "analysis": [{"type": "grammar", "label": "~때문에 (causal particle)", "exp": "Marks the reason or cause of an action. Connects cause to consequence: 'because of; due to'.", "example_in_sentence": "이런 유전적 특성 때문에"}, {"type": "expression", "label": "계속해서 (continuously)", "exp": "계속하다 → 계속해서 works like an adverb meaning 'on and on, continuously'. 계속해서 자랍니다 = keep on growing.", "example_in_sentence": "계속해서"}]}, {"text": "이를 유전적 거대증이라고 불러요.", "translation": "This is called genetic gigantism.", "vocab": [{"ko": "거대증", "en": "gigantism"}, {"ko": "부르다", "en": "to call; to name"}], "analysis": [{"type": "expression", "label": "~이라고 부르다", "exp": "Expression meaning 'to call something ~' or 'to name something ~'. The ~이라고 construction marks the label/name being applied.", "example_in_sentence": "유전적 거대증이라고 불러요"}]}, {"text": "라이거의 몸무게는 최대 500킬로그램(약 1100파운드)까지 나갈 수 있습니다.", "translation": "A liger's weight can reach up to 500 kilograms (approximately 1100 pounds).", "vocab": [{"ko": "몸무게", "en": "body weight"}, {"ko": "최대", "en": "maximum; at most"}, {"ko": "나가다", "en": "to weigh (an amount)"}], "analysis": [{"type": "grammar", "label": "~까지", "exp": "Marks the limit or extent of an action/state. 'up to; as far as; to the extent of'.", "example_in_sentence": "500킬로그램까지"}, {"type": "grammar", "label": "~ㄹ 수 있다 (possibility)", "exp": "Expresses capability or possibility. Combines the future/potential suffix ~ㄹ with the noun 수 (ability) and 있다. 나가다 → 나갈 수 있다.", "example_in_sentence": "나갈 수 있습니다"}]}, {"text": "일반적인 사자나 호랑이보다 훨씬 큰 크기예요.", "translation": "It is a size much larger than ordinary lions or tigers.", "vocab": [{"ko": "일반적", "en": "general; ordinary; typical"}, {"ko": "훨씬", "en": "much; far; significantly"}], "analysis": [{"type": "grammar", "label": "~적인 (noun modifier from ~적)", "exp": "Words ending in 적 take 인 before a noun. 일반적 → 일반적인 사자 = an ordinary lion.", "example_in_sentence": "일반적인 사자나 호랑이"}, {"type": "grammar", "label": "~보다 (comparative particle)", "exp": "Marks the standard of comparison. 'more than; compared to; -er than'.", "example_in_sentence": "사자나 호랑이보다"}]}, {"text": "이는 두 종이 섞이면서 나타나는 독특한 현상입니다.", "translation": "This is a unique phenomenon that appears when two species mix.", "vocab": [{"ko": "종", "en": "species"}, {"ko": "섞이다", "en": "to mix; to blend"}, {"ko": "나타나다", "en": "to appear; to manifest"}, {"ko": "독특하다", "en": "to be unique; to be distinctive"}], "analysis": [{"type": "grammar", "label": "~(으)면서 (as, while)", "exp": "Shows something happening as another action takes place. 섞이다 → 섞이면서 = as (the two species) mix.", "example_in_sentence": "섞이면서"}, {"type": "grammar", "label": "~는 (present noun modifier)", "exp": "Describes the noun that follows. 나타나다 → 나타나는 현상 = a phenomenon that appears.", "example_in_sentence": "나타나는 독특한 현상"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mok13bzt6170' and md5(translation) = 'cc244c32f735c3a0dc4b9d0df33874d8';
update public.article_cache set translation = $t${"texts": ["Recently, CEOs of overseas technology companies have been using robot dogs for work. These robot dogs are helping with various tasks in offices.", "Robot dogs move using artificial intelligence (AI) technology. They can walk and run like people, and they can also transport objects. Additionally, they can handle security tasks.", "Robot technology is also developing rapidly in Korea. Many companies are showing interest in business automation using robots.", "Experts predict that robots will be used in more fields in the future. However, research on how people and robots can work together is also necessary."], "sentences": [{"text": "최근 해외 기술 회사 최고경영자(CEO)들이 로봇 개를 업무에 활용하고 있어요.", "translation": "Recently, CEOs of foreign technology companies are utilizing robot dogs in their work.", "vocab": [{"ko": "최고경영자", "en": "CEO; chief executive officer"}, {"ko": "활용하다", "en": "to utilize; to make use of"}, {"ko": "업무", "en": "work; business; task"}], "analysis": [{"type": "grammar", "label": "~고 있어요", "exp": "Present continuous/progressive aspect. Indicates an ongoing action. Formed: verb stem + -고 있- + ending.", "example_in_sentence": "활용하고 있어요"}]}, {"text": "이 로봇 개들은 사무실에서 다양한 일을 도와주고 있습니다.", "translation": "These robot dogs are helping with various tasks in the office.", "vocab": [{"ko": "로봇", "en": "robot"}, {"ko": "사무실", "en": "office"}, {"ko": "다양하다", "en": "to be various; to be diverse"}], "analysis": [{"type": "grammar", "label": "~고 있습니다", "exp": "Formal present continuous. Same progressive aspect as ~고 있어요 but with formal ending -습니다.", "example_in_sentence": "도와주고 있습니다"}]}, {"text": "로봇 개는 인공지능(AI) 기술로 움직여요.", "translation": "Robot dogs move by artificial intelligence technology.", "vocab": [{"ko": "인공지능", "en": "artificial intelligence; AI"}, {"ko": "움직이다", "en": "to move; to operate"}], "analysis": [{"type": "grammar", "label": "~(으)로 (by means of)", "exp": "Marks the means used to do something. 기술로 움직여요 = moves using (AI) technology.", "example_in_sentence": "기술로 움직여요"}]}, {"text": "사람처럼 걷고 뛸 수 있고, 물건을 운반할 수도 있습니다.", "translation": "They can walk and run like humans, and can also transport objects.", "vocab": [{"ko": "걷다", "en": "to walk"}, {"ko": "뛰다", "en": "to run"}, {"ko": "운반하다", "en": "to transport; to carry"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 수 있다 (can)", "exp": "Expresses ability. 뛰다 → 뛸 수 있다 = can run.", "example_in_sentence": "걷고 뛸 수 있고"}, {"type": "grammar", "label": "~(으)ㄹ 수도 있다 (can also)", "exp": "도 adds 'also' to ~(으)ㄹ 수 있다. 운반하다 → 운반할 수도 있습니다 = can also carry.", "example_in_sentence": "운반할 수도 있습니다"}]}, {"text": "또한 보안 업무도 담당할 수 있어요.", "translation": "Also, they can handle security tasks.", "vocab": [{"ko": "보안", "en": "security"}, {"ko": "담당하다", "en": "to be in charge of; to handle"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 수 있다 (can)", "exp": "Expresses ability. 담당하다 → 담당할 수 있어요 = can handle.", "example_in_sentence": "담당할 수 있어요"}]}, {"text": "한국에서도 로봇 기술이 빠르게 발전하고 있어요.", "translation": "Robot technology is also developing rapidly in Korea.", "vocab": [{"ko": "발전하다", "en": "to develop; to advance; to progress"}, {"ko": "빠르게", "en": "rapidly; quickly"}], "analysis": [{"type": "grammar", "label": "~고 있어요", "exp": "Present continuous/progressive aspect. Formed: verb stem + -고 있- + informal ending -어요.", "example_in_sentence": "발전하고 있어요"}]}, {"text": "많은 기업들이 로봇을 활용한 업무 자동화에 관심을 보이고 있습니다.", "translation": "Many companies are showing interest in task automation using robots.", "vocab": [{"ko": "자동화", "en": "automation"}, {"ko": "관심", "en": "interest; concern"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (past noun modifier)", "exp": "Describes the noun that follows. 활용하다 → 로봇을 활용한 업무 자동화 = automation of work using robots.", "example_in_sentence": "로봇을 활용한 업무"}, {"type": "expression", "label": "관심을 보이다", "exp": "Collocation meaning 'to show interest; to display interest'. Direct object 관심 + 동사 보이다.", "example_in_sentence": "관심을 보이고 있습니다"}]}, {"text": "전문가들은 앞으로 로봇이 더 많은 분야에서 사용될 것이라고 예상해요.", "translation": "Experts anticipate that robots will be used in more fields in the future.", "vocab": [{"ko": "전문가", "en": "expert; specialist"}, {"ko": "분야", "en": "field; area; domain"}, {"ko": "예상하다", "en": "to anticipate; to expect; to forecast"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 것이다", "exp": "Future tense/supposition. Expresses what will happen or what is expected. Formed: verb stem + -(으)ㄹ 것이- + ending.", "example_in_sentence": "사용될 것이라고"}, {"type": "grammar", "label": "~(이)라고 예상하다 (to expect that ~)", "exp": "Reports what someone expects. 것이다 → 것이라고 예상해요 = expect that (it) will ...", "example_in_sentence": "것이라고 예상해요"}]}, {"text": "하지만 사람과 로봇이 함께 일하는 방법에 대한 연구도 필요합니다.", "translation": "However, research on how humans and robots work together is also necessary.", "vocab": [{"ko": "함께", "en": "together; with"}, {"ko": "방법", "en": "method; way; means"}, {"ko": "연구", "en": "research; study"}], "analysis": [{"type": "grammar", "label": "~는 (present noun modifier)", "exp": "Describes the noun that follows. 일하다 → 함께 일하는 방법 = how (people and robots) work together.", "example_in_sentence": "일하는 방법"}, {"type": "grammar", "label": "~에 대한 (about; regarding; on)", "exp": "Expresses the target or topic of an action. ~에 대하다 → ~에 대한 (attributive). Here: 방법에 대한 연구 (research about/on the method).", "example_in_sentence": "방법에 대한 연구"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'molixcm2wukl' and md5(translation) = '0ba853fd0695676292ea59500bb1d66f';
update public.article_cache set translation = $t${"texts": ["There is one gorilla living at Taipei Zoo. This gorilla is female. The gorilla did something special. The gorilla tries to get out of its enclosure. It tries to escape by using a log. It uses the log as a stepping stone. The gorilla is a really smart animal. It can think like a human. It even knows how to use tools. The zookeepers are watching over the gorilla. They help make sure the gorilla doesn't get hurt. The gorilla's health and safety are important.", "Korean Teacher Shortage Becomes Serious, School Classes Disrupted", "What is an \"anxiety bag\"? A Popular Trend", "The United States and China Resume Talks Over Trade Issues", "\"Talking Pig\" Becomes SNS Star", "Apple Greatly Improves iPhone Speed with New AI Chip"], "sentences": [{"text": "타이베이 동물원에 고릴라 한 마리가 살아요.", "translation": "A gorilla lives in Taipei Zoo.", "vocab": [{"ko": "타이베이", "en": "Taipei"}, {"ko": "동물원", "en": "zoo"}, {"ko": "고릴라", "en": "gorilla"}, {"ko": "살다", "en": "to live"}], "analysis": [{"type": "grammar", "label": "에", "exp": "Location particle marking where an action occurs or where someone/something exists.", "example_in_sentence": "타이베이 동물원에"}, {"type": "grammar", "label": "~아/어요 (polite ending)", "exp": "The everyday polite ending. 살다 has ㅏ, so it takes 아요: 살다 → 살아요 = lives.", "example_in_sentence": "살아요"}]}, {"text": "이 고릴라는 암컷이에요.", "translation": "This gorilla is female.", "vocab": [{"ko": "이", "en": "this"}, {"ko": "암컷", "en": "female"}], "analysis": [{"type": "grammar", "label": "는", "exp": "Topic particle marking the subject with contrastive or neutral topic focus.", "example_in_sentence": "이 고릴라는"}, {"type": "grammar", "label": "~이에요", "exp": "Copula (descriptive ending for nouns). 암컷 + 이에요 = identifying/defining.", "example_in_sentence": "암컷이에요"}]}, {"text": "고릴라가 특별한 일을 했어요.", "translation": "The gorilla did something special.", "vocab": [{"ko": "특별하다", "en": "to be special"}, {"ko": "일", "en": "thing; work"}, {"ko": "하다", "en": "to do"}], "analysis": [{"type": "grammar", "label": "가", "exp": "Subject particle marking the agent/doer of the action.", "example_in_sentence": "고릴라가"}, {"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Describing words take ~(으)ㄴ before a noun. 특별하다 → 특별한 일 = something special.", "example_in_sentence": "특별한"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense polite ending. 하다 → 했어요 (completed action).", "example_in_sentence": "했어요"}]}, {"text": "고릴라가 우리에서 나가려고 해요.", "translation": "The gorilla is trying to get out of the enclosure.", "vocab": [{"ko": "우리", "en": "cage; enclosure"}, {"ko": "나가다", "en": "to go out; to exit"}], "analysis": [{"type": "grammar", "label": "에서", "exp": "Locational source particle marking where an action starts or originates from.", "example_in_sentence": "우리에서"}, {"type": "grammar", "label": "~(으)려고 하다 (to try to)", "exp": "Shows an attempt or intention. 나가다 → 나가려고 해요 = is trying to get out.", "example_in_sentence": "나가려고 해요"}]}, {"text": "통나무를 이용해서 탈출하려고 해요.", "translation": "It is trying to escape by using a log.", "vocab": [{"ko": "통나무", "en": "log; trunk"}, {"ko": "이용하다", "en": "to use; to utilize"}, {"ko": "탈출하다", "en": "to escape"}], "analysis": [{"type": "grammar", "label": "를", "exp": "Direct object particle marking the thing being used.", "example_in_sentence": "통나무를"}, {"type": "grammar", "label": "~아/어서 (by ~ing)", "exp": "Shows how something is done. 이용하다 → 이용해서 = by using.", "example_in_sentence": "이용해서"}, {"type": "grammar", "label": "~(으)려고 하다 (to try to)", "exp": "Shows an attempt or intention. 탈출하다 → 탈출하려고 해요 = is trying to escape.", "example_in_sentence": "탈출하려고 해요"}]}, {"text": "통나무를 발판으로 써요.", "translation": "It uses the log as a foothold.", "vocab": [{"ko": "발판", "en": "foothold; stepping stone; base"}, {"ko": "쓰다", "en": "to use"}], "analysis": [{"type": "grammar", "label": "~(으)로 (as)", "exp": "Marks the role something is used for. After a consonant use 으로: 발판 → 발판으로 = as a foothold.", "example_in_sentence": "발판으로"}, {"type": "grammar", "label": "~아/어요 (polite ending)", "exp": "The everyday polite ending. 쓰다 → 써요 (the ㅡ drops) = uses.", "example_in_sentence": "써요"}]}, {"text": "고릴라는 정말 똑똑한 동물이에요.", "translation": "The gorilla is truly an intelligent animal.", "vocab": [{"ko": "정말", "en": "really; truly"}, {"ko": "똑똑하다", "en": "to be smart; to be intelligent"}, {"ko": "동물", "en": "animal"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Describing words take ~(으)ㄴ before a noun. 똑똑하다 → 똑똑한 동물 = a smart animal.", "example_in_sentence": "똑똑한"}, {"type": "grammar", "label": "~이에요", "exp": "Copula for nouns. Identifies/defines the subject.", "example_in_sentence": "동물이에요"}]}, {"text": "사람처럼 생각할 수 있어요.", "translation": "It can think like a human.", "vocab": [{"ko": "사람", "en": "person; human"}, {"ko": "생각하다", "en": "to think"}], "analysis": [{"type": "grammar", "label": "처럼", "exp": "Postposition meaning 'like' or 'similar to'. Marks comparison.", "example_in_sentence": "사람처럼"}, {"type": "grammar", "label": "~(으)ㄹ 수 있다 (can)", "exp": "Says someone is able to do something. 생각하다 → 생각할 수 있어요 = can think.", "example_in_sentence": "생각할 수 있어요"}]}, {"text": "도구를 사용할 줄도 알아요.", "translation": "It also knows how to use tools.", "vocab": [{"ko": "도구", "en": "tool"}, {"ko": "사용하다", "en": "to use"}, {"ko": "알다", "en": "to know"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 줄 알다 (to know how to)", "exp": "Says someone knows how to do something. 사용하다 → 사용할 줄 알아요 = knows how to use.", "example_in_sentence": "사용할 줄도 알아요"}, {"type": "grammar", "label": "도", "exp": "Additive particle meaning 'also; too.' Shows addition to prior statement.", "example_in_sentence": "줄도"}]}, {"text": "동물원 사람들이 고릴라를 지켜보고 있어요.", "translation": "Zoo staff are keeping an eye on the gorilla.", "vocab": [{"ko": "동물원", "en": "zoo"}, {"ko": "사람", "en": "person; people"}, {"ko": "지켜보다", "en": "to watch over; to observe carefully"}], "analysis": [{"type": "grammar", "label": "이/가 (subject particle)", "exp": "Marks the subject. After a consonant use 이: 사람들 → 사람들이.", "example_in_sentence": "사람들이"}, {"type": "grammar", "label": "를", "exp": "Direct object particle marking the thing being watched.", "example_in_sentence": "고릴라를"}, {"type": "grammar", "label": "~고 있다", "exp": "Progressive aspect marker. Shows ongoing/continuous action. 지켜보다 → 지켜보고 있어요.", "example_in_sentence": "지켜보고 있어요"}]}, {"text": "고릴라가 다치지 않게 도와줘요.", "translation": "They help so that the gorilla does not get hurt.", "vocab": [{"ko": "다치다", "en": "to be injured; to get hurt"}, {"ko": "도와주다", "en": "to help; to assist"}], "analysis": [{"type": "grammar", "label": "~지 않게 (so that ~ not)", "exp": "Describes the purpose of an action: so that something does not happen. 다치다 → 다치지 않게 = so that (it) doesn't get hurt.", "example_in_sentence": "다치지 않게"}, {"type": "grammar", "label": "~아/어요 (polite ending)", "exp": "The everyday polite ending. 도와주다 → 도와줘요 (주 + 어요 becomes 줘요) = help.", "example_in_sentence": "도와줘요"}]}, {"text": "고릴라의 건강과 안전이 중요해요.", "translation": "The gorilla's health and safety are important.", "vocab": [{"ko": "건강", "en": "health"}, {"ko": "안전", "en": "safety"}, {"ko": "중요하다", "en": "to be important"}], "analysis": [{"type": "grammar", "label": "의", "exp": "Possessive/genitive particle marking possession or relationship.", "example_in_sentence": "고릴라의"}, {"type": "grammar", "label": "과", "exp": "Coordinating conjunction meaning 'and.' Joins two nouns.", "example_in_sentence": "건강과 안전이"}, {"type": "grammar", "label": "~아/어요 (polite ending)", "exp": "The everyday polite ending. 하다 words become 해요: 중요하다 → 중요해요 = is important.", "example_in_sentence": "중요해요"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mom3u6xksrny' and md5(translation) = '39468f426b73417ac7841b64925832c1';
update public.article_cache set translation = $t${"texts": ["A major earthquake occurred in Izmir, Turkey in 2020. Many buildings collapsed and people were trapped. At this time, one man saved many lives.", "That man's name is Rıdvan Çelik. He was born without arms. However, he did not think of this as a problem.", "When the earthquake occurred, Mr. Çelik entered between the collapsed buildings. His small body could pass through narrow spaces. Without arms, he could move more easily.", "He found people trapped inside the collapsed buildings. He saved many people's lives. People call him a hero. He turned his uniqueness into an advantage."], "sentences": [{"text": "2020년 터키 이즈미르에서 큰 지진이 일어났어요.", "translation": "A large earthquake occurred in Izmir, Turkey in 2020.", "vocab": [{"ko": "지진", "en": "earthquake"}, {"ko": "일어나다", "en": "to occur, happen"}], "analysis": [{"type": "grammar", "label": "~았/었어요", "exp": "Past tense ending for completed action. 일어나다 (occur) + 았어요 = 일어났어요 (occurred).", "example_in_sentence": "일어났어요"}]}, {"text": "많은 건물이 무너지고 사람들이 갇혔어요.", "translation": "Many buildings collapsed and people became trapped.", "vocab": [{"ko": "건물", "en": "building"}, {"ko": "무너지다", "en": "to collapse"}, {"ko": "갇히다", "en": "to be trapped"}], "analysis": [{"type": "grammar", "label": "~고", "exp": "Connective ending that links two sequential or concurrent actions. 무너지고 = collapsed and (then).", "example_in_sentence": "무너지고"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense. 갇히다 + 었어요 = 갇혔어요 (became trapped).", "example_in_sentence": "갇혔어요"}]}, {"text": "이때 한 남성이 많은 생명을 구했어요.", "translation": "At this time, one man saved many lives.", "vocab": [{"ko": "남성", "en": "man, male"}, {"ko": "생명", "en": "life"}, {"ko": "구하다", "en": "to save, rescue"}], "analysis": [{"type": "grammar", "label": "~았/었어요", "exp": "Past tense. 구하다 + 았어요 = 구했어요 (saved).", "example_in_sentence": "구했어요"}]}, {"text": "그 사람의 이름은 리드반 첼리크예요.", "translation": "That person's name is Rıdvan Çelik.", "vocab": [{"ko": "이름", "en": "name"}], "analysis": [{"type": "grammar", "label": "~예요/이에요", "exp": "Polite form of 이다 (to be). After a vowel use 예요: 첼리크 → 첼리크예요 (is Çelik).", "example_in_sentence": "첼리크예요"}]}, {"text": "그는 태어날 때부터 팔이 없었어요.", "translation": "He had no arms from the time of birth.", "vocab": [{"ko": "태어나다", "en": "to be born"}, {"ko": "팔", "en": "arm"}, {"ko": "없다", "en": "to not have, to be absent"}], "analysis": [{"type": "expression", "label": "~(으)ㄹ 때부터", "exp": "Means 'from the time when'. 태어나다 (to be born) → 태어날 때부터 (since he was born).", "example_in_sentence": "태어날 때부터"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense. 없다 + 었어요 = 없었어요 (was absent, had not).", "example_in_sentence": "없었어요"}]}, {"text": "하지만 이것을 문제라고 생각하지 않았어요.", "translation": "However, he did not think of this as a problem.", "vocab": [{"ko": "하지만", "en": "however, but"}, {"ko": "문제", "en": "problem"}, {"ko": "생각하다", "en": "to think"}], "analysis": [{"type": "grammar", "label": "~(이)라고 생각하다", "exp": "Says what you think something is. 문제 + 라고 생각하다 → to think of it as a problem.", "example_in_sentence": "문제라고 생각하지"}, {"type": "grammar", "label": "~지 않다", "exp": "Negation suffix. 생각하다 + 지 않았어요 = did not think.", "example_in_sentence": "생각하지 않았어요"}]}, {"text": "지진이 일어났을 때 첼리크 씨는 무너진 건물 사이로 들어갔어요.", "translation": "When the earthquake occurred, Mr. Çelik went into the space between collapsed buildings.", "vocab": [{"ko": "지진", "en": "earthquake"}, {"ko": "일어나다", "en": "to occur"}, {"ko": "무너지다", "en": "to collapse"}, {"ko": "들어가다", "en": "to go in, enter"}], "analysis": [{"type": "expression", "label": "~ 사이로", "exp": "Through/into the space/gap between. 건물 사이 (space between buildings) + 로 (motion into).", "example_in_sentence": "건물 사이로"}, {"type": "grammar", "label": "~았/었을 때", "exp": "When a past action occurred. 일어나다 + 았을 때 = when occurred.", "example_in_sentence": "일어났을 때"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense. 들어가다 (to go in) → 들어갔어요 (went in).", "example_in_sentence": "들어갔어요"}]}, {"text": "그의 작은 몸은 좁은 공간을 통과할 수 있었어요.", "translation": "His small body was able to pass through narrow spaces.", "vocab": [{"ko": "작다", "en": "to be small"}, {"ko": "좁다", "en": "to be narrow"}, {"ko": "공간", "en": "space"}, {"ko": "통과하다", "en": "to pass through"}], "analysis": [{"type": "grammar", "label": "~ㄹ 수 있다", "exp": "Ability or possibility marker. 통과하다 + ㄹ 수 있었어요 = was able to pass through.", "example_in_sentence": "통과할 수 있었어요"}]}, {"text": "팔이 없어서 더 쉽게 움직일 수 있었어요.", "translation": "Because he had no arms, he was able to move more easily.", "vocab": [{"ko": "팔", "en": "arm"}, {"ko": "없다", "en": "to not have"}, {"ko": "쉽다", "en": "to be easy"}, {"ko": "움직이다", "en": "to move"}], "analysis": [{"type": "grammar", "label": "~어서", "exp": "Causal or sequential connective. 없어서 = because (he had no arms).", "example_in_sentence": "없어서"}, {"type": "grammar", "label": "~ㄹ 수 있다", "exp": "Ability or possibility. 움직이다 + ㄹ 수 있었어요 = was able to move.", "example_in_sentence": "움직일 수 있었어요"}]}, {"text": "그는 무너진 건물 안에 갇힌 사람들을 찾았어요.", "translation": "He found people trapped inside the collapsed building.", "vocab": [{"ko": "무너지다", "en": "to collapse"}, {"ko": "건물", "en": "building"}, {"ko": "갇히다", "en": "to be trapped"}, {"ko": "찾다", "en": "to find"}], "analysis": [{"type": "expression", "label": "~(으)ㄴ (past verb modifier)", "exp": "Describes a noun with a completed action. 갇히다 (to be trapped) → 갇힌 사람들 (people who were trapped).", "example_in_sentence": "갇힌 사람들"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense. 찾다 + 았어요 = 찾았어요 (found).", "example_in_sentence": "찾았어요"}]}, {"text": "많은 사람들의 생명을 구했어요.", "translation": "He saved the lives of many people.", "vocab": [{"ko": "사람", "en": "person, people"}, {"ko": "생명", "en": "life"}, {"ko": "구하다", "en": "to save, rescue"}], "analysis": [{"type": "grammar", "label": "~았/었어요", "exp": "Past tense. 구하다 + 았어요 = 구했어요 (saved).", "example_in_sentence": "구했어요"}]}, {"text": "사람들은 그를 영웅이라고 불러요.", "translation": "People call him a hero.", "vocab": [{"ko": "사람", "en": "person, people"}, {"ko": "영웅", "en": "hero"}, {"ko": "부르다", "en": "to call"}], "analysis": [{"type": "grammar", "label": "~(이)라고 부르다", "exp": "Says what someone is called. 영웅 + 이라고 부르다 → to call (him) a hero.", "example_in_sentence": "영웅이라고 불러요"}, {"type": "grammar", "label": "~아/어요", "exp": "Polite present ending. 부르다 is a 르-irregular verb: 부르다 → 불러요 (call).", "example_in_sentence": "불러요"}]}, {"text": "그는 자신의 특별함을 장점으로 만들었어요.", "translation": "He turned his uniqueness into an advantage.", "vocab": [{"ko": "특별함", "en": "uniqueness; specialness"}, {"ko": "장점", "en": "advantage, strength"}, {"ko": "만들다", "en": "to make"}], "analysis": [{"type": "grammar", "label": "~으로", "exp": "Into/as (transformation marker). 장점 + 으로 = into an advantage.", "example_in_sentence": "장점으로"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense. 만들다 + 었어요 = 만들었어요 (made, turned into).", "example_in_sentence": "만들었어요"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mom3wbgtgfsc' and md5(translation) = '1c7b62c5c5947d7615752d9ed1c57ab6';
update public.article_cache set translation = $t${"texts": ["A photo comparing the appearance of Chinese railways in 1996 and 2022 has become a hot topic. The changes that occurred over 26 years are truly remarkable.", "In 1996, Chinese railways were slow and had outdated facilities. Train stations were also small and inconvenient. Many people had to wait for a long time to board trains.", "However, by 2022, China had become a high-speed rail powerhouse. Trains exceeding 300 kilometers per hour connect the entire country. Train stations have also changed to be large and modern like airports.", "South Korea has also been developing railways since the 1970s. The high-speed rail era opened when KTX (Korean Train eXpress) opened in 2004. The development of transportation is an important indicator showing a country's growth."], "sentences": [{"text": "1996년과 2022년 중국 철도의 모습을 비교한 사진이 화제가 되고 있어요.", "translation": "Photos comparing the appearance of Chinese railways in 1996 and 2022 are becoming a hot topic.", "vocab": [{"ko": "철도", "en": "railroad"}, {"ko": "모습", "en": "appearance; state"}, {"ko": "화제", "en": "topic; hot issue"}], "analysis": [{"type": "grammar", "label": "~고 있어요 (progressive aspect)", "exp": "Indicates an action or state in progress or currently ongoing. From 있다 + present tense.", "example_in_sentence": "화제가 되고 있어요"}, {"type": "grammar", "label": "~(으)ㄴ (past verb modifier)", "exp": "Describes a noun with a completed action. 비교하다 → 비교한 사진 (photos that compare).", "example_in_sentence": "비교한 사진"}]}, {"text": "26년 사이에 일어난 변화가 정말 놀랍습니다.", "translation": "The change that occurred over 26 years is truly remarkable.", "vocab": [{"ko": "변화", "en": "change"}, {"ko": "놀랍다", "en": "to be surprising; to be remarkable"}], "analysis": [{"type": "expression", "label": "~사이에 (during; over the period of)", "exp": "Indicates a time period or interval. Combines 사이 (interval) with locative particle 에.", "example_in_sentence": "26년 사이에"}, {"type": "grammar", "label": "~(으)ㄴ (past verb modifier)", "exp": "Describes a noun with a completed action. 일어나다 → 일어난 변화 (the change that happened).", "example_in_sentence": "일어난 변화"}]}, {"text": "1996년 중국 철도는 속도가 느리고 시설이 낡았어요.", "translation": "In 1996, Chinese railways were slow and had deteriorated facilities.", "vocab": [{"ko": "속도", "en": "speed"}, {"ko": "시설", "en": "facility"}, {"ko": "낡다", "en": "to be worn out; to be old and shabby"}], "analysis": [{"type": "grammar", "label": "~고 (coordinate conjunction)", "exp": "Joins two parallel adjectives or clauses. 느리고 시설이 낡았어요 connects two descriptions.", "example_in_sentence": "느리고"}]}, {"text": "기차역도 작고 불편했습니다.", "translation": "Train stations were also small and inconvenient.", "vocab": [{"ko": "기차역", "en": "train station"}, {"ko": "불편하다", "en": "to be inconvenient"}], "analysis": [{"type": "grammar", "label": "~고 (coordinate conjunction)", "exp": "Connects two parallel adjectives: 작고 and 불편했습니다.", "example_in_sentence": "작고"}]}, {"text": "많은 사람들이 기차를 타기 위해 오랫동안 기다려야 했어요.", "translation": "Many people had to wait for a long time in order to board the train.", "vocab": [{"ko": "사람들", "en": "people (plural)"}, {"ko": "타다", "en": "to board; to ride"}, {"ko": "기다리다", "en": "to wait"}], "analysis": [{"type": "grammar", "label": "~기 위해 (in order to; for the purpose of)", "exp": "Indicates purpose or goal. Nominalized verb 타기 with purposive expression 위해.", "example_in_sentence": "타기 위해"}, {"type": "grammar", "label": "~아/어야 했다", "exp": "Means 'had to'. 기다리다 → 기다려야 했어요 (had to wait).", "example_in_sentence": "기다려야 했어요"}]}, {"text": "하지만 2022년 중국은 고속철도(빠른 기차) 강국이 되었어요.", "translation": "However, by 2022, China had become a superpower in high-speed rail.", "vocab": [{"ko": "고속철도", "en": "high-speed rail"}, {"ko": "강국", "en": "superpower; strong nation"}], "analysis": [{"type": "grammar", "label": "~이/가 되다", "exp": "Means 'to become (something)'. 강국 + 이 되다 → 강국이 되었어요 (became a powerhouse).", "example_in_sentence": "강국이 되었어요"}]}, {"text": "시속 300킬로미터가 넘는 기차가 전국을 연결합니다.", "translation": "Trains exceeding 300 kilometers per hour connect the entire nation.", "vocab": [{"ko": "시속", "en": "speed per hour; km/h"}, {"ko": "넘다", "en": "to exceed; to surpass"}, {"ko": "연결하다", "en": "to connect"}], "analysis": [{"type": "grammar", "label": "~는 (attributive present tense)", "exp": "Present participle modifying noun. 넘는 modifies 기차.", "example_in_sentence": "넘는 기차"}]}, {"text": "기차역도 공항처럼 크고 현대적으로 바뀌었어요.", "translation": "Train stations have also changed to be large and modern like airports.", "vocab": [{"ko": "공항", "en": "airport"}, {"ko": "현대적", "en": "modern; contemporary"}, {"ko": "바뀌다", "en": "to change; to be transformed"}], "analysis": [{"type": "grammar", "label": "~고 (coordinate conjunction)", "exp": "Connects parallel adjectives describing changes: 크고 and 현대적으로.", "example_in_sentence": "크고"}]}, {"text": "한국도 1970년대부터 철도를 발전시켜 왔어요.", "translation": "Korea has also been developing railways since the 1970s.", "vocab": [{"ko": "발전시키다", "en": "to develop; to advance"}], "analysis": [{"type": "grammar", "label": "~아/어 오다", "exp": "Shows an action that has continued from the past up to now: 'have been doing'. 발전시키다 → 발전시켜 왔어요 (have been developing).", "example_in_sentence": "발전시켜 왔어요"}]}, {"text": "2004년 케이티엑스(KTX)가 개통되면서 고속철도 시대가 열렸습니다.", "translation": "As KTX opened in 2004, the era of high-speed rail began.", "vocab": [{"ko": "개통되다", "en": "to be opened for service"}, {"ko": "시대", "en": "era; age"}, {"ko": "열리다", "en": "to open; to begin"}], "analysis": [{"type": "grammar", "label": "~(으)면서", "exp": "Links an event with what happened along with it: 'as'. 개통되다 → 개통되면서 (as it opened).", "example_in_sentence": "개통되면서"}]}, {"text": "교통 발전은 한 나라의 성장을 보여주는 중요한 지표예요.", "translation": "Transportation development is an important indicator showing a nation's growth.", "vocab": [{"ko": "교통", "en": "transportation; traffic"}, {"ko": "발전", "en": "development; progress"}, {"ko": "성장", "en": "growth"}, {"ko": "지표", "en": "indicator; index"}], "analysis": [{"type": "grammar", "label": "~는 (attributive present tense)", "exp": "Present participle modifying 지표. 보여주는 describes what the indicator does.", "example_in_sentence": "보여주는 중요한 지표"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'monnqlfqqm9s' and md5(translation) = '44e79945b203dba7547f98e65e3d227d';
update public.article_cache set translation = $t${"texts": ["Fish in the aquarium are watching television. All the fish are looking at the screen in the same way.", "The fish are not moving and staying still. They seem to be concentrating on the television. It's a really amazing sight.", "People were surprised when they saw this. They learned that fish can also watch television.", "At the aquarium, they make sure the fish don't get bored. When they show television to the fish, they become more active."], "sentences": [{"text": "수족관에 있는 물고기들이 텔레비전을 보고 있어요.", "translation": "Fish in the aquarium are watching television.", "vocab": [{"ko": "수족관", "en": "aquarium"}, {"ko": "물고기", "en": "fish"}, {"ko": "텔레비전", "en": "television"}, {"ko": "보다", "en": "to watch; to look at"}], "analysis": [{"type": "grammar", "label": "~는 (descriptive relative clause modifier)", "exp": "Modifies the noun 물고기들, describing fish that exist in the aquarium. 있다 → 있는.", "example_in_sentence": "있는 물고기들"}, {"type": "grammar", "label": "~고 있어요 (progressive aspect)", "exp": "Indicates an ongoing or habitual action. 보다 → 보고 있다 → 보고 있어요 (polite present).", "example_in_sentence": "보고 있어요"}]}, {"text": "모든 물고기가 화면을 똑같이 바라보고 있어요.", "translation": "All fish are looking at the screen in the same way.", "vocab": [{"ko": "모든", "en": "all; every"}, {"ko": "화면", "en": "screen"}, {"ko": "똑같이", "en": "identically; in the same way"}, {"ko": "바라보다", "en": "to gaze at; to look at"}], "analysis": [{"type": "grammar", "label": "~고 있어요 (progressive aspect)", "exp": "Describes ongoing action of looking. 바라보다 → 바라보고 있다 → 바라보고 있어요.", "example_in_sentence": "바라보고 있어요"}]}, {"text": "물고기들은 움직이지 않고 가만히 있어요.", "translation": "The fish are not moving and staying still.", "vocab": [{"ko": "움직이다", "en": "to move"}, {"ko": "가만히", "en": "still; quietly; motionless"}, {"ko": "있다", "en": "to be; to exist; to stay"}], "analysis": [{"type": "grammar", "label": "~지 않고 (negation + connective)", "exp": "Negates an action and connects to the following clause. 움직이다 → 움직이지 않다 → 움직이지 않고.", "example_in_sentence": "움직이지 않고"}, {"type": "grammar", "label": "~아/어요", "exp": "Polite present ending. 있다 → 있어요.", "example_in_sentence": "있어요"}]}, {"text": "텔레비전에 집중하고 있는 것 같아요.", "translation": "It seems the fish are concentrating on the television.", "vocab": [{"ko": "집중하다", "en": "to concentrate; to focus"}, {"ko": "같다", "en": "to seem; to appear; to look like"}], "analysis": [{"type": "grammar", "label": "~고 있는 (progressive relative clause)", "exp": "Modifies the noun 것, describing an ongoing state. 집중하다 → 집중하고 있다 → 집중하고 있는.", "example_in_sentence": "집중하고 있는"}, {"type": "grammar", "label": "~는 것 같다", "exp": "Means 'it seems like ...'. 집중하고 있다 → 집중하고 있는 것 같아요 (it seems they are concentrating).", "example_in_sentence": "집중하고 있는 것 같아요"}]}, {"text": "정말 신기한 모습이에요.", "translation": "It is a really amazing sight.", "vocab": [{"ko": "정말", "en": "really; very"}, {"ko": "신기하다", "en": "to be amazing; to be wonderful; to be surprising"}, {"ko": "모습", "en": "sight; appearance; look"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Turns an adjective into a word that describes a noun. 신기하다 (amazing) → 신기한 모습 (an amazing sight).", "example_in_sentence": "신기한 모습"}, {"type": "grammar", "label": "이에요 (copula, polite present)", "exp": "Polite copula ending for nominal predicate. Attaches to noun 모습.", "example_in_sentence": "모습이에요"}]}, {"text": "사람들은 이 모습을 보고 놀랐어요.", "translation": "People saw this sight and were surprised.", "vocab": [{"ko": "사람", "en": "person; people"}, {"ko": "이", "en": "this"}, {"ko": "보다", "en": "to see; to watch"}, {"ko": "놀라다", "en": "to be surprised; to be amazed"}], "analysis": [{"type": "grammar", "label": "~고 (conjunctive, sequential action)", "exp": "Connects two actions in sequence: seeing and then being surprised. 보다 → 보고.", "example_in_sentence": "보고 놀랐어요"}, {"type": "grammar", "label": "~았/었어요 (polite past tense)", "exp": "Past tense in polite form. 놀라다 → 놀랐다 → 놀랐어요.", "example_in_sentence": "놀랐어요"}]}, {"text": "물고기도 텔레비전을 볼 수 있다는 것을 알게 되었어요.", "translation": "People came to know that fish can also watch television.", "vocab": [{"ko": "알다", "en": "to know; to learn"}, {"ko": "되다", "en": "to become; to come to"}], "analysis": [{"type": "grammar", "label": "~ㄹ 수 있다 (ability/possibility)", "exp": "Expresses ability or possibility. 보다 → 볼 수 있다 (can watch).", "example_in_sentence": "볼 수 있다"}, {"type": "grammar", "label": "~다는 것 (nominalization with quoted content)", "exp": "Nominalizes a clause by adding ~다는 것; the clause 물고기도 텔레비전을 볼 수 있다 becomes the object of 알다.", "example_in_sentence": "볼 수 있다는 것을"}, {"type": "grammar", "label": "~게 되다 (come to; come to be)", "exp": "Expresses a transition to a new state or realization. 알다 → 알게 되다 → 알게 되었어요.", "example_in_sentence": "알게 되었어요"}]}, {"text": "수족관에서는 물고기들이 지루하지 않도록 해요.", "translation": "In the aquarium, they make sure fish do not get bored.", "vocab": [{"ko": "지루하다", "en": "to be bored; to be tedious"}, {"ko": "하다", "en": "to do; to make"}], "analysis": [{"type": "grammar", "label": "~지 않도록 하다 (prevent/ensure that not)", "exp": "Expresses prevention or ensuring that something does not happen. 지루하다 → 지루하지 않도록 하다.", "example_in_sentence": "지루하지 않도록 해요"}]}, {"text": "텔레비전을 보여주면 물고기들이 더 활발해져요.", "translation": "If you show television to the fish, they become more active.", "vocab": [{"ko": "보여주다", "en": "to show (to someone)"}, {"ko": "활발하다", "en": "to be active; to be lively"}], "analysis": [{"type": "grammar", "label": "~(으)면", "exp": "Means 'if / when'. After a vowel just add 면: 보여주다 → 보여주면 (if you show).", "example_in_sentence": "보여주면"}, {"type": "grammar", "label": "~아/어지다 (become, inchoative)", "exp": "Inchoative auxiliary expressing change of state: becoming active. 활발하다 → 활발해지다 → 활발해져요.", "example_in_sentence": "활발해져요"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mopun5a155bt' and md5(translation) = 'fff97bb006cff07a57e5d5f5cc1153c7';
update public.article_cache set translation = $t${"texts": ["Horses are famous for being animals that eat grass. But did you know that sometimes they also eat small animals? This is a phenomenon observed worldwide.", "The reason horses eat meat is because of nutritional deficiency. This behavior appears especially when they lack minerals like protein or sodium. In such situations, horses eat small animals like birds or mice.", "Similar cases have been reported on Jeju Island in Korea. Horses raised on farms there occasionally show this behavior. Experts explain that this is a natural instinct.", "Horses' main diet is still grass and hay. However, when they lack necessary nutrients, they look for other food. This can be seen as one of the survival instincts of horses."], "sentences": [{"text": "말은 풀을 먹는 동물로 유명해요.", "translation": "Horses are famous as animals that eat grass.", "vocab": [{"ko": "풀", "en": "grass"}, {"ko": "유명하다", "en": "to be famous"}], "analysis": [{"type": "grammar", "label": "~(으)로 유명하다", "exp": "Means 'famous as / for ...'. 풀을 먹는 동물로 유명해요 (famous as animals that eat grass).", "example_in_sentence": "동물로 유명해요"}]}, {"text": "하지만 때로는 작은 동물들을 먹기도 한다는 사실을 아시나요?", "translation": "But did you know that horses sometimes eat small animals too?", "vocab": [{"ko": "때로는", "en": "sometimes"}, {"ko": "작다", "en": "to be small"}, {"ko": "사실", "en": "fact"}], "analysis": [{"type": "grammar", "label": "~기도 하다", "exp": "Means 'also / sometimes do'. 먹다 → 먹기도 하다 (sometimes also eat).", "example_in_sentence": "먹기도 한다"}, {"type": "grammar", "label": "~ㄴ/는다는 사실", "exp": "Means 'the fact that ...'. 먹기도 하다 → 먹기도 한다는 사실 (the fact that they sometimes eat).", "example_in_sentence": "한다는 사실"}]}, {"text": "이는 전 세계적으로 관찰되는 현상이에요.", "translation": "This is a phenomenon observed worldwide.", "vocab": [{"ko": "전 세계적으로", "en": "worldwide; globally"}, {"ko": "관찰되다", "en": "to be observed"}, {"ko": "현상", "en": "phenomenon"}], "analysis": [{"type": "grammar", "label": "~는 (verb modifier)", "exp": "Describes a noun with a present action. 관찰되다 (to be observed) → 관찰되는 현상 (a phenomenon that is observed).", "example_in_sentence": "관찰되는 현상"}]}, {"text": "말이 고기를 먹는 이유는 영양소가 부족하기 때문이에요.", "translation": "The reason horses eat meat is that they lack nutrients.", "vocab": [{"ko": "이유", "en": "reason"}, {"ko": "영양소", "en": "nutrient"}, {"ko": "부족하다", "en": "to be lacking; to be insufficient"}], "analysis": [{"type": "grammar", "label": "~기 때문이다", "exp": "Gives the reason: 'it's because ...'. 부족하다 → 부족하기 때문이에요 (it's because they lack).", "example_in_sentence": "부족하기 때문이에요"}]}, {"text": "특히 단백질이나 나트륨 같은 미네랄이 부족할 때 나타나는 행동이에요.", "translation": "It is a behavior that appears especially when they lack protein or minerals such as sodium.", "vocab": [{"ko": "단백질", "en": "protein"}, {"ko": "나트륨", "en": "sodium"}, {"ko": "행동", "en": "behavior"}], "analysis": [{"type": "expression", "label": "~ 같은", "exp": "Means 'such as; like' after a noun. 나트륨 같은 미네랄 (minerals such as sodium).", "example_in_sentence": "나트륨 같은 미네랄"}, {"type": "grammar", "label": "~(으)ㄹ 때", "exp": "Means 'when'. 부족하다 → 부족할 때 (when they lack).", "example_in_sentence": "부족할 때"}, {"type": "grammar", "label": "~는 (verb modifier)", "exp": "Describes a noun with a present action. 나타나다 (to appear) → 나타나는 행동 (a behavior that appears).", "example_in_sentence": "나타나는 행동"}]}, {"text": "이런 상황에서 말들은 작은 새나 쥐 같은 동물을 먹어요.", "translation": "In such situations, horses eat small animals like birds or mice.", "vocab": [{"ko": "상황", "en": "situation; circumstance"}, {"ko": "새", "en": "bird"}, {"ko": "쥐", "en": "mouse; rat"}], "analysis": [{"type": "expression", "label": "~(이)나", "exp": "Means 'or' between nouns. 새나 쥐 (birds or mice).", "example_in_sentence": "새나 쥐"}]}, {"text": "한국의 제주도에서도 비슷한 사례가 보고된 적이 있어요.", "translation": "Similar cases have also been reported in Jeju Island, Korea.", "vocab": [{"ko": "제주도", "en": "Jeju Island"}, {"ko": "비슷하다", "en": "to be similar"}, {"ko": "사례", "en": "case; example"}, {"ko": "보고되다", "en": "to be reported"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ 적이 있다", "exp": "Means 'has happened before'. 보고되다 → 보고된 적이 있어요 (has been reported before).", "example_in_sentence": "보고된 적이 있어요"}]}, {"text": "목장에서 기르는 말들이 가끔 이런 행동을 보인다고 해요.", "translation": "It is said that horses raised on farms sometimes show this behavior.", "vocab": [{"ko": "목장", "en": "farm; ranch"}, {"ko": "기르다", "en": "to raise; to rear"}, {"ko": "가끔", "en": "occasionally; sometimes"}, {"ko": "보이다", "en": "to show; to display"}], "analysis": [{"type": "grammar", "label": "~는 (verb modifier)", "exp": "Describes a noun with a present action. 기르다 (to raise) → 기르는 말들 (horses that people raise).", "example_in_sentence": "기르는 말들"}, {"type": "grammar", "label": "~ㄴ/는다고 하다", "exp": "Reports what others say: 'they say that ...'. 보이다 → 보인다고 해요 (they say they show).", "example_in_sentence": "보인다고 해요"}]}, {"text": "전문가들은 이것이 자연스러운 본능이라고 설명해요.", "translation": "Experts explain that this is a natural instinct.", "vocab": [{"ko": "전문가", "en": "expert; specialist"}, {"ko": "자연스럽다", "en": "to be natural"}, {"ko": "본능", "en": "instinct"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Turns an adjective into a word that describes a noun. 자연스럽다 is ㅂ-irregular: 자연스럽다 → 자연스러운 본능 (a natural instinct).", "example_in_sentence": "자연스러운 본능"}, {"type": "grammar", "label": "~(이)라고 설명하다", "exp": "Reports an explanation: 'explain that it is ...'. 본능 + 이라고 설명해요 (explain that it is an instinct).", "example_in_sentence": "본능이라고 설명해요"}]}, {"text": "말의 주식은 여전히 풀과 건초예요.", "translation": "Horses' staple food is still grass and hay.", "vocab": [{"ko": "주식", "en": "staple food; main diet"}, {"ko": "여전히", "en": "still"}, {"ko": "건초", "en": "hay"}], "analysis": []}, {"text": "하지만 필요한 영양소가 부족하면 다른 음식을 찾게 돼요.", "translation": "However, if necessary nutrients are lacking, they end up looking for other food.", "vocab": [{"ko": "필요하다", "en": "to be necessary; to need"}, {"ko": "음식", "en": "food"}, {"ko": "찾다", "en": "to find; to look for"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Turns an adjective into a word that describes a noun. 필요하다 (necessary) → 필요한 영양소 (necessary nutrients).", "example_in_sentence": "필요한 영양소"}, {"type": "grammar", "label": "~(으)면", "exp": "Means 'if'. 부족하다 → 부족하면 (if they lack).", "example_in_sentence": "부족하면"}, {"type": "grammar", "label": "~게 되다", "exp": "Means 'to end up doing / come to do'. 찾다 → 찾게 돼요 (end up looking for).", "example_in_sentence": "찾게 돼요"}]}, {"text": "이는 말의 생존 본능 중 하나라고 볼 수 있어요.", "translation": "This can be seen as one of horses' survival instincts.", "vocab": [{"ko": "생존", "en": "survival"}], "analysis": [{"type": "grammar", "label": "~ 중 하나", "exp": "Means 'one of ...'. 생존 본능 중 하나 (one of their survival instincts).", "example_in_sentence": "본능 중 하나"}, {"type": "grammar", "label": "~(이)라고 볼 수 있다", "exp": "Means 'it can be seen as ...'. 하나 + 라고 볼 수 있어요 (can be seen as one).", "example_in_sentence": "하나라고 볼 수 있어요"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mopunpuyngx2' and md5(translation) = 'b0772339ddf0d75cc5b7ccda71b69891';
update public.article_cache set translation = $t${"sentences": [{"text": "타이완 반도체 제조회사(TSMC)에 대한 산업스파이 활동으로 기소된 범죄자들이 최대 10년의 징역형을 선고받았어요.", "idx": 0, "translation": "Criminals indicted for industrial espionage against Taiwan Semiconductor Manufacturing Company (TSMC) were sentenced to up to 10 years imprisonment.", "vocab": [{"ko": "반도체", "en": "semiconductor", "note": "core component in modern electronics"}, {"ko": "산업스파이", "en": "industrial espionage", "note": "stealing corporate/industrial secrets"}, {"ko": "기소하다", "en": "to indict; to prosecute", "note": "legal term"}, {"ko": "징역형", "en": "prison sentence", "note": "imprisonment as punishment"}], "grammar": [{"pattern": "~에 대한", "exp": "expresses 'against' or 'regarding'; shows the target of an action", "example_in_sentence": "타이완 반도체 제조회사(TSMC)에 대한 산업스파이 활동"}, {"pattern": "~으로 기소되다", "exp": "passive construction meaning 'to be indicted/prosecuted for'", "example_in_sentence": "산업스파이 활동으로 기소된"}], "analysis": []}, {"text": "이 사건은 반도체 기술 유출과 관련된 중대한 경제범죄로 분류되었습니다.", "idx": 1, "translation": "This case was classified as a serious economic crime related to semiconductor technology leakage.", "vocab": [{"ko": "기술 유출", "en": "technology leakage; technology theft", "note": "unauthorized disclosure of technical information"}, {"ko": "경제범죄", "en": "economic crime", "note": "crime involving financial/economic damage"}, {"ko": "중대하다", "en": "serious; grave; critical", "note": "adjective form"}], "grammar": [{"pattern": "~과 관련된", "exp": "relational modifier meaning 'related to'; 'connected with'", "example_in_sentence": "반도체 기술 유출과 관련된 중대한 경제범죄"}], "analysis": []}, {"text": "반도체는 현대 기술의 핵심 부품으로, 스마트폰부터 자동차까지 모든 전자제품에 사용돼요.", "idx": 2, "translation": "Semiconductors are a core component of modern technology, used in all electronic products from smartphones to automobiles.", "vocab": [{"ko": "핵심 부품", "en": "core component; essential part", "note": "key/vital component"}, {"ko": "스마트폰", "en": "smartphone", "note": "from English"}, {"ko": "전자제품", "en": "electronic product", "note": "appliance; device"}], "grammar": [{"pattern": "~부터 ~까지", "exp": "expresses range from X to Y, inclusive of both endpoints", "example_in_sentence": "스마트폰부터 자동차까지"}], "analysis": []}, {"text": "특히 타이완은 전 세계 반도체 생산의 60% 이상을 담당하는 핵심 국가입니다.", "idx": 3, "translation": "In particular, Taiwan is a core country that handles over 60% of global semiconductor production.", "vocab": [{"ko": "담당하다", "en": "to be responsible for; to handle; to manage", "note": "verb"}, {"ko": "전 세계", "en": "the entire world; globally", "note": "noun"}], "grammar": [{"pattern": "~이상", "exp": "means 'over; more than; or more'; indicates a minimum threshold", "example_in_sentence": "60% 이상을"}], "analysis": []}, {"text": "따라서 이런 기술 정보는 국가 기밀에 준하는 중요성을 갖고 있어요.", "idx": 4, "translation": "Therefore, such technical information holds importance equivalent to national secrets.", "vocab": [{"ko": "기술 정보", "en": "technical information", "note": "information about technology"}, {"ko": "국가 기밀", "en": "national secret; state secret", "note": "confidential government information"}, {"ko": "중요성", "en": "importance; significance", "note": "abstract noun"}], "grammar": [{"pattern": "~에 준하다", "exp": "means 'to be equivalent to; to match in level/importance'", "example_in_sentence": "국가 기밀에 준하는 중요성"}], "analysis": []}, {"text": "이번 판결은 산업스파이 활동에 대한 강력한 경고 메시지를 담고 있습니다.", "idx": 5, "translation": "This ruling contains a strong warning message against industrial espionage activities.", "vocab": [{"ko": "판결", "en": "judicial ruling; verdict; decision", "note": "from a court"}, {"ko": "경고 메시지", "en": "warning message", "note": "cautionary statement"}], "grammar": [{"pattern": "~을/를 담다", "exp": "verb meaning 'to contain; to embody; to hold'; metaphorical sense of 'include/express'", "example_in_sentence": "강력한 경고 메시지를 담고 있습니다"}], "analysis": []}, {"text": "법원은 기업 기밀 유출이 단순한 개인 범죄가 아니라 국가 경제 안보를 위협하는 중대 범죄라고 판단했어요.", "idx": 6, "translation": "The court determined that leaking corporate secrets is not a simple individual crime but a serious crime that threatens national economic security.", "vocab": [{"ko": "법원", "en": "court", "note": "judicial institution"}, {"ko": "기업 기밀", "en": "corporate secret; trade secret", "note": "company confidential information"}, {"ko": "경제 안보", "en": "economic security", "note": "protection of economic interests"}], "grammar": [{"pattern": "~이 아니라 ~", "exp": "negation pattern meaning 'not X but rather Y'; contrasts two things", "example_in_sentence": "단순한 개인 범죄가 아니라 국가 경제 안보를 위협하는 중대 범죄"}], "analysis": []}, {"text": "한국도 반도체 강국으로서 비슷한 위험에 노출되어 있습니다.", "idx": 7, "translation": "Korea, as a semiconductor powerhouse, is also exposed to similar risks.", "vocab": [{"ko": "강국", "en": "powerhouse; major power; strong nation", "note": "powerful country/industry"}, {"ko": "위험", "en": "risk; danger; hazard", "note": "noun"}, {"ko": "노출되다", "en": "to be exposed to", "note": "passive verb"}], "grammar": [{"pattern": "~로서", "exp": "particle meaning 'as; in one's capacity as'; marks role or position", "example_in_sentence": "반도체 강국으로서"}], "analysis": []}, {"text": "삼성전자와 에스케이하이닉스 같은 국내 반도체 기업들도 기술 보안에 더욱 신경 써야 할 것으로 보여요.", "idx": 8, "translation": "It seems that domestic semiconductor companies such as Samsung Electronics and SK Hynix will also need to pay more attention to technology security.", "vocab": [{"ko": "국내", "en": "domestic; internal; in-country", "note": "within the country"}, {"ko": "기술 보안", "en": "technology security", "note": "protecting technical information"}, {"ko": "신경 쓰다", "en": "to pay attention; to be concerned; to care", "note": "colloquial expression"}], "grammar": [{"pattern": "~ㄹ 것으로 보이다", "exp": "prospective form meaning 'appears to; seems likely to; is expected to'", "example_in_sentence": "더욱 신경 써야 할 것으로 보여요"}], "analysis": []}, {"text": "이번 사건을 통해 각국이 첨단 기술 보호에 얼마나 민감한지 알 수 있습니다.", "idx": 9, "translation": "Through this case, one can see how sensitive each country is to the protection of advanced technology.", "vocab": [{"ko": "첨단 기술", "en": "advanced technology; cutting-edge technology", "note": "high-tech; sophisticated"}, {"ko": "민감하다", "en": "sensitive; touchy; responsive", "note": "adjective"}], "grammar": [{"pattern": "~을/를 통해", "exp": "means 'through; via; by means of'; indicates a method or medium", "example_in_sentence": "이번 사건을 통해"}], "analysis": []}], "version": "p3"}$t$, qa_at = now()
 where article_id = 'mortmxn5ubv7' and md5(translation) = 'a9f8ed09ecdfec4b629098b79ee9f154';
update public.article_cache set translation = $t${"texts": ["A 20-year-old young man living in Vietnam was on his way home after finishing training. At that moment, he discovered a house that was on fire.", "The young man climbed onto the roof together with other people. And he rescued two elderly people who were inside the house first.", "However, there were more family members still trapped inside the house. Two women and three children were unable to get out of the fire.", "The young man went back into the burning house again. And he safely rescued all five family members. Many people are praising this brave young man."], "sentences": [{"text": "베트남에 사는 20살 청년이 훈련을 마치고 집으로 돌아가는 길이었어요.", "translation": "A 20-year-old young man living in Vietnam was on his way home after finishing training.", "vocab": [{"ko": "베트남", "en": "Vietnam", "note": "country name; used with ~에 살다 (live in)"}, {"ko": "훈련", "en": "training", "note": "noun; paired with 마치다 (finish)"}, {"ko": "마치다", "en": "to finish, complete", "note": "action completed before another; often followed by ~고"}, {"ko": "돌아가다", "en": "to return, go back", "note": "movement verb; direction marked with ~으로"}], "grammar": [{"pattern": "~는 중이다 / ~는 길이다", "exp": "Describes an action or state in progress at a specific moment; ~는 길이다 emphasizes being in the process of going/moving.", "example_in_sentence": "집으로 돌아가는 길이었어요"}, {"pattern": "~고 (sequential action)", "exp": "Connects two completed actions in order; the first action happens, then the second.", "example_in_sentence": "훈련을 마치고 집으로 돌아가는"}], "analysis": []}, {"text": "그때 한 집에서 불이 나고 있는 것을 발견했어요.", "translation": "At that moment, he discovered a house that was on fire.", "vocab": [{"ko": "불", "en": "fire", "note": "noun; 불이 나다 (fire breaks out)"}, {"ko": "나다", "en": "to break out, occur", "note": "used with 불 to mean 'fire starts'; different from other meanings of 나다"}, {"ko": "발견하다", "en": "to discover, find", "note": "transitive verb; takes object with ~을/를"}], "grammar": [{"pattern": "~고 있는 것", "exp": "Nominalization of an ongoing action; 'something that is happening'; ~는 것 focuses on the state/action itself.", "example_in_sentence": "불이 나고 있는 것을 발견했어요"}], "analysis": []}, {"text": "청년은 다른 사람들과 함께 지붕으로 올라갔어요.", "translation": "The young man climbed onto the roof together with other people.", "vocab": [{"ko": "다른", "en": "other, different", "note": "adjective; modifies 사람들"}, {"ko": "함께", "en": "together", "note": "adverb; indicates joint action"}, {"ko": "지붕", "en": "roof", "note": "noun; location marked with ~으로"}, {"ko": "올라가다", "en": "to go up, climb", "note": "movement upward; direction marked with ~으로"}], "grammar": [], "analysis": []}, {"text": "그리고 집 안에 있던 노인 두 명을 먼저 구했어요.", "translation": "And first, he rescued two elderly people who were inside the house.", "vocab": [{"ko": "노인", "en": "elderly person", "note": "noun; 두 명 (two people) is the count"}, {"ko": "먼저", "en": "first, beforehand", "note": "adverb; marks priority or sequence"}, {"ko": "구하다", "en": "to rescue, save", "note": "transitive verb; takes object with ~을/를"}], "grammar": [{"pattern": "~던 (past modifier)", "exp": "Describes a state or action that existed in the past; modifies the following noun.", "example_in_sentence": "집 안에 있던 노인"}], "analysis": []}, {"text": "하지만 아직 집 안에 갇힌 가족이 더 있었어요.", "translation": "However, there were more family members still trapped inside the house.", "vocab": [{"ko": "하지만", "en": "however, but", "note": "conjunction; introduces contrast"}, {"ko": "아직", "en": "still, yet", "note": "adverb; indicates continuation or remaining action"}, {"ko": "갇히다", "en": "to be trapped, confined", "note": "passive verb; ~ㄴ form modifies following noun"}, {"ko": "가족", "en": "family", "note": "noun; ~이 더 있었어요 (there were more)"}], "grammar": [{"pattern": "~ㄴ (past participle modifier)", "exp": "Modifies a noun to describe a completed or existing state; here marks a trapped condition.", "example_in_sentence": "갇힌 가족"}], "analysis": []}, {"text": "여성 두 명과 아이 세 명이 불 속에서 나오지 못하고 있었어요.", "translation": "Two women and three children were unable to get out of the fire.", "vocab": [{"ko": "여성", "en": "woman, female", "note": "formal noun; paired with 아이 (child)"}, {"ko": "아이", "en": "child", "note": "noun; counted with 명"}, {"ko": "나오다", "en": "to come out, emerge", "note": "movement verb; negated with ~지 못하다"}], "grammar": [{"pattern": "~지 못하다 (inability/failure)", "exp": "Expresses inability or failure to complete an action; 'cannot' or 'was unable to'.", "example_in_sentence": "나오지 못하고 있었어요"}, {"pattern": "~고 있었어요 (past continuous)", "exp": "Describes an ongoing state or repeated action in the past; emphasizes duration.", "example_in_sentence": "나오지 못하고 있었어요"}], "analysis": []}, {"text": "청년은 다시 불타는 집 안으로 들어갔어요.", "translation": "The young man went back into the burning house again.", "vocab": [{"ko": "다시", "en": "again, once more", "note": "adverb; marks repetition"}, {"ko": "불타다", "en": "to burn, be on fire", "note": "verb; ~는 form modifies following noun"}, {"ko": "들어가다", "en": "to enter, go in", "note": "movement verb; direction marked with ~으로"}], "grammar": [{"pattern": "~는 (present participle modifier)", "exp": "Modifies a noun to describe an ongoing or habitual action; here describes the house as actively burning.", "example_in_sentence": "불타는 집"}], "analysis": []}, {"text": "그리고 가족 다섯 명을 모두 안전하게 구해냈어요.", "translation": "And he safely rescued all five family members.", "vocab": [{"ko": "안전하다", "en": "to be safe (안전하게 = safely)", "note": "adverb form of 안전하다; modifies the rescue action"}, {"ko": "구해내다", "en": "to rescue, save (completely)", "note": "compound verb; ~어내다 emphasizes completing the action fully"}, {"ko": "모두", "en": "all, everyone", "note": "adverb; emphasizes totality"}], "grammar": [], "analysis": []}, {"text": "많은 사람들이 이 용감한 청년을 칭찬하고 있어요.", "translation": "Many people are praising this brave young man.", "vocab": [{"ko": "많다", "en": "to be many; to be a lot", "note": "adjective; modifies 사람들"}, {"ko": "용감하다", "en": "to be brave; to be courageous", "note": "adjective; modifies 청년"}, {"ko": "칭찬하다", "en": "to praise, compliment", "note": "transitive verb; takes object with ~을/를"}], "grammar": [{"pattern": "~고 있다 (present continuous)", "exp": "Describes an action ongoing in the present; emphasizes the continuous or repeated nature.", "example_in_sentence": "칭찬하고 있어요"}], "analysis": []}]}$t$, qa_at = now()
 where article_id = 'mortntpdue4g' and md5(translation) = '36db6c3c3bcd89e897437cc34456a591';
update public.article_cache set translation = $t${"texts": ["The Anna's hummingbird is a small, beautiful bird. This bird's most special feature is its shimmering purple feathers.", "But there is a surprising fact. This purple color is not because of pigment. It appears purple because of the very small structures inside the feathers.", "On the feathers, there are layers so small that they cannot be seen with the naked eye. These layers act like mirrors and reflect light.", "So depending on the angle from which it is viewed, the color changes. This phenomenon is one of the mysterious things that can be seen in nature. So this kind of scientific principle was hidden in the hummingbird's beautiful color."], "sentences": [{"text": "안나 벌새(Anna's hummingbird)는 작고 아름다운 새예요.", "translation": "The Anna's hummingbird is a small, beautiful bird.", "vocab": [{"ko": "벌새", "en": "hummingbird", "note": ""}, {"ko": "아름답다", "en": "to be beautiful", "note": "vowel-irregular: 아름답+은 → 아름다운"}], "analysis": []}, {"text": "이 새의 가장 특별한 점은 반짝이는 보라색 깃털입니다.", "translation": "This bird's most special feature is its shimmering purple feathers.", "vocab": [{"ko": "특별하다", "en": "to be special", "note": ""}, {"ko": "반짝이다", "en": "to sparkle, shimmer", "note": ""}, {"ko": "깃털", "en": "feather", "note": ""}], "analysis": []}, {"text": "그런데 놀라운 사실이 있어요.", "translation": "But there is a surprising fact.", "vocab": [{"ko": "놀랍다", "en": "to be surprising", "note": "ㅂ-irregular: 놀랍+은 → 놀라운"}, {"ko": "사실", "en": "fact", "note": ""}], "analysis": []}, {"text": "이 보라색은 색소 때문이 아니에요.", "translation": "This purple color is not because of pigment.", "vocab": [{"ko": "보라색", "en": "purple (color)", "note": ""}, {"ko": "색소", "en": "pigment", "note": ""}], "analysis": [{"type": "grammar", "label": "~ 때문이다 / ~ 때문에", "exp": "때문 means 'because of'. 색소 때문이 아니에요 = it is not because of pigment.", "example_in_sentence": "색소 때문이 아니에요"}]}, {"text": "깃털 안에 있는 아주 작은 구조 때문에 보라색으로 보입니다.", "translation": "It appears purple because of the very small structures inside the feathers.", "vocab": [{"ko": "구조", "en": "structure", "note": ""}, {"ko": "보이다", "en": "to be seen, to appear", "note": "passive of 보다"}], "analysis": [{"type": "grammar", "label": "~ 때문에 (because of N)", "exp": "because of (noun). 구조 → 구조 때문에 = \"because of the structure\".", "example_in_sentence": "구조 때문에"}, {"type": "grammar", "label": "~(으)로 보이다", "exp": "Means 'to look like / appear as ~'. 보라색으로 보입니다 = it looks purple.", "example_in_sentence": "보라색으로 보입니다"}]}, {"text": "깃털에는 눈에 보이지 않을 정도로 작은 층들이 있어요.", "translation": "On the feathers, there are layers so small that they cannot be seen with the naked eye.", "vocab": [{"ko": "층", "en": "layer, floor", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 정도로", "exp": "Means 'so ~ that' / 'to the point of ~'. 보이지 않다 → 보이지 않을 정도로 작은 = so small that you can't see them.", "example_in_sentence": "보이지 않을 정도로 작은"}, {"type": "grammar", "label": "~지 않다", "exp": "long-form negation. 보이다 → 보이지 않다 = \"to not be visible\". 보이지 않을 = \"that is not visible (modifier)\".", "example_in_sentence": "보이지 않을"}]}, {"text": "이 층들이 거울처럼 작용해서 빛을 반사합니다.", "translation": "These layers act like mirrors and reflect light.", "vocab": [{"ko": "거울", "en": "mirror", "note": ""}, {"ko": "작용하다", "en": "to act, to function", "note": ""}, {"ko": "빛", "en": "light", "note": ""}, {"ko": "반사하다", "en": "to reflect", "note": ""}], "analysis": [{"type": "grammar", "label": "~아/어서 (cause / sequence)", "exp": "reason or sequence connector. 작용하다 → 작용해서 = \"because (it) acts / and then acts\". 하다 contracts to 해서.", "example_in_sentence": "작용해서"}, {"type": "expression", "label": "~처럼", "exp": "Particle meaning 'like / as'. 거울 → 거울처럼 = like a mirror.", "example_in_sentence": "거울처럼"}]}, {"text": "그래서 보는 각도에 따라 색깔이 달라져요.", "translation": "So depending on the angle from which it is viewed, the color changes.", "vocab": [{"ko": "각도", "en": "angle", "note": ""}, {"ko": "달라지다", "en": "to change; to become different", "note": "르-irregular: 다르+아 → 달라"}, {"ko": "색깔", "en": "color", "note": ""}], "analysis": [{"type": "grammar", "label": "~에 따라(서) (depending on / as)", "exp": "variation / dependence. 각도 → 각도에 따라 = \"depending on the angle / according to the angle\".", "example_in_sentence": "각도에 따라"}, {"type": "grammar", "label": "르 불규칙 (르 → ㄹㄹ)", "exp": "르-irregular: 다르다 → 달라(요), 모르다 → 몰라, 부르다 → 불러. Here 다르다 + 아져요 → 달라져요 = \"becomes different\".", "example_in_sentence": "달라져요"}, {"type": "expression", "label": "~아/어지다 (become)", "exp": "change-of-state suffix. 다르다 → 달라지다 = \"to become different / to change\". Marks a transition into a state.", "example_in_sentence": "달라져요"}]}, {"text": "이런 현상은 자연에서 볼 수 있는 신기한 일 중 하나입니다.", "translation": "This phenomenon is one of the amazing things you can see in nature.", "vocab": [{"ko": "현상", "en": "phenomenon", "note": ""}, {"ko": "자연", "en": "nature", "note": ""}, {"ko": "신기하다", "en": "to be amazing, mysterious", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 수 있다", "exp": "Means 'can'. 보다 → 볼 수 있는 = that (you) can see.", "example_in_sentence": "볼 수 있는"}, {"type": "grammar", "label": "~ 중 하나", "exp": "Means 'one of ~'. 신기한 일 중 하나 = one of the amazing things.", "example_in_sentence": "신기한 일 중 하나"}]}, {"text": "벌새의 아름다운 색깔에는 이런 과학적 원리가 숨어 있었네요.", "translation": "So this kind of scientific principle was hidden in the hummingbird's beautiful color.", "vocab": [{"ko": "과학적", "en": "scientific", "note": ""}, {"ko": "원리", "en": "principle", "note": ""}, {"ko": "숨다", "en": "to hide", "note": ""}], "analysis": [{"type": "grammar", "label": "~네요 (discovery)", "exp": "realization / mild surprise. 있다 → 있었네요 = \"oh, (it) was\". Marks discovery: \"so (it) was, huh\".", "example_in_sentence": "있었네요"}, {"type": "grammar", "label": "~아/어 있다 (resultant state)", "exp": "resulting state from a completed action. 숨다 → 숨어 있다 = \"to remain hidden\". 숨어 있었다 = \"was (kept) hidden\".", "example_in_sentence": "숨어 있었네요"}, {"type": "grammar", "label": "~적 (-ic / -al adjective suffix)", "exp": "Sino-Korean noun → adjective. 과학 → 과학적 = \"scientific\". Forms: 적이다 / 적인 N / 적으로.", "example_in_sentence": "과학적 원리"}]}], "version": "s5"}$t$, qa_at = now()
 where article_id = 'mot918spdjod' and md5(translation) = 'a395cdd4920e10e814ba96aa38d563e6';
update public.article_cache set translation = $t${"texts": ["American singer Sabrina Carpenter has become a hot topic on the internet. People were surprised because her appearance without makeup and with makeup looked so different.", "Internet users compared the two photos side by side. Some people called Carpenter a \"catfish.\" Catfish refers to a person who hides their true appearance.", "However, many fans are supporting Carpenter. They say that wearing makeup is a normal thing that all women do. They believe that musical talent is more important than appearance.", "This kind of controversy happens frequently to celebrities. In the age of social media, a single photo can become a big topic of discussion."], "sentences": [{"text": "미국 가수 사브리나 카펜터가 인터넷에서 화제가 되고 있어요.", "translation": "American singer Sabrina Carpenter has become a hot topic on the internet.", "vocab": [{"ko": "가수", "en": "singer", "note": "Common noun for profession"}, {"ko": "화제", "en": "hot topic; topic of discussion", "note": "Used with 되다 to mean 'become a topic'"}], "grammar": [{"pattern": "~고 있어요", "exp": "Indicates an ongoing action or state in present time.", "example_in_sentence": "화제가 되고 있어요"}], "analysis": []}, {"text": "메이크업을 하지 않은 모습과 메이크업을 한 모습이 너무 달라서 사람들이 놀랐어요.", "translation": "People were surprised because her appearance without makeup and with makeup looked so different.", "vocab": [{"ko": "메이크업", "en": "makeup", "note": "Loanword; 하다 verb for 'to apply makeup'"}, {"ko": "모습", "en": "appearance; look", "note": "Refers to visual appearance or how someone looks"}, {"ko": "놀라다", "en": "to be surprised", "note": "Passive emotion; conjugates to 놀랐어요 in past"}], "grammar": [{"pattern": "~어서", "exp": "Expresses cause or reason; 'because' or 'so'.", "example_in_sentence": "달라서 사람들이 놀랐어요"}], "analysis": []}, {"text": "인터넷 사용자들이 두 사진을 나란히 놓고 비교했어요.", "translation": "Internet users compared the two photos side by side.", "vocab": [{"ko": "사용자", "en": "user", "note": "Formal term; 인터넷 사용자 = internet user"}, {"ko": "나란히", "en": "side by side; in a line", "note": "Adverb describing arrangement of objects"}, {"ko": "비교하다", "en": "to compare", "note": "Common academic verb; pairs with 놓고 for 'place side by side and compare'"}], "grammar": [{"pattern": "~고", "exp": "Connects two actions; 'place and then compare'.", "example_in_sentence": "나란히 놓고 비교했어요"}], "analysis": []}, {"text": "어떤 사람들은 카펜터가 '캣피시'라고 말했어요.", "translation": "Some people called Carpenter a \"catfish.\"", "vocab": [{"ko": "어떤", "en": "some; certain", "note": "Modifier meaning 'certain people' or 'some people'"}], "grammar": [], "analysis": []}, {"text": "캣피시는 자신의 진짜 모습을 숨기는 사람을 뜻해요.", "translation": "Catfish refers to a person who hides their true appearance.", "vocab": [{"ko": "뜻하다", "en": "to mean; to refer to", "note": "Used with noun subjects: 'X means/refers to Y'"}, {"ko": "숨기다", "en": "to hide; to conceal", "note": "Transitive verb; 진짜 모습을 숨기다 = hide one's true appearance"}], "grammar": [{"pattern": "~는 사람", "exp": "Relative clause modifying 사람; the present tense form ~는 describes the noun.", "example_in_sentence": "모습을 숨기는 사람"}], "analysis": []}, {"text": "하지만 많은 팬들은 카펜터를 응원하고 있어요.", "translation": "However, many fans are supporting Carpenter.", "vocab": [{"ko": "하지만", "en": "however; but", "note": "Formal conjunction introducing contrast"}, {"ko": "응원하다", "en": "to support; to cheer for", "note": "Common verb for backing a person or team"}], "grammar": [{"pattern": "~고 있어요", "exp": "Indicates ongoing action in present.", "example_in_sentence": "응원하고 있어요"}], "analysis": []}, {"text": "메이크업은 모든 여성이 하는 일반적인 일이라고 말해요.", "translation": "They say that wearing makeup is a normal thing that all women do.", "vocab": [{"ko": "일반적", "en": "general; common; ordinary", "note": "Adjective; 일반적인 일 = a common/normal thing"}], "grammar": [{"pattern": "~다고 말하다", "exp": "Reports direct speech; 'say that...'", "example_in_sentence": "일반적인 일이라고 말해요"}], "analysis": []}, {"text": "외모보다는 음악 실력이 더 중요하다고 생각해요.", "translation": "They believe that musical talent is more important than appearance.", "vocab": [{"ko": "음악 실력", "en": "musical talent; musical skill", "note": "Compound: 음악 (music) + 실력 (skill/ability)"}, {"ko": "중요하다", "en": "to be important", "note": "Adjective; used with 더 for comparison"}], "grammar": [{"pattern": "~보다는", "exp": "Comparison particle; 'more than' or 'rather than'.", "example_in_sentence": "외모보다는 음악 실력이 더 중요하다"}], "analysis": []}, {"text": "이런 논란은 연예인들에게 자주 일어나요.", "translation": "This kind of controversy happens frequently to celebrities.", "vocab": [{"ko": "논란", "en": "controversy; dispute", "note": "Noun for a heated public debate"}, {"ko": "연예인", "en": "celebrity; entertainer", "note": "Formal term for public figures in entertainment"}, {"ko": "자주", "en": "often; frequently", "note": "Adverb modifying frequency"}], "grammar": [{"pattern": "~에게", "exp": "Marks the recipient or target of an action; 'to/for'.", "example_in_sentence": "연예인들에게 자주 일어나요"}], "analysis": []}, {"text": "소셜 미디어 시대에는 사진 한 장으로 큰 화제가 될 수 있어요.", "translation": "In the age of social media, a single photo can become a big topic of discussion.", "vocab": [{"ko": "소셜 미디어", "en": "social media", "note": "Loanword; modern technology term"}, {"ko": "시대", "en": "age; era; period", "note": "Noun for a historical or cultural period"}, {"ko": "한 장", "en": "one; a single (counter for flat objects)", "note": "Counter word: 장 for sheets, pages, photos"}], "grammar": [{"pattern": "~ㄹ 수 있어요", "exp": "Expresses possibility; 'can' or 'is able to'.", "example_in_sentence": "큰 화제가 될 수 있어요"}], "analysis": []}]}$t$, qa_at = now()
 where article_id = 'mot9s42wj4zd' and md5(translation) = '8d27fbda38126f46d793021f8d5da14a';
update public.article_cache set translation = $t${"texts": ["A very special animal was discovered in Kenya. It is the only white giraffe in the world.", "Unlike regular giraffes, this giraffe's entire body is white. Usually giraffes have brown spots, but this giraffe is completely white.", "Scientists say this giraffe is very rare. There is only one giraffe of this color on Earth.", "The Kenyan government is protecting this special giraffe. Many people are visiting Kenya to see this amazing animal."], "sentences": [{"text": "케냐에서 매우 특별한 동물이 발견됐어요.", "translation": "A very special animal was discovered in Kenya.", "vocab": [{"ko": "케냐", "en": "Kenya"}, {"ko": "매우", "en": "very"}, {"ko": "특별하다", "en": "to be special"}, {"ko": "발견되다", "en": "to be discovered"}], "analysis": [{"type": "grammar", "label": "~에서", "exp": "Locative particle marking the place where an action occurs. 케냐 + 에서 = in/at Kenya.", "example_in_sentence": "케냐에서"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense polite ending. 발견되다 → 발견되었어요 → 발견됐어요 (was discovered).", "example_in_sentence": "발견됐어요"}]}, {"text": "전 세계에서 유일한 흰색 기린이에요.", "translation": "It is the only white giraffe in the entire world.", "vocab": [{"ko": "전 세계", "en": "entire world"}, {"ko": "유일하다", "en": "to be only/unique"}, {"ko": "흰색", "en": "white color"}, {"ko": "기린", "en": "giraffe"}], "analysis": [{"type": "grammar", "label": "~에서", "exp": "Locative particle marking scope or range. 전 세계 + 에서 = in/among the entire world.", "example_in_sentence": "전 세계에서"}, {"type": "grammar", "label": "~이에요", "exp": "Polite 'to be' after a noun ending in a consonant. 기린 + 이에요 = is a giraffe.", "example_in_sentence": "기린이에요"}]}, {"text": "이 기린은 일반 기린과 다르게 온몸이 하얀색이에요.", "translation": "Unlike ordinary giraffes, this giraffe's whole body is white.", "vocab": [{"ko": "일반", "en": "ordinary/general"}, {"ko": "다르다", "en": "to be different"}, {"ko": "온몸", "en": "whole body"}, {"ko": "하얀색", "en": "white color"}], "analysis": [{"type": "grammar", "label": "~와/과 다르게", "exp": "Means 'unlike' or 'differently from'. 일반 기린과 다르게 = unlike ordinary giraffes.", "example_in_sentence": "일반 기린과 다르게"}, {"type": "grammar", "label": "~게", "exp": "Adverbializer turning adjectives into manner adverbs. 다르다 → 다르게 = differently.", "example_in_sentence": "다르게"}]}, {"text": "보통 기린은 갈색 점무늬가 있지만 이 기린은 완전히 흰색이에요.", "translation": "Ordinary giraffes have brown spots, but this giraffe is completely white.", "vocab": [{"ko": "보통", "en": "ordinary/usually"}, {"ko": "갈색", "en": "brown color"}, {"ko": "점무늬", "en": "spot/pattern"}, {"ko": "완전히", "en": "completely"}], "analysis": [{"type": "grammar", "label": "~지만", "exp": "Connective ending expressing contrast or concession between two clauses. 있지만 = 'have (but)'. Joins main clauses.", "example_in_sentence": "있지만"}, {"type": "grammar", "label": "~이에요", "exp": "Present copula. 흰색 + 이에요 = is white color.", "example_in_sentence": "흰색이에요"}]}, {"text": "과학자들은 이 기린이 매우 귀하다고 말해요.", "translation": "Scientists say that this giraffe is very rare.", "vocab": [{"ko": "과학자", "en": "scientist"}, {"ko": "귀하다", "en": "to be rare/precious"}, {"ko": "말하다", "en": "to say"}], "analysis": [{"type": "grammar", "label": "~다고 말하다", "exp": "Reports what someone says. 귀하다 → 귀하다고 말해요 (they say that it is rare).", "example_in_sentence": "귀하다고 말해요"}, {"type": "grammar", "label": "~어요", "exp": "Present tense ending for polite/spoken style. 말하다 → 말해요.", "example_in_sentence": "말해요"}]}, {"text": "이런 색깔의 기린은 지구상에 단 한 마리밖에 없어요.", "translation": "There is only one giraffe with this color on Earth.", "vocab": [{"ko": "색깔", "en": "color"}, {"ko": "지구상", "en": "on Earth"}, {"ko": "단", "en": "only/merely"}, {"ko": "마리", "en": "counter for animals"}], "analysis": [{"type": "grammar", "label": "~의", "exp": "Possessive/genitive particle marking attribution or relationship. 색깔 + 의 = 'of color' or 'with color'.", "example_in_sentence": "색깔의"}, {"type": "grammar", "label": "~밖에 없다", "exp": "Means 'only'. 밖에 is always followed by a negative word. 한 마리밖에 없어요 = there is only one.", "example_in_sentence": "한 마리밖에 없어요"}]}, {"text": "케냐 정부는 이 특별한 기린을 보호하고 있어요.", "translation": "The Kenyan government is protecting this special giraffe.", "vocab": [{"ko": "정부", "en": "government"}, {"ko": "보호하다", "en": "to protect"}], "analysis": [{"type": "grammar", "label": "~고 있다", "exp": "Progressive/continuous aspect. 보호하다 + ~고 있어요 = 'is protecting (ongoing action)'. Shows action in progress.", "example_in_sentence": "보호하고 있어요"}]}, {"text": "많은 사람들이 이 신기한 동물을 보기 위해 케냐를 방문하고 있어요.", "translation": "Many people are visiting Kenya to see this amazing animal.", "vocab": [{"ko": "많다", "en": "to be many"}, {"ko": "사람", "en": "person/people"}, {"ko": "신기하다", "en": "to be amazing/interesting"}, {"ko": "보다", "en": "to see"}], "analysis": [{"type": "grammar", "label": "~기 위해", "exp": "Shows purpose: 'in order to'. 보다 → 보기 위해 (in order to see).", "example_in_sentence": "보기 위해"}, {"type": "grammar", "label": "~고 있다", "exp": "Progressive aspect. 방문하다 + ~고 있어요 = 'are visiting (ongoing action)'.", "example_in_sentence": "방문하고 있어요"}]}], "version": "s6"}$t$, qa_at = now()
