update public.article_cache set translation = $t${"texts": ["The Wikimedia Foundation announced that it will shut down Wikinews. Wikinews was an online news site that operated for 21 years.", "The foundation said it will close Wikinews in all languages on March 30th. It cited the difficulty of continuing the site for a long time as the reason.", "Wikinews was a site where anyone could write news. However, recently the number of users has decreased significantly.", "Since this is a decision by the Wikimedia Foundation, which is famous for Wikipedia, many people are showing interest in it."], "sentences": [{"text": "위키미디어 재단이 위키뉴스(Wikinews)를 닫는다고 발표했어요.", "translation": "The Wikimedia Foundation announced that it will shut down Wikinews.", "vocab": [{"ko": "위키미디어 재단", "en": "Wikimedia Foundation", "note": "Proper noun; the organization behind Wikipedia and Wikinews"}, {"ko": "닫다", "en": "to close, shut down", "note": "Used for closing websites, buildings, or businesses"}, {"ko": "발표하다", "en": "to announce", "note": "Official announcement of news or information"}], "grammar": [{"pattern": "~(으)ㄴ다고 발표하다", "exp": "Expresses announcing a future action or plan using reported speech with ~(으)ㄴ다 form inside a quotation", "example_in_sentence": "닫는다고 발표했어요"}], "analysis": []}, {"text": "위키뉴스는 21년 동안 운영된 온라인 뉴스 사이트예요.", "translation": "Wikinews was an online news site that operated for 21 years.", "vocab": [{"ko": "운영되다", "en": "to be operated, run", "note": "Passive form; describes how a business or service functions over time"}, {"ko": "온라인", "en": "online", "note": "Internet-based; borrowed word from English"}], "grammar": [], "analysis": []}, {"text": "재단은 3월 30일에 모든 언어의 위키뉴스를 닫겠다고 말했어요.", "translation": "The foundation said it will close Wikinews in all languages on March 30th.", "vocab": [{"ko": "닫다", "en": "to close, shut down", "note": "Same as sentence 1; repeated for consistency"}, {"ko": "말하다", "en": "to say, tell", "note": "Used here in reported speech context"}], "grammar": [{"pattern": "~(으)ㄹ 것이다 / ~겠다", "exp": "Expresses future intention or plan, here in reported speech form (~겠다고 말했어요)", "example_in_sentence": "닫겠다고 말했어요"}], "analysis": []}, {"text": "오랫동안 계속하기 어렵다는 이유를 들었어요.", "translation": "It cited the difficulty of continuing the site for a long time as the reason.", "vocab": [{"ko": "들다", "en": "to cite, raise (a reason)", "note": "~을/를 들다 = to bring up or mention something as evidence or reason"}, {"ko": "계속하다", "en": "to continue", "note": "To keep doing or maintain something"}], "grammar": [{"pattern": "~기 어렵다", "exp": "Expresses that an action (in ~기 form) is difficult to do", "example_in_sentence": "계속하기 어렵다"}], "analysis": []}, {"text": "위키뉴스는 누구나 뉴스를 쓸 수 있는 사이트였어요.", "translation": "Wikinews was a site where anyone could write news.", "vocab": [{"ko": "누구나", "en": "anyone, everyone", "note": "Universal pronoun; anyone at all can do the action"}, {"ko": "쓰다", "en": "to write", "note": "Write text, articles, or documents"}], "grammar": [], "analysis": []}, {"text": "하지만 최근에는 사용하는 사람이 많이 줄었어요.", "translation": "However, recently the number of users has decreased significantly.", "vocab": [{"ko": "사용하다", "en": "to use", "note": "Use a tool, service, or website"}, {"ko": "줄다", "en": "to decrease, diminish", "note": "Quantity or number becomes smaller"}], "grammar": [{"pattern": "~고 있다", "exp": "Describes a state or ongoing situation (past state continuing to present)", "example_in_sentence": "줄었어요 (past state); with context, shows a change over time"}], "analysis": []}, {"text": "위키백과(Wikipedia)로 유명한 위키미디어 재단의 결정이어서 많은 사람들이 관심을 보이고 있어요.", "translation": "Since this is a decision by the Wikimedia Foundation, which is famous for Wikipedia, many people are showing interest in it.", "vocab": [{"ko": "유명하다", "en": "to be famous, well-known", "note": "Descriptive verb; something or someone is known widely"}, {"ko": "결정", "en": "decision", "note": "A choice or determination made"}, {"ko": "관심을 보이다", "en": "to show interest, demonstrate concern", "note": "Expression of attention or care toward something"}], "grammar": [{"pattern": "~(으)니까 / ~어서 (causal connector)", "exp": "Connects the reason (famous foundation's decision) to the result (many showing interest)", "example_in_sentence": "결정이어서 많은 사람들이 관심을 보이고 있어요"}], "analysis": []}]}$t$, qa_at = now()
