update public.article_cache set translation = $t${"texts": ["There is a beautiful road in Amsterdam, the Netherlands. This road is lined with plane trees stretching along its length.", "The branches of the trees meet above the road and create a natural tunnel. It looks like there's a green roof.", "When you walk along this road, you can feel the coolness under the shade of the trees. Many people come to see this beautiful scenery.", "In spring and summer, the green leaves are even more beautiful. In autumn, they change to yellow and orange, showing another kind of beauty."], "sentences": [{"text": "네덜란드 암스테르담에 아름다운 길이 있어요.", "translation": "There is a beautiful road in Amsterdam, the Netherlands.", "vocab": [{"ko": "아름답다", "en": "to be beautiful", "note": ""}, {"ko": "길", "en": "road, path", "note": ""}], "analysis": [{"type": "grammar", "label": "~에 (location/time)", "exp": "static location particle. indicates where something exists or takes place. 암스테르담 → 암스테르담에", "example_in_sentence": "암스테르담에"}, {"type": "expression", "label": "~이/가 있다", "exp": "Means 'there is'. 길 + 이 있어요 = there is a road.", "example_in_sentence": "길이 있어요"}]}, {"text": "이 길에는 플라타너스 나무들이 길게 늘어서 있어요.", "translation": "This road is lined with plane trees stretching along its length.", "vocab": [{"ko": "플라타너스", "en": "plane tree (sycamore)", "note": ""}, {"ko": "늘어서다", "en": "to stand in a row; to line up", "note": ""}], "analysis": [{"type": "grammar", "label": "~아/어 있다", "exp": "Shows a state that continues. 늘어서다 → 늘어서 있어요 (are standing in a row).", "example_in_sentence": "늘어서 있어요"}, {"type": "grammar", "label": "~게 (adverbializer suffix)", "exp": "forms adverbs from adjectives/verbs. 길다 (long) → 길게 (lengthily, along the length)", "example_in_sentence": "길게"}, {"type": "grammar", "label": "~이/가 (subject marker)", "exp": "subject particle. 나무들 → 나무들이", "example_in_sentence": "나무들이"}, {"type": "grammar", "label": "~에는", "exp": "에 (at/on) + 는 (topic). 이 길에는 = on this road.", "example_in_sentence": "길에는"}]}, {"text": "나무들의 가지가 길 위에서 만나서 자연 터널을 만들어요.", "translation": "The branches of the trees meet above the road and create a natural tunnel.", "vocab": [{"ko": "가지", "en": "branch", "note": ""}, {"ko": "만나다", "en": "to meet", "note": ""}, {"ko": "자연", "en": "nature, natural", "note": ""}, {"ko": "터널", "en": "tunnel", "note": ""}], "analysis": [{"type": "grammar", "label": "~을/를 (object marker)", "exp": "direct object particle. 터널 → 터널을", "example_in_sentence": "터널을"}, {"type": "grammar", "label": "~이/가 (subject marker)", "exp": "subject particle. 가지 → 가지가", "example_in_sentence": "가지가"}, {"type": "grammar", "label": "~에서 (location/source)", "exp": "location of action particle. indicates where an action occurs. 길 위 → 길 위에서 (above/on the road)", "example_in_sentence": "길 위에서"}, {"type": "grammar", "label": "~의 (possessive)", "exp": "possessive/attributive particle. 나무 → 나무들의 (of the trees)", "example_in_sentence": "나무들의"}, {"type": "grammar", "label": "~아/어서 (cause / sequence)", "exp": "connective suffix expressing sequence. 만나다 → 만나서 (meet and then create)", "example_in_sentence": "만나서"}]}, {"text": "마치 초록색 지붕이 있는 것 같아요.", "translation": "It looks like there's a green roof.", "vocab": [{"ko": "초록색", "en": "green (color)", "note": ""}, {"ko": "지붕", "en": "roof", "note": ""}], "analysis": [{"type": "grammar", "label": "~이/가 (subject marker)", "exp": "subject particle. 지붕 → 지붕이", "example_in_sentence": "지붕이"}, {"type": "grammar", "label": "~는 것 같다", "exp": "Means 'it seems like' or 'it looks like'. 있다 → 있는 것 같아요 (it looks like there is).", "example_in_sentence": "있는 것 같아요"}]}, {"text": "이 길을 걸으면 나무 그늘 아래에서 시원함을 느낄 수 있어요.", "translation": "When you walk along this road, you can feel the coolness under the shade of the trees.", "vocab": [{"ko": "걷다", "en": "to walk", "note": "ㄷ-irregular"}, {"ko": "그늘", "en": "shade", "note": ""}, {"ko": "시원함", "en": "coolness, freshness", "note": ""}, {"ko": "느끼다", "en": "to feel, sense", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 수 있다", "exp": "Means 'can'. 느끼다 → 느낄 수 있어요 (can feel).", "example_in_sentence": "느낄 수 있어요"}, {"type": "grammar", "label": "~(으)면 (if/when)", "exp": "conditional. 걷다 → 걸으면 (when/if walk). ㄷ-irregular stem 걷 → 걸", "example_in_sentence": "걸으면"}, {"type": "grammar", "label": "~을/를 (object marker)", "exp": "direct object particle. 시원함 → 시원함을", "example_in_sentence": "시원함을"}, {"type": "grammar", "label": "~에서 (location/source)", "exp": "location of action particle. 아래 → 아래에서 (under/from under)", "example_in_sentence": "아래에서"}]}, {"text": "많은 사람들이 이 아름다운 풍경을 보러 와요.", "translation": "Many people come to see this beautiful scenery.", "vocab": [{"ko": "많다", "en": "to be many", "note": ""}, {"ko": "사람", "en": "person", "note": ""}, {"ko": "풍경", "en": "scenery, landscape", "note": ""}, {"ko": "보다", "en": "to see, watch", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)러 (purpose with movement)", "exp": "purpose verb + movement verb. indicates 'come/go to do'. 보다 → 보러 와요 (come to see)", "example_in_sentence": "보러 와요"}, {"type": "grammar", "label": "ㅂ irregular + ~(으)ㄴ", "exp": "아름답다 → 아름다운 풍경 (beautiful scenery): ㅂ becomes 우 before the modifier.", "example_in_sentence": "아름다운 풍경"}, {"type": "grammar", "label": "~을/를 (object marker)", "exp": "direct object particle. 풍경 → 풍경을", "example_in_sentence": "풍경을"}, {"type": "grammar", "label": "~이/가 (subject marker)", "exp": "subject particle. 사람들 → 사람들이", "example_in_sentence": "사람들이"}, {"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Adjective form used before a noun. 많다 → 많은 사람들 (many people).", "example_in_sentence": "많은 사람들"}]}, {"text": "봄과 여름에는 초록색 잎이 더욱 예뻐요.", "translation": "In spring and summer, the green leaves are even more beautiful.", "vocab": [{"ko": "봄", "en": "spring (season)", "note": ""}, {"ko": "여름", "en": "summer", "note": ""}, {"ko": "잎", "en": "leaf", "note": ""}, {"ko": "예쁘다", "en": "to be pretty", "note": ""}], "analysis": [{"type": "grammar", "label": "~이/가 (subject marker)", "exp": "subject particle. 잎 → 잎이", "example_in_sentence": "잎이"}, {"type": "grammar", "label": "~에는", "exp": "에 (in) + 는 (topic). 봄과 여름에는 = in spring and summer.", "example_in_sentence": "봄과 여름에는"}, {"type": "grammar", "label": "~와/과", "exp": "Means 'and' between nouns. 봄 + 과 + 여름 = spring and summer.", "example_in_sentence": "봄과 여름"}, {"type": "expression", "label": "더욱 + adjective", "exp": "더욱 means 'even more'. 더욱 예뻐요 = are even prettier.", "example_in_sentence": "더욱 예뻐요"}]}, {"text": "가을에는 노란색과 주황색으로 변해서 또 다른 아름다움을 보여줘요.", "translation": "In autumn, they change to yellow and orange, showing another kind of beauty.", "vocab": [{"ko": "가을", "en": "autumn, fall", "note": ""}, {"ko": "노란색", "en": "yellow", "note": ""}, {"ko": "주황색", "en": "orange (color)", "note": ""}, {"ko": "변하다", "en": "to change, transform", "note": ""}], "analysis": [{"type": "grammar", "label": "~아/어서 (cause / sequence)", "exp": "connective suffix expressing sequence. 변하다 → 변해서 (change and then show)", "example_in_sentence": "변해서"}, {"type": "grammar", "label": "~을/를 (object marker)", "exp": "direct object particle. 아름다움 → 아름다움을", "example_in_sentence": "아름다움을"}, {"type": "grammar", "label": "또 다른", "exp": "Means 'another' or 'a different'. 또 다른 아름다움 = another kind of beauty.", "example_in_sentence": "또 다른 아름다움"}, {"type": "grammar", "label": "~과/와 (with/and)", "exp": "formal conjunction particle joining nouns. 노란색 + 과 + 주황색 (yellow and orange)", "example_in_sentence": "노란색과 주황색으로"}, {"type": "expression", "label": "~(으)로 변하다", "exp": "Means 'to change into'. 주황색으로 변해서 = changing to orange.", "example_in_sentence": "주황색으로 변해서"}, {"type": "expression", "label": "~을 보여주다", "exp": "to show/display something. give-benefactive verb. 아름다움을 보여줘요 = show beauty (to viewer)", "example_in_sentence": "아름다움을 보여줘요"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mozuwq3nnjzm' and md5(translation) = 'a8d655483ef5202269431f2719e58f14';
update public.article_cache set translation = $t${"texts": ["One of the most extreme forms of parental care exists in nature: mothers being consumed by their own offspring.", "This behavior is called matriphagy and has been observed in some species of insects, worms, arachnids, and amphibians.", "Mothers provide their own bodies as the first meal for their young, thereby increasing their offspring's chances of survival.", "This sacrificial behavior is a result of natural selection, as the survival of multiple offspring is more advantageous for species preservation than the survival of the individual mother."], "sentences": [{"text": "자연계에서 가장 극단적인 자식 돌봄 방법 중 하나가 있어요.", "translation": "One of the most extreme forms of parental care exists in nature.", "vocab": [{"ko": "자연계", "en": "natural world", "note": "the world of nature"}, {"ko": "극단적이다", "en": "to be extreme", "note": "very severe or intense"}, {"ko": "돌봄", "en": "care", "note": "taking care of someone"}], "analysis": [{"type": "grammar", "label": "~중 하나", "exp": "one of/among. Used to indicate one item from a group. 방법 (method) → 방법 중 하나 (one of the methods)", "example_in_sentence": "방법 중 하나가"}]}, {"text": "바로 어미가 자신의 새끼들에게 먹히는 것입니다.", "translation": "It is the mother being eaten by her own young.", "vocab": [{"ko": "어미", "en": "mother animal", "note": "female parent of animals"}, {"ko": "새끼", "en": "young animal", "note": "baby animal or offspring"}, {"ko": "먹히다", "en": "to be eaten", "note": "passive form of 먹다"}], "analysis": [{"type": "grammar", "label": "~는 것이다", "exp": "Explains what something is: 'it is (the act of)…'. 먹히다 → 먹히는 것입니다 (it is being eaten).", "example_in_sentence": "먹히는 것입니다"}]}, {"text": "이런 행동을 모식(母食)이라고 불러요.", "translation": "This behavior is called matriphagy.", "vocab": [{"ko": "행동", "en": "behavior", "note": "action or conduct"}, {"ko": "모식", "en": "matriphagy", "note": "母 (mother) + 食 (eating)"}, {"ko": "부르다", "en": "to call", "note": "to name or refer to as"}], "analysis": [{"type": "grammar", "label": "~(이)라고 부르다", "exp": "to call/name something. 모식 → 모식이라고 → 모식이라고 불러요", "example_in_sentence": "모식이라고 불러요"}]}, {"text": "곤충, 벌레, 거미류, 양서류의 일부 종에서 관찰됩니다.", "translation": "It has been observed in some species of insects, worms, arachnids, and amphibians.", "vocab": [{"ko": "곤충", "en": "insect", "note": "small six-legged creatures"}, {"ko": "거미류", "en": "arachnids", "note": "spiders and related creatures"}, {"ko": "양서류", "en": "amphibians", "note": "animals that live both on land and water"}, {"ko": "관찰되다", "en": "to be observed", "note": "to be watched or noticed"}], "analysis": []}, {"text": "어미는 자신의 몸을 새끼들의 첫 번째 먹이로 제공해요.", "translation": "Mothers provide their own bodies as the first meal for their young.", "vocab": [{"ko": "몸", "en": "body", "note": "physical body"}, {"ko": "먹이", "en": "food/prey", "note": "food for animals"}, {"ko": "제공하다", "en": "to provide", "note": "to supply or offer"}], "analysis": [{"type": "grammar", "label": "~(으)로", "exp": "particle indicating method, means, or role. 먹이 + 로 → 먹이로 (as food)", "example_in_sentence": "먹이로 제공해요"}]}, {"text": "이를 통해 새끼들이 생존할 확률을 높입니다.", "translation": "Through this, they increase their offspring's chances of survival.", "vocab": [{"ko": "생존하다", "en": "to survive", "note": "to stay alive"}, {"ko": "확률", "en": "probability/chance", "note": "likelihood of something happening"}, {"ko": "높이다", "en": "to raise/increase", "note": "to make higher"}], "analysis": [{"type": "expression", "label": "~을/를 통해", "exp": "Means 'through' or 'by means of'. 이를 통해 = through this.", "example_in_sentence": "이를 통해"}]}, {"text": "이런 희생적 행동은 자연 선택의 결과예요.", "translation": "This sacrificial behavior is a result of natural selection.", "vocab": [{"ko": "희생적이다", "en": "to be sacrificial", "note": "involving personal sacrifice"}, {"ko": "선택", "en": "selection/choice", "note": "act of choosing"}, {"ko": "결과", "en": "result", "note": "outcome or consequence"}], "analysis": []}, {"text": "어미 개체보다 여러 새끼들이 살아남는 것이 종족 보존에 더 유리하기 때문입니다.", "translation": "This is because the survival of multiple offspring is more advantageous for species preservation than the survival of the individual mother.", "vocab": [{"ko": "개체", "en": "individual", "note": "single organism"}, {"ko": "살아남다", "en": "to survive", "note": "to remain alive"}, {"ko": "종족", "en": "species", "note": "group of similar organisms"}, {"ko": "보존", "en": "preservation", "note": "keeping something safe"}], "analysis": [{"type": "grammar", "label": "~보다", "exp": "particle for comparison meaning 'than' or 'compared to'. 개체 + 보다 → 개체보다 (than the individual)", "example_in_sentence": "어미 개체보다"}, {"type": "grammar", "label": "~기 때문이다", "exp": "because/due to. Indicates reason or cause. 유리하다 → 유리하기 → 유리하기 때문입니다", "example_in_sentence": "유리하기 때문입니다"}]}], "version": "s1"}$t$, qa_at = now()
