update public.article_cache set translation = $t${"texts": ["Dragonflies are insects that have excellent hunting abilities. One dragonfly can catch and eat more than 100 mosquitoes in a day. They hunt not only mosquitoes but also many other small insects.", "Dragonflies show unique flying abilities. Unlike most other insects, they can also fly backwards. Thanks to this special flying technique, they can easily catch prey in the air.", "A dragonfly's field of vision is close to almost 360 degrees. Thanks to this wide field of vision, they can quickly discover dangers or prey in their surroundings. Large compound eyes create this excellent visual ability.", "Dragonfly wings suppress bacterial growth because of their natural structure. The special structure of the wing surface plays a role in preventing bacteria from growing. Furthermore, dragonflies are truly beautiful insects."], "sentences": [{"text": "잠자리는 뛰어난 사냥 능력을 가진 곤충이에요.", "translation": "Dragonflies are insects that have excellent hunting abilities.", "vocab": [{"ko": "잠자리", "en": "dragonfly", "note": ""}, {"ko": "뛰어나다", "en": "to be excellent/outstanding", "note": ""}, {"ko": "사냥", "en": "hunting", "note": ""}, {"ko": "곤충", "en": "insect", "note": ""}], "analysis": []}, {"text": "한 마리가 하루에 모기를 100마리 이상 잡아먹을 수 있어요.", "translation": "One dragonfly can catch and eat more than 100 mosquitoes in a day.", "vocab": [{"ko": "마리", "en": "counter for animals", "note": ""}, {"ko": "모기", "en": "mosquito", "note": ""}, {"ko": "잡아먹다", "en": "to catch and eat", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 수 있다/없다 (ability/possibility)", "exp": "ability or possibility. 잡아먹다 → 잡아먹을 수 있다 → 잡아먹을 수 있어요", "example_in_sentence": "잡아먹을 수 있어요"}]}, {"text": "이들은 모기뿐만 아니라 다른 작은 벌레들도 많이 사냥해요.", "translation": "They hunt not only mosquitoes but also many other small insects.", "vocab": [{"ko": "벌레", "en": "bug/insect", "note": ""}], "analysis": [{"type": "grammar", "label": "~뿐만 아니라", "exp": "'not only N (but also)'. 모기뿐만 아니라 다른 벌레들도 = not only mosquitoes but also other bugs.", "example_in_sentence": "모기뿐만 아니라"}, {"type": "grammar", "label": "~도 (also)", "exp": "inclusive. 벌레들 → 벌레들도 = 'insects also'", "example_in_sentence": "벌레들도"}]}, {"text": "잠자리는 독특한 비행 능력을 보여줘요.", "translation": "Dragonflies show unique flying abilities.", "vocab": [{"ko": "독특하다", "en": "to be unique/distinctive", "note": ""}, {"ko": "비행", "en": "flight", "note": ""}, {"ko": "보여주다", "en": "to show", "note": ""}], "analysis": []}, {"text": "다른 대부분의 곤충과 달리 뒤로도 날 수 있어요.", "translation": "Unlike most other insects, they can also fly backwards.", "vocab": [{"ko": "대부분", "en": "most/majority", "note": ""}, {"ko": "달리", "en": "unlike", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 수 있다/없다 (ability/possibility)", "exp": "ability or possibility. 날다 → 날 수 있다 → 날 수 있어요", "example_in_sentence": "날 수 있어요"}, {"type": "grammar", "label": "~과/와 달리", "exp": "'unlike N'. 대부분의 곤충과 달리 = unlike most insects.", "example_in_sentence": "곤충과 달리"}, {"type": "grammar", "label": "~도 (also)", "exp": "inclusive. 뒤로 → 뒤로도 = 'backwards also'", "example_in_sentence": "뒤로도"}]}, {"text": "이런 특별한 비행 기술 덕분에 공중에서 먹이를 쉽게 잡을 수 있어요.", "translation": "Thanks to this special flying technique, they can easily catch prey in the air.", "vocab": [{"ko": "특별하다", "en": "to be special", "note": ""}, {"ko": "기술", "en": "technique/skill", "note": ""}, {"ko": "공중", "en": "air/sky", "note": ""}, {"ko": "먹이", "en": "prey/food", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 수 있다/없다 (ability/possibility)", "exp": "ability or possibility. 잡다 → 잡을 수 있다 → 잡을 수 있어요", "example_in_sentence": "잡을 수 있어요"}, {"type": "grammar", "label": "~게 (adverbializer suffix)", "exp": "forms adverbs from adjectives. 쉽다 → 쉽게 = 'easily'", "example_in_sentence": "쉽게"}, {"type": "grammar", "label": "~에서 (location/source)", "exp": "at/in (location of action). 공중 → 공중에서 = 'in the air'", "example_in_sentence": "공중에서"}]}, {"text": "잠자리의 시야는 거의 360도에 가까워요.", "translation": "A dragonfly's field of vision is nearly 360 degrees.", "vocab": [{"ko": "시야", "en": "field of vision", "note": ""}, {"ko": "가깝다", "en": "to be close", "note": ""}], "analysis": []}, {"text": "이 넓은 시야 덕분에 주변의 위험이나 먹이를 빠르게 발견할 수 있어요.", "translation": "Thanks to this wide field of vision, they can quickly discover dangers or prey in their surroundings.", "vocab": [{"ko": "넓다", "en": "to be wide", "note": ""}, {"ko": "주변", "en": "surroundings", "note": ""}, {"ko": "위험", "en": "danger", "note": ""}, {"ko": "발견하다", "en": "to discover", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 수 있다/없다 (ability/possibility)", "exp": "ability or possibility. 발견하다 → 발견할 수 있다 → 발견할 수 있어요", "example_in_sentence": "발견할 수 있어요"}, {"type": "grammar", "label": "~게 (adverbializer suffix)", "exp": "forms adverbs from adjectives. 빠르다 → 빠르게 = 'quickly'", "example_in_sentence": "빠르게"}, {"type": "grammar", "label": "~(이)나 (or / about / as much as)", "exp": "alternation. 위험 → 위험이나 = 'dangers or'", "example_in_sentence": "위험이나"}]}, {"text": "큰 복합눈이 이런 뛰어난 시각 능력을 만들어줘요.", "translation": "Large compound eyes create this excellent visual ability.", "vocab": [{"ko": "복합눈", "en": "compound eye", "note": ""}, {"ko": "시각", "en": "vision/sight", "note": ""}, {"ko": "만들어주다", "en": "to create/make", "note": ""}], "analysis": []}, {"text": "잠자리 날개는 자연적인 구조 때문에 세균의 성장을 억제해요.", "translation": "Dragonfly wings suppress bacterial growth because of their natural structure.", "vocab": [{"ko": "날개", "en": "wing", "note": ""}, {"ko": "구조", "en": "structure", "note": ""}, {"ko": "세균", "en": "bacteria", "note": ""}, {"ko": "억제하다", "en": "to suppress", "note": ""}], "analysis": [{"type": "grammar", "label": "~ 때문에 (because of N)", "exp": "because of (noun). 구조 → 구조 때문에 = 'because of the structure'", "example_in_sentence": "구조 때문에"}, {"type": "grammar", "label": "~적 (-ic / -al adjective suffix)", "exp": "Sino-Korean noun → adjective. 자연 → 자연적인 = 'natural'", "example_in_sentence": "자연적인"}]}, {"text": "날개 표면의 특별한 구조가 세균이 자라지 못하게 막는 역할을 해요.", "translation": "The special structure of the wing surface plays a role in preventing bacteria from growing.", "vocab": [{"ko": "표면", "en": "surface", "note": ""}, {"ko": "자라다", "en": "to grow", "note": ""}, {"ko": "막다", "en": "to prevent/block", "note": ""}, {"ko": "역할", "en": "role", "note": ""}], "analysis": [{"type": "grammar", "label": "~지 못하다", "exp": "long-form inability. 자라다 → 자라지 못하다 = 'cannot grow'", "example_in_sentence": "자라지 못하게"}, {"type": "grammar", "label": "~지 못하게 막다", "exp": "'to stop something from V-ing'. 자라다 → 자라지 못하게 막다 (to keep it from growing).", "example_in_sentence": "자라지 못하게 막는"}]}, {"text": "또한 잠자리는 정말 아름다운 곤충이에요.", "translation": "Furthermore, dragonflies are truly beautiful insects.", "vocab": [{"ko": "또한", "en": "furthermore/also", "note": ""}, {"ko": "아름답다", "en": "to be beautiful", "note": ""}], "analysis": []}], "version": "s6"}$t$, qa_at = now()
