update public.article_cache set translation = $t${"texts": ["The Mona Lisa is the most famous painting in the world. However, for a long time it was not known who the woman in this painting was.", "In 2005, a German researcher made an important discovery. He found a handwritten memo in the margin of an old book.", "In this memo, it was written that Leonardo da Vinci was painting a portrait of Lisa del Giocondo in 1503. This memo was confirmed to be genuine.", "In this way, it was finally discovered who the Mona Lisa is. Lisa del Giocondo was the wife of an Italian merchant."], "sentences": [{"text": "모나리자는 세계에서 가장 유명한 그림이에요.", "translation": "The Mona Lisa is the most famous painting in the world.", "vocab": [{"ko": "세계", "en": "world", "note": "noun; 세계에서 = 'in the world'"}, {"ko": "유명하다", "en": "to be famous", "note": "adjective; 유명한 is the modifier form"}, {"ko": "그림", "en": "painting / drawing / picture", "note": "noun"}], "analysis": [{"type": "grammar", "label": "~은/는 (topic marker)", "exp": "Topic particle. 모나리자 + 는 → 모나리자는 ('as for the Mona Lisa'). Used because 모나리자 ends in a vowel.", "example_in_sentence": "모나리자는"}, {"type": "grammar", "label": "~에서 (location/source)", "exp": "Location-of-action particle. 세계 + 에서 → 세계에서 ('in the world').", "example_in_sentence": "세계에서"}]}, {"text": "하지만 이 그림 속 여성이 누구인지는 오랫동안 알려지지 않았어요.", "translation": "However, for a long time it was not known who the woman in this painting was.", "vocab": [{"ko": "여성", "en": "woman / female", "note": "noun; formal/neutral term"}, {"ko": "오랫동안", "en": "for a long time", "note": "adverb; 오래 + 동안 combined"}, {"ko": "알려지다", "en": "to become known / to be known", "note": "passive of 알리다 (to inform)"}], "analysis": [{"type": "grammar", "label": "~지만 (but)", "exp": "Contrast conjunction. 하다 → 하지만 ('but / however'); here used as a sentence-initial connective.", "example_in_sentence": "하지만"}, {"type": "grammar", "label": "~이/가 (subject marker)", "exp": "Subject particle. 여성 + 이 → 여성이 ('the woman [is the subject]'). Used because 여성 ends in a consonant.", "example_in_sentence": "여성이"}, {"type": "grammar", "label": "~은/는 (topic marker)", "exp": "Topic/contrastive particle. 누구인지 + 는 → 누구인지는 ('as for who [she] is'). Marks the embedded clause as the topic.", "example_in_sentence": "누구인지는"}, {"type": "grammar", "label": "~지 않다", "exp": "Long-form negation. 알려지다 → 알려지지 않다 → 알려지지 않았어요 ('was not known').", "example_in_sentence": "알려지지 않았어요"}, {"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "Past polite ending. 않다 → 않았어요; stem 않 has vowel ㅏ → 았어요 ('was not').", "example_in_sentence": "않았어요"}]}, {"text": "2005년에 독일 연구자가 중요한 발견을 했어요.", "translation": "In 2005, a German researcher made an important discovery.", "vocab": [{"ko": "연구자", "en": "researcher", "note": "noun; 연구 (research) + 자 (person)"}, {"ko": "중요하다", "en": "to be important", "note": "adjective; 중요한 is the modifier form"}, {"ko": "발견", "en": "discovery / finding", "note": "noun; 발견하다 = to discover"}], "analysis": [{"type": "grammar", "label": "~에 (location/time)", "exp": "Time particle. 2005년 + 에 → 2005년에 ('in the year 2005').", "example_in_sentence": "2005년에"}, {"type": "grammar", "label": "~이/가 (subject marker)", "exp": "Subject particle. 연구자 + 가 → 연구자가 ('a researcher [did]'). Used because 연구자 ends in a vowel.", "example_in_sentence": "연구자가"}, {"type": "grammar", "label": "~을/를 (object marker)", "exp": "Direct object particle. 발견 + 을 → 발견을 ('a discovery [as object]'). Used because 발견 ends in a consonant.", "example_in_sentence": "발견을"}, {"type": "grammar", "label": "했어요 (하다 past polite)", "exp": "하다 verb past polite. 하다 → 했어요 ('did / made'). 발견을 하다 = to make a discovery.", "example_in_sentence": "했어요"}]}, {"text": "그는 오래된 책의 여백에서 손으로 쓴 메모를 찾았어요.", "translation": "He found a handwritten memo in the margin of an old book.", "vocab": [{"ko": "오래되다", "en": "to be old / to be aged", "note": "verb; 오래된 is the past modifier form meaning 'old'"}, {"ko": "여백", "en": "margin / blank space", "note": "noun; 여백에서 = 'in the margin'"}, {"ko": "찾다", "en": "to find / to look for", "note": "verb; context here means 'to find'"}, {"ko": "메모", "en": "memo / note", "note": "noun; loanword from English 'memo'"}], "analysis": [{"type": "grammar", "label": "~은/는 (topic marker)", "exp": "Topic particle. 그 + 는 → 그는 ('he [as topic]'). Used because 그 ends in a vowel.", "example_in_sentence": "그는"}, {"type": "grammar", "label": "~의 (possessive)", "exp": "Possessive/attributive particle. 책 + 의 → 책의 ('of the book / the book's').", "example_in_sentence": "책의"}, {"type": "grammar", "label": "~에서 (location/source)", "exp": "Location-of-action particle. 여백 + 에서 → 여백에서 ('in the margin').", "example_in_sentence": "여백에서"}, {"type": "grammar", "label": "~(으)로 (means/direction)", "exp": "Instrument/means particle. 손 + 으로 → 손으로 ('by hand / with the hand'). Used because 손 ends in a consonant (ㄴ).", "example_in_sentence": "손으로"}, {"type": "grammar", "label": "~을/를 (object marker)", "exp": "Direct object particle. 메모 + 를 → 메모를 ('the memo [as object]'). Used because 메모 ends in a vowel.", "example_in_sentence": "메모를"}, {"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "Past polite ending. 찾다 → 찾 + 았어요 → 찾았어요 ('found'). Stem vowel ㅏ → 았.", "example_in_sentence": "찾았어요"}]}, {"text": "이 메모에는 레오나르도 다 빈치가 1503년에 리사 델 지오콘도의 초상화를 그리고 있다고 적혀 있었어요.", "translation": "In this memo, it was written that Leonardo da Vinci was painting a portrait of Lisa del Giocondo in 1503.", "vocab": [{"ko": "초상화", "en": "portrait", "note": "noun; 초상 (portrait) + 화 (painting)"}, {"ko": "그리다", "en": "to draw / to paint", "note": "verb; 그리고 있다 = 'is painting'"}, {"ko": "적히다", "en": "to be written / to be noted", "note": "passive of 적다 (to write/note down)"}], "analysis": [{"type": "grammar", "label": "~에는", "exp": "에 (in) + 는 (topic): 메모 → 메모에는 ('in this memo').", "example_in_sentence": "메모에는"}, {"type": "grammar", "label": "~이/가 (subject marker)", "exp": "Subject particle. 레오나르도 다 빈치 + 가 → 레오나르도 다 빈치가 ('Leonardo da Vinci [as subject]'). Ends in vowel → 가.", "example_in_sentence": "레오나르도 다 빈치가"}, {"type": "grammar", "label": "~에 (location/time)", "exp": "Time particle. 1503년 + 에 → 1503년에 ('in the year 1503').", "example_in_sentence": "1503년에"}, {"type": "grammar", "label": "~의 (possessive)", "exp": "Possessive particle. 리사 델 지오콘도 + 의 → 리사 델 지오콘도의 ('of Lisa del Giocondo').", "example_in_sentence": "리사 델 지오콘도의"}, {"type": "grammar", "label": "~을/를 (object marker)", "exp": "Direct object particle. 초상화 + 를 → 초상화를 ('the portrait [as object]'). Ends in vowel → 를.", "example_in_sentence": "초상화를"}, {"type": "grammar", "label": "~고 있다 (continuous)", "exp": "Progressive aspect. 그리다 → 그리 + 고 있다 → 그리고 있다 ('is painting'). Embedded in a quoted clause here.", "example_in_sentence": "그리고 있다고"}, {"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "Past polite ending. 있다 → 있 + 었어요 → 있었어요 ('was [written]'). Stem vowel not ㅏ/ㅗ → 었.", "example_in_sentence": "있었어요"}]}, {"text": "이 메모는 진짜임이 확인되었어요.", "translation": "This memo was confirmed to be genuine.", "vocab": [{"ko": "진짜", "en": "real / genuine / true", "note": "noun/adverb; 진짜임 = 'the fact of being genuine' (nominalised)"}, {"ko": "확인되다", "en": "to be confirmed / to be verified", "note": "passive of 확인하다 (to confirm)"}], "analysis": [{"type": "grammar", "label": "~은/는 (topic marker)", "exp": "Topic particle. 메모 + 는 → 메모는 ('this memo [as topic]'). Ends in vowel → 는.", "example_in_sentence": "메모는"}, {"type": "grammar", "label": "~이/가 (subject marker)", "exp": "Subject particle. 진짜임 + 이 → 진짜임이 ('the fact of being genuine [as subject]'). Ends in consonant → 이.", "example_in_sentence": "진짜임이"}, {"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "Past polite ending. 되다 → 되 + 었어요 → 됐어요 (contracted) / 되었어요 ('was confirmed'). Here written in full form 되었어요.", "example_in_sentence": "확인되었어요"}]}, {"text": "이렇게 해서 모나리자가 누구인지 마침내 알게 되었어요.", "translation": "In this way, people finally learned who the Mona Lisa was.", "vocab": [{"ko": "이렇게", "en": "in this way / like this", "note": "adverb; 이렇다 → 이렇게"}, {"ko": "마침내", "en": "finally / at last", "note": "adverb"}, {"ko": "알다", "en": "to know / to come to know", "note": "verb; 알게 되다 = 'come to know'"}], "analysis": [{"type": "grammar", "label": "~이/가 (subject marker)", "exp": "Subject particle. 모나리자 + 가 → 모나리자가 ('the Mona Lisa [as subject]'). Ends in vowel → 가.", "example_in_sentence": "모나리자가"}, {"type": "grammar", "label": "~아/어서 (cause / sequence)", "exp": "Sequence/reason connector. 하다 → 해서 ('and so / by doing this'). 이렇게 해서 = 'by doing it this way / in this way'.", "example_in_sentence": "이렇게 해서"}, {"type": "grammar", "label": "~게 되다 (come to / passive)", "exp": "Circumstance change pattern. 알다 → 알 + 게 되다 → 알게 되었어요 ('came to know / it came about that [we] knew').", "example_in_sentence": "알게 되었어요"}, {"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "Past polite ending. 되다 → 되 + 었어요 → 되었어요 ('came to be / it became so'). Stem vowel not ㅏ/ㅗ → 었.", "example_in_sentence": "되었어요"}]}, {"text": "리사 델 지오콘도는 이탈리아 상인의 아내였어요.", "translation": "Lisa del Giocondo was the wife of an Italian merchant.", "vocab": [{"ko": "상인", "en": "merchant / trader", "note": "noun"}, {"ko": "아내", "en": "wife", "note": "noun; refers to one's own or another's wife"}], "analysis": [{"type": "grammar", "label": "~은/는 (topic marker)", "exp": "Topic particle. 리사 델 지오콘도 + 는 → 리사 델 지오콘도는 ('as for Lisa del Giocondo'). Ends in vowel → 는.", "example_in_sentence": "리사 델 지오콘도는"}, {"type": "grammar", "label": "~의 (possessive)", "exp": "Possessive particle. 상인 + 의 → 상인의 ('of the merchant / the merchant's').", "example_in_sentence": "상인의"}, {"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "Past polite ending. 이다 → 이었어요 → contracted to 였어요 ('was'). 아내 + 였어요 → 아내였어요 ('was [the] wife').", "example_in_sentence": "아내였어요"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mp1ufuf158ch' and md5(translation) = '44183148377c584d6a014205135b0e09';
update public.article_cache set translation = $t${"texts": ["There's something special about astronauts' helmets. There are small pieces of Velcro attached to the inside of the helmet. This Velcro serves an important purpose. It helps astronauts scratch their noses during spacewalks. In space, you can't take off your helmet. So even if your nose itches, you can't scratch it with your hands. With Velcro, astronauts can rub their noses against the Velcro inside the helmet to scratch the itchy spot. It's a small idea, but it's very useful for astronauts.", "Korean Teacher Shortage Becomes Serious, School Classes Disrupted", "What is an \"anxiety bag\"? A Popular Trend", "The United States and China Resume Talks Over Trade Issues", "\"Talking Pig\" Becomes SNS Star", "Apple Greatly Improves iPhone Speed with New AI Chip"], "sentences": [{"text": "우주 비행사들의 헬멧에는 특별한 것이 있어요.", "translation": "Astronauts' helmets have something special in them.", "vocab": [{"ko": "우주", "en": "space"}, {"ko": "비행사", "en": "pilot; astronaut"}, {"ko": "헬멧", "en": "helmet"}, {"ko": "특별하다", "en": "to be special"}], "analysis": [{"type": "grammar", "label": "~의 (possessive particle)", "exp": "Marks possession or association. 비행사 → 비행사의", "example_in_sentence": "비행사들의"}, {"type": "grammar", "label": "~에는 (locative + topic particle)", "exp": "Marks location with contrastive/topic emphasis. 헬멧 → 헬멧에는", "example_in_sentence": "헬멧에는"}, {"type": "grammar", "label": "~아/어요 (present polite)", "exp": "Polite present ending: 있다 → 있어요 (there is).", "example_in_sentence": "있어요"}]}, {"text": "헬멧 안쪽에 작은 벨크로 조각이 붙어 있어요.", "translation": "Small pieces of velcro are attached inside the helmet.", "vocab": [{"ko": "안쪽", "en": "inside; inner side"}, {"ko": "조각", "en": "piece; scrap"}, {"ko": "붙다", "en": "to stick; to be attached"}], "analysis": [{"type": "grammar", "label": "~에 (locative particle)", "exp": "Marks location where something exists or occurs. 안쪽 → 안쪽에", "example_in_sentence": "안쪽에"}, {"type": "grammar", "label": "~어/아 있어요 (resultative state)", "exp": "Indicates a current state resulting from a past action. 붙다 → 붙어 있어요", "example_in_sentence": "붙어 있어요"}]}, {"text": "이 벨크로는 중요한 역할을 해요.", "translation": "This velcro plays an important role.", "vocab": [{"ko": "역할", "en": "role; function"}, {"ko": "하다", "en": "to do; to play (a role)"}], "analysis": [{"type": "grammar", "label": "~은/는 (topic particle)", "exp": "Marks the topic of the sentence. 벨크로 → 벨크로는", "example_in_sentence": "벨크로는"}, {"type": "expression", "label": "역할을 하다 (to play a role)", "exp": "Common collocation expressing function or duty. The object 역할 takes 을/를.", "example_in_sentence": "역할을 해요"}]}, {"text": "우주 비행사들이 우주 활동을 할 때 코를 긁을 수 있게 도와줘요.", "translation": "It helps astronauts scratch their noses when they are working in space.", "vocab": [{"ko": "활동", "en": "activity"}, {"ko": "코", "en": "nose"}, {"ko": "긁다", "en": "to scratch"}, {"ko": "도와주다", "en": "to help; to assist"}], "analysis": [{"type": "grammar", "label": "~을/를 (object particle)", "exp": "Marks the direct object: 코 → 코를 (the nose).", "example_in_sentence": "코를"}, {"type": "grammar", "label": "~을/를 하다 (to do [noun])", "exp": "Makes a noun into a verb phrase. 활동 → 활동을 하다", "example_in_sentence": "활동을 할"}, {"type": "grammar", "label": "~을 수 있다 (can; be able to)", "exp": "Expresses ability or possibility. 긁다 → 긁을 수 있다", "example_in_sentence": "긁을 수 있게"}, {"type": "grammar", "label": "~(으)ㄹ 수 있게 도와주다", "exp": "'to help someone be able to V'. 긁다 → 긁을 수 있게 도와줘요 (helps them scratch).", "example_in_sentence": "긁을 수 있게 도와줘요"}]}, {"text": "우주에서는 헬멧을 벗을 수 없어요.", "translation": "In space, you cannot take off the helmet.", "vocab": [{"ko": "벗다", "en": "to take off; to remove"}], "analysis": [{"type": "grammar", "label": "~에서는 (locative + topic particle)", "exp": "Marks location with topic/contrast. 우주 → 우주에서는", "example_in_sentence": "우주에서는"}, {"type": "grammar", "label": "~을/를 (accusative particle)", "exp": "Marks direct object. 헬멧 → 헬멧을", "example_in_sentence": "헬멧을"}, {"type": "grammar", "label": "~을 수 없다 (cannot; be unable to)", "exp": "Negates possibility or ability. 벗다 → 벗을 수 없어요", "example_in_sentence": "벗을 수 없어요"}]}, {"text": "그래서 코가 가려워도 손으로 긁을 수 없어요.", "translation": "So even if the nose itches, you cannot scratch it with your hands.", "vocab": [{"ko": "가렵다", "en": "to itch"}, {"ko": "손", "en": "hand"}], "analysis": [{"type": "grammar", "label": "~어/아도 (even if; even though)", "exp": "Introduces a concessive clause. 가렵다 → 가려워도", "example_in_sentence": "가려워도"}, {"type": "grammar", "label": "~으로 (instrumental particle)", "exp": "Marks means or tool. 손 → 손으로", "example_in_sentence": "손으로"}, {"type": "grammar", "label": "~을 수 없다 (cannot; be unable to)", "exp": "Negates possibility. 긁다 → 긁을 수 없어요", "example_in_sentence": "긁을 수 없어요"}]}, {"text": "벨크로가 있으면 코를 헬멧 안의 벨크로에 비벼서 가려운 곳을 긁을 수 있어요.", "translation": "If there is velcro, you can rub your nose against the velcro inside the helmet and scratch the itchy spot.", "vocab": [{"ko": "있다", "en": "to exist; to have"}, {"ko": "비비다", "en": "to rub"}, {"ko": "곳", "en": "place; spot"}], "analysis": [{"type": "grammar", "label": "~으면 (if; when [conditional])", "exp": "Introduces a conditional clause. 있다 → 있으면", "example_in_sentence": "있으면"}, {"type": "grammar", "label": "~에 (dative particle)", "exp": "Marks the target or destination of an action. 벨크로 → 벨크로에", "example_in_sentence": "벨크로에"}, {"type": "grammar", "label": "~어/아서 (connective: and; and then)", "exp": "Connects sequential actions or related clauses. 비비다 → 비벼서", "example_in_sentence": "비벼서"}]}, {"text": "작은 아이디어지만 우주 비행사들에게는 매우 유용해요.", "translation": "Though it is a small idea, it is very useful for astronauts.", "vocab": [{"ko": "아이디어", "en": "idea"}, {"ko": "유용하다", "en": "to be useful"}], "analysis": [{"type": "grammar", "label": "~지만 (but; although)", "exp": "'but / although'. After a noun ending in a vowel, 이지만 shortens to 지만: 아이디어 → 아이디어지만 (it's an idea, but).", "example_in_sentence": "아이디어지만"}, {"type": "grammar", "label": "~에게는 (dative + topic particle)", "exp": "Marks recipient/target with topic emphasis. 비행사들 → 비행사들에게는", "example_in_sentence": "비행사들에게는"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mpaexycevr22' and md5(translation) = '34f6ba70c07581087e03042988ceb5dd';
update public.article_cache set translation = $t${"texts": ["In 1945, the United States dropped leaflets before dropping the atomic bomb on Nagasaki. These leaflets warned Japanese civilians.", "The leaflets had messages written in Japanese. The US announced that it would use a new weapon.", "The US warned that cities would be destroyed if the Japanese government did not surrender. They told civilians to evacuate to safe places.", "However, many people did not believe this warning. A few days later, the second atomic bomb was dropped on Nagasaki."], "sentences": [{"text": "1945년 미국이 나가사키에 핵폭탄을 떨어뜨리기 전에 전단을 뿌렸어요.", "translation": "In 1945, the United States dropped leaflets before dropping the atomic bomb on Nagasaki.", "vocab": [{"ko": "미국", "en": "United States", "note": ""}, {"ko": "핵폭탄", "en": "nuclear bomb", "note": ""}, {"ko": "떨어뜨리다", "en": "to drop", "note": ""}, {"ko": "전단", "en": "leaflet, flyer", "note": ""}], "analysis": [{"type": "grammar", "label": "~기 전에", "exp": "before V-ing. Verb stem + 기 전에 = before doing that action. 떨어뜨리다 → 떨어뜨리기 전에 (before dropping)", "example_in_sentence": "떨어뜨리기 전에"}, {"type": "grammar", "label": "~았/었/였어요", "exp": "past polite ending. Verb stem + 았/었어요 = did (polite). 뿌리다 → 뿌렸어요 (dropped/scattered)", "example_in_sentence": "뿌렸어요"}, {"type": "grammar", "label": "~에 (location/time)", "exp": "static location / time / direction", "example_in_sentence": "나가사키에"}]}, {"text": "이 전단들은 일본 시민들에게 경고했어요.", "translation": "These leaflets warned Japanese civilians.", "vocab": [{"ko": "시민", "en": "citizen, civilian", "note": ""}, {"ko": "경고하다", "en": "to warn", "note": ""}], "analysis": [{"type": "grammar", "label": "~에게", "exp": "to (person). Shows the recipient of an action. 시민들에게 = to the civilians", "example_in_sentence": "시민들에게"}, {"type": "grammar", "label": "~았/었/였어요", "exp": "past polite ending. 경고하다 → 경고했어요 (warned)", "example_in_sentence": "경고했어요"}]}, {"text": "전단에는 일본어로 메시지가 적혀 있었어요.", "translation": "The leaflets had messages written in Japanese.", "vocab": [{"ko": "일본어", "en": "Japanese language", "note": ""}, {"ko": "메시지", "en": "message", "note": ""}, {"ko": "적히다", "en": "to be written", "note": ""}], "analysis": [{"type": "grammar", "label": "~에는", "exp": "topic marker after location particle. 전단에 (on leaflets) + 는 (topic) = as for on the leaflets", "example_in_sentence": "전단에는"}, {"type": "grammar", "label": "~(으)로", "exp": "means/method particle. Shows how something is done. 일본어로 = in Japanese (language)", "example_in_sentence": "일본어로"}, {"type": "grammar", "label": "~아/어 있다", "exp": "Shows a state that remains after an action: 적히다 (to be written) → 적혀 있었어요 (was written).", "example_in_sentence": "적혀 있었어요"}]}, {"text": "미국은 새로운 무기를 사용할 것이라고 알렸어요.", "translation": "The US announced that it would use a new weapon.", "vocab": [{"ko": "새롭다", "en": "to be new", "note": ""}, {"ko": "무기", "en": "weapon", "note": ""}, {"ko": "사용하다", "en": "to use", "note": ""}, {"ko": "알리다", "en": "to inform, announce", "note": ""}], "analysis": [{"type": "grammar", "label": "~ㄴ/은", "exp": "past verb modifier or present adjective modifier. 새롭다 → 새로운 (new, modifying noun)", "example_in_sentence": "새로운"}, {"type": "grammar", "label": "~을/를", "exp": "object marker. Shows direct object of verb. 무기를 = weapon (as object)", "example_in_sentence": "무기를"}, {"type": "grammar", "label": "~(으)ㄹ 것이다", "exp": "Future / prediction, 'will'. 사용하다 → 사용할 것이다 (will use).", "example_in_sentence": "사용할 것이라고"}, {"type": "grammar", "label": "~(이)라고 알리다", "exp": "Reports what was announced. After 것이다 the quote ending is 이라고: 사용할 것이다 → 사용할 것이라고 알렸어요 (announced that it would use).", "example_in_sentence": "것이라고 알렸어요"}]}, {"text": "미국은 일본 정부가 항복하지 않으면 도시들이 파괴될 것이라고 경고했어요.", "translation": "The US warned that cities would be destroyed if the Japanese government did not surrender.", "vocab": [{"ko": "정부", "en": "government", "note": ""}, {"ko": "항복하다", "en": "to surrender", "note": ""}, {"ko": "도시", "en": "city", "note": ""}, {"ko": "파괴되다", "en": "to be destroyed", "note": ""}], "analysis": [{"type": "grammar", "label": "~이/가", "exp": "subject marker. Shows subject of sentence. 정부가 = the government (as subject)", "example_in_sentence": "정부가"}, {"type": "grammar", "label": "~지 않다", "exp": "Makes a verb negative: 항복하다 → 항복하지 않다 (not surrender).", "example_in_sentence": "항복하지 않으면"}, {"type": "grammar", "label": "~(으)면", "exp": "'if'. 않다 → 않으면 (if (they) do not ...).", "example_in_sentence": "않으면"}, {"type": "grammar", "label": "~(으)ㄹ 것이라고 경고하다", "exp": "Reports a warning: 파괴되다 → 파괴될 것이다 (will be destroyed) → 파괴될 것이라고 경고했어요 (warned that they would be destroyed).", "example_in_sentence": "파괴될 것이라고"}]}, {"text": "시민들에게 안전한 곳으로 피하라고 했어요.", "translation": "They told civilians to evacuate to safe places.", "vocab": [{"ko": "안전하다", "en": "to be safe", "note": ""}, {"ko": "곳", "en": "place", "note": ""}, {"ko": "피하다", "en": "to avoid; to take shelter", "note": ""}], "analysis": [{"type": "grammar", "label": "~ㄴ/은", "exp": "adjective modifier. 안전하다 → 안전한 (safe, modifying noun)", "example_in_sentence": "안전한"}, {"type": "grammar", "label": "~(으)로", "exp": "direction particle. Shows direction of movement. 곳으로 = to the place", "example_in_sentence": "곳으로"}, {"type": "grammar", "label": "~(으)라고 하다", "exp": "Reports a command: 피하다 → 피하라 (Take shelter!) → 피하라고 했어요 (told them to take shelter).", "example_in_sentence": "피하라고 했어요"}]}, {"text": "하지만 많은 사람들이 이 경고를 믿지 않았어요.", "translation": "However, many people did not believe this warning.", "vocab": [{"ko": "많다", "en": "to be many, much", "note": ""}, {"ko": "사람", "en": "person", "note": ""}, {"ko": "믿다", "en": "to believe", "note": ""}], "analysis": [{"type": "grammar", "label": "하지만", "exp": "however, but. Connects contrasting clauses.", "example_in_sentence": "하지만"}, {"type": "grammar", "label": "~ㄴ/은", "exp": "adjective modifier. 많다 → 많은 (many, modifying noun)", "example_in_sentence": "많은"}, {"type": "grammar", "label": "~지 않다", "exp": "negation. 믿다 → 믿지 않다 → 믿지 않았어요 (did not believe)", "example_in_sentence": "믿지 않았어요"}, {"type": "grammar", "label": "~았/었/였어요", "exp": "past polite ending combined with negation. 믿지 않다 → 믿지 않았어요", "example_in_sentence": "않았어요"}]}, {"text": "며칠 후 나가사키에 두 번째 원자폭탄이 투하됐어요.", "translation": "A few days later, the second atomic bomb was dropped on Nagasaki.", "vocab": [{"ko": "며칠", "en": "a few days", "note": ""}, {"ko": "후", "en": "after, later", "note": ""}, {"ko": "번째", "en": "ordinal number suffix", "note": ""}, {"ko": "원자폭탄", "en": "atomic bomb", "note": ""}], "analysis": [{"type": "grammar", "label": "~에", "exp": "location particle. Shows where action takes place. 나가사키에 = in/on Nagasaki", "example_in_sentence": "나가사키에"}, {"type": "grammar", "label": "~이/가", "exp": "subject marker. 원자폭탄이 = the atomic bomb (as subject)", "example_in_sentence": "원자폭탄이"}, {"type": "grammar", "label": "~았/었/였어요", "exp": "past polite ending. 투하되다 → 투하됐어요 (was dropped)", "example_in_sentence": "투하됐어요"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mpaez25dj4wo' and md5(translation) = '86762cc82d1a38e7e29aa4fa2283efc0';
update public.article_cache set translation = $t${"texts": ["In 1743, something interesting happened in France. At that time, male surgeons wanted to work as midwives. The doctors tried not to provide education to female midwives.", "There was a woman named Angélique du Coudray. She became angry when she saw this situation. So she started a campaign to stop the doctors.", "The French king gave Angélique a special task. The king told her to teach midwifery throughout the entire country. This was a very important job.", "Angélique taught countless students. She worked hard for midwife education. Thanks to her efforts, many women were able to become midwives."], "sentences": [{"text": "1743년에 프랑스에서 흥미로운 일이 있었어요.", "translation": "In 1743, something interesting happened in France.", "vocab": [{"ko": "흥미롭다", "en": "to be interesting", "note": "흥미(interest) + -롭다(suffix forming adjectives)"}], "analysis": [{"type": "grammar", "label": "~에서", "exp": "location marker. indicates where an action takes place. 프랑스에서 (in France)", "example_in_sentence": "프랑스에서"}, {"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "past tense polite form. 있다 + 었어요 = 있었어요 (there was/were)", "example_in_sentence": "있었어요"}, {"type": "grammar", "label": "~롭다", "exp": "adjective suffix meaning 'having the quality of'. 흥미(interest) + 롭다 → 흥미롭다 (interesting)", "example_in_sentence": "흥미로운"}, {"type": "grammar", "label": "~에 (location/time)", "exp": "static location / time / direction", "example_in_sentence": "년에"}]}, {"text": "그때 남자 의사들이 조산사 일을 하고 싶어했어요.", "translation": "At that time, male doctors wanted to do the work of midwives.", "vocab": [{"ko": "의사", "en": "doctor", "note": "medical doctor"}, {"ko": "조산사", "en": "midwife", "note": "person who assists in childbirth"}], "analysis": [{"type": "grammar", "label": "~이/가", "exp": "subject marker. marks the grammatical subject of the sentence. 의사들이 (the doctors)", "example_in_sentence": "의사들이"}, {"type": "grammar", "label": "~을/를", "exp": "object marker. marks the direct object. 일을 (work/job)", "example_in_sentence": "일을"}, {"type": "grammar", "label": "~고 싶어하다", "exp": "Says what someone else wants to do (used for third persons). 하다 → 하고 싶어했어요 (they wanted to do).", "example_in_sentence": "하고 싶어했어요"}, {"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "Past polite ending. 싶어하다 → 싶어했어요 (wanted).", "example_in_sentence": "싶어했어요"}]}, {"text": "의사들은 여자 조산사들에게 교육을 주지 않으려고 했어요.", "translation": "The doctors tried not to provide education to female midwives.", "vocab": [{"ko": "여자", "en": "woman", "note": "female person"}, {"ko": "교육", "en": "education", "note": "teaching and training"}, {"ko": "주다", "en": "to give", "note": "basic verb for giving"}], "analysis": [{"type": "grammar", "label": "~은/는", "exp": "topic marker. indicates what the sentence is about. 의사들은 (as for the doctors)", "example_in_sentence": "의사들은"}, {"type": "grammar", "label": "~에게", "exp": "dative marker for people. indicates the recipient of an action. 조산사들에게 (to the midwives)", "example_in_sentence": "조산사들에게"}, {"type": "grammar", "label": "~지 않다", "exp": "negation. verb stem + 지 않다 = negative form. 주다 → 주지 않다 (not give)", "example_in_sentence": "주지 않으려고"}, {"type": "grammar", "label": "~(으)려고 하다", "exp": "Shows an intention or attempt: 'try to'. 않다 → 않으려고 했어요 (tried not to).", "example_in_sentence": "않으려고 했어요"}, {"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "past tense polite form. 하다 + 었어요 = 했어요 (did/tried)", "example_in_sentence": "했어요"}]}, {"text": "앙젤리크 뒤 쿠드레라는 여자가 있었어요.", "translation": "There was a woman named Angélique du Coudray.", "vocab": [{"ko": "여자", "en": "woman", "note": "female person"}], "analysis": [{"type": "grammar", "label": "~(이)라는", "exp": "called/named. indicates someone's name or what something is called. 뒤 쿠드레라는 (named du Coudray)", "example_in_sentence": "뒤 쿠드레라는"}, {"type": "grammar", "label": "~이/가", "exp": "subject marker. marks the grammatical subject. 여자가 (a woman)", "example_in_sentence": "여자가"}, {"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "past tense polite form. 있다 + 었어요 = 있었어요 (there was/existed)", "example_in_sentence": "있었어요"}]}, {"text": "그녀는 이 상황을 보고 화가 났어요.", "translation": "She became angry when she saw this situation.", "vocab": [{"ko": "그녀", "en": "she", "note": "third person feminine pronoun"}, {"ko": "상황", "en": "situation", "note": "circumstances or condition"}, {"ko": "보다", "en": "to see", "note": "basic verb for seeing"}, {"ko": "화", "en": "anger", "note": "feeling of anger or rage"}], "analysis": [{"type": "grammar", "label": "~은/는", "exp": "topic marker. indicates what the sentence is about. 그녀는 (as for her)", "example_in_sentence": "그녀는"}, {"type": "grammar", "label": "~을/를", "exp": "object marker. marks the direct object. 상황을 (the situation)", "example_in_sentence": "상황을"}, {"type": "grammar", "label": "~고", "exp": "connective ending. connects two actions in sequence. 보고 (seeing and)", "example_in_sentence": "보고"}, {"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "past tense polite form. 나다 + 았어요 = 났어요 (arose/came out)", "example_in_sentence": "났어요"}, {"type": "expression", "label": "화가 나다", "exp": "idiomatic expression meaning 'to get angry'. literally 'anger comes out'", "example_in_sentence": "화가 났어요"}]}, {"text": "그래서 의사들을 막으려고 캠페인을 시작했어요.", "translation": "So she started a campaign to stop the doctors.", "vocab": [{"ko": "그래서", "en": "so, therefore", "note": "conjunctive adverb showing result"}, {"ko": "막다", "en": "to block, to stop", "note": "prevent something from happening"}, {"ko": "캠페인", "en": "campaign", "note": "organized effort for a cause"}, {"ko": "시작하다", "en": "to start", "note": "begin something"}], "analysis": [{"type": "grammar", "label": "~을/를", "exp": "object marker. marks the direct object. 의사들을 (the doctors), 캠페인을 (the campaign)", "example_in_sentence": "의사들을"}, {"type": "grammar", "label": "~(으)려고", "exp": "intention. expresses purpose or attempt. 막으려고 (in order to stop)", "example_in_sentence": "막으려고"}, {"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "Past polite ending. 시작하다 → 시작했어요 (started).", "example_in_sentence": "시작했어요"}]}, {"text": "프랑스 왕이 앙젤리크에게 특별한 일을 맡겼어요.", "translation": "The French king gave Angélique a special task.", "vocab": [{"ko": "왕", "en": "king", "note": "monarch or ruler"}, {"ko": "특별하다", "en": "to be special", "note": "different from ordinary"}, {"ko": "맡기다", "en": "to entrust", "note": "give responsibility to someone"}], "analysis": [{"type": "grammar", "label": "~이/가", "exp": "subject marker. marks the grammatical subject. 왕이 (the king)", "example_in_sentence": "왕이"}, {"type": "grammar", "label": "~에게", "exp": "dative marker for people. indicates the recipient. 앙젤리크에게 (to Angélique)", "example_in_sentence": "앙젤리크에게"}, {"type": "grammar", "label": "~ㄴ/은", "exp": "adnominal ending for past/completed action or present state of adjectives. 특별하다 → 특별한 (special)", "example_in_sentence": "특별한"}, {"type": "grammar", "label": "~을/를", "exp": "object marker. marks the direct object. 일을 (work/task)", "example_in_sentence": "일을"}, {"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "past tense polite form. 맡기다 + 었어요 = 맡겼어요 (entrusted)", "example_in_sentence": "맡겼어요"}]}, {"text": "왕은 그녀에게 나라 전체에서 조산사를 가르치라고 했어요.", "translation": "The king told her to teach midwives throughout the whole country.", "vocab": [{"ko": "나라", "en": "country", "note": "nation or state"}, {"ko": "전체", "en": "whole, entire", "note": "all parts together"}, {"ko": "가르치다", "en": "to teach", "note": "provide instruction or education"}], "analysis": [{"type": "grammar", "label": "~은/는", "exp": "topic marker. indicates what the sentence is about. 왕은 (as for the king)", "example_in_sentence": "왕은"}, {"type": "grammar", "label": "~에게", "exp": "dative marker for people. indicates the recipient. 그녀에게 (to her)", "example_in_sentence": "그녀에게"}, {"type": "grammar", "label": "~에서", "exp": "location marker. indicates where an action takes place. 전체에서 (throughout)", "example_in_sentence": "전체에서"}, {"type": "grammar", "label": "~을/를", "exp": "Object marker. Marks the direct object. 조산사를 (midwives).", "example_in_sentence": "조산사를"}, {"type": "grammar", "label": "~(으)라고 하다", "exp": "indirect imperative. reports someone's command or instruction. 가르치라고 (told to teach)", "example_in_sentence": "가르치라고"}, {"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "past tense polite form. 하다 + 었어요 = 했어요 (said/told)", "example_in_sentence": "했어요"}]}, {"text": "이것은 매우 중요한 일이었어요.", "translation": "This was a very important job.", "vocab": [{"ko": "이것", "en": "this", "note": "demonstrative pronoun for nearby object"}, {"ko": "매우", "en": "very", "note": "adverb intensifying degree"}, {"ko": "중요하다", "en": "to be important", "note": "having great significance"}], "analysis": [{"type": "grammar", "label": "~은/는", "exp": "topic marker. indicates what the sentence is about. 이것은 (as for this)", "example_in_sentence": "이것은"}, {"type": "grammar", "label": "~ㄴ/은", "exp": "adnominal ending for present state of adjectives. 중요하다 → 중요한 (important)", "example_in_sentence": "중요한"}, {"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "past tense polite form. 이다 + 었어요 = 이었어요 (was)", "example_in_sentence": "이었어요"}]}, {"text": "앙젤리크는 수많은 학생들을 가르쳤어요.", "translation": "Angélique taught countless students.", "vocab": [{"ko": "수많다", "en": "to be countless", "note": "extremely many in number"}, {"ko": "학생", "en": "student", "note": "person who studies"}, {"ko": "가르치다", "en": "to teach", "note": "provide instruction or education"}], "analysis": [{"type": "grammar", "label": "~은/는", "exp": "topic marker. indicates what the sentence is about. 앙젤리크는 (as for Angélique)", "example_in_sentence": "앙젤리크는"}, {"type": "grammar", "label": "~ㄴ/은", "exp": "adnominal ending for present state of adjectives. 수많다 → 수많은 (countless)", "example_in_sentence": "수많은"}, {"type": "grammar", "label": "~을/를", "exp": "object marker. marks the direct object. 학생들을 (the students)", "example_in_sentence": "학생들을"}, {"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "past tense polite form. 가르치다 + 었어요 = 가르쳤어요 (taught)", "example_in_sentence": "가르쳤어요"}]}, {"text": "그녀는 조산사 교육을 위해 열심히 일했어요.", "translation": "She worked hard for midwife education.", "vocab": [{"ko": "교육", "en": "education", "note": "teaching and training"}, {"ko": "열심히", "en": "diligently, hard", "note": "with great effort and dedication"}, {"ko": "일하다", "en": "to work", "note": "perform labor or job"}], "analysis": [{"type": "grammar", "label": "~은/는", "exp": "topic marker. indicates what the sentence is about. 그녀는 (as for her)", "example_in_sentence": "그녀는"}, {"type": "grammar", "label": "~을/를 위해(서)", "exp": "for the sake of. indicates purpose or benefit. 교육을 위해 (for education)", "example_in_sentence": "교육을 위해"}, {"type": "grammar", "label": "~히 (adverb ending)", "exp": "Turns a word into an adverb. 열심 (hard work) + 히 → 열심히 (hard, diligently).", "example_in_sentence": "열심히"}, {"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "Past polite ending. 일하다 → 일했어요 (worked).", "example_in_sentence": "일했어요"}]}, {"text": "덕분에 많은 여자들이 조산사가 될 수 있었어요.", "translation": "Thanks to her efforts, many women were able to become midwives.", "vocab": [{"ko": "덕분", "en": "thanks to; credit", "note": "benefit or help from someone"}, {"ko": "많다", "en": "to be many", "note": "large in number or amount"}, {"ko": "되다", "en": "to become", "note": "change into a different state"}], "analysis": [{"type": "grammar", "label": "덕분에", "exp": "'Thanks to (that)' — gives a good reason for a result. At the start of a sentence it means 'thanks to her (work)'.", "example_in_sentence": "덕분에"}, {"type": "grammar", "label": "~ㄴ/은", "exp": "adnominal ending for present state of adjectives. 많다 → 많은 (many)", "example_in_sentence": "많은"}, {"type": "grammar", "label": "~이/가", "exp": "subject marker. marks the grammatical subject. 여자들이 (the women)", "example_in_sentence": "여자들이"}, {"type": "grammar", "label": "~(으)ㄹ 수 있다", "exp": "ability/possibility. can do or be able to do. 될 수 있다 (can become)", "example_in_sentence": "될 수 있었어요"}, {"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "past tense polite form. 있다 + 었어요 = 있었어요 (was able to)", "example_in_sentence": "있었어요"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mpbuk5nl913t' and md5(translation) = '6ff5979a62dc408a6ac782803ccc10b3';
update public.article_cache set translation = $t${"texts": ["Greece is scheduled to repay 6.9 billion euros in June. Once this amount is fully repaid, Greece will no longer be the most indebted nation in the Eurozone.", "Greece had long been the most indebted nation in the Eurozone. However, this repayment brings that record to an end.", "6.9 billion euros is a very large sum. Greece is able to repay this amount in June.", "This repayment is an important change for Greece. Greece is now no longer the Eurozone's most indebted nation."], "sentences": [{"text": "그리스는 6월에 69억 유로를 갚을 예정이에요.", "translation": "Greece is scheduled to repay 6.9 billion euros in June.", "vocab": [{"ko": "갚다", "en": "to repay, to pay back", "note": "used for repaying debts or loans"}, {"ko": "예정", "en": "schedule, plan", "note": "noun meaning something that is planned or scheduled"}], "analysis": [{"type": "grammar", "label": "~을/를 (object marker)", "exp": "Object particle. Attaches to the noun that receives the action of the verb. 유로 + 를 = 유로를 (euros [as the object of repaying]).", "example_in_sentence": "유로를"}, {"type": "grammar", "label": "~(으)ㄹ 예정이다", "exp": "'Is scheduled / planned to ~'. 갚다 → 갚을 예정이에요 (is scheduled to repay).", "example_in_sentence": "갚을 예정이에요"}, {"type": "grammar", "label": "~에 (location/time)", "exp": "Time particle. Attaches to a time expression to mark when something happens. 6월 + 에 = 6월에 (in June).", "example_in_sentence": "6월에"}]}, {"text": "이 돈을 다 갚으면 그리스는 유로존에서 빚이 가장 많은 나라가 아니에요.", "translation": "Once this amount is fully repaid, Greece will no longer be the most indebted nation in the Eurozone.", "vocab": [{"ko": "갚다", "en": "to repay, to pay back", "note": "repaying a debt"}, {"ko": "빚", "en": "debt", "note": "money owed to others"}, {"ko": "많다", "en": "to be many, to be much", "note": "adjective describing a large quantity or amount"}], "analysis": [{"type": "grammar", "label": "~(으)면 (if/when)", "exp": "Conditional connective. Verb stem + (으)면 = 'if/when ~'. 갚다 → 갚으면 (if/when [one] repays). Used here to express a condition that leads to a result.", "example_in_sentence": "갚으면"}, {"type": "grammar", "label": "~에서 (location/source)", "exp": "Location particle indicating where something takes place or a source. 유로존 + 에서 = 유로존에서 (in/within the Eurozone).", "example_in_sentence": "유로존에서"}, {"type": "grammar", "label": "~ㄴ/은 (past verb / present adj modifier)", "exp": "Adnominal (modifier) ending for adjectives in present tense. 많다 (to be many/much) → 많은 + 나라 = 'a country with the most [debt]'. The adjective stem 많- + 은 modifies the noun 나라.", "example_in_sentence": "많은 나라"}, {"type": "grammar", "label": "~이/가 아니다", "exp": "'Is not' — the negative of 이다. 나라가 아니에요 (is not the country).", "example_in_sentence": "나라가 아니에요"}]}, {"text": "그리스는 오랫동안 유로존에서 빚이 가장 많은 나라였어요.", "translation": "Greece had long been the most indebted nation in the Eurozone.", "vocab": [{"ko": "오랫동안", "en": "for a long time", "note": "adverb indicating a long duration"}, {"ko": "빚", "en": "debt", "note": "money owed"}, {"ko": "많다", "en": "to be many, to be much", "note": "adjective"}], "analysis": [{"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "Past tense polite ending. 나라이다 (to be a country) → 나라였어요 (was a country). The copula 이다 contracts: 이었어요 → 였어요 after a vowel-final noun (나라).", "example_in_sentence": "나라였어요"}, {"type": "grammar", "label": "~ㄴ/은 (past verb / present adj modifier)", "exp": "Adnominal ending for adjectives. 많다 → 많은 + 나라 = 'a country that has the most (debt)'. The adjective modifies the noun that follows.", "example_in_sentence": "많은 나라"}, {"type": "grammar", "label": "~에서 (location/source)", "exp": "Location particle marking where a state exists or an action takes place. 유로존 + 에서 = 유로존에서 (in the Eurozone).", "example_in_sentence": "유로존에서"}]}, {"text": "하지만 이번 상환으로 그 기록이 끝났어요.", "translation": "However, with this repayment, that record came to an end.", "vocab": [{"ko": "상환", "en": "repayment (of debt)", "note": "formal noun for paying back borrowed money"}, {"ko": "기록", "en": "record", "note": "here meaning a long-held status or streak"}, {"ko": "끝나다", "en": "to end, to finish", "note": "intransitive verb; the subject ends on its own"}], "analysis": [{"type": "grammar", "label": "~(으)로 (means/direction)", "exp": "Particle indicating means or cause. 상환 + 으로 = 상환으로 (by means of / through this repayment). Used here to show what caused the record to end.", "example_in_sentence": "상환으로"}, {"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "Past tense polite ending. 끝나다 (to end) → stem 끝나- + 았어요 = 끝났어요 (ended). The ㅏ vowel in the stem triggers 았.", "example_in_sentence": "끝났어요"}]}, {"text": "69억 유로는 매우 큰 금액이에요.", "translation": "6.9 billion euros is a very large sum.", "vocab": [{"ko": "매우", "en": "very, extremely", "note": "adverb intensifying an adjective"}, {"ko": "크다", "en": "to be big, to be large", "note": "adjective"}, {"ko": "금액", "en": "amount of money, sum", "note": "formal noun for a monetary amount"}], "analysis": [{"type": "grammar", "label": "~은/는 (topic marker)", "exp": "Topic particle. Marks 69억 유로 as the topic of the sentence. 69억 유로 + 는 = 69억 유로는 (As for 6.9 billion euros, …).", "example_in_sentence": "69억 유로는"}, {"type": "grammar", "label": "~ㄴ/은 (adjective + noun)", "exp": "Lets an adjective describe a noun. Vowel stems take ㄴ: 크다 → 큰 금액 (a large sum).", "example_in_sentence": "큰 금액"}]}, {"text": "그리스는 이 금액을 6월에 갚을 수 있어요.", "translation": "Greece is able to repay this amount in June.", "vocab": [{"ko": "갚다", "en": "to repay, to pay back", "note": ""}, {"ko": "금액", "en": "amount of money, sum", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 수 있다/없다 (ability/possibility)", "exp": "Ability/possibility construction. Verb stem + (으)ㄹ 수 있다 = 'can / is able to'. 갚다 → 갚을 수 있어요 (can repay). The ㄹ is added to the stem 갚- (consonant-final) with 을.", "example_in_sentence": "갚을 수 있어요"}, {"type": "grammar", "label": "~을/를 (object marker)", "exp": "Object particle. Marks the noun receiving the action. 금액 + 을 = 금액을 (this amount [as the object]).", "example_in_sentence": "금액을"}, {"type": "grammar", "label": "~에 (location/time)", "exp": "Time particle. 6월 + 에 = 6월에 (in June), marking when the repayment happens.", "example_in_sentence": "6월에"}, {"type": "grammar", "label": "~아/어/여요 (present polite)", "exp": "present polite informal ending", "example_in_sentence": "있어요"}]}, {"text": "이번 상환은 그리스에게 중요한 변화예요.", "translation": "This repayment is an important change for Greece.", "vocab": [{"ko": "상환", "en": "repayment (of debt)", "note": ""}, {"ko": "중요하다", "en": "to be important", "note": "adjective"}, {"ko": "변화", "en": "change", "note": "noun meaning a shift or transformation in a situation"}], "analysis": [{"type": "grammar", "label": "~에게/한테 (to person)", "exp": "Dative particle for people or organizations. 그리스 + 에게 = 그리스에게 (for/to Greece). Marks the beneficiary or the entity for which something is relevant.", "example_in_sentence": "그리스에게"}, {"type": "grammar", "label": "~ㄴ/은 (past verb / present adj modifier)", "exp": "Adnominal ending for adjectives. 중요하다 (to be important) → 중요한 + 변화 = 'an important change'. Stem 중요하- + ㄴ = 중요한.", "example_in_sentence": "중요한 변화"}]}, {"text": "이제 그리스는 유로존 최대 채무국이 아니에요.", "translation": "Greece is now no longer the Eurozone's most indebted nation.", "vocab": [{"ko": "이제", "en": "now, from now on", "note": "adverb marking a new present state"}, {"ko": "최대", "en": "largest, greatest, maximum", "note": "prefix/noun used before a noun to mean 'biggest' or 'most'"}, {"ko": "채무국", "en": "debtor nation", "note": "a country that owes large amounts of debt"}], "analysis": [{"type": "grammar", "label": "~이/가 (subject marker)", "exp": "Subject particle. 채무국 + 이 = 채무국이, marking 채무국 as the subject complement of the negated copula 아니에요.", "example_in_sentence": "채무국이"}, {"type": "grammar", "label": "~이/가 아니다", "exp": "'Is not' — the negative of 이다. 채무국이 아니에요 (is not the debtor nation).", "example_in_sentence": "채무국이 아니에요"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mpckq31v2rbr' and md5(translation) = 'c7f5f0ee9d3bbfbf4319f455bcb06c73';
update public.article_cache set translation = $t${"texts": ["In 2017, two orangutans came out of the fence at Perth Zoo in Australia. The zoo immediately locked the door.", "A 5-year-old male orangutan fell into the flower bed next to the fence. It had come out to the outside of the fence.", "Then the mother orangutan went to the baby. She had gone to fetch the baby.", "The mother used the visitor walkway and returned to the exhibit area. She came back on her own."], "sentences": [{"text": "2017년에 호주 퍼스 동물원에서 오랑우탄 두 마리가 울타리 밖으로 나왔어요.", "translation": "In 2017, two orangutans got out of their enclosure at Perth Zoo in Australia.", "vocab": [{"ko": "동물원", "en": "zoo", "note": ""}, {"ko": "울타리", "en": "fence / enclosure", "note": ""}, {"ko": "나오다", "en": "to come out", "note": "나오다 = 나 (out) + 오다 (come)"}], "analysis": [{"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "Past polite ending. 나오다 → stem 나오 + 았어요 → contracts to 나왔어요.", "example_in_sentence": "나왔어요"}, {"type": "grammar", "label": "~이/가 (subject marker)", "exp": "Subject particle attached to a noun ending in a vowel. 마리 → 마리가.", "example_in_sentence": "두 마리가"}, {"type": "grammar", "label": "~에서 (location/source)", "exp": "Marks the location where an action takes place. 동물원 + 에서 = at/in the zoo.", "example_in_sentence": "동물원에서"}, {"type": "grammar", "label": "~에 (location/time)", "exp": "Marks a point in time. 2017년 + 에 = in (the year) 2017.", "example_in_sentence": "2017년에"}, {"type": "grammar", "label": "~(으)로 (means/direction)", "exp": "Marks direction toward which movement occurs. 밖 + 으로 = to the outside / out.", "example_in_sentence": "밖으로"}]}, {"text": "동물원은 바로 문을 잠갔어요.", "translation": "The zoo immediately locked the door.", "vocab": [{"ko": "잠그다", "en": "to lock", "note": "잠그다 → 잠갔어요 (past); ㅡ drops before 아/어"}, {"ko": "바로", "en": "immediately / right away", "note": ""}], "analysis": [{"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "Past polite ending. 잠그다 → stem 잠그 + 았어요 → ㅡ drops → 잠갔어요.", "example_in_sentence": "잠갔어요"}, {"type": "grammar", "label": "~을/를 (object marker)", "exp": "Direct object particle. 문 ends in a consonant → 문 + 을 = 문을.", "example_in_sentence": "문을"}, {"type": "grammar", "label": "~은/는 (topic marker)", "exp": "Topic particle. 동물원 ends in consonant ㄴ → 동물원 + 은 = 동물원은.", "example_in_sentence": "동물원은"}]}, {"text": "5살 수컷 오랑우탄이 울타리 옆 화단으로 떨어졌어요.", "translation": "A 5-year-old male orangutan fell into the flower bed next to the fence.", "vocab": [{"ko": "수컷", "en": "male (animal)", "note": "opposite: 암컷 (female animal)"}, {"ko": "화단", "en": "flower bed", "note": ""}, {"ko": "떨어지다", "en": "to fall / to drop", "note": "떨어지다 → 떨어졌어요 (past)"}], "analysis": [{"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "Past polite ending. 떨어지다 → stem 떨어지 + 었어요 → 떨어졌어요.", "example_in_sentence": "떨어졌어요"}, {"type": "grammar", "label": "~이/가 (subject marker)", "exp": "Subject particle. 오랑우탄 ends in consonant ㄴ → 오랑우탄 + 이 = 오랑우탄이.", "example_in_sentence": "오랑우탄이"}, {"type": "grammar", "label": "~(으)로 (means/direction)", "exp": "Marks direction of movement. 화단 ends in consonant ㄴ → 화단 + 으로 = 화단으로 (into the flower bed).", "example_in_sentence": "화단으로"}]}, {"text": "울타리 밖으로 나온 거예요.", "translation": "It had gotten outside the fence.", "vocab": [{"ko": "밖", "en": "outside", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)로 (means/direction)", "exp": "Marks direction of movement. 밖 ends in consonant ㄱ → 밖 + 으로 = 밖으로 (to the outside).", "example_in_sentence": "밖으로"}, {"type": "expression", "label": "~(으)ㄴ 거예요", "exp": "Explains a situation: 'it's that ~'. 나오다 → 나온 거예요 (it had come out).", "example_in_sentence": "나온 거예요"}]}, {"text": "그러자 어미 오랑우탄이 아기에게 갔어요.", "translation": "Then the mother orangutan went to the baby.", "vocab": [{"ko": "어미", "en": "mother (animal)", "note": "used for animal mothers; 엄마 is used for humans"}, {"ko": "가다", "en": "to go", "note": "가다 → 갔어요 (past)"}, {"ko": "그러자", "en": "then / at that moment", "note": "connects two events: 'and then / upon that'"}], "analysis": [{"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "Past polite ending. 가다 → stem 가 + 았어요 → vowel contracts → 갔어요.", "example_in_sentence": "갔어요"}, {"type": "grammar", "label": "~이/가 (subject marker)", "exp": "Subject particle. 오랑우탄 ends in consonant ㄴ → 오랑우탄 + 이 = 오랑우탄이.", "example_in_sentence": "오랑우탄이"}, {"type": "grammar", "label": "~에게/한테 (to person)", "exp": "Indirect object marker for animate beings. 아기 + 에게 = to the baby.", "example_in_sentence": "아기에게"}]}, {"text": "아기를 데리러 간 거예요.", "translation": "She had gone to fetch the baby.", "vocab": [{"ko": "데리다", "en": "to bring (a person/animal) along", "note": "데리러 가다 = go to pick up / go to get someone"}], "analysis": [{"type": "grammar", "label": "~(으)러 (purpose with movement)", "exp": "Expresses purpose of movement. 데리다 → stem 데리 + 러 + 가다 = 데리러 가다 (go to fetch/bring).", "example_in_sentence": "데리러"}, {"type": "grammar", "label": "~을/를 (object marker)", "exp": "Direct object particle. 아기 ends in vowel → 아기 + 를 = 아기를.", "example_in_sentence": "아기를"}, {"type": "expression", "label": "~(으)ㄴ 거예요", "exp": "Explains or clarifies the reason for a prior action. 가다 → 간 거예요 = 'It is that she went (to do something)'.", "example_in_sentence": "간 거예요"}]}, {"text": "어미는 방문객 보행로를 이용해서 전시 구역으로 돌아왔어요.", "translation": "The mother used the visitor walkway and returned to the exhibit area.", "vocab": [{"ko": "방문객", "en": "visitor", "note": ""}, {"ko": "보행로", "en": "walkway / footpath", "note": "보행 (walking) + 로 (road/path)"}, {"ko": "이용하다", "en": "to use / to make use of", "note": "이용해서 = using (and then)"}, {"ko": "돌아오다", "en": "to return / to come back", "note": "돌아오다 → 돌아왔어요 (past)"}], "analysis": [{"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "Past polite ending. 돌아오다 → stem 돌아오 + 았어요 → contracts → 돌아왔어요.", "example_in_sentence": "돌아왔어요"}, {"type": "grammar", "label": "~아/어서 (cause / sequence)", "exp": "Expresses sequence: 'and then / by doing'. 이용하다 → stem 이용하 + 여서 → contracts → 이용해서 (by using / using and then).", "example_in_sentence": "이용해서"}, {"type": "grammar", "label": "~을/를 (object marker)", "exp": "Direct object particle. 보행로 ends in vowel → 보행로 + 를 = 보행로를.", "example_in_sentence": "보행로를"}, {"type": "grammar", "label": "~은/는 (topic marker)", "exp": "Topic particle. 어미 ends in vowel → 어미 + 는 = 어미는.", "example_in_sentence": "어미는"}, {"type": "grammar", "label": "~(으)로 (means/direction)", "exp": "Marks direction of return. 구역 ends in consonant ㄱ → 구역 + 으로 = 구역으로 (to the exhibit area).", "example_in_sentence": "전시 구역으로"}]}, {"text": "스스로 돌아온 거예요.", "translation": "She came back on her own.", "vocab": [{"ko": "스스로", "en": "by oneself / on one's own", "note": "adverb; emphasises self-directed action"}], "analysis": [{"type": "expression", "label": "~(으)ㄴ 거예요", "exp": "Clarifies or explains a fact with mild emphasis. 돌아오다 → 돌아온 거예요 = 'It is that she came back (on her own)'.", "example_in_sentence": "돌아온 거예요"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mpi1m1cjdqrp' and md5(translation) = '29db3f270868de56d3ecc349cafe5eeb';
update public.article_cache set translation = $t${"texts": ["Five baby cheetahs were born on October 5, 2025, at the Smithsonian's Conservation Biology Institute in Front Royal, Virginia, USA.", "The cubs' mother is named Zura. She is five years old and takes good care of her babies.", "Baby cheetahs are born with their eyes closed, opening them after about four to seven days, and their ears are initially flat against their heads.", "The cubs gain about 50 grams of weight each day, and at six weeks old they will have their first veterinary exam.", "Cheetahs are the fastest land animals in the world, but their global population has dropped by more than 90 percent since 1900.", "The institute works to raise cheetahs in good health, and a total of 90 cheetahs have now been born at the facility."], "sentences": [{"text": "미국 버지니아주 스미스소니언 생물 보전 연구소에서 아기 치타 다섯 마리가 태어났어요.", "translation": "Five baby cheetahs were born at the Smithsonian Conservation Biology Institute in Virginia, USA.", "vocab": [{"ko": "치타", "en": "cheetah"}, {"ko": "태어나다", "en": "to be born"}, {"ko": "마리", "en": "counter for animals"}, {"ko": "연구소", "en": "research center"}], "analysis": [{"type": "grammar", "label": "~에서", "exp": "Locative particle indicating the place/location where an action occurs. 연구소 (research center) + ~에서 marks where the babies were born.", "example_in_sentence": "연구소에서"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense suffix. 태어나다 (to be born) becomes 태어났어요, indicating completed action in the past.", "example_in_sentence": "태어났어요"}]}, {"text": "태어난 날은 2025년 10월 5일이에요.", "translation": "The day they were born was October 5, 2025.", "vocab": [{"ko": "태어나다", "en": "to be born"}, {"ko": "날", "en": "day"}], "analysis": [{"type": "grammar", "label": "~은/는", "exp": "Topic-marking particle. 날 (day) + ~은 marks the topic being introduced in the sentence.", "example_in_sentence": "날은"}, {"type": "grammar", "label": "이에요", "exp": "Present tense copula. Connects the subject to a predicate noun, equivalent to 'is'.", "example_in_sentence": "이에요"}]}, {"text": "아기 치타들의 엄마 이름은 주라예요.", "translation": "The mother cheetah's name is Jura.", "vocab": [{"ko": "엄마", "en": "mother"}, {"ko": "이름", "en": "name"}], "analysis": [{"type": "grammar", "label": "~의", "exp": "Possessive particle. 치타들 (baby cheetahs) + ~의 shows possession, creating 'the baby cheetahs' mother'.", "example_in_sentence": "치타들의"}, {"type": "grammar", "label": "이에요/예요", "exp": "Polite 'is'. After a vowel, 이에요 becomes 예요: 주라 + 예요 = 주라예요 'is Jura'.", "example_in_sentence": "주라예요"}]}, {"text": "주라는 다섯 살이에요.", "translation": "Jura is five years old.", "vocab": [{"ko": "살", "en": "years old"}], "analysis": [{"type": "grammar", "label": "~는", "exp": "Topic-marking particle. 주라 (proper noun) + ~는 marks the subject being discussed.", "example_in_sentence": "주라는"}, {"type": "grammar", "label": "이에요", "exp": "Present tense copula. Connects subject to age predicate.", "example_in_sentence": "이에요"}]}, {"text": "주라는 아기들을 잘 돌봐 줘요.", "translation": "Jura takes good care of the babies.", "vocab": [{"ko": "돌보다", "en": "to care for; to look after"}], "analysis": [{"type": "grammar", "label": "~을/를", "exp": "Direct object marker. 아기들 (babies) + ~을 marks the target of the action 'care for'.", "example_in_sentence": "아기들을"}, {"type": "grammar", "label": "~아/어 주다", "exp": "Auxiliary construction expressing 'do something for someone'. 돌보다 becomes 돌봐, then + 주다, implying care done on behalf of others.", "example_in_sentence": "돌봐 줘요"}]}, {"text": "아기 치타들은 처음에 눈을 감고 태어나요.", "translation": "Baby cheetahs are born with their eyes closed at first.", "vocab": [{"ko": "처음", "en": "at first; initially"}, {"ko": "눈", "en": "eye"}, {"ko": "감다", "en": "to close"}], "analysis": [{"type": "grammar", "label": "~을/를", "exp": "Direct object marker. 눈 (eyes) + ~을 marks the target of the action 'close'.", "example_in_sentence": "눈을"}, {"type": "grammar", "label": "~고", "exp": "Connective suffix indicating sequential or accompanying actions. 감다 becomes 감고, combining 'closing eyes' with 'being born'.", "example_in_sentence": "감고"}]}, {"text": "4일에서 7일쯤 지나면 눈을 떠요.", "translation": "After about 4 to 7 days, they open their eyes.", "vocab": [{"ko": "일", "en": "day"}, {"ko": "지나다", "en": "to pass; to elapse"}, {"ko": "뜨다", "en": "to open"}], "analysis": [{"type": "grammar", "label": "~에서", "exp": "Range marker in temporal expressions. 4일 to 7일 + ~에서 indicates a time range of 4-7 days.", "example_in_sentence": "4일에서 7일쯤"}, {"type": "grammar", "label": "~(으)면", "exp": "Ending meaning 'if / when'. 지나다 → 지나면 'when (the days) pass'.", "example_in_sentence": "지나면"}]}, {"text": "귀도 처음에는 머리에 붙어 있어요.", "translation": "At first, their ears are also attached to the head.", "vocab": [{"ko": "귀", "en": "ear"}, {"ko": "머리", "en": "head"}, {"ko": "붙다", "en": "to be attached"}], "analysis": [{"type": "grammar", "label": "~도", "exp": "Additive particle meaning 'also'. 귀 (ears) + ~도 indicates ears are mentioned in addition to eyes.", "example_in_sentence": "귀도"}, {"type": "grammar", "label": "~에", "exp": "Locative particle. 머리 (head) + ~에 marks where ears are attached/located.", "example_in_sentence": "머리에"}, {"type": "grammar", "label": "~어 있다", "exp": "State/continuative aspect. 붙다 becomes 붙어 있어요, indicating a state of being attached.", "example_in_sentence": "붙어 있어요"}]}, {"text": "아기 치타들은 매일 약 50그램씩 무거워져요.", "translation": "The baby cheetahs get about 50 grams heavier every day.", "vocab": [{"ko": "매일", "en": "every day"}, {"ko": "약", "en": "about; approximately"}, {"ko": "무겁다", "en": "to be heavy"}], "analysis": [{"type": "grammar", "label": "~씩", "exp": "Distribution/unit marker. 50그램 (50 grams) + ~씩 indicates the amount per each day.", "example_in_sentence": "50그램씩"}, {"type": "grammar", "label": "~어지다", "exp": "Change of state suffix. 무겁다 becomes 무거워져요, indicating they become heavier (gradual change).", "example_in_sentence": "무거워져요"}]}, {"text": "여섯 주가 지나면 첫 번째 병원 검사를 받아요.", "translation": "After six weeks pass, they receive their first veterinary checkup.", "vocab": [{"ko": "주", "en": "week"}, {"ko": "지나다", "en": "to pass"}, {"ko": "검사", "en": "checkup; examination"}, {"ko": "받다", "en": "to receive"}], "analysis": [{"type": "grammar", "label": "~가", "exp": "Subject marker. 여섯 주 (six weeks) + ~가 marks the subject that does the action of passing.", "example_in_sentence": "주가"}, {"type": "grammar", "label": "~(으)면", "exp": "Ending meaning 'if / when'. 지나다 → 지나면 'when (six weeks) pass'.", "example_in_sentence": "지나면"}, {"type": "grammar", "label": "~을/를", "exp": "Direct object marker. 검사 (checkup) + ~를 marks the object being received.", "example_in_sentence": "검사를"}]}, {"text": "치타는 세계에서 가장 빠른 땅 위 동물이에요.", "translation": "The cheetah is the fastest land animal in the world.", "vocab": [{"ko": "세계", "en": "world"}, {"ko": "빠르다", "en": "to be fast"}, {"ko": "땅", "en": "land; ground"}, {"ko": "동물", "en": "animal"}], "analysis": [{"type": "grammar", "label": "~에서", "exp": "Locative/scope particle. 세계 (world) + ~에서 marks the scope within which the superlative applies.", "example_in_sentence": "세계에서"}, {"type": "grammar", "label": "가장", "exp": "Superlative adverb meaning 'most'. Modifies 빠른 (fast) to create the superlative 'fastest'.", "example_in_sentence": "가장 빠른"}]}, {"text": "지금 치타는 수가 많이 줄었어요.", "translation": "Currently, the cheetah population has decreased significantly.", "vocab": [{"ko": "지금", "en": "now; currently"}, {"ko": "수", "en": "number; quantity"}, {"ko": "줄다", "en": "to decrease; to reduce"}], "analysis": [{"type": "grammar", "label": "~이/가", "exp": "Subject marker. 수 (number/quantity) + ~가 marks the subject of the sentence.", "example_in_sentence": "수가"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense suffix. 줄다 becomes 줄었어요, indicating a completed action in the past.", "example_in_sentence": "줄었어요"}]}, {"text": "1900년보다 90퍼센트 넘게 줄었어요.", "translation": "It has decreased by over 90 percent compared to 1900.", "vocab": [{"ko": "넘다", "en": "to exceed; to go over"}], "analysis": [{"type": "grammar", "label": "~보다", "exp": "Comparative particle. 1900년 (the year 1900) + ~보다 marks the comparison point.", "example_in_sentence": "1900년보다"}, {"type": "grammar", "label": "~게", "exp": "Adverbial suffix. 넘다 becomes 넘게, functioning as an adverb modifying 줄었어요.", "example_in_sentence": "넘게"}]}, {"text": "이 연구소에서는 치타를 건강하게 키워요.", "translation": "This research center raises cheetahs healthily.", "vocab": [{"ko": "연구소", "en": "research center"}, {"ko": "건강하다", "en": "to be healthy"}, {"ko": "키우다", "en": "to raise; to bring up"}], "analysis": [{"type": "grammar", "label": "~에서는", "exp": "Locative + topic particle. 연구소 + ~에서는 marks the location as the topic of discussion.", "example_in_sentence": "연구소에서는"}, {"type": "grammar", "label": "~을/를", "exp": "Direct object marker. 치타 (cheetah) + ~를 marks the object being raised.", "example_in_sentence": "치타를"}, {"type": "grammar", "label": "~게", "exp": "Adverbial suffix. 건강하다 becomes 건강하게, modifying 키워요 to mean 'raise in a healthy manner'.", "example_in_sentence": "건강하게"}]}, {"text": "지금까지 이 연구소에서 치타 90마리가 태어났어요.", "translation": "So far, 90 cheetahs have been born at this research center.", "vocab": [{"ko": "지금까지", "en": "so far; up to now"}, {"ko": "마리", "en": "counter for animals"}, {"ko": "태어나다", "en": "to be born"}], "analysis": [{"type": "grammar", "label": "~까지", "exp": "Extent/limit particle. 지금 + ~까지 creates 'up to now', indicating a duration from past to present.", "example_in_sentence": "지금까지"}, {"type": "grammar", "label": "~이/가", "exp": "Subject marker. 치타 90마리 (90 cheetahs) + ~가 marks the subject of the action.", "example_in_sentence": "마리가"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense suffix. 태어나다 becomes 태어났어요, indicating completed action from past to now.", "example_in_sentence": "태어났어요"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mv2d28mo2ha3' and md5(translation) = '336a79b4209faa740e726257dc84ea6c';
update public.article_cache set translation = $t${"texts": ["Bora, formerly of SISTAR, appeared on the YouTube channel 'No Back Tak,' where she talked about her dating style and breakup experience.", "Bora said, 'I tend to take good care of others, so people say I'm like a mom,' but added that she also wants to be on the receiving end of care.", "Bora also spoke about her personality, saying she talks seriously about issues only when the same problem comes up several times.", "When asked about her hardest breakup, Bora shared that at 3 p.m. her boyfriend texted her saying he was going to do something, but by 5 p.m. she received a call saying they should break up.", "Bora revealed that her ex said he had been thinking about it beforehand but never said anything, and she expressed that he should have at least given a hint instead of simply saying 'live well.'"], "sentences": [{"text": "시스타 출신 보라가 유튜브 채널 '노빽탁'에 나왔어요.", "translation": "Bora, from Sistar, appeared on the YouTube channel 'Nobbyeok Tak'.", "vocab": [{"ko": "출신", "en": "(originally) from; former member of"}, {"ko": "채널", "en": "channel"}, {"ko": "나오다", "en": "to appear; to come out"}], "analysis": []}, {"text": "보라는 이 방송에서 자신의 연애 스타일과 이별 경험을 이야기했어요.", "translation": "On this broadcast, Bora talked about her dating style and breakup experiences.", "vocab": [{"ko": "방송", "en": "broadcast; program"}, {"ko": "연애", "en": "dating; romantic relationship"}, {"ko": "이별", "en": "breakup; parting"}, {"ko": "경험", "en": "experience"}], "analysis": [{"type": "grammar", "label": "~에서", "exp": "Locative/contextual particle indicating the setting or location of an action. '방송에서' = on the broadcast.", "example_in_sentence": "방송에서"}]}, {"text": "보라는 \"저는 상대방을 잘 챙겨요.", "translation": "Bora said, \"I take good care of the other person.", "vocab": [{"ko": "상대방", "en": "the other person; partner"}, {"ko": "챙기다", "en": "to take care of; to look after"}], "analysis": []}, {"text": "그래서 사람들이 저를 엄마 같다고 해요\"라고 말했어요.", "translation": "So people say I'm like a mom,\" she said.", "vocab": [{"ko": "그래서", "en": "so; therefore; that's why"}, {"ko": "사람", "en": "person; people"}, {"ko": "엄마", "en": "mother; mom"}], "analysis": [{"type": "grammar", "label": "N 같다", "exp": "'To be like N': 엄마 같다 = 'is like a mom'.", "example_in_sentence": "엄마 같다"}, {"type": "grammar", "label": "~다고 하다", "exp": "Reported speech construction. '같다고 해요' = 'say/tell that (it) is like'; reports what others say.", "example_in_sentence": "같다고 해요"}]}, {"text": "하지만 보라는 \"저도 사실 누군가에게 받고 싶어요\"라고 했어요.", "translation": "However, Bora said, \"Actually, I want to be on the receiving end from someone too.\"", "vocab": [{"ko": "하지만", "en": "but; however"}, {"ko": "사실", "en": "actually; in fact"}, {"ko": "누군가", "en": "someone; somebody"}, {"ko": "받다", "en": "to receive; to take"}], "analysis": [{"type": "grammar", "label": "~에게 (from)", "exp": "With 받다, 에게 marks the giver, 'from': 누군가에게 받다 = 'receive from someone'.", "example_in_sentence": "누군가에게"}, {"type": "grammar", "label": "~고 싶다", "exp": "Desiderative expression meaning 'want to'. '받고 싶어요' = 받다(receive) + 고 싶어요(want to).", "example_in_sentence": "받고 싶어요"}]}, {"text": "보라는 또 자신의 성격에 대해서도 이야기했어요.", "translation": "Bora also talked about her personality.", "vocab": [{"ko": "또", "en": "also; moreover; again"}, {"ko": "자신", "en": "oneself; one's own"}, {"ko": "성격", "en": "personality; character"}], "analysis": [{"type": "grammar", "label": "~에 대해(서)", "exp": "Postposition phrase meaning 'about; concerning; regarding'. Shows the topic of discussion.", "example_in_sentence": "성격에 대해서"}, {"type": "grammar", "label": "~도", "exp": "Particle 'also; too'. '대해서도' adds emphasis that this is another topic discussed.", "example_in_sentence": "대해서도"}]}, {"text": "그는 \"같은 문제가 여러 번 생기면 그때 진지하게 이야기해요\"라고 말했어요.", "translation": "She said, \"If the same problem occurs multiple times, then I talk seriously about it.\"", "vocab": [{"ko": "같다", "en": "to be the same"}, {"ko": "문제", "en": "problem; issue"}, {"ko": "여러", "en": "several; multiple"}, {"ko": "번", "en": "time(s); occasion(s)"}], "analysis": [{"type": "grammar", "label": "~(으)면", "exp": "Ending meaning 'if / when'. 생기다 → 생기면 'if (the same problem) comes up'.", "example_in_sentence": "생기면"}, {"type": "grammar", "label": "~게", "exp": "Adverbial ending forming an adverb from adjective. '진지하게' = 진지하다(serious) + 게 (in a serious manner).", "example_in_sentence": "진지하게"}]}, {"text": "가장 힘든 이별에 대한 질문도 있었어요.", "translation": "There was also a question about the most difficult breakup.", "vocab": [{"ko": "가장", "en": "most; the most"}, {"ko": "힘들다", "en": "to be hard; to be difficult"}, {"ko": "질문", "en": "question; query"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Turns an adjective into a noun modifier. 힘들다 drops its ㄹ: 힘들다 → 힘든 이별 'a hard breakup'.", "example_in_sentence": "힘든"}, {"type": "grammar", "label": "~도", "exp": "Particle meaning 'also'. '질문도' = there was also a question.", "example_in_sentence": "질문도"}]}, {"text": "보라는 오후 3시에 남자 친구에게 \"나 뭐 좀 하고 올게\"라는 연락을 받았어요.", "translation": "Bora received a message from her boyfriend at 3 PM saying \"I'll do something and be back.\"", "vocab": [{"ko": "오후", "en": "afternoon; PM"}, {"ko": "남자 친구", "en": "boyfriend"}, {"ko": "연락", "en": "contact; message; communication"}], "analysis": [{"type": "grammar", "label": "~에게", "exp": "Dative particle 'to; from'. '친구에게' marks the source of the message.", "example_in_sentence": "친구에게"}, {"type": "grammar", "label": "~(이)라는 (quoted modifier)", "exp": "Short for 라고 하는: links a quote to a noun. \"…올게\"라는 연락 = 'a message saying \"…\"'.", "example_in_sentence": "라는 연락"}]}, {"text": "그런데 오후 5시에 \"우리 헤어져야 할 것 같아\"라는 전화를 받았어요.", "translation": "But at 5 PM, she received a phone call saying \"I think we should break up.\"", "vocab": [{"ko": "그런데", "en": "but; however; yet"}, {"ko": "헤어지다", "en": "to break up; to separate; to part"}, {"ko": "전화", "en": "phone call; telephone"}], "analysis": [{"type": "grammar", "label": "~아/어야 하다", "exp": "Obligation/necessity marker meaning 'must; have to; should'. '헤어져야 하다' = must break up.", "example_in_sentence": "헤어져야"}, {"type": "grammar", "label": "~ㄹ 것 같다", "exp": "Conjecture/supposition meaning 'seems like; appears to'. '할 것 같아' = seems/appears to (need to break up).", "example_in_sentence": "할 것 같아"}]}, {"text": "보라는 남자 친구가 \"미리 생각하고 있었지만 말을 안 했다\"고 했다고 전했어요.", "translation": "Bora conveyed that her boyfriend said he had been thinking about it beforehand but didn't tell her.", "vocab": [{"ko": "미리", "en": "beforehand; in advance; previously"}, {"ko": "생각하다", "en": "to think"}], "analysis": [{"type": "grammar", "label": "~고 있었다", "exp": "Progressive past tense. '생각하고 있었다' = was thinking (ongoing action in past).", "example_in_sentence": "생각하고 있었지만"}, {"type": "grammar", "label": "~지만", "exp": "Conjunctive ending meaning 'but; although; yet'. Connects contrasting clauses.", "example_in_sentence": "있었지만"}, {"type": "grammar", "label": "~다고 하다 (reported speech)", "exp": "Reports someone's words. Here it is stacked: he said \"…안 했다\" (했다고), and Bora passed that on (전했어요).", "example_in_sentence": "했다고 전했어요"}]}, {"text": "보라는 \"그러면 적어도 힌트라도 줘야 해요.", "translation": "Bora said, \"Then you should at least give a hint.", "vocab": [{"ko": "그러면", "en": "then; in that case; if so"}, {"ko": "적어도", "en": "at least; at the minimum"}, {"ko": "힌트", "en": "hint; clue"}, {"ko": "주다", "en": "to give"}], "analysis": [{"type": "grammar", "label": "~라도", "exp": "Particle meaning 'at least; even if only'. '힌트라도' = even just a hint.", "example_in_sentence": "힌트라도"}, {"type": "grammar", "label": "~아/어야 하다", "exp": "'Have to; should'. 주다 → 줘야 해요 'should give'.", "example_in_sentence": "줘야 해요"}]}, {"text": "그냥 '잘 살아'라는 식이었어요\"라고 말했어요.", "translation": "It was just like, 'Have a good life,'\" she said.", "vocab": [{"ko": "그냥", "en": "just; simply; merely"}, {"ko": "식", "en": "way; style; manner"}], "analysis": [{"type": "expression", "label": "~라는 식", "exp": "Expression meaning 'in a manner/way of saying...'. Describes how something was said or done.", "example_in_sentence": "'잘 살아'라는 식"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense polite ending. '이었어요' = 이다(be) + 었어요 (past polite).", "example_in_sentence": "이었어요"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mv2w1oebmqjf' and md5(translation) = 'f4bbf9e027dbc54657a4a9b290d7095f';
update public.article_cache set translation = $t${"texts": ["Canadian writer Anne Carson has been awarded the 2026 Nobel Prize in Literature. As a poet, translator, classicist, essayist, and visual artist, she has expanded the boundaries of contemporary literature for over four decades.", "What stands out most in Carson's work is not the originality of form, but her ability to make thought itself a literary event. By connecting scholarship and creative writing as one, she has demonstrated that intellectual writing and imagination can enrich each other.", "Carson is also well known for her deep exploration of ancient Greek literature. She regards ancient writers such as Sappho, Simonides, Sophocles, and Euripides not as mere objects of study but as conversational partners. In her writing, the voices of antiquity connect with the present through themes such as desire, sorrow, loss, and death.", "Her work repeatedly addresses the theme of distance: distance between lovers, distance between languages, and distance between the living and the dead. Carson portrays desire not as a movement toward possession but as an encounter with absence, finding both suffering and possibility in the gaps and intervals within human experience.", "This thematic consciousness is intimately connected with formal experimentation. In works such as \"Eros the Bittersweet,\" \"Autobiography of Red,\" \"Beauty of the Husband,\" \"Nox,\" and \"Float,\" she employs fragmentation, quotation, rupture, and collage techniques. These forms are not decoration but methods of inquiry.", "Carson's influence is already evident among younger generations of writers and scholars. The growing number of those who move freely between criticism, translation, poetry, and prose has learned intellectual freedom from Carson's approach to writing. The Nobel Prize in Literature has often recognized writers who have expanded the possibilities of literature, and Anne Carson is clearly one such writer."], "sentences": [{"text": "캐나다 작가 앤 카슨이 2026년 노벨 문학상을 받게 되었습니다.", "translation": "Canadian writer Anne Carson has been awarded the 2026 Nobel Prize in Literature.", "vocab": [{"ko": "노벨 문학상", "en": "Nobel Prize in Literature"}], "analysis": [{"type": "grammar", "label": "~게 되다", "exp": "Expresses a change of state or resultant condition; marks an unexpected or inevitable outcome. Chain: 받다 → 받게 되다.", "example_in_sentence": "받게 되었습니다"}]}, {"text": "그는 시인, 번역가, 고전학자, 수필가, 시각 예술가로 활동하면서 40년 이상 현대 문학의 경계를 넓혀 왔습니다.", "translation": "Working as a poet, translator, classicist, essayist and visual artist, she has been widening the boundaries of contemporary literature for over 40 years.", "vocab": [{"ko": "고전학자", "en": "classicist; classical scholar"}, {"ko": "수필가", "en": "essayist"}, {"ko": "경계를 넓히다", "en": "expand boundaries; broaden horizons"}], "analysis": [{"type": "grammar", "label": "~(으)면서", "exp": "'While (doing)': two things happen at the same time. 활동하다 → 활동하면서 'while working (as)'.", "example_in_sentence": "활동하면서"}, {"type": "grammar", "label": "~아/어 왔다", "exp": "Auxiliary verb construction marking a continuous action from past to present. Chain: 넓히다 → 넓혀 왔다.", "example_in_sentence": "넓혀 왔습니다"}]}, {"text": "카슨의 작품에서 가장 주목할 점은 형식의 독창성보다는 사유 자체를 문학적 사건으로 만드는 능력입니다.", "translation": "The most noteworthy point in Carson's works is the ability to make thought itself into a literary event, rather than the originality of form.", "vocab": [{"ko": "주목하다", "en": "pay attention to; notice"}, {"ko": "독창성", "en": "originality; uniqueness"}, {"ko": "사유", "en": "thought; reflection; thinking"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 점", "exp": "A prospective modifier + 점 'point': 주목하다 → 주목할 점 'a point worth noting'.", "example_in_sentence": "주목할 점"}, {"type": "expression", "label": "~보다는", "exp": "Contrastive particle marking preference or shift of focus; indicates 'rather than' or 'instead of'. Compares two entities.", "example_in_sentence": "독창성보다는"}]}, {"text": "학문과 창작을 하나로 연결하면서 지적인 글쓰기와 상상력이 서로를 풍요롭게 할 수 있다는 것을 보여 주었습니다.", "translation": "By connecting scholarship and creative work as one, she demonstrated that intellectual writing and imagination can mutually enrich each other.", "vocab": [{"ko": "학문", "en": "scholarship; learning; academics"}, {"ko": "풍요롭게 하다", "en": "enrich; make abundant"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 수 있다", "exp": "'Can; be able to'. 하다 → 할 수 있다 'can (enrich)'.", "example_in_sentence": "할 수 있다"}, {"type": "grammar", "label": "~다는 것", "exp": "Turns a whole statement into a noun, 'the fact that…': 할 수 있다 → 할 수 있다는 것을 보여 주다 'show that (they) can…'.", "example_in_sentence": "할 수 있다는 것을"}]}, {"text": "카슨은 고대 그리스 문학을 깊이 탐구하는 것으로도 잘 알려져 있습니다.", "translation": "Carson is also well known for deeply exploring ancient Greek literature.", "vocab": [{"ko": "탐구하다", "en": "explore; investigate; probe"}], "analysis": [{"type": "grammar", "label": "~는 것으로", "exp": "Nominalizing suffix + instrumental particle; marks the means or basis for which something is known. Chain: 탐구하다 → 탐구하는 것으로.", "example_in_sentence": "탐구하는 것으로도"}, {"type": "grammar", "label": "~아/어 있다 (state)", "exp": "Shows a resulting state: 알려지다 'to become known' → 알려져 있다 'is known'.", "example_in_sentence": "알려져 있습니다"}]}, {"text": "사포, 시모니데스, 소포클레스, 에우리피데스 같은 고대 작가들을 단순한 연구 대상이 아니라 대화 상대로 여기기 때문입니다.", "translation": "Because she regards ancient writers such as Sappho, Simonides, Sophocles, and Euripides not as mere objects of study but as conversation partners.", "vocab": [{"ko": "여기다", "en": "regard; view; consider"}], "analysis": [{"type": "expression", "label": "~이 아니라", "exp": "Contrastive negation particle; marks explicit rejection of one thing in favor of another. Negates and introduces alternative.", "example_in_sentence": "대상이 아니라"}, {"type": "grammar", "label": "~기 때문이다", "exp": "Causal nominalizing suffix; marks the reason or cause. Chain: 여기다 → 여기기 때문이다.", "example_in_sentence": "여기기 때문입니다"}]}, {"text": "그의 글 속에서 고대의 목소리는 욕망, 슬픔, 상실, 죽음 같은 주제를 통해 현재와 연결됩니다.", "translation": "In her writing, ancient voices connect with the present through themes such as desire, sorrow, loss and death.", "vocab": [{"ko": "목소리", "en": "voice; sound"}, {"ko": "상실", "en": "loss; deprivation"}], "analysis": [{"type": "grammar", "label": "~을 통해", "exp": "Particle marking means or medium; 'through' or 'by means of'. Indicates channel of connection.", "example_in_sentence": "주제를 통해"}]}, {"text": "그의 작품은 거리라는 주제를 반복해서 다룹니다.", "translation": "Her works return again and again to the theme of distance.", "vocab": [{"ko": "거리", "en": "distance; gap; space"}, {"ko": "다루다", "en": "deal with; handle; treat"}], "analysis": [{"type": "grammar", "label": "~(이)라는", "exp": "Links a name or label to a noun, 'called / of': 거리라는 주제 'the theme of distance'.", "example_in_sentence": "거리라는 주제"}]}, {"text": "연인 사이의 거리, 언어와 언어 사이의 거리, 산 자와 죽은 자 사이의 거리가 그것입니다.", "translation": "They are the distance between lovers, the distance between languages, and the distance between the living and the dead.", "vocab": [{"ko": "연인", "en": "lover; beloved; sweetheart"}], "analysis": []}, {"text": "카슨은 욕망을 소유를 향한 움직임이 아니라 부재와의 만남으로 그려 내며, 인간 경험 속의 틈과 간격에서 고통과 가능성을 동시에 찾아냅니다.", "translation": "Carson depicts desire not as movement toward possession but as an encounter with absence, and simultaneously finds suffering and possibility in the gaps and spaces within human experience.", "vocab": [{"ko": "욕망", "en": "desire; wanting; craving"}, {"ko": "소유", "en": "possession; ownership"}, {"ko": "부재", "en": "absence; non-presence"}, {"ko": "틈", "en": "gap; crack; fissure"}], "analysis": [{"type": "expression", "label": "~을/를 향한", "exp": "Relative particle marking direction or aim; 'directed toward' or 'aimed at'.", "example_in_sentence": "소유를 향한 움직임"}, {"type": "grammar", "label": "~(으)며", "exp": "Connective suffix expressing multiple concurrent or sequential actions; and/while/at the same time. Chain: 그려내다 → 그려 내며.", "example_in_sentence": "그려 내며"}, {"type": "expression", "label": "N 속의", "exp": "속 'inside' + 의 links it to the next noun: 인간 경험 속의 틈 'the gaps within human experience'.", "example_in_sentence": "경험 속의 틈"}]}, {"text": "이러한 주제 의식은 형식 실험과 긴밀하게 연결되어 있습니다.", "translation": "This thematic consciousness is closely connected to formal experimentation.", "vocab": [{"ko": "주제 의식", "en": "thematic consciousness; awareness of theme"}, {"ko": "긴밀하다", "en": "close; tight; intimate"}], "analysis": [{"type": "grammar", "label": "~아/어 있다", "exp": "Auxiliary marking state or resultant condition of a completed action. Chain: 연결되다 → 연결되어 있다.", "example_in_sentence": "연결되어 있습니다"}]}, {"text": "『에로스, 쓴 달콤함』, 『붉음의 자서전』, 『남편의 아름다움』, 『녹스』, 『플로트』 등의 작품에서 단편화, 인용, 단절, 콜라주 기법을 사용합니다.", "translation": "In works such as 'Eros the Bittersweet', 'Autobiography of Red', 'Beauty of the Husband', 'Nox', and 'Float', she employs fragmentation, quotation, disjunction, and collage techniques.", "vocab": [{"ko": "단편화", "en": "fragmentation; breaking into fragments"}, {"ko": "인용", "en": "quotation; citation"}, {"ko": "단절", "en": "disconnection; rupture; break"}], "analysis": []}, {"text": "이러한 형식은 장식이 아니라 탐구의 방식입니다.", "translation": "Such form is not decoration but a method of inquiry.", "vocab": [{"ko": "장식", "en": "decoration; ornament"}], "analysis": [{"type": "expression", "label": "~이 아니라", "exp": "Contrastive negation; rejects first proposition and asserts second.", "example_in_sentence": "장식이 아니라"}]}, {"text": "카슨의 영향은 이미 젊은 세대의 작가들과 학자들에게서 나타나고 있습니다.", "translation": "Carson's influence is already showing in writers and scholars of the younger generation.", "vocab": [{"ko": "영향", "en": "influence; impact; effect"}], "analysis": [{"type": "grammar", "label": "~고 있다", "exp": "Auxiliary marking progressive or ongoing action. Chain: 나타나다 → 나타나고 있다.", "example_in_sentence": "나타나고 있습니다"}]}, {"text": "비평, 번역, 시, 산문 사이를 자유롭게 오가는 이들이 늘어난 것은 카슨의 작업 방식에서 지적 자유를 배웠기 때문입니다.", "translation": "The increase in those who freely move between criticism, translation, poetry, and prose is because they learned intellectual freedom from Carson's working methods.", "vocab": [{"ko": "비평", "en": "criticism; critique"}, {"ko": "오가다", "en": "come and go; move back and forth; shuttle"}, {"ko": "늘어나다", "en": "increase; grow; expand"}], "analysis": [{"type": "grammar", "label": "~는 이들", "exp": "Relative modifier + noun; marks those performing the action. Chain: 오가다 → 오가는 이들.", "example_in_sentence": "오가는 이들"}, {"type": "grammar", "label": "~기 때문이다", "exp": "Causal nominalizing suffix marking reason or cause for preceding clause.", "example_in_sentence": "배웠기 때문입니다"}]}, {"text": "노벨 문학상은 문학의 가능성을 확장한 작가들을 자주 인정해 왔는데, 앤 카슨은 분명 그 자리에 속하는 작가입니다.", "translation": "The Nobel Prize in Literature has frequently recognized writers who expanded literary possibilities, and Anne Carson is clearly a writer who belongs in that place.", "vocab": [{"ko": "확장하다", "en": "expand; extend; widen"}, {"ko": "인정하다", "en": "acknowledge; recognize; admit"}, {"ko": "속하다", "en": "belong to; be part of; fall into"}], "analysis": [{"type": "grammar", "label": "~아/어 왔다", "exp": "Auxiliary marking repeated or continuous action from past to present. Chain: 인정하다 → 인정해 왔다.", "example_in_sentence": "인정해 왔는데"}, {"type": "grammar", "label": "~는데", "exp": "Connective ending marking contrast, background, or transition between clauses.", "example_in_sentence": "왔는데"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mv2w8e4ewpkw' and md5(translation) = '9e30de28dffd6fe5c7d700f91e26fcf4';
update public.article_cache set translation = $t${"texts": ["Very large tortoises live on an island in the Indian Ocean called Aldabra, and a survey found about 180,000 of them there.", "In the 1800s, there were fewer than 1,000 tortoises, but people worked to protect them and the island became a nature reserve in 1981.", "The number of tortoises has grown greatly, and researchers said this is very good news.", "However, there are concerns — cats and rats eat tortoise eggs, the climate is also changing, and people want to keep protecting the tortoises."], "sentences": [{"text": "아주 큰 거북이들이 인도양의 섬에 살고 있어요.", "translation": "Very large turtles are living on an island in the Indian Ocean.", "vocab": [{"ko": "거북이", "en": "turtle"}, {"ko": "인도양", "en": "Indian Ocean"}, {"ko": "섬", "en": "island"}, {"ko": "살다", "en": "to live"}], "analysis": [{"type": "grammar", "label": "~고 있어요", "exp": "Shows an ongoing action or state: 살다 → 살고 있어요 'are living'.", "example_in_sentence": "살고 있어요"}]}, {"text": "섬 이름은 알다브라예요.", "translation": "The island's name is Aldabra.", "vocab": [{"ko": "섬", "en": "island"}, {"ko": "이름", "en": "name"}], "analysis": [{"type": "grammar", "label": "이에요/예요", "exp": "Polite 'is'. After a vowel use 예요: 알다브라 + 예요 = 'is Aldabra'.", "example_in_sentence": "알다브라예요"}]}, {"text": "조사를 했는데 거북이가 약 18만 마리 있어요.", "translation": "A survey was conducted, and there are approximately 180,000 turtles.", "vocab": [{"ko": "조사", "en": "survey; investigation"}, {"ko": "하다", "en": "to do"}, {"ko": "마리", "en": "counter for animals"}, {"ko": "있다", "en": "to exist; to have"}], "analysis": [{"type": "grammar", "label": "~는데 (background)", "exp": "Gives background before the main point: 하다 → 했는데 '(they) did (a survey), and…'.", "example_in_sentence": "했는데"}, {"type": "grammar", "label": "~을/를", "exp": "Direct object particle. Marks the noun as the object of the preceding verb. 조사 (survey) + 를.", "example_in_sentence": "조사를"}]}, {"text": "1800년대에는 거북이가 1,000마리도 없었어요.", "translation": "In the 1800s, there were not even 1,000 turtles.", "vocab": [{"ko": "1800년대", "en": "1800s"}, {"ko": "없다", "en": "to not exist; to not have"}], "analysis": [{"type": "grammar", "label": "~았/었어요", "exp": "Past tense marker for completed action or state. 없다 (to not exist) + 었어요 → 없었어요.", "example_in_sentence": "없었어요"}, {"type": "grammar", "label": "~도", "exp": "Particle indicating emphasis or 'even'. Shows that even 1,000 turtles did not exist. 1,000마리 + 도.", "example_in_sentence": "1,000마리도"}]}, {"text": "그런데 사람들이 거북이를 지켜줬어요.", "translation": "However, people protected the turtles.", "vocab": [{"ko": "사람", "en": "person; people"}, {"ko": "거북이", "en": "turtle"}, {"ko": "지키다", "en": "to protect; to guard"}], "analysis": [{"type": "grammar", "label": "~아/어주다", "exp": "Auxiliary verb expressing action done for someone's benefit or as a favor. 지키다 (to protect) + 어주다 → 지켜줬어요 (past tense).", "example_in_sentence": "지켜줬어요"}]}, {"text": "1981년에 이 섬은 자연 보호 구역이 됐어요.", "translation": "In 1981, this island became a nature conservation area.", "vocab": [{"ko": "자연", "en": "nature"}, {"ko": "보호", "en": "protection"}, {"ko": "구역", "en": "area; zone"}, {"ko": "되다", "en": "to become"}], "analysis": [{"type": "grammar", "label": "~이/가 되다", "exp": "'To become N': 구역 + 이 되다 → 구역이 됐어요 'became a (protected) area'.", "example_in_sentence": "구역이 됐어요"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense marker. 되다 (to become) + 었어요 → 됐어요.", "example_in_sentence": "됐어요"}]}, {"text": "지금은 거북이 수가 많이 늘었어요.", "translation": "Now the number of turtles has increased a lot.", "vocab": [{"ko": "지금", "en": "now"}, {"ko": "수", "en": "number; quantity"}, {"ko": "늘다", "en": "to increase; to grow"}], "analysis": [{"type": "grammar", "label": "~았/었어요", "exp": "Past tense marker. 늘다 (to increase) + 었어요 → 늘었어요.", "example_in_sentence": "늘었어요"}]}, {"text": "연구자들은 이것이 아주 좋은 소식이라고 했어요.", "translation": "Researchers said this is very good news.", "vocab": [{"ko": "연구자", "en": "researcher"}, {"ko": "소식", "en": "news"}, {"ko": "좋다", "en": "to be good"}], "analysis": [{"type": "grammar", "label": "~(이)라고 하다", "exp": "Reports what someone said: 좋은 소식이다 → 좋은 소식이라고 했어요 'said (it) was good news'.", "example_in_sentence": "좋은 소식이라고"}, {"type": "grammar", "label": "~았/었/였어요", "exp": "Past polite. 하다 → 했어요 'said'.", "example_in_sentence": "했어요"}]}, {"text": "하지만 걱정도 있어요.", "translation": "However, there is also concern.", "vocab": [{"ko": "걱정", "en": "concern; worry"}, {"ko": "있다", "en": "to exist; to have"}], "analysis": [{"type": "grammar", "label": "~도", "exp": "Particle indicating 'also' or 'as well'. Shows additional concern alongside good news. 걱정 + 도.", "example_in_sentence": "걱정도"}]}, {"text": "고양이와 쥐가 거북이 알을 먹어요.", "translation": "Cats and rats eat turtle eggs.", "vocab": [{"ko": "고양이", "en": "cat"}, {"ko": "쥐", "en": "rat; mouse"}, {"ko": "알", "en": "egg"}, {"ko": "먹다", "en": "to eat"}], "analysis": [{"type": "grammar", "label": "~과/와", "exp": "Coordinating conjunction particle joining nouns. 고양이 (cat) + 와 + 쥐 (rat).", "example_in_sentence": "고양이와"}]}, {"text": "날씨도 변하고 있어요.", "translation": "The weather is also changing.", "vocab": [{"ko": "날씨", "en": "weather"}, {"ko": "변하다", "en": "to change"}], "analysis": [{"type": "grammar", "label": "~고 있어요", "exp": "Progressive aspect marker indicating ongoing action. 변하다 (to change) + 고 있어요.", "example_in_sentence": "변하고 있어요"}]}, {"text": "사람들은 거북이를 계속 지키고 싶어 해요.", "translation": "People want to continue protecting turtles.", "vocab": [{"ko": "사람", "en": "person; people"}, {"ko": "거북이", "en": "turtle"}, {"ko": "계속", "en": "continually; continuously"}, {"ko": "지키다", "en": "to protect; to guard"}], "analysis": [{"type": "grammar", "label": "~고 싶어 하다", "exp": "'Want to' for other people (not I/you): 지키다 → 지키고 싶어 해요 'want to protect'.", "example_in_sentence": "지키고 싶어 해요"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mv4bayrf6xnu' and md5(translation) = '32a72773af84207df2bf71caf4d06e39';
update public.article_cache set translation = $t${"texts": ["Honey Ross (28), daughter of British TV presenter Jonathan Ross, is learning Welsh using the Duolingo app.", "Her boyfriend Gav Murphy (41) is originally from Wales. The two met on Instagram and quickly bonded over their shared love of films.", "The couple live in London, so opportunities to practise Welsh are limited. Murphy encourages Honey to speak Welsh to their dog, Coco.", "Murphy said, 'Coco won't tell you if you're wrong.' He also said Honey's excellent memory helps her when learning a new language.", "Honey is a writer and podcaster. In 2017, she co-founded the Pink Protest movement for women's rights, which succeeded in securing UK government funding.", "Murphy gets on well with Honey's father Jonathan Ross, as they both love to laugh. Murphy enjoys hearing Jonathan's stories about the many famous people he has met."], "sentences": [{"text": "영국 방송인 조나단 로스의 딸 허니 로스(28세)가 웨일스어를 배우고 있어요.", "translation": "Honey Ross (28), daughter of British broadcaster Jonathan Ross, is learning Welsh.", "vocab": [{"ko": "방송인", "en": "broadcaster"}, {"ko": "딸", "en": "daughter"}, {"ko": "배우다", "en": "to learn"}], "analysis": []}, {"text": "허니는 듀오링고 앱으로 공부하고 있어요.", "translation": "Honey is studying using the Duolingo app.", "vocab": [{"ko": "앱", "en": "app"}, {"ko": "공부하다", "en": "to study"}], "analysis": [{"type": "grammar", "label": "~으로", "exp": "Instrumental particle marking the means or tool used to perform an action.", "example_in_sentence": "앱으로"}]}, {"text": "허니의 남자 친구 개브 머피(41세)는 웨일스 출신이에요.", "translation": "Honey's boyfriend Gabe Murphy (age 41) is from Wales.", "vocab": [{"ko": "남자 친구", "en": "boyfriend"}, {"ko": "출신", "en": "origin; native of"}], "analysis": []}, {"text": "두 사람은 인스타그램에서 만났고, 영화를 좋아해서 금방 친해졌어요.", "translation": "The two met on Instagram, and because they both liked movies, they quickly became close.", "vocab": [{"ko": "만나다", "en": "to meet"}, {"ko": "영화", "en": "movie"}, {"ko": "좋아하다", "en": "to like"}, {"ko": "금방", "en": "quickly; soon"}], "analysis": [{"type": "grammar", "label": "~았고", "exp": "Conjunctive ending for past tense. Connects two clauses; second clause typically provides additional information or consequence.", "example_in_sentence": "만났고"}, {"type": "grammar", "label": "~아/어서", "exp": "Causal/reason connector: 'because' or 'so'. Indicates reason for action in following clause.", "example_in_sentence": "좋아해서"}, {"type": "grammar", "label": "~아/어지다", "exp": "Shows a change of state: 친하다 'to be close' → 친해지다 'to become close' → 친해졌어요.", "example_in_sentence": "친해졌어요"}]}, {"text": "두 사람은 런던에 살고 있어요.", "translation": "The two live in London.", "vocab": [{"ko": "살다", "en": "to live"}], "analysis": []}, {"text": "그래서 웨일스어를 연습할 기회가 많지 않아요.", "translation": "So she doesn't have many chances to practice Welsh.", "vocab": [{"ko": "연습하다", "en": "to practice"}, {"ko": "기회", "en": "opportunity"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ (noun modifier)", "exp": "Prospective modifier for 'to do': 연습하다 → 연습할 기회 'a chance to practice'.", "example_in_sentence": "연습할"}, {"type": "grammar", "label": "~지 않다", "exp": "Negative 'not': 많다 → 많지 않아요 'are not many'.", "example_in_sentence": "많지 않아요"}]}, {"text": "머피는 허니에게 두 사람의 강아지 코코에게 웨일스어로 말해 보라고 해요.", "translation": "Murphy tells Honey to try speaking Welsh to their dog Coco.", "vocab": [{"ko": "강아지", "en": "dog"}, {"ko": "말하다", "en": "to speak"}], "analysis": [{"type": "grammar", "label": "~에게", "exp": "Dative particle marking indirect object or recipient of action.", "example_in_sentence": "허니에게"}, {"type": "grammar", "label": "~(으)로", "exp": "Instrumental particle marking language or tool used.", "example_in_sentence": "웨일스어로"}, {"type": "grammar", "label": "~아/어 보다", "exp": "Auxiliary expressing attempted action or trying something out. Here: '말해 보다' = try speaking.", "example_in_sentence": "말해 보라고"}, {"type": "grammar", "label": "~(으)라고 하다", "exp": "Reports a command or suggestion: 말해 보다 → 말해 보라고 해요 'tells (her) to try speaking'.", "example_in_sentence": "말해 보라고 해요"}]}, {"text": "머피는 \"코코는 틀려도 뭐라고 하지 않으니까요\"라고 말했어요.", "translation": "Murphy said, \"Coco won't say anything even if you make mistakes.\"", "vocab": [{"ko": "틀리다", "en": "to make a mistake"}, {"ko": "뭐라고 하다", "en": "to say something; to criticize"}], "analysis": [{"type": "grammar", "label": "~어도", "exp": "Concessive marker meaning 'even if' or 'although'. Marks condition that doesn't prevent main action.", "example_in_sentence": "틀려도"}, {"type": "grammar", "label": "~지 않다", "exp": "Negation form combining negation marker ~지 with ~않다.", "example_in_sentence": "하지 않으니까"}, {"type": "grammar", "label": "~(으)니까", "exp": "Reason 'because'. After a consonant use 으니까: 않다 → 않으니까. Ending a sentence with ~니까요 gives the reason on its own.", "example_in_sentence": "않으니까"}]}, {"text": "허니는 기억력이 아주 좋아서 언어 공부에 도움이 된다고 해요.", "translation": "Honey says she has a very good memory, which helps her study languages.", "vocab": [{"ko": "기억력", "en": "memory"}, {"ko": "아주", "en": "very"}, {"ko": "도움", "en": "help"}, {"ko": "되다", "en": "to become (도움이 되다 = to help)"}], "analysis": [{"type": "grammar", "label": "~아/어서", "exp": "Causal connector. Indicates reason why language study becomes helpful.", "example_in_sentence": "좋아서"}, {"type": "expression", "label": "도움이 되다", "exp": "'To be helpful': 도움 'help' + 이 되다. 도움이 된다고 해요 = '(she) says it helps'.", "example_in_sentence": "도움이 된다고"}]}, {"text": "허니는 작가이고 팟캐스터이기도 해요.", "translation": "Honey is a writer and also a podcaster.", "vocab": [{"ko": "작가", "en": "writer"}, {"ko": "팟캐스터", "en": "podcaster"}], "analysis": [{"type": "grammar", "label": "~이고", "exp": "'Is N and…': 작가이다 → 작가이고 'is a writer and'.", "example_in_sentence": "작가이고"}, {"type": "grammar", "label": "~이기도 하다", "exp": "'Is also N': 팟캐스터이다 → 팟캐스터이기도 해요 'is also a podcaster'.", "example_in_sentence": "팟캐스터이기도 해요"}]}, {"text": "그녀는 2017년에 여성 권리를 위한 핑크 프로테스트 운동을 함께 만들었어요.", "translation": "She co-created the Pink Protest movement for women's rights in 2017.", "vocab": [{"ko": "여성", "en": "woman"}, {"ko": "권리", "en": "right"}, {"ko": "운동", "en": "movement"}, {"ko": "만들다", "en": "to create"}], "analysis": [{"type": "grammar", "label": "~을/를 위한", "exp": "Purpose/beneficiary marker. '~을/를 위하다' = to be for. Here forms modifier '~을/를 위한'.", "example_in_sentence": "권리를 위한"}]}, {"text": "이 운동은 영국 정부에서 지원을 받는 데 성공했어요.", "translation": "This movement succeeded in receiving support from the British government.", "vocab": [{"ko": "정부", "en": "government"}, {"ko": "지원", "en": "support"}, {"ko": "받다", "en": "to receive"}, {"ko": "성공하다", "en": "to succeed"}], "analysis": [{"type": "grammar", "label": "~는 데 성공하다", "exp": "'Succeed in doing': 받다 → 받는 데 성공했어요 'succeeded in getting (support)'.", "example_in_sentence": "받는 데 성공했어요"}]}, {"text": "머피는 허니의 아버지 조나단 로스와도 사이가 좋아요.", "translation": "Murphy also has a good relationship with Honey's father Jonathan Ross.", "vocab": [{"ko": "아버지", "en": "father"}, {"ko": "사이", "en": "relationship; between"}], "analysis": [{"type": "grammar", "label": "~와도", "exp": "Particle combining ~와 (with) + ~도 (also). Marks inclusive/emphatic co-participant.", "example_in_sentence": "로스와도"}, {"type": "expression", "label": "사이가 좋다", "exp": "Idiomatic expression meaning 'to have a good relationship'. Relationship + good.", "example_in_sentence": "사이가 좋아요"}]}, {"text": "두 사람 모두 웃음을 좋아하기 때문이에요.", "translation": "It is because both of them like laughter.", "vocab": [{"ko": "모두", "en": "both; all"}, {"ko": "웃음", "en": "laughter"}], "analysis": [{"type": "grammar", "label": "~기 때문이다", "exp": "'It's because…': 좋아하다 → 좋아하기 때문이에요 'it's because (they) like'.", "example_in_sentence": "좋아하기 때문이에요"}]}, {"text": "머피는 조나단이 많은 유명한 사람들을 만났기 때문에, 그 이야기를 듣고 싶어 해요.", "translation": "Murphy wants to hear those stories because Jonathan has met many famous people.", "vocab": [{"ko": "많다", "en": "to be many; to be a lot"}, {"ko": "유명하다", "en": "to be famous"}, {"ko": "사람", "en": "person"}, {"ko": "이야기", "en": "story"}], "analysis": [{"type": "grammar", "label": "~기 때문에", "exp": "'Because': 만나다 → 만났기 때문에 'because (he) has met'.", "example_in_sentence": "만났기 때문에"}, {"type": "grammar", "label": "~고 싶어 하다", "exp": "'Want to' for a third person: 듣다 → 듣고 싶어 해요 'wants to hear'.", "example_in_sentence": "듣고 싶어 해요"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mv4bhj5iqpcy' and md5(translation) = 'cbd9ccba3f960ef6972d25eb14f8bc4a';
update public.article_cache set translation = $t${"texts": ["Billboard released its World Albums chart dated October 10. &TEAM's mini album 'Mark on Me' re-entered the chart at No. 1, marking the first time the group has ever topped it. The album also debuted in the top 20 of the Billboard 200, setting a new personal best for &TEAM.", "Stray Kids' latest mini album 'THIS & THAT' dropped to No. 2 in its eighth week after six non-consecutive weeks at No. 1, while holding steady at No. 34 on the Billboard 200. The group's 2025 album 'KARMA' also climbed back to No. 23 in its 55th week on the chart.", "ENHYPEN's mini album 'THE SIN : BLISS' rose to No. 3 in its sixth week, also climbing back to No. 161 on the Billboard 200. ILLIT's 'MAMIHLAPINATAPAI' reached No. 6 in its 22nd week, continuing its steady presence on the chart.", "BTS's anthology album 'Proof' jumped to No. 7 in its 225th week on the chart. EVAN (Heeseung)'s debut mini album 'DEATH OF ME' took No. 8 in its fourth week, while LE SSERAFIM's 'PUREFLOW' rose to No. 11 in its 19th week.", "ATEEZ's 'GOLDEN HOUR : Part.5' held at No. 14, aespa's 'LEMONADE' came in at No. 18, and NewJeans' 'Get Up' ranked No. 19 in its 160th week on the chart."], "sentences": [{"text": "빌보드가 10월 10일 자 월드 앨범 차트를 발표했습니다.", "translation": "Billboard announced the World Album Chart dated October 10.", "vocab": [{"ko": "발표하다", "en": "to announce; to publish"}], "analysis": []}, {"text": "이번 주 &TEAM의 미니 앨범 'Mark on Me'가 차트 1위에 재진입하면서 그룹 역사상 처음으로 1위를 차지하게 되었습니다.", "translation": "&TEAM's mini album 'Mark on Me' re-entered the chart at number 1 this week, marking the first time the group has achieved number 1 status in their history.", "vocab": [{"ko": "재진입하다", "en": "to re-enter"}, {"ko": "차지하다", "en": "to take; to occupy; to claim"}], "analysis": [{"type": "grammar", "label": "~면서", "exp": "Connective ending indicating concurrent or sequential actions. Shows that re-entering and achieving 1st place happen together.", "example_in_sentence": "재진입하면서"}, {"type": "grammar", "label": "~게 되다", "exp": "Auxiliary verb phrase expressing a change of state or realization. 차지하다 + 게 되다 indicates the group came to achieve 1st place (passive realization).", "example_in_sentence": "차지하게 되었습니다"}]}, {"text": "이 앨범은 빌보드 200에서도 상위 20위 안에 데뷔하며 &TEAM의 최고 순위를 기록했습니다.", "translation": "This album also debuted within the top 20 on the Billboard 200, recording &TEAM's highest ranking.", "vocab": [{"ko": "데뷔하다", "en": "to debut; to make a first appearance"}, {"ko": "기록하다", "en": "to record; to mark"}], "analysis": [{"type": "grammar", "label": "~(으)며", "exp": "Written connector 'and / while': 데뷔하다 → 데뷔하며 'debuted (in the top 20) and…'.", "example_in_sentence": "데뷔하며"}]}, {"text": "스트레이 키즈의 최신 미니 앨범 'THIS & THAT'은 여섯 번의 비연속 1위를 기록한 후 이번 주 2위로 내려왔습니다.", "translation": "Stray Kids' latest mini album 'THIS & THAT' has dropped to number 2 this week after recording six non-consecutive number 1s.", "vocab": [{"ko": "비연속", "en": "non-consecutive; discontinuous"}, {"ko": "내려오다", "en": "to come down; to drop (in ranking)"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ 후(에)", "exp": "'After doing': 기록하다 → 기록한 후 'after recording'.", "example_in_sentence": "기록한 후"}]}, {"text": "차트에 오른 지 8주째이며, 빌보드 200에서는 34위를 유지하고 있습니다.", "translation": "It is in its 8th week on the chart, and is maintaining 34th place on the Billboard 200.", "vocab": [{"ko": "유지하다", "en": "to maintain; to keep"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ 지 N째", "exp": "'It has been N since…': 오르다 → 오른 지 8주째 'the 8th week since it entered (the chart)'.", "example_in_sentence": "오른 지 8주째"}, {"type": "grammar", "label": "~고 있다", "exp": "Progressive aspect marker. Verb 유지하다 + 고 있다 shows ongoing/habitual action in present.", "example_in_sentence": "유지하고 있습니다"}]}, {"text": "같은 그룹의 2025년 앨범 'KARMA'는 55주째에 23위로 다시 올라왔습니다.", "translation": "The same group's 2025 album 'KARMA' has risen again to 23rd place in its 55th week.", "vocab": [{"ko": "올라오다", "en": "to come up; to rise (in ranking)"}], "analysis": [{"type": "expression", "label": "~로 다시 올라오다", "exp": "Expression indicating a return to or recovery of a higher ranking position after falling.", "example_in_sentence": "23위로 다시 올라왔습니다"}]}, {"text": "ENHYPEN의 미니 앨범 'THE SIN : BLISS'는 6주째에 3위로 상승했습니다.", "translation": "ENHYPEN's mini album 'THE SIN : BLISS' has risen to 3rd place in its 6th week.", "vocab": [{"ko": "상승하다", "en": "to rise; to go up"}], "analysis": []}, {"text": "빌보드 200에서도 161위로 다시 올라오면서 두 차트 모두에서 순위가 높아졌습니다.", "translation": "On the Billboard 200, it also rose again to 161st place, with rankings improving on both charts.", "vocab": [{"ko": "높아지다", "en": "to become high; to improve (of ranking)"}], "analysis": [{"type": "grammar", "label": "~(으)면서", "exp": "'While / as': 올라오다 → 올라오면서 'as it climbed back (to 161st)'.", "example_in_sentence": "올라오면서"}]}, {"text": "ILLIT의 'MAMIHLAPINATAPAI'는 22주째에 6위에 오르면서 꾸준히 차트에 머물고 있습니다.", "translation": "ILLIT's 'MAMIHLAPINATAPAI' has risen to 6th place in its 22nd week, steadily remaining on the chart.", "vocab": [{"ko": "꾸준히", "en": "steadily; consistently"}, {"ko": "머물다", "en": "to stay; to remain"}], "analysis": [{"type": "grammar", "label": "~고 있다", "exp": "Progressive aspect marker. 머물다 + 고 있다 indicates the ongoing state of remaining on the chart.", "example_in_sentence": "머물고 있습니다"}]}, {"text": "BTS의 앤솔로지 앨범 'Proof'는 225주째에 7위로 뛰어올랐습니다.", "translation": "BTS's anthology album 'Proof' has jumped to 7th place in its 225th week.", "vocab": [{"ko": "뛰어오르다", "en": "to jump (up); to leap; to surge"}], "analysis": []}, {"text": "EVAN(히승)의 첫 미니 앨범 'DEATH OF ME'는 4주째에 8위를 차지했으며, LE SSERAFIM의 'PUREFLOW'는 19주째에 11위로 상승했습니다.", "translation": "EVAN(Hiseung)'s first mini album 'DEATH OF ME' has claimed 8th place in its 4th week, and LE SSERAFIM's 'PUREFLOW' has risen to 11th place in its 19th week.", "vocab": [{"ko": "차지하다", "en": "to take; to occupy; to claim"}], "analysis": [{"type": "grammar", "label": "~(으)며", "exp": "Written connector 'and': 차지했다 → 차지했으며 'took (8th place), and…'.", "example_in_sentence": "차지했으며"}]}, {"text": "이 밖에 ATEEZ의 'GOLDEN HOUR : Part.5'가 14위를 유지했고, aespa의 'LEMONADE'는 18위, 뉴진스의 'Get Up'은 160주째에 19위를 기록했습니다.", "translation": "Beyond this, ATEEZ's 'GOLDEN HOUR : Part.5' has maintained 14th place, aespa's 'LEMONADE' is at 18th, and NewJeans' 'Get Up' has recorded 19th place in its 160th week.", "vocab": [{"ko": "유지하다", "en": "to maintain; to keep"}], "analysis": [{"type": "expression", "label": "이 밖에", "exp": "Expression meaning 'besides this; furthermore; in addition to.' Lists additional information outside the previous content.", "example_in_sentence": "이 밖에"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mv4bo3fr1wel' and md5(translation) = '06502d865bf83a4f1aafe0c88572cb6d';
update public.article_cache set translation = $t${"texts": ["The European Union has decided to cap imports of Chinese hybrid electric vehicles at 350,000 units per year, with the European Commission officially confirming the measure, which is set to take effect in December.", "Because the measure is being taken under WTO safeguard provisions, it can be implemented swiftly without the anti-dumping investigation procedures that would otherwise be required; vehicles imported above the quota will not face tariffs but will be blocked at European ports.", "Sales of Chinese battery electric and plug-in hybrid vehicles in the EU are projected to reach approximately 800,000 units this year, and the import cap is expected to halve China's current 6% market share to around 3%.", "Chinese-branded vehicles manufactured within the EU, such as those produced in Hungary, are exempt from the quota, while EU companies producing vehicles in China will be subject to it, officials stated.", "As part of the four-year agreement signed in Beijing last week, China agreed to eliminate some tariffs on auto parts and halve duties on EU exports including footwear, olive oil, and ice cream; officials emphasized that the quota has China's full support and that dialogue on other sectors continues.", "Amid a trade deficit with China now running at £1 billion per day, a shift in thinking is underway within the EU — policy focus is moving away from boosting exports to curbing imports, with Andrew Small of the European Council on Foreign Relations noting that China is likely to draw the EU into prolonged negotiations on other sectors."], "sentences": [{"text": "유럽연합은 중국산 하이브리드 전기차 수입량을 연간 35만 대로 제한하기로 하였습니다.", "translation": "The European Union decided to limit annual imports of Chinese hybrid electric vehicles to 350,000 units.", "vocab": [{"ko": "하이브리드", "en": "hybrid"}, {"ko": "수입량", "en": "import volume"}, {"ko": "연간", "en": "annually; per year"}, {"ko": "제한하다", "en": "to limit; to restrict"}], "analysis": [{"type": "grammar", "label": "~기로 하다", "exp": "'Decide to': 제한하다 → 제한하기로 하였습니다 'decided to limit'.", "example_in_sentence": "제한하기로 하였습니다"}]}, {"text": "유럽 집행위원회가 이를 공식 확인한 가운데, 해당 조치는 오는 12월부터 발효될 예정입니다.", "translation": "With the European Commission officially confirming this, the measure is scheduled to take effect starting this December.", "vocab": [{"ko": "집행위원회", "en": "executive commission; commission"}, {"ko": "공식", "en": "official; formally"}, {"ko": "가운데", "en": "amid; in the midst of"}, {"ko": "발효되다", "en": "to take effect; to come into force"}], "analysis": [{"type": "expression", "label": "~(으)ㄴ 가운데", "exp": "'Amid / as (something happened)': 확인하다 → 확인한 가운데 'with (the Commission) having confirmed this'.", "example_in_sentence": "확인한 가운데"}, {"type": "grammar", "label": "~(으)ㄹ 예정이다", "exp": "'Is scheduled to': 발효되다 → 발효될 예정입니다 'is scheduled to take effect'.", "example_in_sentence": "발효될 예정입니다"}]}, {"text": "이번 조치는 세계무역기구 긴급수입제한 규정을 근거로 하는 만큼, 반덤핑 조사 절차를 거치지 않고도 신속히 시행될 수 있습니다.", "translation": "Since this measure is based on WTO emergency import restriction regulations, it can be implemented quickly without going through anti-dumping investigation procedures.", "vocab": [{"ko": "근거", "en": "basis; ground; evidence"}, {"ko": "반덤핑", "en": "anti-dumping"}, {"ko": "절차", "en": "procedure; process"}, {"ko": "신속하다", "en": "to be swift; to be quick"}], "analysis": [{"type": "expression", "label": "~을/를 근거로 하다", "exp": "'To be based on N': 규정을 근거로 하다 'to be based on the rules'.", "example_in_sentence": "규정을 근거로 하는"}, {"type": "grammar", "label": "~는 만큼", "exp": "'Since / as (it is the case that)': 근거로 하다 → 근거로 하는 만큼 'since it is based on'.", "example_in_sentence": "근거로 하는 만큼"}, {"type": "grammar", "label": "~지 않고도", "exp": "Negation ~지 않다 + ~고도; means 'without doing' or 'even without doing.' Emphasizes accomplishment despite omission of a step.", "example_in_sentence": "거치지 않고도"}]}, {"text": "할당량을 초과하여 수입된 차량에는 관세가 부과되지 않는 대신, 유럽 항구 세관에서 통관이 차단됩니다.", "translation": "Vehicles imported beyond the quota will not face tariffs; instead, they will be blocked from clearing customs at European ports.", "vocab": [{"ko": "할당량", "en": "quota; allocation"}, {"ko": "초과하다", "en": "to exceed; to surpass"}, {"ko": "관세", "en": "tariff; customs duty"}, {"ko": "통관", "en": "customs clearance"}], "analysis": [{"type": "grammar", "label": "~는 대신", "exp": "Present attributive ~는 + 대신(instead); means 'instead of doing' or 'in place of.' Indicates substitution or alternative action.", "example_in_sentence": "부과되지 않는 대신"}, {"type": "grammar", "label": "~아/어 (-여)", "exp": "Formal written form of 해서: 초과하다 → 초과하여 수입된 차량 'vehicles imported beyond (the quota)'.", "example_in_sentence": "초과하여"}]}, {"text": "올해 중국산 배터리 전기차 및 플러그인 하이브리드 판매량은 약 80만 대에 달할 것으로 전망됩니다.", "translation": "Sales of Chinese-made battery electric vehicles and plug-in hybrids are projected to reach approximately 800,000 units this year.", "vocab": [{"ko": "배터리", "en": "battery"}, {"ko": "플러그인", "en": "plug-in"}, {"ko": "판매량", "en": "sales volume"}, {"ko": "달하다", "en": "to reach; to amount to"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 것으로 전망되다", "exp": "'Is expected to': 달하다 → 달할 것으로 전망됩니다 'is projected to reach'.", "example_in_sentence": "달할 것으로 전망됩니다"}]}, {"text": "이번 수입 상한으로 인하여 현재 6%에 달하는 중국의 시장 점유율은 3%로 절반 수준에 그칠 것으로 예상됩니다.", "translation": "Because of this import cap, China's market share, now at 6%, is expected to be cut in half to 3%.", "vocab": [{"ko": "상한", "en": "ceiling; upper limit"}, {"ko": "점유율", "en": "market share; share"}, {"ko": "그치다", "en": "to end at; to stop at"}], "analysis": [{"type": "grammar", "label": "~(으)로 인하여", "exp": "Formal 'due to; because of': 상한으로 인하여 'because of the (import) cap'.", "example_in_sentence": "상한으로 인하여"}, {"type": "grammar", "label": "~에 달하는", "exp": "Locative ~에 + 달하다(reach); attributive form meaning 'that reaches' or 'that amounts to.' Modifies noun with a specific measurement.", "example_in_sentence": "6%에 달하는"}, {"type": "expression", "label": "~에 그치다", "exp": "'To stop at / only reach (a low level)': 절반 수준에 그칠 것 'will stay at only half'.", "example_in_sentence": "절반 수준에 그칠"}]}, {"text": "헝가리 등 유럽연합 역내에서 생산되는 중국 브랜드 차량은 이번 할당 적용 대상에서 제외됩니다.", "translation": "Chinese-brand vehicles produced within the EU, such as in Hungary, are excluded from this quota application.", "vocab": [{"ko": "역내", "en": "within the region; intra-regional"}, {"ko": "생산되다", "en": "to be produced; to be manufactured"}, {"ko": "제외되다", "en": "to be excluded; to be exempted"}], "analysis": [{"type": "grammar", "label": "~에서 생산되는", "exp": "Locative ~에서 (from/in) + 생산되다(to be produced, passive); present attributive form modifying noun. Indicates location/agent of production.", "example_in_sentence": "역내에서 생산되는"}, {"type": "grammar", "label": "~에서 제외되다", "exp": "Locative ~에서 (from) + 제외되다(to be excluded, passive); means 'to be excluded from' or 'to be exempted from.'", "example_in_sentence": "적용 대상에서 제외됩니다"}]}, {"text": "반면 중국 내에서 차량을 생산하는 유럽연합 기업들은 규제 대상에 포함된다고 당국은 밝혔습니다.", "translation": "On the other hand, EU companies that produce vehicles within China are included in the scope of regulation, according to authorities.", "vocab": [{"ko": "반면", "en": "on the other hand; in contrast"}, {"ko": "규제", "en": "regulation; control"}, {"ko": "포함되다", "en": "to be included; to be contained"}, {"ko": "당국", "en": "authorities; officials"}], "analysis": [{"type": "expression", "label": "~는 (noun modifier)", "exp": "Present modifier: 생산하다 → 차량을 생산하는 기업 'companies that make cars'.", "example_in_sentence": "생산하는 유럽연합 기업들은"}, {"type": "grammar", "label": "~다고 밝히다", "exp": "Reported statement: 포함되다 → 포함된다고 밝혔습니다 '(the authorities) said they are included'.", "example_in_sentence": "포함된다고 당국은 밝혔습니다"}]}, {"text": "지난주 베이징에서 체결된 4년 협정의 일환으로 중국은 일부 자동차 부품 관세를 폐지하고, 신발·올리브유·아이스크림 등 유럽연합산 제품에 대한 관세를 절반으로 인하하기로 합의하였습니다.", "translation": "As part of a 4-year agreement concluded in Beijing last week, China agreed to abolish tariffs on some auto parts and reduce tariffs on EU-origin products such as shoes, olive oil, and ice cream by half.", "vocab": [{"ko": "체결되다", "en": "to be signed; to be concluded"}, {"ko": "일환", "en": "part; aspect; component"}, {"ko": "폐지하다", "en": "to abolish; to eliminate"}, {"ko": "인하하다", "en": "to reduce; to lower (formal)"}], "analysis": [{"type": "expression", "label": "~의 일환으로", "exp": "Genitive ~의 + 일환(part/aspect) + ~로(as); means 'as part of' or 'in the context of.' Indicates component or aspect of a larger whole.", "example_in_sentence": "협정의 일환으로"}, {"type": "grammar", "label": "~기로 합의하다", "exp": "'Agree to do': 인하하다 → 인하하기로 합의하였습니다 'agreed to cut'.", "example_in_sentence": "인하하기로 합의하였습니다"}]}, {"text": "당국자들은 이번 할당 조치가 중국의 전폭적인 지지를 받고 있으며, 화학제품·재생에너지·가구 등 여타 품목에 대하여도 대화가 지속되고 있다고 강조하였습니다.", "translation": "Officials emphasized that this quota measure is receiving full support from China, and that dialogue is ongoing regarding other items such as chemicals, renewable energy, and furniture.", "vocab": [{"ko": "당국자", "en": "official; authority representative"}, {"ko": "전폭적", "en": "full; wholehearted; complete"}, {"ko": "지지", "en": "support; backing"}, {"ko": "지속되다", "en": "to be sustained; to continue"}], "analysis": [{"type": "grammar", "label": "~고 있으며", "exp": "'Is …ing, and': 받다 → 받고 있으며 'is receiving (support), and…'.", "example_in_sentence": "받고 있으며"}, {"type": "expression", "label": "~에 대하여", "exp": "Dative case marker ~에 (target/scope) + 대하여(toward/regarding); means 'regarding' or 'concerning.' Indicates object or target of action/discussion.", "example_in_sentence": "여타 품목에 대하여도"}]}, {"text": "유럽연합이 중국에 대하여 하루 10억 파운드의 무역 적자를 기록하고 있는 가운데, 내부에서는 인식의 전환이 이루어지고 있습니다.", "translation": "Amid the EU recording a daily trade deficit of 1 billion pounds against China, a shift in perception is taking place internally.", "vocab": [{"ko": "무역 적자", "en": "trade deficit"}, {"ko": "기록하다", "en": "to record; to register"}, {"ko": "인식", "en": "recognition; perception; awareness"}, {"ko": "전환", "en": "shift; conversion; change"}], "analysis": [{"type": "expression", "label": "~는 가운데", "exp": "'Amid / while': 기록하고 있다 → 기록하고 있는 가운데 'while (the EU) is running…'.", "example_in_sentence": "기록하고 있는 가운데"}, {"type": "grammar", "label": "~이/가 이루어지다", "exp": "'(Something) takes place': 전환이 이루어지다 'a shift happens' → 이루어지고 있습니다 'is happening'.", "example_in_sentence": "인식의 전환이 이루어지고 있습니다"}]}, {"text": "수출 확대를 통해 무역 불균형을 해소하려던 기존 전략에서 벗어나, 수입 억제에 초점을 맞추는 방향으로 정책 기조가 옮겨가고 있습니다.", "translation": "Policy is shifting away from the old strategy of trying to fix the trade imbalance by expanding exports, toward a focus on curbing imports.", "vocab": [{"ko": "수출 확대", "en": "export expansion; increase in exports"}, {"ko": "해소하다", "en": "to resolve; to clear; to settle"}, {"ko": "벗어나다", "en": "to get away from; to deviate from"}, {"ko": "억제", "en": "suppression; restraint; control"}], "analysis": [{"type": "grammar", "label": "~(으)려던", "exp": "'That was meant to': 해소하다 → 해소하려던 전략 'the strategy that was meant to resolve (the imbalance)'.", "example_in_sentence": "해소하려던 기존 전략"}, {"type": "expression", "label": "~에서 벗어나다", "exp": "Locative ~에서 (from) + 벗어나다(to escape/deviate); means 'to depart from' or 'to break away from.' Indicates rejection or abandonment of prior approach.", "example_in_sentence": "전략에서 벗어나"}, {"type": "expression", "label": "~에 초점을 맞추다", "exp": "Goal/target ~에 (on) + 초점(focus) + 맞추다(to adjust/align); idiomatic: 'to focus on' or 'to direct attention to.'", "example_in_sentence": "수입 억제에 초점을 맞추는"}, {"type": "grammar", "label": "~는 방향으로", "exp": "'Toward (doing)': 초점을 맞추는 방향으로 옮겨가다 'shift toward focusing on'.", "example_in_sentence": "맞추는 방향으로"}]}, {"text": "유럽대외관계위원회 아시아 프로그램 책임자 앤드루 스몰은 중국이 여타 분야에서 유럽연합을 장기 협상으로 끌어들이려 할 가능성이 높다고 분석하였습니다.", "translation": "Andrew Small, director of the Asia Program at the European Council on Foreign Relations, analyzed that China likely seeks to draw the EU into prolonged negotiations in other sectors.", "vocab": [{"ko": "대외관계", "en": "foreign relations; external relations"}, {"ko": "책임자", "en": "head; director; person in charge"}, {"ko": "장기 협상", "en": "prolonged/long-term negotiations"}, {"ko": "끌어들이다", "en": "to draw in; to pull into; to involve"}], "analysis": [{"type": "grammar", "label": "~(으)려 하다", "exp": "'Try / intend to': 끌어들이다 → 끌어들이려 할 가능성이 높다 'is likely to try to draw in'.", "example_in_sentence": "끌어들이려 할 가능성이 높다고"}, {"type": "grammar", "label": "~(으)로 (into)", "exp": "Marks what something is drawn into: 장기 협상으로 끌어들이다 'draw (the EU) into long negotiations'.", "example_in_sentence": "장기 협상으로 끌어들이려"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mv5rgzg09ids' and md5(translation) = 'c30b91127ae9f3739c1177a181695a1c';
update public.article_cache set translation = $t${"texts": ["The global market for trading reptiles and amphibians as pets is growing rapidly, with scientists warning of serious threats to biodiversity and human health as pathogens can spread when animals are moved across regions.", "Experts say social media and weak regulation are the main drivers of this market, as influencers make keeping lizards and snakes look trendy, and reptiles are widely considered easy to care for, leading many people to buy them without adequate preparation.", "Legal gaps compound the problem: animals illegally captured in one country can be sold legally once exported, the wildlife convention CITES struggles to protect species before they become threatened, and penalties for wildlife trafficking remain weak — smugglers enjoy high profits with almost no risk of imprisonment.", "One proposed solution gaining attention is the 'positive list' system, where importing countries only allow species confirmed as safe and ban all others; legislation like the U.S. Lacey Act, which makes it illegal to trade species banned for export by other countries, is also presented as a model for other nations.", "A UN Convention against Transnational Organized Crime meeting is scheduled in Vienna later this month, where negotiations on stronger international rules covering wildlife crime may begin; researchers emphasize that unlike climate change, this problem can be resolved relatively quickly if governments choose to act."], "sentences": [{"text": "전 세계적으로 파충류와 양서류를 애완동물로 거래하는 시장이 빠르게 커지고 있습니다.", "translation": "Globally, the market for trading reptiles and amphibians as pets is growing rapidly.", "vocab": [{"ko": "파충류", "en": "reptile"}, {"ko": "양서류", "en": "amphibian"}, {"ko": "애완동물", "en": "pet"}, {"ko": "커지다", "en": "to grow, expand"}], "analysis": [{"type": "grammar", "label": "~고 있다", "exp": "Progressive aspect marker. Indicates ongoing action in present. Form: verb stem + 고 있다.", "example_in_sentence": "커지고 있습니다"}, {"type": "grammar", "label": "~는 (relative clause modifier)", "exp": "Present tense attributive ending on verb. Modifies the following noun. Form: verb stem + 는.", "example_in_sentence": "거래하는 시장"}]}, {"text": "과학자들은 이 거래가 생물 다양성과 인간 건강에 심각한 위협이 될 수 있다고 말합니다.", "translation": "Scientists say that this trade could pose a serious threat to biodiversity and human health.", "vocab": [{"ko": "생물 다양성", "en": "biodiversity"}, {"ko": "위협", "en": "threat"}, {"ko": "심각하다", "en": "to be serious, grave"}], "analysis": [{"type": "grammar", "label": "~ㄹ 수 있다", "exp": "Possibility/ability marker. Indicates what is possible or capable of happening. Form: verb stem + ㄹ 수 있다.", "example_in_sentence": "될 수 있다"}, {"type": "grammar", "label": "~다고 말하다", "exp": "Quotative pattern with 말하다. Reports speech or assertion. Form: sentence + 다고 말하다.", "example_in_sentence": "될 수 있다고 말합니다"}]}, {"text": "동물들이 한 지역에서 다른 지역으로 이동하면서 병원균도 함께 퍼질 수 있기 때문입니다.", "translation": "This is because pathogens can spread along with animals as they move from one region to another.", "vocab": [{"ko": "이동하다", "en": "to move, migrate"}, {"ko": "병원균", "en": "pathogen"}, {"ko": "퍼지다", "en": "to spread"}], "analysis": [{"type": "grammar", "label": "~(으)면서", "exp": "'While / as': 이동하다 → 이동하면서 'as (animals) move'.", "example_in_sentence": "이동하면서"}, {"type": "grammar", "label": "~기 때문이다", "exp": "Causal nominalization. Marks the reason for preceding statement. Form: verb stem + 기 때문이다.", "example_in_sentence": "퍼질 수 있기 때문입니다"}]}, {"text": "전문가들은 소셜 미디어와 느슨한 규제가 이 시장을 키운 주요 원인이라고 설명합니다.", "translation": "Experts explain that social media and lax regulations are the main causes that have grown this market.", "vocab": [{"ko": "느슨하다", "en": "to be loose, lax"}, {"ko": "규제", "en": "regulation"}, {"ko": "원인", "en": "cause, reason"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (past modifier)", "exp": "Past modifier: 키우다 → 이 시장을 키운 원인 'the causes that grew this market'.", "example_in_sentence": "키운 주요 원인"}, {"type": "grammar", "label": "~라고 설명하다", "exp": "Quotative with copula. Reports or explains a statement. Form: noun + (이)라고 설명하다.", "example_in_sentence": "원인이라고 설명합니다"}]}, {"text": "소셜 미디어 인플루언서들이 도마뱀이나 뱀을 키우는 것을 멋있게 보여 주면서 수요가 늘어나게 되었습니다.", "translation": "As social media influencers made keeping lizards or snakes look cool, demand grew.", "vocab": [{"ko": "도마뱀", "en": "lizard"}, {"ko": "수요", "en": "demand"}, {"ko": "늘어나다", "en": "to increase"}], "analysis": [{"type": "expression", "label": "~(으)면서", "exp": "'As / while': 보여 주다 → 보여 주면서 'as (influencers) showed…'.", "example_in_sentence": "보여 주면서"}, {"type": "grammar", "label": "~는 것을", "exp": "Turns a verb into a noun object 'doing…': 키우다 → 키우는 것을 'keeping (lizards)'.", "example_in_sentence": "키우는 것을"}, {"type": "grammar", "label": "~게 되다", "exp": "'Came to / ended up': 늘어나다 → 늘어나게 되었습니다 '(demand) ended up growing'.", "example_in_sentence": "늘어나게 되었습니다"}]}, {"text": "또한 파충류는 키우기 쉽다고 알려져 있어 많은 사람들이 충분한 준비 없이 구입하는 경우가 많습니다.", "translation": "Furthermore, because reptiles are known to be easy to keep, many people purchase them without sufficient preparation.", "vocab": [{"ko": "알려지다", "en": "to be known"}, {"ko": "충분하다", "en": "to be sufficient"}, {"ko": "구입하다", "en": "to purchase"}], "analysis": [{"type": "grammar", "label": "~다고 알려지다", "exp": "Passive form indicating common knowledge. What is known/reported about something. Form: adjective/verb + 다고 알려지다.", "example_in_sentence": "쉽다고 알려져 있어"}, {"type": "grammar", "label": "~는 경우가 많다", "exp": "Frequency expression. Indicates instances of something happen often. Form: verb + ㄴ/는 경우가 많다.", "example_in_sentence": "구입하는 경우가 많습니다"}]}, {"text": "현재 법적 허점도 문제입니다.", "translation": "Currently, legal loopholes are also a problem.", "vocab": [{"ko": "허점", "en": "loophole, gap"}], "analysis": []}, {"text": "한 나라에서 불법으로 포획된 동물이라도 다른 나라로 수출되면 합법적으로 판매될 수 있습니다.", "translation": "Even if an animal is illegally captured in one country, it can still be sold legally if exported to another country.", "vocab": [{"ko": "포획하다", "en": "to capture"}, {"ko": "수출하다", "en": "to export"}, {"ko": "합법적", "en": "legal, lawful"}], "analysis": [{"type": "grammar", "label": "~(이)라도 (even if, concessive)", "exp": "Concessive particle. Indicates that even in a given condition, the result holds. Form: noun + (이)라도.", "example_in_sentence": "동물이라도"}, {"type": "grammar", "label": "~(으)면", "exp": "Ending meaning 'if': 수출되다 → 수출되면 'if (it) is exported'.", "example_in_sentence": "수출되면"}, {"type": "grammar", "label": "~ㄹ 수 있다 (possibility)", "exp": "Potential/possibility marker. What is possible or can happen. Form: verb stem + ㄹ 수 있다.", "example_in_sentence": "판매될 수 있습니다"}]}, {"text": "국제 야생동물 협약인 사이테스는 종이 위기에 처하기 전에 선제적으로 보호하는 데 한계가 있으며, 야생동물 밀수에 대한 처벌도 약하다고 지적됩니다.", "translation": "CITES, an international wildlife treaty, has limitations in proactively protecting species before they become endangered, and it is pointed out that penalties for wildlife smuggling are also weak.", "vocab": [{"ko": "협약", "en": "treaty, convention"}, {"ko": "위기에 처하다", "en": "to be in crisis, endangered"}, {"ko": "선제적", "en": "proactive, preventative"}, {"ko": "밀수", "en": "smuggling"}], "analysis": [{"type": "grammar", "label": "~인 (relative clause copula)", "exp": "Attributive copula. Modifies noun. Form: noun + 인.", "example_in_sentence": "협약인 사이테스"}, {"type": "grammar", "label": "~기 전에 (before nominalization)", "exp": "Temporal marker meaning 'before.' Indicates prior sequence of events. Form: verb stem + 기 전에.", "example_in_sentence": "처하기 전에"}, {"type": "grammar", "label": "~는 데 한계가 있다", "exp": "Limitation expression. Indicates constraints on an action. Form: verb + ㄴ/는 데 한계가 있다.", "example_in_sentence": "보호하는 데 한계가 있으며"}, {"type": "grammar", "label": "~다고 지적되다", "exp": "Passive quotation. Indicates something is pointed out/noted in reports. Form: statement + 다고 지적되다.", "example_in_sentence": "약하다고 지적됩니다"}]}, {"text": "밀수업자들은 높은 이익을 얻으면서도 실제로 감옥에 가는 위험은 거의 없다고 합니다.", "translation": "Smugglers reportedly earn big profits while facing almost no real risk of going to prison.", "vocab": [{"ko": "이익", "en": "profit, gain"}, {"ko": "감옥", "en": "prison, jail"}, {"ko": "위험", "en": "risk, danger"}], "analysis": [{"type": "grammar", "label": "~으면서도 (concessive conjunction)", "exp": "Concessive connector. Expresses contrast despite preceding condition. Form: verb stem + 으면서도.", "example_in_sentence": "얻으면서도"}, {"type": "grammar", "label": "~다고 하다 (reported speech)", "exp": "Report or hearsay marker. Indicates what people say. Form: statement + 다고 하다.", "example_in_sentence": "없다고 합니다"}]}, {"text": "해결책으로는 '긍정 목록' 제도가 주목받고 있습니다.", "translation": "As a solution, the 'positive list' system is receiving attention.", "vocab": [{"ko": "해결책", "en": "solution, remedy"}, {"ko": "주목받다", "en": "to receive attention, to be noticed"}], "analysis": [{"type": "grammar", "label": "~으로는 (as, in terms of)", "exp": "Marking the role or capacity in which something acts. Form: noun + 으로는.", "example_in_sentence": "해결책으로는"}, {"type": "grammar", "label": "~고 있다 (ongoing progressive)", "exp": "Progressive aspect. Indicates ongoing action. Form: verb stem + 고 있다.", "example_in_sentence": "주목받고 있습니다"}]}, {"text": "이 제도는 수입 국가가 안전하다고 확인된 종만 목록에 올리고, 목록에 없는 종의 수입을 금지하는 방식입니다.", "translation": "This system is a method where the importing country lists only species confirmed to be safe, and prohibits importing species not on the list.", "vocab": [{"ko": "확인하다", "en": "to confirm, verify"}, {"ko": "목록", "en": "list"}, {"ko": "금지하다", "en": "to prohibit, ban"}], "analysis": [{"type": "grammar", "label": "~다고 확인되다 (past tense passive)", "exp": "Passive form indicating what has been verified. Form: adjective + 다고 확인된.", "example_in_sentence": "안전하다고 확인된"}, {"type": "grammar", "label": "~고", "exp": "'And' between two actions: 올리다 → 올리고 'puts (them) on the list, and (bans…)'.", "example_in_sentence": "올리고"}]}, {"text": "미국의 레이시법처럼 다른 나라가 수출을 금지한 종을 거래하는 것을 불법으로 규정하는 법률도 다른 나라들이 따라할 수 있는 모델로 제시되었습니다.", "translation": "Laws defining as illegal the trading of species that other countries have prohibited from exporting, like the U.S. Lacey Act, have also been presented as a model that other countries can follow.", "vocab": [{"ko": "법률", "en": "law, statute"}, {"ko": "규정하다", "en": "to stipulate, define"}, {"ko": "따라하다", "en": "to follow, emulate"}, {"ko": "모델", "en": "model"}], "analysis": [{"type": "grammar", "label": "~처럼 (like, as, in the manner of)", "exp": "Comparative particle. Form: noun/verb + 처럼.", "example_in_sentence": "레이시법처럼"}, {"type": "grammar", "label": "~ㄴ (past tense attributive)", "exp": "Past tense attributive ending. Modifies following noun. Form: verb stem + ㄴ/은.", "example_in_sentence": "금지한 종"}, {"type": "grammar", "label": "~는 것을 (nominalizer + object)", "exp": "Nominalizes verb action and marks as object. Form: verb + ㄴ/는 것을.", "example_in_sentence": "거래하는 것을"}, {"type": "grammar", "label": "~ㄹ 수 있는 (potential attributive)", "exp": "Potential/possibility attributive. Modifies noun describing what is possible. Form: verb stem + ㄹ 수 있는.", "example_in_sentence": "따라할 수 있는 모델"}]}, {"text": "이달 말 빈에서 유엔 초국가적 조직범죄 협약 회의가 열릴 예정입니다.", "translation": "At the end of this month, a United Nations Convention Against Transnational Organized Crime conference is scheduled to be held in Vienna.", "vocab": [{"ko": "초국가적", "en": "transnational"}, {"ko": "조직범죄", "en": "organized crime"}, {"ko": "열리다", "en": "to be held, take place"}], "analysis": [{"type": "grammar", "label": "~ㄹ 예정이다 (scheduled to)", "exp": "Intention/plan marker. Indicates something is planned or scheduled. Form: verb stem + ㄹ 예정이다.", "example_in_sentence": "열릴 예정입니다"}]}, {"text": "이 회의에서 야생동물 거래를 포함한 환경 범죄에 대해 더 강력한 국제 규범을 만드는 협상이 시작될 수 있습니다.", "translation": "At this conference, negotiations to create stronger international norms regarding environmental crimes, including wildlife trafficking, may begin.", "vocab": [{"ko": "포함하다", "en": "to include"}, {"ko": "환경 범죄", "en": "environmental crime"}, {"ko": "규범", "en": "norm, standard"}, {"ko": "협상", "en": "negotiation"}], "analysis": [{"type": "grammar", "label": "~ㄴ (past tense attributive)", "exp": "Past tense attributive. Modifies noun. Form: verb stem + ㄴ/은.", "example_in_sentence": "포함한 환경 범죄"}, {"type": "grammar", "label": "~는 (present tense attributive)", "exp": "Present tense attributive. Modifies noun. Form: verb stem + 는.", "example_in_sentence": "만드는 협상"}, {"type": "grammar", "label": "~ㄹ 수 있다 (possibility)", "exp": "Potential/possibility marker. Form: verb stem + ㄹ 수 있다.", "example_in_sentence": "시작될 수 있습니다"}]}, {"text": "연구자들은 기후 변화 등 다른 환경 문제와 달리 이 문제는 정부가 의지를 가진다면 비교적 빠르게 해결할 수 있다고 강조합니다.", "translation": "Researchers emphasize that, unlike climate change and other environmental issues, this problem can be resolved relatively quickly if governments are willing.", "vocab": [{"ko": "기후 변화", "en": "climate change"}, {"ko": "의지", "en": "will, determination"}, {"ko": "비교적", "en": "relatively, comparatively"}, {"ko": "강조하다", "en": "to emphasize"}], "analysis": [{"type": "expression", "label": "~와/과 달리", "exp": "'Unlike N': 문제 + 와 달리 'unlike (other) problems'. Use 과 달리 after a consonant.", "example_in_sentence": "문제와 달리"}, {"type": "grammar", "label": "~(ㄴ/는)다면", "exp": "'If (hypothetically)': 가지다 → 가진다면 'if (governments) have (the will)'.", "example_in_sentence": "가진다면"}, {"type": "grammar", "label": "~ㄹ 수 있다 (possibility)", "exp": "Potential/capability marker. Form: verb stem + ㄹ 수 있다.", "example_in_sentence": "해결할 수 있다"}, {"type": "grammar", "label": "~다고 강조하다 (reported emphasis)", "exp": "Report form marking emphasis. Indicates what is stressed. Form: statement + 다고 강조하다.", "example_in_sentence": "있다고 강조합니다"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mv76kja4nr72' and md5(translation) = '8e8d4a74df197d922bdab68f7ad184e9';
update public.article_cache set translation = $t${"texts": ["A new study suggests that focusing on sounds, rather than vocabulary or grammar, is key to learning a foreign language well.", "A research team from UCL and Tohoku University studied 67 Japanese learners of English, using brain scans to examine how participants processed sounds.", "Learners with higher auditory precision learned new pronunciations faster and more accurately; their brains processed foreign-language sounds more like non-speech sounds, with less interference from their native language.", "Learners with lower auditory precision processed foreign sounds using their native language's pronunciation patterns, making it harder to accurately learn new sounds.", "Lead researcher Professor Saito-van Poeteren of UCL said the problem for British learners is not biological, but rather too little meaningful exposure combined with teaching methods that do not train auditory skills.", "The study suggests that schools need to teach sound perception alongside grammar and vocabulary, with language education tailored to learners' individual auditory characteristics."], "sentences": [{"text": "새로운 연구에서 외국어를 잘 배우려면 소리에 집중하는 것이 중요해요.", "translation": "A new study says that to learn a foreign language well, it is important to focus on its sounds.", "vocab": [{"ko": "새롭다", "en": "to be new"}, {"ko": "외국어", "en": "foreign language"}, {"ko": "집중하다", "en": "to focus"}, {"ko": "중요하다", "en": "to be important"}], "analysis": [{"type": "grammar", "label": "~(으)려면", "exp": "'If you want to / in order to': 배우다 → 배우려면 'to learn (well)'.", "example_in_sentence": "배우려면"}, {"type": "grammar", "label": "~는 것", "exp": "Turns a verb into a noun 'doing…': 집중하다 → 집중하는 것이 'focusing' (as the subject).", "example_in_sentence": "집중하는 것이"}, {"type": "expression", "label": "~에 집중하다", "exp": "Collocation meaning 'to concentrate/focus on'; 집중 (concentration) + 하다 (to do).", "example_in_sentence": "소리에 집중하는"}]}, {"text": "단어나 문법을 먼저 배우는 것보다 그 언어의 소리를 잘 듣는 것이 더 도움이 돼요.", "translation": "Listening well to the sound of the language helps more than learning words or grammar first.", "vocab": [{"ko": "단어", "en": "word"}, {"ko": "문법", "en": "grammar"}, {"ko": "먼저", "en": "first"}, {"ko": "도움이 되다", "en": "to be helpful"}], "analysis": [{"type": "grammar", "label": "~(이)나", "exp": "Particle meaning 'or': 단어나 문법 'words or grammar'.", "example_in_sentence": "단어나"}, {"type": "grammar", "label": "~는 것보다", "exp": "Comparison particle 보다 after nominalizer ~는 것; means 'more than (doing) X'.", "example_in_sentence": "배우는 것보다"}, {"type": "expression", "label": "도움이 되다", "exp": "Fixed collocation; noun 도움 (help) + 이 + 되다 (to become); means 'to be helpful/beneficial'.", "example_in_sentence": "더 도움이 돼요"}]}, {"text": "영국 UCL과 일본 도호쿠 대학교 연구팀이 일본인 영어 학습자 67명을 조사했어요.", "translation": "A research team from UCL in the UK and Tohoku University in Japan studied 67 Japanese learners of English.", "vocab": [{"ko": "영국", "en": "UK; Britain"}, {"ko": "대학교", "en": "university"}, {"ko": "연구팀", "en": "research team"}, {"ko": "조사하다", "en": "to investigate"}], "analysis": [{"type": "grammar", "label": "~과", "exp": "Conjunctive particle 'and'; connects nouns in coordination.", "example_in_sentence": "UCL과"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense ending; 조사하다 → 조사했어요 (investigated).", "example_in_sentence": "조사했어요"}]}, {"text": "연구팀은 뇌 사진을 찍어서 학습자들이 소리를 어떻게 듣는지 살펴봤어요.", "translation": "The research team took brain images and examined how learners listen to sound.", "vocab": [{"ko": "뇌", "en": "brain"}, {"ko": "사진", "en": "photo; image"}, {"ko": "찍다", "en": "to take (a photo)"}, {"ko": "살펴보다", "en": "to examine"}], "analysis": [{"type": "grammar", "label": "~아/어서 (sequence)", "exp": "Links two actions in order: 찍다 → 찍어서 'took (brain images) and then'.", "example_in_sentence": "찍어서"}, {"type": "grammar", "label": "~는지", "exp": "Indirect question marker; converts predicate to interrogative embedded clause.", "example_in_sentence": "어떻게 듣는지"}]}, {"text": "소리를 잘 구별하는 학습자들은 외국어 발음을 더 빠르고 정확하게 배웠어요.", "translation": "Learners who distinguish sound well learned foreign language pronunciation faster and more accurately.", "vocab": [{"ko": "구별하다", "en": "to distinguish"}, {"ko": "발음", "en": "pronunciation"}, {"ko": "빠르다", "en": "to be fast"}, {"ko": "정확하다", "en": "to be accurate"}], "analysis": [{"type": "grammar", "label": "~는 N", "exp": "Attributive form ~는 modifies noun 학습자들; denotes present/habitual action.", "example_in_sentence": "구별하는 학습자들"}, {"type": "grammar", "label": "~고", "exp": "Conjunctive ending connecting two predicates in parallel; 빠르고 정확하게 (fast and accurately).", "example_in_sentence": "빠르고 정확하게"}]}, {"text": "이 학습자들의 뇌는 외국어 소리를 언어가 아닌 일반 소리처럼 처리했어요.", "translation": "These learners' brains processed foreign-language sounds as ordinary sounds rather than as language.", "vocab": [{"ko": "뇌", "en": "brain"}, {"ko": "언어", "en": "language"}, {"ko": "일반", "en": "general"}, {"ko": "처리하다", "en": "to process"}], "analysis": [{"type": "grammar", "label": "~이/가 아닌", "exp": "'That is not N': 아니다 → 아닌. 언어가 아닌 일반 소리 'ordinary sounds, not language'.", "example_in_sentence": "언어가 아닌"}, {"type": "grammar", "label": "~처럼", "exp": "Postposition meaning 'like; as'; shows comparison or manner.", "example_in_sentence": "소리처럼"}]}, {"text": "그래서 모국어의 영향을 덜 받았어요.", "translation": "Therefore, they were less affected by their native language.", "vocab": [{"ko": "모국어", "en": "native language"}, {"ko": "영향", "en": "influence"}, {"ko": "받다", "en": "to receive"}], "analysis": [{"type": "grammar", "label": "영향을 받다", "exp": "'To be influenced (by)': 영향 'influence' + 을 받다 'receive'. 덜 받았어요 'were less influenced'.", "example_in_sentence": "영향을 덜 받았어요"}, {"type": "grammar", "label": "덜", "exp": "Adverb meaning 'less'; modifies verb to express reduced degree or quantity.", "example_in_sentence": "덜 받았어요"}]}, {"text": "소리를 잘 구별하지 못하는 학습자들은 모국어 발음 방식으로 외국어 소리를 들었어요.", "translation": "Learners who couldn't tell sounds apart well heard foreign sounds through the pronunciation patterns of their native language.", "vocab": [{"ko": "구별하다", "en": "to distinguish"}, {"ko": "발음", "en": "pronunciation"}, {"ko": "방식", "en": "method; way"}], "analysis": [{"type": "grammar", "label": "~지 못하다", "exp": "Negation of ability; ~지 않다 (does not) vs. ~지 못하다 (cannot/unable to). 구별하다 → 구별하지 못하다.", "example_in_sentence": "구별하지 못하는"}, {"type": "grammar", "label": "~로", "exp": "Postposition indicating means, method, or manner; 방식으로 = 'by means of; in the manner of'.", "example_in_sentence": "방식으로"}]}, {"text": "이것 때문에 새로운 소리를 정확하게 배우기가 더 어려웠어요.", "translation": "Because of this, it was harder to learn new sounds accurately.", "vocab": [{"ko": "때문", "en": "because of; reason"}, {"ko": "새롭다", "en": "to be new"}, {"ko": "정확하다", "en": "to be accurate"}, {"ko": "어렵다", "en": "to be difficult"}], "analysis": [{"type": "grammar", "label": "~기가 어렵다", "exp": "~기 turns a verb into a noun: 배우다 → 배우기가 어려웠어요 'learning was hard'.", "example_in_sentence": "배우기가"}, {"type": "grammar", "label": "~았/었어요", "exp": "Past tense; 어렵다 → 어려웠어요 (was difficult).", "example_in_sentence": "어려웠어요"}]}, {"text": "연구를 이끈 UCL의 사이토반 포터런 교수는 영국 사람들이 언어를 못 배우는 이유가 생물학적인 것이 아니라고 했어요.", "translation": "Professor Saitoban Potterun of UCL, who led the research, said that the reason British people fail to learn language is not biological.", "vocab": [{"ko": "이끌다", "en": "to lead"}, {"ko": "교수", "en": "professor"}, {"ko": "이유", "en": "reason"}, {"ko": "생물학적", "en": "biological"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (past modifier)", "exp": "Past modifier: 이끌다 → 이끈 (ㄹ drops) 'who led (the study)'.", "example_in_sentence": "이끈"}, {"type": "grammar", "label": "~이/가 아니라고 하다", "exp": "Reports a negative statement: 아니다 → 아니라고 했어요 'said (it) is not'.", "example_in_sentence": "아니라고 했어요"}]}, {"text": "그는 \"많은 사람들이 외국어를 듣는 시간이 너무 적고, 소리 듣기 능력을 키우는 교육을 받지 못하는 것이 문제\"라고 말했어요.", "translation": "He said \"The problem is that many people have too little time listening to foreign languages and lack education to develop sound-listening ability.\"", "vocab": [{"ko": "많다", "en": "to be many; to be a lot"}, {"ko": "시간", "en": "time"}, {"ko": "능력", "en": "ability"}, {"ko": "키우다", "en": "to develop; to raise"}], "analysis": [{"type": "grammar", "label": "~는 N", "exp": "Attributive ~는 modifies nouns; 듣는 시간 = 'time (that is) listening'.", "example_in_sentence": "듣는 시간이"}, {"type": "grammar", "label": "~고", "exp": "Conjunctive ~고 lists two parallel predicates: 적고 (is few) and 받지 못하는 (fail to receive).", "example_in_sentence": "적고"}, {"type": "grammar", "label": "~지 못하다", "exp": "Negation of ability; 받다 → 받지 못하다 = '(they) fail to receive/cannot receive'.", "example_in_sentence": "받지 못하는"}]}, {"text": "이 연구는 학교에서 문법과 단어뿐만 아니라 소리 듣기 교육도 중요하다고 말해요.", "translation": "This study says that in schools, teaching students to listen to sounds is important, not just grammar and vocabulary.", "vocab": [{"ko": "학교", "en": "school"}, {"ko": "문법", "en": "grammar"}, {"ko": "단어", "en": "word"}, {"ko": "중요하다", "en": "to be important"}], "analysis": [{"type": "expression", "label": "~뿐만 아니라 ~도", "exp": "Parallel construction 'not only X but also Y'; 뿐만 아니라 (not only) + 도 (also).", "example_in_sentence": "단어뿐만 아니라 소리 듣기 교육도"}, {"type": "grammar", "label": "~다고 말하다", "exp": "Quotative ~다고 + 말하다 (to say); 중요하다 → 중요하다고 말해요.", "example_in_sentence": "중요하다고 말해요"}]}, {"text": "학습자의 소리 듣기 특성에 맞는 외국어 교육이 필요해요.", "translation": "Foreign language education suited to learners' sound-listening characteristics is necessary.", "vocab": [{"ko": "특성", "en": "characteristic"}, {"ko": "맞다", "en": "to fit; to suit"}, {"ko": "교육", "en": "education"}, {"ko": "필요하다", "en": "to be necessary"}], "analysis": [{"type": "grammar", "label": "~는 N", "exp": "Attributive form ~는 modifies noun; 맞는 교육 = 'education that fits/suits'.", "example_in_sentence": "맞는 외국어 교육이"}, {"type": "grammar", "label": "~어요", "exp": "Present tense polite ending; 필요하다 → 필요해요 (is necessary).", "example_in_sentence": "필요해요"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mv8lzwnjdv4h' and md5(translation) = '49c66e49ccaa74765153d7d7c4a7646b';
update public.article_cache set translation = $t${"texts": ["The Inter-Parliamentary Alliance on China (Ipac) has published an audit report on the UK's approach to China, concluding that its China policy lacks coherence and is plagued by a shortage of senior-level expertise.", "The report criticises past UK engagement with China for having exposed the country to interference risks while largely failing to deliver on promised opportunities, and states that any engagement must be grounded in the recognition that the People's Republic of China is an inherently hostile authoritarian state that does not share British values.", "The report cites a visiting Chinese delegation that noted no senior UK government official engaging with Beijing spoke Mandarin or had significant experience of living in China; it further observes that existing British expertise remains siloed and has not been translated into operational capability, with budget cuts compounding the problem.", "Ipac counts around 50 MPs among its members from Labour, the Conservatives, the Liberal Democrats, the Scottish National Party, the Greens, and Reform; former security minister Tom Tugendhat praised the report as a clear-eyed account of the defining foreign policy challenge of the century.", "A UK government spokesperson acknowledged that working with China entails both opportunities and threats, while the Chinese Embassy in London dismissed Ipac's report as fabrication designed to mislead the public and undermine China's international relations.", "While accepting that disengagement is not an option, the report calls for clearly defined red lines around critical infrastructure, frontier technologies, and human rights; the climate crisis is identified as a lower-risk area for cooperation, though the report acknowledges that meeting climate targets requires accepting medium-term dependence on supply chains tainted by forced labour and unfair trade practices.", "Former diplomat and director of the Lau China Institute at King's College London Kerry Brown welcomed the recognition that better language skills are needed, but stressed that lived experience in China is now the critical issue, noting that essential knowledge cannot be learned in a classroom and that opportunities for such experience are both increasingly difficult to access and insufficiently supported."], "sentences": [{"text": "대중국 의원 동맹(이하 아이팩)이 영국의 대중국 접근 방식에 대한 감사 보고서를 발표하였습니다.", "translation": "The Inter-Parliamentary Alliance on China (hereinafter IPAC) released an audit report on the UK's approach to China.", "vocab": [{"ko": "대중국", "en": "toward China; China-related"}, {"ko": "접근 방식", "en": "approach; manner of approach"}, {"ko": "감사 보고서", "en": "audit report; inspection report"}, {"ko": "발표하다", "en": "to release; to announce"}], "analysis": [{"type": "grammar", "label": "이하", "exp": "'Hereafter': (이하 아이팩) = '(hereafter IPAC)', introducing a short name.", "example_in_sentence": "이하 아이팩"}, {"type": "grammar", "label": "~에 대한 (attributive)", "exp": "Attributive form of ~에 대하다 (regarding/concerning). Modifies a following noun to indicate its object or subject matter.", "example_in_sentence": "대중국 접근 방식에 대한 감사 보고서"}]}, {"text": "보고서는 영국의 대중국 정책이 일관성을 결여한 채 고위급 전문 인력 부족에 시달리고 있다고 지적하였습니다.", "translation": "The report pointed out that the UK's China policy lacks consistency and suffers from a shortage of senior expert personnel.", "vocab": [{"ko": "일관성", "en": "consistency; coherence"}, {"ko": "결여하다", "en": "to lack; to be deficient in"}, {"ko": "고위급", "en": "senior-level; high-ranking"}, {"ko": "시달리다", "en": "to suffer from; to be afflicted with"}], "analysis": [{"type": "expression", "label": "~을 결여한 채", "exp": "Expresses a state of lacking something while persisting in that deficient condition. ~은 채 marks continuation in that state.", "example_in_sentence": "일관성을 결여한 채"}, {"type": "grammar", "label": "~다고 지적하다 (indirect quotation + verb)", "exp": "Combines indirect quotation ~다고 with verb 지적하다 (point out). Reports what the subject found or noted.", "example_in_sentence": "시달리고 있다고 지적하였습니다"}]}, {"text": "보고서는 중국과의 과거 관계 형성이 약속된 기회를 실현하는 데 그쳤을 뿐, 외부 간섭의 위험에 영국을 노출시키는 경우가 많았다고 비판하였습니다.", "translation": "The report criticized past relationship-building with China, saying it went no further than pursuing promised opportunities and often exposed the UK to the risk of outside interference.", "vocab": [{"ko": "관계 형성", "en": "relationship-building; formation of relations"}, {"ko": "실현하다", "en": "to realize; to achieve"}, {"ko": "간섭", "en": "interference; intervention"}, {"ko": "노출시키다", "en": "to expose; to lay bare"}], "analysis": [{"type": "grammar", "label": "~는 데 그치다 (limitation)", "exp": "~는 데 (in respect to/in regard to) + 그치다 (merely/only amount to). Indicates an action stops at a certain point, implying limitation or insufficiency.", "example_in_sentence": "실현하는 데 그쳤을 뿐"}, {"type": "grammar", "label": "~(으)ㄹ 뿐", "exp": "'Only / merely (and nothing more)': 그치다 → 그쳤을 뿐 'merely stopped at'.", "example_in_sentence": "그쳤을 뿐"}, {"type": "expression", "label": "~는 경우가 많다 (frequency expression)", "exp": "Indicates a frequent or common occurrence. ~는 경우 (cases where) + 많다 (many).", "example_in_sentence": "노출시키는 경우가 많았다"}, {"type": "grammar", "label": "~다고 비판하다 (indirect quotation + verb)", "exp": "Combines indirect quotation with verb 비판하다 (criticize). Reports evaluative judgment.", "example_in_sentence": "많았다고 비판하였습니다"}]}, {"text": "아울러 중국 인민공화국은 본질적으로 적대적인 권위주의 국가이며 영국과 가치관을 공유하지 않는다는 인식을 바탕으로 대중국 관여 정책이 수립되어야 한다고 명시하였습니다.", "translation": "It also stated that the UK's policy of engagement with China should be built on the understanding that the People's Republic of China is an inherently hostile authoritarian state that does not share the UK's values.", "vocab": [{"ko": "아울러", "en": "furthermore; in addition"}, {"ko": "본질적", "en": "inherent; fundamental"}, {"ko": "적대적", "en": "hostile; adversarial"}, {"ko": "권위주의", "en": "authoritarianism"}], "analysis": [{"type": "grammar", "label": "~(이)며", "exp": "Formal 'is N and': 국가이다 → 국가이며 'is a state, and'.", "example_in_sentence": "국가이며"}, {"type": "expression", "label": "~다는 인식을 바탕으로", "exp": "~다는 인식 (recognition/understanding that ~) + ~을 바탕으로 (on the basis of). Indicates premise or foundation for subsequent statement.", "example_in_sentence": "공유하지 않는다는 인식을 바탕으로"}, {"type": "grammar", "label": "~아/어야 하다", "exp": "'Must / should': 수립되다 'to be established' → 수립되어야 한다 'should be established'.", "example_in_sentence": "수립되어야 한다"}, {"type": "grammar", "label": "~다고 명시하다 (indirect quotation + verb)", "exp": "Combines indirect quotation with verb 명시하다 (specify/state explicitly). Reports an explicit assertion.", "example_in_sentence": "수립되어야 한다고 명시하였습니다"}]}, {"text": "보고서는 중국을 방문한 한 대표단의 사례를 인용하였습니다.", "translation": "The report cited the example of a delegation that visited China.", "vocab": [{"ko": "방문하다", "en": "to visit"}, {"ko": "대표단", "en": "delegation; representative group"}, {"ko": "사례", "en": "example; case; instance"}, {"ko": "인용하다", "en": "to cite; to quote"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (past modifier)", "exp": "Past modifier: 방문하다 → 중국을 방문한 대표단 'a delegation that visited China'.", "example_in_sentence": "중국을 방문한 한 대표단"}]}, {"text": "해당 대표단은 영국 정부에서 고위급으로 베이징과 교류하는 인사 중 중국어 구사자나 중국 거주 경험자가 없다는 점에 주목하였습니다.", "translation": "The delegation noted that none of the UK government officials who deal with Beijing at a senior level speak Chinese or have lived in China.", "vocab": [{"ko": "해당", "en": "corresponding; relevant"}, {"ko": "교류하다", "en": "to exchange; to interact"}, {"ko": "중국어 구사자", "en": "Chinese speaker"}, {"ko": "거주", "en": "residence; dwelling"}], "analysis": [{"type": "grammar", "label": "~는 인사 (attributive relative clause)", "exp": "~는 (present/habitual marker) modifies 인사 (personnel/person). Creates relative clause describing the personnel engaged in the action.", "example_in_sentence": "교류하는 인사"}, {"type": "expression", "label": "N 중", "exp": "'Among N': 교류하는 인사 중 'among the officials who deal with (Beijing)'.", "example_in_sentence": "인사 중"}, {"type": "expression", "label": "~다는 점에 주목하다 (to note/pay attention to the fact that)", "exp": "~다는 점 (the fact/point that ~) + 주목하다 (note/pay attention). Reports recognition of a significant fact.", "example_in_sentence": "없다는 점에 주목하였습니다"}]}, {"text": "영국 내에 전문 지식이 존재하기는 하나 부서 간에 분산된 채 실질적 역량으로 전환되지 못하고 있으며, 예산 삭감 또한 문제를 악화시키고 있다고 보고서는 지적하였습니다.", "translation": "The report pointed out that although expert knowledge exists within the UK, it remains dispersed across departments and is not being converted into practical capacity, and budget cuts are also worsening the problem.", "vocab": [{"ko": "전문 지식", "en": "expert knowledge; expertise"}, {"ko": "부서", "en": "department; division"}, {"ko": "분산되다", "en": "to be dispersed; to be scattered"}, {"ko": "역량", "en": "capacity; capability"}], "analysis": [{"type": "grammar", "label": "~기는 하나 (concessive: although)", "exp": "~기는 (even if/although) + 하나 (but/yet). Concessive conjunction admitting a fact while denying its implication.", "example_in_sentence": "존재하기는 하나"}, {"type": "expression", "label": "~ 간에 (between; among)", "exp": "Postposition marking relationship among multiple entities. Often used as ~간에 or ~간(에서).", "example_in_sentence": "부서 간에 분산된"}, {"type": "grammar", "label": "~(으)ㄴ 채", "exp": "'While remaining in a state': 분산되다 → 분산된 채 'while staying scattered'.", "example_in_sentence": "분산된 채"}, {"type": "grammar", "label": "~지 못하다 (inability; failure)", "exp": "Auxiliary expressing inability or failure to complete an action. ~지 못하다 = cannot/unable to.", "example_in_sentence": "전환되지 못하고 있으며"}]}, {"text": "아이팩에는 노동당, 보수당, 자유민주당, 스코틀랜드 국민당, 녹색당, 개혁당 소속 의원 약 50명이 참여하고 있습니다.", "translation": "About 50 members from the Labour Party, Conservative Party, Liberal Democrats, Scottish National Party, Green Party, and Reform Party participate in IPAC.", "vocab": [{"ko": "노동당", "en": "Labour Party"}, {"ko": "보수당", "en": "Conservative Party"}, {"ko": "소속", "en": "affiliation; membership"}, {"ko": "참여하다", "en": "to participate; to take part"}], "analysis": [{"type": "expression", "label": "~소속 (affiliated with; belonging to)", "exp": "Noun-modifying form indicating membership or affiliation. Placed before modified noun to show which organization someone belongs to.", "example_in_sentence": "개혁당 소속 의원"}, {"type": "grammar", "label": "~고 있다 (progressive/durative)", "exp": "Auxiliary marking ongoing or habitual action/state. Indicates current participation or continued involvement.", "example_in_sentence": "참여하고 있습니다"}]}, {"text": "전직 안보부 장관 톰 터건댓은 보고서가 이 시대의 핵심적인 외교 정책 문제를 명료하게 직시한 보고서라고 평가하였습니다.", "translation": "Former Security Minister Tom Tugendhat evaluated the report as one that clearly addresses the core diplomatic policy issue of this era.", "vocab": [{"ko": "전직", "en": "former; ex-"}, {"ko": "안보부", "en": "security ministry; ministry of national security"}, {"ko": "장관", "en": "minister"}, {"ko": "직시하다", "en": "to face squarely; to confront directly"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (past modifier)", "exp": "Past modifier: 직시하다 → 직시한 보고서 'a report that squarely faced (the issue)'.", "example_in_sentence": "직시한 보고서"}, {"type": "grammar", "label": "~라고 평가하다 (indirect quotation + evaluation)", "exp": "Combines nominal quotation ~라고 with verb 평가하다 (evaluate/assess). Reports an evaluative judgment.", "example_in_sentence": "보고서라고 평가하였습니다"}]}, {"text": "영국 정부 대변인은 중국과의 협력이 기회를 제공하는 동시에 위협도 수반한다는 점을 분명히 인식하고 있다고 밝혔습니다.", "translation": "A UK government spokesperson said the government is well aware that cooperation with China brings opportunities but also carries threats.", "vocab": [{"ko": "대변인", "en": "spokesman; spokesperson"}, {"ko": "협력", "en": "cooperation; collaboration"}, {"ko": "수반하다", "en": "to entail; to involve; to bring with"}, {"ko": "분명히", "en": "clearly; distinctly"}], "analysis": [{"type": "expression", "label": "~는 동시에 (simultaneously; at the same time)", "exp": "~는 동시(에) marks two actions/states occurring simultaneously. Indicates coexistence of two conditions.", "example_in_sentence": "기회를 제공하는 동시에 위협도 수반한다"}, {"type": "expression", "label": "~다는 점을 인식하다 (to recognize/be aware of the fact that)", "exp": "~다는 점 (the fact that; the point that) + 인식하다 (recognize/be aware of). Reports conscious acknowledgment.", "example_in_sentence": "수반한다는 점을 인식하고 있다"}]}, {"text": "이에 대하여 런던 주재 중국 대사관은 아이팩의 유일한 목표는 허위를 조작하고 여론을 오도하며 중국과 타국 간의 관계를 훼손하는 것이라고 반박하였습니다.", "translation": "In response, the Chinese Embassy in London countered that IPAC's sole goal is to fabricate falsehoods, mislead public opinion, and damage relations between China and other countries.", "vocab": [{"ko": "이에 대하여", "en": "in response to this; to this"}, {"ko": "주재", "en": "stationed; resident"}, {"ko": "허위", "en": "falsehood; false information"}, {"ko": "조작하다", "en": "to fabricate; to manipulate"}], "analysis": [{"type": "expression", "label": "~에 대하여 (in response to; regarding)", "exp": "Postposition marking direction or target of response. Introduces counter-statement or reaction.", "example_in_sentence": "이에 대하여"}, {"type": "grammar", "label": "~고 / ~(으)며", "exp": "Both join actions in a list, 'and': 조작하고 … 오도하며 … 훼손하는 'fabricating, misleading and damaging'.", "example_in_sentence": "조작하고 여론을 오도하며"}, {"type": "grammar", "label": "~는 것이다 (nominalization/assertion)", "exp": "~는 것 (the act/fact of ~) + 이다 (be). Nominalizes verb phrase and asserts it as fact/identity.", "example_in_sentence": "훼손하는 것이라고"}]}, {"text": "보고서는 관여 중단은 선택지가 될 수 없다는 점을 인정하는 만큼, 핵심 기반 시설·첨단 기술·인권 등의 분야에서 명확한 한계선을 설정할 것을 촉구하였습니다.", "translation": "Acknowledging that disengagement cannot be an option, the report called for clear red lines in areas such as critical infrastructure, advanced technology and human rights.", "vocab": [{"ko": "관여 중단", "en": "disengagement; cessation of engagement"}, {"ko": "선택지", "en": "option; choice"}, {"ko": "인정하다", "en": "to acknowledge; to admit"}, {"ko": "핵심 기반 시설", "en": "critical infrastructure"}], "analysis": [{"type": "expression", "label": "~이/가 될 수 없다", "exp": "'Cannot be N': 선택지가 될 수 없다 'cannot be an option'.", "example_in_sentence": "선택지가 될 수 없다"}, {"type": "expression", "label": "~는 만큼", "exp": "'Since / as': 인정하다 → 인정하는 만큼 'since (the report) acknowledges'.", "example_in_sentence": "인정하는 만큼"}, {"type": "grammar", "label": "~(으)ㄹ 것을 촉구하다", "exp": "'Call for (doing)': 설정하다 → 설정할 것을 촉구하였습니다 'urged that (clear lines) be set'.", "example_in_sentence": "설정할 것을 촉구하였습니다"}]}, {"text": "기후 위기는 상대적으로 위험도가 낮은 협력 영역으로 분류되었으나, 중국 없이는 기후 목표 달성이 불가능하기에 강제 노동과 불공정 무역 관행으로 얼룩진 공급망에 대한 중기적 의존을 감수해야 한다는 점도 명시되었습니다.", "translation": "Although climate crisis was classified as a relatively low-risk area of cooperation, the report also specified that medium-term dependence on supply chains tainted by forced labor and unfair trade practices must be accepted because climate targets cannot be achieved without China.", "vocab": [{"ko": "위험도", "en": "risk level; degree of risk"}, {"ko": "분류되다", "en": "to be classified; to be categorized"}, {"ko": "강제 노동", "en": "forced labor"}, {"ko": "불공정", "en": "unfair; unjust"}], "analysis": [{"type": "grammar", "label": "~으나 (concessive: however; but)", "exp": "Coordinate connective linking two clauses with contrasting information. Admits first fact while introducing opposing second point.", "example_in_sentence": "분류되었으나"}, {"type": "grammar", "label": "~기에 (because; since; on the ground that)", "exp": "Causal connective ~기 + ~에. Marks reason or cause for following statement.", "example_in_sentence": "불가능하기에"}, {"type": "expression", "label": "~으로 얼룩진 (tainted/stained with)", "exp": "~으로 얼룩지다 (be stained/marked with). Describes something marred or corrupted by specified condition.", "example_in_sentence": "강제 노동과 불공정 무역 관행으로 얼룩진 공급망"}, {"type": "expression", "label": "~에 대한 (regarding; concerning; toward)", "exp": "Attributive form of ~에 대하다 modifying following noun. Indicates object or target of the relation.", "example_in_sentence": "공급망에 대한 의존"}]}, {"text": "킹스 칼리지 런던 류 중국 연구소 소장 케리 브라운 전 외교관은 언어 능력 향상의 필요성에 대한 공감대 형성을 환영하면서도, 현재 가장 중요한 문제는 중국에서의 직접적인 생활 경험이라고 강조하였습니다.", "translation": "Kerry Brown, former diplomat and director of the Lau China Institute at King's College London, welcomed the formation of consensus regarding the necessity of improving language abilities but emphasized that the most important issue currently is direct living experience in China.", "vocab": [{"ko": "언어 능력", "en": "language ability; language skills"}, {"ko": "공감대 형성", "en": "formation of consensus; building agreement"}, {"ko": "환영하다", "en": "to welcome; to embrace"}, {"ko": "직접적", "en": "direct; firsthand"}], "analysis": [{"type": "expression", "label": "~에 대한 (regarding; about)", "exp": "Attributive postposition marking object or topic of the preceding noun. Indicates what ~필요성 (necessity) concerns.", "example_in_sentence": "향상의 필요성에 대한"}, {"type": "grammar", "label": "~(으)면서도", "exp": "'While / even as': 환영하다 → 환영하면서도 'while welcoming (it), (he) also…'.", "example_in_sentence": "환영하면서도"}, {"type": "grammar", "label": "~라고 강조하다 (indirect quotation + emphatic verb)", "exp": "Nominal quotation ~라고 + verb 강조하다 (emphasize/stress). Reports assertion with emphasis.", "example_in_sentence": "경험이라고 강조하였습니다"}]}, {"text": "그는 교실에서 배울 수 없는 것들이 있으며, 이를 현지 생활을 통해 습득하는 것이 현재로서는 매우 어려운 데다 충분한 지원도 이루어지지 않고 있다고 지적하였습니다.", "translation": "He pointed out that there are things that can't be learned in a classroom, and that picking them up by living in the country is currently very difficult, with not enough support being provided either.", "vocab": [], "analysis": []}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mv8mjbykaxue' and md5(translation) = '17424dbf2f684151be9003bf67e6e07f';
update public.article_cache set translation = $t${"texts": ["A post discussing why C-section births are on the rise caught widespread attention on a Korean online community, noting that more mothers are opting for C-sections over natural childbirth.", "A C-section is a delivery method where the baby is delivered through an incision in the abdomen, and it is preferred partly because pain management is easier and the delivery time can be scheduled in advance.", "As the average age of mothers in Korea rises, high-risk pregnancies appear to be increasing as well, and C-sections are being chosen not only for medical reasons but also based on the mother's personal preference.", "Interestingly, the topic of 'saju' also came up in the discussion — saju is a traditional Korean concept of reading one's fate based on the date and time of birth, and some expressed the view that a C-section birth could interfere with one's saju.", "Korea's C-section rate is considered high by global standards, and as the range of birth options expands, the factors mothers weigh when making their decision are also changing."], "sentences": [{"text": "한 온라인 커뮤니티에 제왕절개 출산이 늘어나는 이유를 다룬 글이 올라오면서 많은 사람들의 관심을 받았습니다.", "translation": "A post about why cesarean births are increasing went up on an online community and drew a lot of attention.", "vocab": [{"ko": "제왕절개", "en": "cesarean section"}, {"ko": "다루다", "en": "to deal with; to cover"}, {"ko": "올라오다", "en": "to be posted; to come up"}, {"ko": "관심을 받다", "en": "to receive attention"}], "analysis": [{"type": "grammar", "label": "~는 이유", "exp": "Attributive form of present tense using ~는 to modify a noun. Marks ongoing or habitual action: 늘어나다(to increase) → 늘어나는(increasing).", "example_in_sentence": "늘어나는 이유"}, {"type": "grammar", "label": "~(으)면서", "exp": "'As / when': 올라오다 → 올라오면서 'as (the post) went up, …'.", "example_in_sentence": "올라오면서"}, {"type": "expression", "label": "~(으)ㄴ 글", "exp": "Past participle form using ~(으)ㄴ to describe a noun. Shows completed or perfected state: 다루다 → 다룬 글(a post that dealt with).", "example_in_sentence": "다룬 글"}]}, {"text": "자연분만 대신 제왕절개를 선택하는 산모가 많아지고 있다고 합니다.", "translation": "It is said that more mothers are choosing cesarean sections instead of natural childbirth.", "vocab": [{"ko": "자연분만", "en": "natural childbirth"}, {"ko": "대신", "en": "instead of"}, {"ko": "선택하다", "en": "to choose"}, {"ko": "산모", "en": "mother; pregnant woman"}], "analysis": [{"type": "grammar", "label": "~고 있다", "exp": "Ongoing change: 많아지다 'to become more' → 많아지고 있다 'are becoming more (common)'.", "example_in_sentence": "많아지고 있다"}, {"type": "grammar", "label": "~다고 합니다", "exp": "Indirect reported speech with ~다고 합니다(it is said that). Conveys hearsay or general claim: 선택하는 산모가 많아지고 있다 → 선택하는 산모가 많아지고 있다고 합니다.", "example_in_sentence": "있다고 합니다"}]}, {"text": "제왕절개는 배를 절개해서 아기를 꺼내는 출산 방법입니다.", "translation": "Cesarean section is a delivery method in which the abdomen is incised to remove the baby.", "vocab": [{"ko": "배", "en": "abdomen; belly"}, {"ko": "절개하다", "en": "to incise; to cut"}, {"ko": "꺼내다", "en": "to take out; to remove"}, {"ko": "출산", "en": "childbirth; delivery"}], "analysis": [{"type": "grammar", "label": "~아/어서", "exp": "Connective ending expressing sequential action or means. Shows the first action leads to the second: 절개하다 → 절개해서(by incising).", "example_in_sentence": "절개해서"}, {"type": "grammar", "label": "~는 N", "exp": "Attributive form using ~는 to modify a noun. Indicates action describing the noun: 꺼내다 → 꺼내는 출산 방법(a delivery method that removes).", "example_in_sentence": "꺼내는 출산 방법"}]}, {"text": "자연분만보다 통증 조절이 쉽고 출산 시간을 예측할 수 있기 때문입니다.", "translation": "It is because pain control is easier than natural childbirth and delivery time can be predicted.", "vocab": [{"ko": "통증", "en": "pain"}, {"ko": "조절", "en": "control"}, {"ko": "예측하다", "en": "to predict"}], "analysis": [{"type": "grammar", "label": "~기 때문이다", "exp": "'It's because…': 있다 → 있기 때문입니다 'it's because (you) can (predict)'.", "example_in_sentence": "있기 때문입니다"}, {"type": "grammar", "label": "~(으)ㄹ 수 있다", "exp": "'Can': 예측하다 → 예측할 수 있다 'can predict'.", "example_in_sentence": "예측할 수 있기"}]}, {"text": "한국에서는 산모의 나이가 높아지면서 고위험 임신이 늘어나는 것 같습니다.", "translation": "It seems that high-risk pregnancies are increasing in Korea as mothers' age grows higher.", "vocab": [{"ko": "나이", "en": "age"}, {"ko": "높아지다", "en": "to increase; to become higher"}, {"ko": "고위험", "en": "high-risk"}, {"ko": "임신", "en": "pregnancy"}], "analysis": [{"type": "grammar", "label": "~(으)면서", "exp": "'As (one thing changes, another does)': 높아지다 → 높아지면서 'as (mothers' age) rises'.", "example_in_sentence": "높아지면서"}, {"type": "grammar", "label": "~는 것 같다", "exp": "Expression of supposition or likelihood using nominalizer ~는 것 and 같다: 늘어나다 → 늘어나는 것 같다(it seems to be increasing).", "example_in_sentence": "늘어나는 것 같습니다"}]}, {"text": "의료적 이유뿐만 아니라 산모 본인의 선택으로 제왕절개를 하는 경우도 있다고 합니다.", "translation": "It is said that there are also cases where cesarean sections are performed not only for medical reasons but also by the mother's own choice.", "vocab": [{"ko": "의료적", "en": "medical"}, {"ko": "이유", "en": "reason"}, {"ko": "선택", "en": "choice"}], "analysis": [{"type": "expression", "label": "~뿐만 아니라", "exp": "Inclusive/additive connector indicating 'not only X but also Y'. Adds emphasis to inclusivity: 의료적 이유 뿐만 아니라 산모 본인의 선택으로(not only medical reasons but also by mother's choice).", "example_in_sentence": "뿐만 아니라"}, {"type": "grammar", "label": "~으로", "exp": "Instrumental case marker showing means or reason: 선택 → 선택으로(by choice).", "example_in_sentence": "선택으로"}, {"type": "grammar", "label": "~는 경우", "exp": "Attributive form marking a case or instance: 하다 → 하는 경우(a case where it is done).", "example_in_sentence": "하는 경우"}]}, {"text": "한편, 사주와 관련된 이야기도 함께 언급되었습니다.", "translation": "Meanwhile, stories about saju (Korean fortune-telling) were also mentioned.", "vocab": [{"ko": "한편", "en": "on the other hand; meanwhile"}, {"ko": "사주", "en": "fortune-telling; destiny by birth date and time"}, {"ko": "관련되다", "en": "to be related"}, {"ko": "언급하다", "en": "to mention"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ", "exp": "Past participle form using ~(으)ㄴ to modify a noun: 관련되다 → 관련된 이야기(stories that are related).", "example_in_sentence": "관련된 이야기"}, {"type": "grammar", "label": "~되다 (passive)", "exp": "되다 makes many 하다 verbs passive: 언급하다 'to mention' → 언급되다 'to be mentioned' → 언급되었습니다 'was mentioned'.", "example_in_sentence": "언급되었습니다"}]}, {"text": "사주는 태어난 날짜와 시간으로 운명을 본다는 전통적인 개념인데, 제왕절개로 태어나면 사주가 맞지 않는다는 의견도 나왔습니다.", "translation": "Fortune-telling is a traditional concept that interprets destiny based on birth date and time, but opinions also emerged that if one is born by cesarean section, the fortune-telling does not match.", "vocab": [{"ko": "태어나다", "en": "to be born"}, {"ko": "운명", "en": "fate; destiny"}, {"ko": "보다", "en": "to see; to read (a fortune)"}, {"ko": "전통적", "en": "traditional"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ N", "exp": "Attributive form using ~(으)ㄴ to modify a noun: 태어나다 → 태어난 날짜(birth date).", "example_in_sentence": "태어난 날짜"}, {"type": "grammar", "label": "~다는 N", "exp": "Nominalizing ending ~다는 used attributively to describe a concept or claim: 본다 → 본다는 개념(a concept that interprets).", "example_in_sentence": "본다는 전통적인 개념"}, {"type": "grammar", "label": "~(으)면", "exp": "Ending meaning 'if': 태어나다 → 태어나면 'if (a baby) is born'.", "example_in_sentence": "태어나면"}, {"type": "grammar", "label": "~지 않다", "exp": "Negation using ~지 않다: 맞다 → 맞지 않다(does not match).", "example_in_sentence": "맞지 않는다"}]}, {"text": "한국의 제왕절개 비율은 세계적으로도 높은 편에 속합니다.", "translation": "Korea's cesarean rate is on the high side even by global standards.", "vocab": [{"ko": "비율", "en": "rate; ratio"}, {"ko": "세계적으로", "en": "globally; worldwide"}, {"ko": "높다", "en": "to be high"}, {"ko": "편에 속하다", "en": "to fall into a category; to be among"}], "analysis": [{"type": "expression", "label": "~ 편에 속하다", "exp": "Idiomatic phrase meaning to fall into a certain category or group: 높은 편에 속합니다(belongs to the higher category).", "example_in_sentence": "높은 편에 속합니다"}]}, {"text": "출산 방식에 대한 선택지가 다양해지면서 산모들의 고려 사항도 함께 달라지고 있습니다.", "translation": "As the options for how to give birth become more varied, what mothers have to consider is changing too.", "vocab": [{"ko": "방식", "en": "method; way"}, {"ko": "선택지", "en": "option; choice"}, {"ko": "다양해지다", "en": "to become diverse"}, {"ko": "고려 사항", "en": "consideration; factor to consider"}], "analysis": [{"type": "grammar", "label": "~(으)면서", "exp": "'As (one thing changes, another does)': 다양해지다 → 다양해지면서 'as (options) become more varied'.", "example_in_sentence": "다양해지면서"}, {"type": "grammar", "label": "~고 있다", "exp": "Progressive aspect indicating ongoing or continuous action: 달라지다 → 달라지고 있다(are changing).", "example_in_sentence": "달라지고 있습니다"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mv8mvyyfpma7' and md5(translation) = '41a9031160d830e446717273282569e9';
update public.article_cache set translation = $t${"texts": ["Sightings of the Persian leopard in the Caucasus are extremely rare — only three times in Georgia and ten times in Armenia over the past 20 years, with fewer than 1,100 individuals left worldwide.", "One leopard in particular has drawn attention: a leopard named Aren, who is presumed to have traveled about 240 kilometers from Armenia to Georgia on three legs, across cold and rugged mountain terrain, likely injured by landmines.", "The Caucasus region still holds minefields from past conflicts, and thousands of kilometers of Soviet-era barbed wire also pose dangers to leopards, bears, deer, and people alike along its borders.", "The NGO NACRES, based in Georgia, operates with a staff of just three people led by zoologist Bejan Lortkipanidze, and due to severe funding shortages, their work is largely limited to monitoring.", "Lortkipanidze said that if he had unlimited resources, he would set up a monitoring center and prioritize education outreach — visiting remote villages to teach locals what to do when they encounter a leopard and reducing human-wildlife conflict.", "WWF is also monitoring leopards in the same area, but both organizations face growing difficulties as conservation funding tightens globally; still, the survival of leopards like Aren and the work of those protecting them continues."], "sentences": [{"text": "코카서스 지역에서 페르시아표범을 보는 일은 매우 드뭅니다.", "translation": "Seeing a Persian leopard in the Caucasus region is very rare.", "vocab": [{"ko": "코카서스", "en": "Caucasus"}, {"ko": "페르시아표범", "en": "Persian leopard"}, {"ko": "드물다", "en": "to be rare"}], "analysis": [{"type": "grammar", "label": "~는 일", "exp": "Nominalizes an action (보다 'to see') into a noun phrase meaning 'the act/matter of seeing'; conveys the event itself as a countable noun.", "example_in_sentence": "페르시아표범을 보는 일"}]}, {"text": "지난 20년 동안 조지아에서는 세 번, 아르메니아에서는 열 번만 목격되었습니다.", "translation": "Over the past 20 years, it has been sighted only three times in Georgia and ten times in Armenia.", "vocab": [{"ko": "지난", "en": "past"}, {"ko": "동안", "en": "during; over"}, {"ko": "목격되다", "en": "to be sighted"}], "analysis": [{"type": "grammar", "label": "~만", "exp": "Particle limiting the quantity to an exclusive number; emphasizes 'only' and 'no more than' the stated amount.", "example_in_sentence": "세 번, 아르메니아에서는 열 번만"}, {"type": "grammar", "label": "~되다 (passive)", "exp": "목격하다 'to sight' → 목격되다 'to be sighted' → 목격되었습니다 'was sighted'.", "example_in_sentence": "목격되었습니다"}]}, {"text": "현재 페르시아표범은 전 세계에 1,100마리도 남지 않은 멸종 위기 동물입니다.", "translation": "Currently, the Persian leopard is an endangered animal with fewer than 1,100 individuals remaining in the entire world.", "vocab": [{"ko": "현재", "en": "currently; at present"}, {"ko": "남다", "en": "to remain; to be left"}, {"ko": "멸종 위기", "en": "endangerment; threat of extinction"}], "analysis": [{"type": "grammar", "label": "~도 + negation", "exp": "Particle emphasizing surprise or extremity in negative contexts; 1,100마리도 남지 않다 = 'not even 1,100 individuals remain' (even fewer than expected).", "example_in_sentence": "1,100마리도 남지 않은"}, {"type": "grammar", "label": "~은/ㄴ (attributive adjective form)", "exp": "Modifies following noun; 남지 않은 'not remaining' becomes an adjective phrase describing 동물 'animal'.", "example_in_sentence": "남지 않은 멸종 위기 동물"}]}, {"text": "그중에서 특히 주목받는 표범이 있습니다.", "translation": "Among them, there is a leopard that particularly draws attention.", "vocab": [{"ko": "그중에서", "en": "among them; from among those"}, {"ko": "특히", "en": "particularly; especially"}, {"ko": "주목받다", "en": "to draw/receive attention"}], "analysis": [{"type": "grammar", "label": "~는/은 (attributive present tense)", "exp": "Modifies noun; 주목받다 + ~는 describes an ongoing or habitual state; 주목받는 표범 = 'a leopard that draws attention'.", "example_in_sentence": "주목받는 표범"}]}, {"text": "연구자들이 '아렌'이라고 이름을 붙인 이 표범은 세 개의 다리로 약 240킬로미터를 이동한 것으로 추정됩니다.", "translation": "This leopard, which researchers named 'Aren,' is estimated to have traveled approximately 240 kilometers on three legs.", "vocab": [{"ko": "연구자", "en": "researcher"}, {"ko": "붙이다", "en": "to attach; to give (a name)"}, {"ko": "이동하다", "en": "to move; to travel"}], "analysis": [{"type": "grammar", "label": "~(이)라고 이름을 붙이다", "exp": "'To name (something) X': '아렌'이라고 이름을 붙이다 'to name it Aren'.", "example_in_sentence": "'아렌'이라고 이름을 붙인"}, {"type": "grammar", "label": "~(으)ㄴ (past modifier)", "exp": "Past modifier: 붙이다 → 이름을 붙인 이 표범 'this leopard (that researchers) named'.", "example_in_sentence": "붙인 이 표범"}, {"type": "grammar", "label": "~으로/로", "exp": "Instrumental particle indicating means or tool; 다리로 'by/with legs' specifies how the leopard moved.", "example_in_sentence": "세 개의 다리로"}, {"type": "expression", "label": "~은/ㄴ 것으로 추정되다", "exp": "Expression meaning 'is estimated/presumed to have'; combines nominalizer ~은/ㄴ 것 with 추정되다 'to be estimated'.", "example_in_sentence": "이동한 것으로 추정됩니다"}]}, {"text": "아르메니아에서 조지아까지 춥고 험한 산악 지형을 건넌 것입니다.", "translation": "That means it crossed cold, rugged mountain terrain from Armenia to Georgia.", "vocab": [{"ko": "험하다", "en": "to be rugged; to be harsh"}, {"ko": "산악", "en": "mountainous"}, {"ko": "건너다", "en": "to cross; to traverse"}], "analysis": [{"type": "grammar", "label": "~고 (coordinating adjectives)", "exp": "Connects two adjectives 춥다 'cold' + 험하다 'rugged' to modify the same noun; emphasizes multiple qualities.", "example_in_sentence": "춥고 험한 산악 지형"}, {"type": "grammar", "label": "~(으)ㄴ 것이다", "exp": "Explains what happened: 건너다 → 건넌 것입니다 '(that is,) it crossed'.", "example_in_sentence": "건넌 것입니다"}]}, {"text": "아렌이 다리를 잃게 된 것은 코카서스 지역 곳곳에 남아 있는 지뢰 때문인 것으로 보입니다.", "translation": "It appears that Aren lost its leg due to landmines remaining throughout the Caucasus region.", "vocab": [{"ko": "잃다", "en": "to lose"}, {"ko": "곳곳", "en": "here and there; throughout"}, {"ko": "남다", "en": "to remain; to be left"}, {"ko": "지뢰", "en": "landmine"}], "analysis": [{"type": "grammar", "label": "~게 되다", "exp": "Auxiliary verb phrase indicating a change of state or coming to be in a condition; 잃게 되다 'to come to lose' emphasizes the unintended or accidental nature.", "example_in_sentence": "다리를 잃게 된"}, {"type": "expression", "label": "N 때문인 것으로 보이다", "exp": "'It seems to be because of N': 지뢰 때문인 것으로 보입니다 'it appears to be due to landmines'.", "example_in_sentence": "지뢰 때문인 것으로 보입니다"}, {"type": "grammar", "label": "~아/어 있는", "exp": "남다 → 남아 있다 'to remain (a state)' → 남아 있는 지뢰 'landmines that remain'.", "example_in_sentence": "남아 있는 지뢰"}]}, {"text": "코카서스 지역에는 과거 분쟁으로 인한 지뢰밭이 여전히 남아 있습니다.", "translation": "In the Caucasus region, minefields caused by past conflicts still remain.", "vocab": [{"ko": "과거", "en": "past"}, {"ko": "분쟁", "en": "conflict; dispute"}, {"ko": "지뢰밭", "en": "minefield"}], "analysis": [{"type": "expression", "label": "~으로 인한", "exp": "Preposition-like expression meaning 'caused by; due to'; 분쟁으로 인한 지뢰밭 = 'minefields caused by conflict'.", "example_in_sentence": "과거 분쟁으로 인한 지뢰밭"}, {"type": "grammar", "label": "~아/어 있다", "exp": "Shows a state that continues: 남다 → 남아 있습니다 '(minefields) still remain'.", "example_in_sentence": "남아 있습니다"}]}, {"text": "또한 소련 시대부터 수천 킬로미터에 걸쳐 설치된 철조망도 표범, 곰, 사슴 등 야생동물에게 위험합니다.", "translation": "Additionally, barbed wire installed over thousands of kilometers since the Soviet era is also dangerous to wildlife such as leopards, bears, and deer.", "vocab": [{"ko": "소련", "en": "Soviet Union"}, {"ko": "시대", "en": "era; period"}, {"ko": "수천", "en": "thousands"}], "analysis": [{"type": "grammar", "label": "~부터", "exp": "Starting point particle marking temporal origin; 시대부터 'from/since the era' indicates a starting time extending to present.", "example_in_sentence": "소련 시대부터"}, {"type": "grammar", "label": "~에 걸쳐", "exp": "Expression meaning 'spanning; over'; indicates extent or distribution over a distance; 수천 킬로미터에 걸쳐 'spanning thousands of kilometers'.", "example_in_sentence": "수천 킬로미터에 걸쳐"}, {"type": "grammar", "label": "~도", "exp": "Particle meaning 'also'; marks addition of another subject or element; 철조망도 '(not only landmines but) barbed wire also'.", "example_in_sentence": "철조망도"}, {"type": "grammar", "label": "~은/ㄴ (attributive past tense)", "exp": "Modifies noun; 설치된 철조망 'barbed wire (that was) installed' describes a completed action.", "example_in_sentence": "설치된 철조망"}]}, {"text": "국경선을 따라 놓인 이러한 시설들은 사람과 동물 모두에게 위협이 되고 있습니다.", "translation": "These facilities placed along the border are becoming a threat to both people and animals.", "vocab": [{"ko": "국경선", "en": "border line"}, {"ko": "놓이다", "en": "to be placed; to be laid"}, {"ko": "위협", "en": "threat"}], "analysis": [{"type": "expression", "label": "~을/를 따라", "exp": "Expression meaning 'along; following'; 국경선을 따라 'along the border line' indicates spatial arrangement.", "example_in_sentence": "국경선을 따라"}, {"type": "grammar", "label": "~은/ㄴ (attributive past tense)", "exp": "Modifies noun; 놓인 시설들 'facilities (that were) placed' describes completed placement action.", "example_in_sentence": "놓인 이러한 시설들"}, {"type": "expression", "label": "A와 B 모두에게", "exp": "Expression meaning 'to both A and B'; distributes the target to two recipients: 사람과 동물 모두에게 'to both people and animals'.", "example_in_sentence": "사람과 동물 모두에게"}, {"type": "grammar", "label": "~이 되다 + ~고 있다", "exp": "Auxiliary combination: 되다 'to become' + progressive ~고 있다 'is becoming'; describes an ongoing change of state.", "example_in_sentence": "위협이 되고 있습니다"}]}, {"text": "이 지역에서 야생동물을 보호하기 위해 노력하는 단체가 있습니다.", "translation": "There is an organization working in this region to protect wildlife.", "vocab": [{"ko": "보호하다", "en": "to protect"}, {"ko": "노력하다", "en": "to make effort; to strive"}], "analysis": [{"type": "grammar", "label": "~기 위해", "exp": "Purpose/intention construction; 보호하기 위해 'in order to protect' indicates purposive motivation for 노력하다 'to make effort'.", "example_in_sentence": "보호하기 위해"}, {"type": "grammar", "label": "~는 (attributive present tense)", "exp": "Modifies noun; 노력하는 단체 'organization (that) makes effort' describes an ongoing or habitual action.", "example_in_sentence": "노력하는 단체"}]}, {"text": "조지아에 설립된 비정부기구 나크레스는 동물학자 베잔 로르트키파니제를 중심으로 단 세 명이 일하고 있습니다.", "translation": "Nacres, an NGO founded in Georgia, has just three people working there, led by zoologist Bejan Lortkipanidze.", "vocab": [{"ko": "설립되다", "en": "to be established; to be founded"}, {"ko": "비정부기구", "en": "NGO; non-governmental organization"}, {"ko": "동물학자", "en": "zoologist"}], "analysis": [{"type": "grammar", "label": "~은/ㄴ (attributive past tense)", "exp": "Modifies noun; 설립된 비정부기구 'NGO (that was) established' describes a completed action.", "example_in_sentence": "설립된 비정부기구"}, {"type": "expression", "label": "~을/를 중심으로", "exp": "Expression meaning 'centered on; with ~ as the center'; X를 중심으로 'with X as the center/focus'.", "example_in_sentence": "동물학자 베잔 로르트키파니제를 중심으로"}, {"type": "grammar", "label": "~고 있다 (progressive aspect)", "exp": "Indicates ongoing or habitual action; 일하고 있습니다 'are working' emphasizes current continuous state.", "example_in_sentence": "일하고 있습니다"}]}, {"text": "예산이 매우 부족하기 때문에 표범을 직접 보호하기보다는 주로 모니터링을 하고 있습니다.", "translation": "Because the budget is very limited, rather than directly protecting the leopard, they mainly conduct monitoring.", "vocab": [{"ko": "예산", "en": "budget"}, {"ko": "부족하다", "en": "to be insufficient; to be lacking"}, {"ko": "직접", "en": "directly"}, {"ko": "모니터링", "en": "monitoring"}], "analysis": [{"type": "grammar", "label": "~기 때문에", "exp": "Reason/cause construction; 부족하기 때문에 'because of being insufficient' provides causal explanation for the action change.", "example_in_sentence": "부족하기 때문에"}, {"type": "expression", "label": "~기보다는", "exp": "Contrastive construction meaning 'rather than ~'; 보호하기보다는 '(rather than protecting directly) instead'.", "example_in_sentence": "보호하기보다는"}]}, {"text": "로르트키파니제는 충분한 자원이 생긴다면 모니터링 센터를 세우고 싶다고 했습니다.", "translation": "Lortkipanidze said that if sufficient resources were available, he would want to establish a monitoring center.", "vocab": [{"ko": "충분하다", "en": "to be sufficient; to be enough"}, {"ko": "자원", "en": "resources"}, {"ko": "생기다", "en": "to occur; to arise; to become available"}], "analysis": [{"type": "grammar", "label": "~ㄴ다면 (conditional)", "exp": "Conditional connective; 생긴다면 'if (resources) were to occur/be available' expresses hypothetical condition.", "example_in_sentence": "생긴다면"}, {"type": "grammar", "label": "~고 싶다 (desiderative)", "exp": "Auxiliary expressing wish or desire; 세우고 싶다 'want to establish' conveys personal aspiration.", "example_in_sentence": "세우고 싶다고"}, {"type": "grammar", "label": "~다고 하다 (reported speech)", "exp": "Marks indirect quotation or reported statement; conveyed what was said in past tense context.", "example_in_sentence": "싶다고 했습니다"}]}, {"text": "또한 투셰티 같은 외딴 지역의 마을을 찾아가 주민들에게 표범을 발견했을 때 어떻게 행동해야 하는지 알리고 싶어 합니다.", "translation": "He also wants to visit villages in remote areas like Tusheti and inform residents how they should behave when a leopard is discovered.", "vocab": [{"ko": "투셰티", "en": "Tusheti (region)"}, {"ko": "같다", "en": "to be like; such as"}, {"ko": "외딴", "en": "remote; isolated"}, {"ko": "찾아가다", "en": "to visit; to go find"}], "analysis": [{"type": "grammar", "label": "~았/었을 때", "exp": "'When (something has happened)': 발견하다 → 발견했을 때 'when (they) spot (a leopard)'.", "example_in_sentence": "발견했을 때"}, {"type": "expression", "label": "~아/어야 하다", "exp": "'Should': 행동하다 → 행동해야 하다. With ~는지: 어떻게 행동해야 하는지 'how (they) should act'.", "example_in_sentence": "행동해야 하는지"}, {"type": "grammar", "label": "~고 싶어 하다", "exp": "'Want to' for a third person: 알리다 → 알리고 싶어 합니다 'wants to let (them) know'.", "example_in_sentence": "알리고 싶어 합니다"}]}, {"text": "사람과 야생동물 사이의 갈등을 줄이기 위한 교육이 필요하다고 보는 것입니다.", "translation": "He believes that education is necessary to reduce conflict between people and wildlife.", "vocab": [{"ko": "사이", "en": "between"}, {"ko": "갈등", "en": "conflict"}, {"ko": "줄이다", "en": "to reduce; to lessen"}], "analysis": [{"type": "expression", "label": "A와/과 B 사이의", "exp": "'Between A and B': 사람과 야생동물 사이의 갈등 'conflict between people and wildlife'.", "example_in_sentence": "사람과 야생동물 사이의"}, {"type": "grammar", "label": "~기 위한", "exp": "Purpose/intention marker; 줄이기 위한 '(designed/made) for reducing' indicates purposive modification.", "example_in_sentence": "줄이기 위한 교육"}, {"type": "expression", "label": "~다고 보다", "exp": "Expression meaning 'to believe; to think/regard'; 필요하다고 보다 'regards as necessary; believes is necessary'.", "example_in_sentence": "필요하다고 보는 것입니다"}]}, {"text": "나크레스와 함께 세계자연기금도 같은 지역에 카메라를 설치하며 표범을 모니터링하고 있습니다.", "translation": "Together with Nacres, the World Wildlife Fund is also installing cameras in the same region and monitoring leopards.", "vocab": [{"ko": "함께", "en": "together; with"}, {"ko": "세계자연기금", "en": "World Wildlife Fund"}, {"ko": "설치하다", "en": "to install"}], "analysis": [{"type": "grammar", "label": "~(으)며", "exp": "Written connector 'and / while': 설치하다 → 설치하며 'installing (cameras) and…'.", "example_in_sentence": "설치하며"}, {"type": "grammar", "label": "~고 있다 (progressive aspect)", "exp": "Indicates ongoing action; 모니터링하고 있습니다 'are monitoring' emphasizes continuous/habitual state.", "example_in_sentence": "모니터링하고 있습니다"}]}, {"text": "하지만 전 세계적으로 환경 보호 분야의 자금이 줄어들면서 두 단체 모두 어려운 상황에서 활동을 이어 가고 있습니다.", "translation": "However, as environmental protection funding decreases globally, both organizations continue their activities in difficult circumstances.", "vocab": [{"ko": "전 세계적으로", "en": "globally; worldwide"}, {"ko": "환경 보호", "en": "environmental protection"}, {"ko": "분야", "en": "field; domain"}, {"ko": "자금", "en": "funding; capital"}], "analysis": [{"type": "grammar", "label": "~(으)면서", "exp": "'As (one thing changes, another happens)': 줄어들다 → 줄어들면서 'as (funding) shrinks'.", "example_in_sentence": "줄어들면서"}, {"type": "expression", "label": "~ㄴ/은 상황에서", "exp": "Expression meaning 'in a ~ situation'; 어려운 상황에서 'in difficult circumstances'.", "example_in_sentence": "어려운 상황에서"}, {"type": "expression", "label": "~을/를 이어 가다", "exp": "Expression meaning 'to continue; to carry on'; 활동을 이어 가다 'to continue activities/work'.", "example_in_sentence": "활동을 이어 가고"}]}, {"text": "그럼에도 아렌처럼 극한의 환경에서 살아남은 표범과 이를 지키려는 사람들의 노력은 계속되고 있습니다.", "translation": "Even so, leopards like Aren that have survived extreme conditions, and the efforts of the people trying to protect them, carry on.", "vocab": [{"ko": "그럼에도", "en": "nevertheless; despite that"}, {"ko": "극한", "en": "extreme; extremity"}, {"ko": "살아남다", "en": "to survive"}], "analysis": [{"type": "expression", "label": "그럼에도", "exp": "'Even so; nevertheless' (short for 그러함에도 'despite that').", "example_in_sentence": "그럼에도"}, {"type": "grammar", "label": "~(으)ㄴ (past modifier)", "exp": "Past modifier: 살아남다 → 살아남은 표범 'leopards that survived'.", "example_in_sentence": "살아남은 표범"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mvr6wwtuf8t9' and md5(translation) = '017c44c3f1dbfcf9079518fa70b06cc2';
update public.article_cache set translation = $t${"texts": ["Model Joo Woo-jae drew attention after sharing that his quality of life improved after quitting Americano. He reported that positive changes occurred in both his body and daily life after giving up coffee.", "In Korea, Americano is one of the most common beverages for both office workers and students. This is because coffee culture has become deeply rooted, with cafes found throughout the streets.", "Joo Woo-jae was someone who regularly enjoyed Americano, but at some point he decided to quit coffee. Since then, various aspects of his life have changed, including improvements in sleep quality.", "Many people seem to relate to the difficulty of breaking free from a caffeine-dependent lifestyle. In particular, it is noteworthy that the habit of solving fatigue with coffee may actually interfere with sleep.", "Experts say that reducing caffeine intake can improve sleep quality and enhance overall condition. It prompts us to reconsider that while a cup of coffee helps us endure our daily routines, it may simultaneously be lowering our quality of life."], "sentences": [{"text": "모델 주우재가 아메리카노를 끊은 뒤 삶의 질이 높아졌다는 내용이 올라와 주목을 받았습니다.", "translation": "A post saying that model Joo Woo-jae's quality of life improved after he quit Americanos went up and drew attention.", "vocab": [{"ko": "끊다", "en": "to quit; to stop"}, {"ko": "올라오다", "en": "to be posted; to go up"}, {"ko": "주목을 받다", "en": "to draw attention"}], "analysis": [{"type": "grammar", "label": "~은/ㄴ 뒤", "exp": "Temporal conjunction indicating 'after' a completed action. Past tense modifier (끊은) + 뒤 marks sequence of events.", "example_in_sentence": "끊은 뒤"}, {"type": "grammar", "label": "~다는 내용", "exp": "Nominalizes a clause (높아졌다) and adds 내용 (content/claim) to report indirect speech or proposition.", "example_in_sentence": "높아졌다는 내용"}, {"type": "expression", "label": "주목을 받다", "exp": "Collocation meaning 'to attract/receive attention.' Object-marking construction with 을 + 받다.", "example_in_sentence": "주목을 받았습니다"}]}, {"text": "그는 커피를 끊으면서 몸과 일상에 긍정적인 변화가 생겼다고 합니다.", "translation": "He reportedly said that quitting coffee brought positive changes to his body and daily life.", "vocab": [{"ko": "끊다", "en": "to quit; to stop"}, {"ko": "변화", "en": "change"}, {"ko": "생기다", "en": "to occur; to arise"}], "analysis": [{"type": "grammar", "label": "~으면서", "exp": "Connective suffix indicating simultaneous or accompanying action. Base 끊다 + 으면서 marks concurrent event with main clause.", "example_in_sentence": "끊으면서"}, {"type": "grammar", "label": "~다고 합니다", "exp": "Hearsay/report marker. Nominalized clause (생겼다) + 고 + 합니다 conveys indirect information or claim.", "example_in_sentence": "생겼다고 합니다"}]}, {"text": "한국에서 아메리카노는 직장인과 학생 모두에게 가장 흔한 음료 중 하나입니다.", "translation": "In Korea, Americano is one of the most common beverages for both office workers and students.", "vocab": [{"ko": "흔하다", "en": "to be common; to be frequent"}, {"ko": "음료", "en": "beverage; drink"}], "analysis": [{"type": "grammar", "label": "가장 … N 중 하나", "exp": "'One of the most …': 가장 흔한 음료 중 하나 'one of the most common drinks'.", "example_in_sentence": "가장 흔한 음료 중 하나"}]}, {"text": "길거리 곳곳에 카페가 있을 만큼 커피 문화가 깊이 자리 잡고 있기 때문입니다.", "translation": "That's because coffee culture is so deeply rooted that there are cafés on every street.", "vocab": [{"ko": "곳곳", "en": "everywhere; here and there"}, {"ko": "자리 잡다", "en": "to be established; to take root"}], "analysis": [{"type": "expression", "label": "~(으)ㄹ 만큼", "exp": "'So much that…': 있다 → 있을 만큼 'so much that there are (cafés everywhere)'.", "example_in_sentence": "있을 만큼"}, {"type": "grammar", "label": "~기 때문이다", "exp": "Causal ending. ~기 nominalizes action + 때문이다 marks definitive reason/cause in formal speech.", "example_in_sentence": "있기 때문입니다"}]}, {"text": "주우재는 아메리카노를 즐겨 마시던 사람이었는데, 어느 순간 커피를 끊게 되었습니다.", "translation": "Joo Woo-jae was someone who habitually enjoyed drinking Americano, but at some point he came to quit coffee.", "vocab": [{"ko": "즐겨", "en": "habitually; with pleasure"}, {"ko": "끊다", "en": "to quit; to stop"}], "analysis": [{"type": "grammar", "label": "~던", "exp": "Past habitual/retrospective modifier. Combines with action verb (마시) to express repeated past action viewed from present.", "example_in_sentence": "마시던"}, {"type": "grammar", "label": "~게 되다", "exp": "Passive/inchoative auxiliary. 끊다 + 게 되다 marks involuntary transition or gradual change into state.", "example_in_sentence": "끊게 되었습니다"}, {"type": "expression", "label": "어느 순간", "exp": "Temporal expression meaning 'at some point; suddenly.' Often marks threshold moment of change.", "example_in_sentence": "어느 순간"}]}, {"text": "그 이후로 수면의 질이 나아지는 등 여러 면에서 생활이 달라졌다고 합니다.", "translation": "Since then, he says, his life has changed in many ways, such as sleeping better.", "vocab": [{"ko": "나아지다", "en": "to improve; to get better"}, {"ko": "달라지다", "en": "to change; to become different"}], "analysis": [{"type": "grammar", "label": "~다고 합니다", "exp": "Hearsay/report marker. Reports indirect information with hedging tone.", "example_in_sentence": "달라졌다고 합니다"}]}, {"text": "카페인에 의존하는 생활에서 벗어나는 것이 쉽지 않다는 점에서 많은 사람들이 공감하는 것 같습니다.", "translation": "Many people seem to relate, since breaking away from a caffeine-dependent life isn't easy.", "vocab": [{"ko": "의존하다", "en": "to depend on; to rely on"}, {"ko": "벗어나다", "en": "to escape from; to break away from"}, {"ko": "공감하다", "en": "to empathize; to relate to"}], "analysis": [{"type": "grammar", "label": "~는 (noun modifier)", "exp": "Present modifier: 의존하다 → 카페인에 의존하는 생활 'a life dependent on caffeine'.", "example_in_sentence": "의존하는 생활"}, {"type": "grammar", "label": "~다는 점에서", "exp": "Causal/thematic marker. Nominalized clause (쉽지 않다) + 점 (point/aspect) + 에서 marks reason/perspective.", "example_in_sentence": "쉽지 않다는 점에서"}, {"type": "grammar", "label": "~는 것 같다", "exp": "Conjecture/appearance marker. ~는 것 nominalizes; 같다 adds epistemic hedge 'seems/appears to.'", "example_in_sentence": "공감하는 것 같습니다"}]}, {"text": "특히 피로를 커피로 해결하는 습관이 오히려 수면을 방해할 수 있다는 점은 눈여겨볼 만합니다.", "translation": "In particular, it's worth noting that the habit of fighting fatigue with coffee can actually disturb sleep.", "vocab": [{"ko": "피로", "en": "fatigue; tiredness"}, {"ko": "방해하다", "en": "to hinder; to interfere with"}, {"ko": "눈여겨보다", "en": "to pay attention to; to note"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 수 있다", "exp": "'Can; may': 방해하다 → 방해할 수 있다 'can disturb'.", "example_in_sentence": "방해할 수 있다"}, {"type": "grammar", "label": "~다는 점", "exp": "Nominalizes proposition to treat it as 'the point/fact that.' Shifts emphasis to content itself.", "example_in_sentence": "수면을 방해할 수 있다는 점"}, {"type": "expression", "label": "~ㄹ 만하다", "exp": "Evaluative suffix meaning 'worth; deserving.' Adjoins to verb to mark worthy of action.", "example_in_sentence": "눈여겨볼 만합니다"}]}, {"text": "전문가들은 카페인 섭취를 줄이면 수면의 질이 개선되면서 전반적인 컨디션이 좋아질 수 있다고 말합니다.", "translation": "Experts say that cutting down on caffeine can improve sleep quality and, with it, your overall condition.", "vocab": [{"ko": "섭취", "en": "intake; consumption"}, {"ko": "줄이다", "en": "to reduce; to decrease"}, {"ko": "개선되다", "en": "to improve; to be improved"}, {"ko": "전반적", "en": "overall; general"}], "analysis": [{"type": "grammar", "label": "~(으)면", "exp": "Ending meaning 'if': 줄이다 → 줄이면 'if (you) reduce'.", "example_in_sentence": "줄이면"}, {"type": "grammar", "label": "~(으)면서", "exp": "'As / along with': 개선되다 → 개선되면서 'as (sleep) improves, (your condition) also…'.", "example_in_sentence": "개선되면서"}, {"type": "grammar", "label": "~ㄹ 수 있다", "exp": "Possibility marker. 좋아지다 + ㄹ 수 있다 signals potential or capacity.", "example_in_sentence": "좋아질 수 있다"}]}, {"text": "커피 한 잔이 일상을 버티게 해 주는 동시에 삶의 질을 낮추고 있을 수도 있다는 점을 다시 생각해 보게 됩니다.", "translation": "It makes you think again about how a cup of coffee may be helping you get through the day while also lowering your quality of life.", "vocab": [{"ko": "버티다", "en": "to endure; to hold out; to withstand"}, {"ko": "동시에", "en": "at the same time; simultaneously"}, {"ko": "낮추다", "en": "to lower; to reduce"}], "analysis": [{"type": "grammar", "label": "~게 하다", "exp": "Causative auxiliary. 버티다 + 게 하다 marks 'to make/enable [someone] to endure.'", "example_in_sentence": "버티게 해"}, {"type": "expression", "label": "~는 동시에", "exp": "'While at the same time': 해 주다 → 해 주는 동시에 'while helping (you get through)'.", "example_in_sentence": "해 주는 동시에"}, {"type": "grammar", "label": "~고 있다", "exp": "Progressive aspect. 낮추다 + 고 있다 marks ongoing or habitual action in present time.", "example_in_sentence": "낮추고 있을"}, {"type": "grammar", "label": "~게 되다", "exp": "Inchoative/spontaneous marker. 생각해 보다 + 게 되다 marks natural or unintentional transition into thinking.", "example_in_sentence": "생각해 보게 됩니다"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mvr7fl3vun8f' and md5(translation) = 'bc84fd866f67eda1f51c49e01241bb92';
update public.article_cache set translation = $t${"texts": ["Solar power generation is establishing itself as a key driver of global energy transition. Solar has now overtaken nuclear power generation and become the fastest-growing energy source.", "As the amount of electricity produced by solar panels increases significantly, existing energy sources are falling behind in the competition. Even nuclear power plants appear unable to keep pace with solar's rapid growth rate.", "Experts emphasize that \"solar power is now the engine of energy transition.\" Solar has gained this level of influence because production costs have steadily decreased along with technological advances.", "If solar power generation expands further, major changes are expected across the entire power system. Countries are actively moving forward with expanding renewable energy, including solar, to reduce carbon emissions."], "sentences": [{"text": "태양광 발전이 전 세계 전력 전환의 핵심 동력으로 자리잡고 있습니다.", "translation": "Solar power generation is establishing itself as a key driver of global energy transition.", "vocab": [{"ko": "태양광", "en": "solar power", "note": ""}, {"ko": "발전", "en": "generation; development", "note": ""}, {"ko": "전환", "en": "transition; shift", "note": ""}, {"ko": "핵심", "en": "core; key", "note": ""}], "analysis": [{"type": "grammar", "label": "~고 있다", "exp": "progressive aspect. Indicates ongoing action or state. 자리잡다 → 자리잡고 있다 (is establishing itself).", "example_in_sentence": "자리잡고 있습니다"}, {"type": "expression", "label": "~(으)로 자리잡다", "exp": "'To become established as N': 핵심 동력으로 자리잡다 'establish itself as a key driver'.", "example_in_sentence": "동력으로 자리잡고"}]}, {"text": "태양광은 이제 원자력 발전을 제치고 가장 빠르게 성장하는 에너지원이 되었다고 합니다.", "translation": "Solar has now reportedly overtaken nuclear power to become the fastest-growing energy source.", "vocab": [{"ko": "원자력", "en": "nuclear power", "note": ""}, {"ko": "제치다", "en": "to overtake; to surpass", "note": ""}, {"ko": "성장", "en": "growth", "note": ""}, {"ko": "에너지원", "en": "energy source", "note": ""}], "analysis": [{"type": "grammar", "label": "~게", "exp": "adverbializer suffix. Forms adverbs from adjectives. 빠르다 → 빠르게 (quickly).", "example_in_sentence": "빠르게"}, {"type": "expression", "label": "~을/를 제치고", "exp": "overtake; surpass; outpace. Indicates surpassing or going beyond something/someone.", "example_in_sentence": "원자력 발전을 제치고"}, {"type": "grammar", "label": "~다고 하다", "exp": "Reports information: 되다 → 되었다고 합니다 '(it) is said to have become'.", "example_in_sentence": "에너지원이 되었다고 합니다"}]}, {"text": "태양광 패널이 생산하는 전력량이 크게 늘어나면서 기존 에너지원들이 경쟁에서 뒤처지게 되었습니다.", "translation": "As the amount of electricity produced by solar panels increases significantly, existing energy sources are falling behind in the competition.", "vocab": [{"ko": "패널", "en": "panel", "note": ""}, {"ko": "생산하다", "en": "to produce", "note": ""}, {"ko": "전력량", "en": "amount of electricity", "note": ""}, {"ko": "늘어나다", "en": "to increase", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)면서", "exp": "simultaneous action. Two events occur at the same time. 늘어나면서 (while increasing / as it increases).", "example_in_sentence": "늘어나면서"}, {"type": "grammar", "label": "~게 되다", "exp": "'End up / come to': 뒤처지다 → 뒤처지게 되었습니다 'ended up falling behind'.", "example_in_sentence": "뒤처지게 되었습니다"}, {"type": "grammar", "label": "~게", "exp": "adverbializer suffix. Forms adverbs from adjectives. 크다 → 크게 (greatly; significantly).", "example_in_sentence": "크게"}]}, {"text": "원자력 발전소조차 태양광의 급격한 성장 속도를 따라가지 못하고 있는 것 같습니다.", "translation": "Even nuclear power plants appear unable to keep pace with solar's rapid growth rate.", "vocab": [{"ko": "발전소", "en": "power plant", "note": ""}, {"ko": "급격하다", "en": "to be rapid; to be sudden", "note": ""}, {"ko": "속도", "en": "speed; rate", "note": ""}, {"ko": "따라가다", "en": "to keep up with; to follow", "note": ""}], "analysis": [{"type": "grammar", "label": "~조차", "exp": "emphatic particle. Emphasizes inclusion, often with negation or surprise. 원자력 발전소조차 (even nuclear power plants).", "example_in_sentence": "발전소조차"}, {"type": "grammar", "label": "~지 못하다", "exp": "Negative 'cannot': 따라가다 → 따라가지 못하다 'cannot keep up'.", "example_in_sentence": "따라가지 못하고"}, {"type": "expression", "label": "~는 것 같다", "exp": "'Seems (to be)': 못하고 있다 → 못하고 있는 것 같습니다 'seem to be unable'.", "example_in_sentence": "있는 것 같습니다"}]}, {"text": "전문가들은 \"태양광은 이제 전력 전환의 엔진\"이라고 강조합니다.", "translation": "Experts emphasize that \"solar power is now the engine of energy transition.\"", "vocab": [{"ko": "전문가", "en": "expert; specialist", "note": ""}, {"ko": "엔진", "en": "engine", "note": ""}, {"ko": "강조하다", "en": "to emphasize; to stress", "note": ""}], "analysis": [{"type": "grammar", "label": "~(이)라고 강조하다", "exp": "Reports a quoted statement after a noun: \"…엔진\"이라고 강조합니다 'emphasize that (it) is \"the engine…\"'.", "example_in_sentence": "엔진\"이라고 강조합니다"}]}, {"text": "태양광이 이 정도의 영향력을 갖게 된 것은 기술 발전과 함께 생산 비용이 꾸준히 낮아졌기 때문입니다.", "translation": "Solar has gained this level of influence because production costs have steadily decreased along with technological advances.", "vocab": [{"ko": "정도", "en": "degree; extent; level", "note": ""}, {"ko": "영향력", "en": "influence; impact", "note": ""}, {"ko": "기술", "en": "technology; technique", "note": ""}, {"ko": "비용", "en": "cost; expense", "note": ""}], "analysis": [{"type": "grammar", "label": "~게 되다", "exp": "'Come to': 가지다 → 갖게 되다 'come to have' → 갖게 된 것은 'the fact that (solar) came to have'.", "example_in_sentence": "갖게 된"}, {"type": "grammar", "label": "~과/와", "exp": "with; accompaniment. Marks cooperation or joint action. 기술 발전과 함께 (together with technological advances).", "example_in_sentence": "발전과"}, {"type": "grammar", "label": "~히", "exp": "Makes an adverb from many 하다 adjectives: 꾸준하다 'to be steady' → 꾸준히 'steadily'.", "example_in_sentence": "꾸준히"}, {"type": "expression", "label": "~기 때문이다", "exp": "'It's because…': 낮아지다 → 낮아졌기 때문입니다 'because (costs) have fallen'.", "example_in_sentence": "낮아졌기 때문입니다"}]}, {"text": "태양광 발전이 더욱 확대되면 전력 시스템 전체에 큰 변화가 생길 전망입니다.", "translation": "If solar power generation expands further, major changes are expected across the entire power system.", "vocab": [{"ko": "확대하다", "en": "to expand; to enlarge", "note": ""}, {"ko": "시스템", "en": "system", "note": ""}, {"ko": "전체", "en": "whole; entire", "note": ""}, {"ko": "변화", "en": "change; transformation", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)면", "exp": "conditional. If/when something happens. 확대되면 (if it expands).", "example_in_sentence": "확대되면"}, {"type": "grammar", "label": "~(으)ㄹ 전망이다", "exp": "'Is expected to': 생기다 → 생길 전망입니다 '(big changes) are expected to come'.", "example_in_sentence": "생길 전망입니다"}]}, {"text": "각국은 탄소 배출을 줄이기 위해 태양광을 비롯한 재생에너지 확대에 적극 나서고 있습니다.", "translation": "Countries are actively moving forward with expanding renewable energy, including solar, to reduce carbon emissions.", "vocab": [{"ko": "각국", "en": "each country; various countries", "note": ""}, {"ko": "탄소", "en": "carbon", "note": ""}, {"ko": "배출", "en": "emission", "note": ""}, {"ko": "줄이다", "en": "to reduce; to cut down", "note": ""}], "analysis": [{"type": "grammar", "label": "~기 위해(서)", "exp": "in order to / for the purpose of. Expresses purpose or intention. 줄이기 위해 (in order to reduce).", "example_in_sentence": "줄이기 위해"}, {"type": "grammar", "label": "~을/를 비롯한", "exp": "including / starting with. Introduces a leading example in a list. 태양광을 비롯한 (including solar).", "example_in_sentence": "태양광을 비롯한"}, {"type": "grammar", "label": "~고 있다", "exp": "progressive aspect. Ongoing action or state. 나서고 있다 (are actively taking action).", "example_in_sentence": "나서고 있습니다"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mvro6davzi74' and md5(translation) = '716f1fa9925f08fcfba0c73f5691df51';
update public.article_cache set translation = $t${"texts": ["Starting on the 26th, posts with titles like 'Gimpo Aegibong Starbucks right now' spread across online communities and social media. The photos made it look as if a huge North Korean self-propelled gun and soldiers holding red flags were standing right outside the cafe's window.", "However, Kukmin Ilbo and other outlets reported that the photo was very likely created or altered with generative AI: the view in the photo does not match what can actually be seen from the cafe, and the distances do not add up.", "The Aegibong Starbucks itself is real. It opened in November 2024 on the observation deck of Aegibong Peace Ecopark in Gimpo, about 1.4 km from North Korea's Gaepung County, and about 123,000 people visited it in its first year.", "The media explained that some North Korean equipment can indeed be observed in the area across the way, but it is not right in front of the cafe as the photo shows.", "AI-made photos like this are often hard to tell apart from real ones. When you come across a surprising photo, it is a good idea to check where it came from and look up news reports before sharing it."], "sentences": [{"text": "지난 26일부터 온라인 커뮤니티와 SNS에 '김포 애기봉 스타벅스 근황' 같은 제목의 글이 퍼졌습니다.", "translation": "Starting on the 26th, posts with titles like 'Gimpo Aegibong Starbucks right now' spread across online communities and social media.", "vocab": [{"ko": "지난", "en": "last; past (지난 26일 = 'the 26th of this month')"}, {"ko": "근황", "en": "latest update; how someone or something is doing lately"}, {"ko": "제목", "en": "title"}, {"ko": "퍼지다", "en": "to spread"}], "analysis": [{"type": "grammar", "label": "~부터", "exp": "'From / starting': 26일 + 부터 = 'starting on the 26th'.", "example_in_sentence": "26일부터"}, {"type": "expression", "label": "N 같은 N", "exp": "'N-like; such as N': '… 근황' 같은 제목 'titles like \"… 근황\"'.", "example_in_sentence": "근황' 같은 제목"}, {"type": "grammar", "label": "~았/었습니다", "exp": "Formal polite past ending: 퍼지다 → 퍼졌습니다 'spread' (지 + 었 → 졌).", "example_in_sentence": "퍼졌습니다"}]}, {"text": "사진 속 카페 창문 바로 밖에는 거대한 북한 자주포와 붉은 깃발을 든 군인들이 서 있는 것처럼 보였습니다.", "translation": "In the photos, it looked as if a huge North Korean self-propelled gun and soldiers holding red flags were standing right outside the cafe's window.", "vocab": [{"ko": "거대하다", "en": "to be huge"}, {"ko": "자주포", "en": "self-propelled gun (artillery)"}, {"ko": "깃발", "en": "flag"}, {"ko": "들다", "en": "to hold (in one's hand)"}], "analysis": [{"type": "expression", "label": "N 속", "exp": "'In / inside N': 사진 속 'in the photo'.", "example_in_sentence": "사진 속"}, {"type": "grammar", "label": "ㄹ-dropping", "exp": "Stems ending in ㄹ drop the ㄹ before ㄴ: 들다 → 든 군인들 'soldiers holding (flags)'.", "example_in_sentence": "든 군인들"}, {"type": "grammar", "label": "~아/어 있다", "exp": "A state that continues after an action: 서다 'to stand (up)' → 서 있다 'to be standing'.", "example_in_sentence": "서 있는"}, {"type": "grammar", "label": "~는 것처럼 보이다", "exp": "'To look as if …': 서 있다 → 서 있는 것처럼 보였습니다 'it looked as if (they) were standing'.", "example_in_sentence": "서 있는 것처럼 보였습니다"}]}, {"text": "하지만 국민일보 등 여러 언론은 이 사진이 생성형 AI로 만들어지거나 수정됐을 가능성이 높다고 보도했습니다.", "translation": "However, Kukmin Ilbo and other media outlets reported that the photo was very likely created or altered with generative AI.", "vocab": [{"ko": "언론", "en": "the press; the media"}, {"ko": "생성형 AI", "en": "generative AI"}, {"ko": "수정되다", "en": "to be edited; to be altered"}, {"ko": "보도하다", "en": "to report (news)"}], "analysis": [{"type": "grammar", "label": "~거나", "exp": "'Or': 만들어지다 → 만들어지거나 '(was) either made … or …'.", "example_in_sentence": "만들어지거나"}, {"type": "grammar", "label": "~았/었을 가능성이 높다", "exp": "'It is likely that … (happened)': 수정되다 → 수정됐을 가능성이 높다 'is likely to have been altered'.", "example_in_sentence": "수정됐을 가능성이 높다"}, {"type": "grammar", "label": "~다고 (reported speech)", "exp": "Quotes a statement: 높다 + 고 보도했습니다 'reported that (the chance) is high'.", "example_in_sentence": "높다고 보도했습니다"}, {"type": "expression", "label": "N 등", "exp": "'N and others; such as N': 국민일보 등 여러 언론 'Kukmin Ilbo and other media'.", "example_in_sentence": "국민일보 등"}]}, {"text": "사진 속 풍경이 카페에서 실제로 보이는 모습과 다르고, 거리도 맞지 않는다는 것입니다.", "translation": "Their point was that the view in the photo is different from what can actually be seen from the cafe, and the distances do not add up either.", "vocab": [{"ko": "풍경", "en": "view; scenery"}, {"ko": "실제로", "en": "actually; in reality"}, {"ko": "거리", "en": "distance"}, {"ko": "맞다", "en": "to match; to fit"}], "analysis": [{"type": "grammar", "label": "~는 (verb modifier)", "exp": "Present modifier for verbs: 보이다 'to be seen' → 보이는 모습 'what can be seen'.", "example_in_sentence": "보이는 모습"}, {"type": "expression", "label": "N과/와 다르다", "exp": "'To be different from N': 모습 + 과 다르다 'different from what (one sees)'.", "example_in_sentence": "모습과 다르고"}, {"type": "grammar", "label": "~지 않다", "exp": "Negation: 맞다 → 맞지 않다 'not to match'.", "example_in_sentence": "맞지 않는다"}, {"type": "grammar", "label": "~다는 것이다", "exp": "Sums up or explains the point of what was just said: '… 맞지 않는다' + 는 것입니다 'the point is that (it) does not match'.", "example_in_sentence": "않는다는 것입니다"}]}, {"text": "애기봉 스타벅스는 실제로 있는 매장입니다.", "translation": "The Aegibong Starbucks itself is a real store.", "vocab": [{"ko": "실제로", "en": "actually; really"}, {"ko": "매장", "en": "store; shop"}], "analysis": [{"type": "grammar", "label": "~는 (verb modifier)", "exp": "있다 → 있는 매장 'a store that exists'.", "example_in_sentence": "있는 매장"}, {"type": "grammar", "label": "~입니다", "exp": "Formal polite 'is': 매장 + 입니다 'is a store'.", "example_in_sentence": "매장입니다"}]}, {"text": "2024년 11월 김포 애기봉평화생태공원 전망대에 문을 열었으며, 북한 개풍군과는 약 1.4km 떨어져 있습니다.", "translation": "It opened in November 2024 on the observation deck of Aegibong Peace Ecopark in Gimpo, and it is about 1.4 km from North Korea's Gaepung County.", "vocab": [{"ko": "전망대", "en": "observation deck"}, {"ko": "문을 열다", "en": "to open (for business)"}, {"ko": "떨어지다", "en": "to be (a distance) away; to be apart"}, {"ko": "약", "en": "about; approximately"}], "analysis": [{"type": "grammar", "label": "~(으)며", "exp": "Formal 'and' that links two clauses, used mostly in writing and news: 열었다 → 열었으며 'opened, and …'.", "example_in_sentence": "열었으며"}, {"type": "grammar", "label": "과는 (와/과 + 는)", "exp": "과 'from / with' + 는 (topic): 개풍군과는 … 떨어져 있습니다 'is … away from Gaepung County'.", "example_in_sentence": "개풍군과는"}, {"type": "grammar", "label": "~아/어 있다", "exp": "A state that continues: 떨어지다 → 떨어져 있습니다 'is (located) … away'.", "example_in_sentence": "떨어져 있습니다"}]}, {"text": "문을 연 뒤 첫 1년 동안 이 매장에는 약 12만 3천 명이 다녀갔습니다.", "translation": "In its first year after opening, about 123,000 people visited this store.", "vocab": [{"ko": "첫", "en": "first"}, {"ko": "동안", "en": "during; for (a period)"}, {"ko": "명", "en": "counter for people"}, {"ko": "다녀가다", "en": "to visit; to come by"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ 뒤", "exp": "'After …': 열다 → 연 뒤 'after opening' (the ㄹ drops before ㄴ).", "example_in_sentence": "연 뒤"}, {"type": "expression", "label": "N 동안", "exp": "'For / during N': 첫 1년 동안 'during the first year'.", "example_in_sentence": "1년 동안"}, {"type": "grammar", "label": "에는 (place + topic)", "exp": "에 'at' + 는 (topic): 이 매장에는 'at this store'.", "example_in_sentence": "매장에는"}]}, {"text": "언론은 건너편 북한 지역에서 일부 장비를 실제로 관측할 수 있는 것은 맞지만, 사진처럼 카페 바로 앞에 있는 것은 아니라고 설명했습니다.", "translation": "The media explained that while it is true some North Korean equipment can actually be observed in the area across the way, it is not right in front of the cafe as in the photo.", "vocab": [{"ko": "건너편", "en": "the other side; across the way"}, {"ko": "장비", "en": "equipment"}, {"ko": "관측하다", "en": "to observe"}, {"ko": "설명하다", "en": "to explain"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 수 있다", "exp": "'Can': 관측하다 → 관측할 수 있는 '(equipment) that can be observed'.", "example_in_sentence": "관측할 수 있는"}, {"type": "grammar", "label": "~지만", "exp": "'But / although': 맞다 → 맞지만 'it is true, but …'.", "example_in_sentence": "맞지만"}, {"type": "grammar", "label": "N처럼", "exp": "'Like N': 사진처럼 'as in the photo'.", "example_in_sentence": "사진처럼"}, {"type": "grammar", "label": "~(이)라고 (quoting 아니다)", "exp": "Reported speech after 이다/아니다 uses 라고: 아니다 → 아니라고 설명했습니다 'explained that it is not'.", "example_in_sentence": "아니라고 설명했습니다"}]}, {"text": "이처럼 AI로 만든 사진은 진짜와 구별하기 어려울 때가 많습니다.", "translation": "Photos made with AI like this are often hard to tell apart from real ones.", "vocab": [{"ko": "이처럼", "en": "like this"}, {"ko": "진짜", "en": "the real thing"}, {"ko": "구별하다", "en": "to tell apart; to distinguish"}, {"ko": "어렵다", "en": "to be difficult"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (past modifier)", "exp": "Past modifier for verbs: 만들다 → 만든 사진 'photos made (with AI)'. The ㄹ drops before ㄴ.", "example_in_sentence": "만든 사진"}, {"type": "grammar", "label": "~기 어렵다", "exp": "'Hard to …': 구별하다 → 구별하기 어렵다 'hard to tell apart'.", "example_in_sentence": "구별하기 어려울"}, {"type": "grammar", "label": "~(으)ㄹ 때가 많다", "exp": "'Often …' (lit. 'there are many times when …'): 어렵다 → 어려울 때가 많습니다 'is often hard'. ㅂ becomes 우: 어렵다 → 어려울.", "example_in_sentence": "어려울 때가 많습니다"}]}, {"text": "놀라운 사진을 보면 공유하기 전에 출처를 확인하고 언론 보도를 한 번 더 찾아보는 것이 좋습니다.", "translation": "When you see a surprising photo, it is a good idea to check its source and look up news reports once more before sharing it.", "vocab": [{"ko": "공유하다", "en": "to share"}, {"ko": "출처", "en": "source"}, {"ko": "확인하다", "en": "to check"}, {"ko": "찾아보다", "en": "to look up"}], "analysis": [{"type": "grammar", "label": "~(으)면", "exp": "'If / when': 보다 → 보면 'when you see'.", "example_in_sentence": "보면"}, {"type": "grammar", "label": "~기 전에", "exp": "'Before …': 공유하다 → 공유하기 전에 'before sharing'.", "example_in_sentence": "공유하기 전에"}, {"type": "grammar", "label": "~고 (and)", "exp": "Links two actions: 확인하다 → 확인하고 'check and …'.", "example_in_sentence": "확인하고"}, {"type": "grammar", "label": "~는 것이 좋다", "exp": "'It is good to … / you should …': 찾아보다 → 찾아보는 것이 좋습니다.", "example_in_sentence": "찾아보는 것이 좋습니다"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mwaegibong29' and md5(translation) = '514c2b3254214ef7c6c8ed995db3b5c0';
update public.article_cache set translation = $t${"texts": ["Haeinsa is a Buddhist temple in Hapcheon, South Gyeongsang Province. It is home to the Tripitaka Koreana, a set of about 80,000 woodblocks carved with Buddhist scriptures in the 13th century, during the Goryeo period. The Tripitaka Koreana is also UNESCO-listed heritage.", "At 2 p.m. on October 29, Haeinsa held a gobulsik, a Buddhist ceremony that tells the Buddha a big undertaking is beginning, to start carving the Tripitaka Koreana onto new woodblocks again. The theme of the event was 'The Tripitaka Carved Anew, Heading Toward Humanity.'", "From now on, about 100 monks and graduates of Haeinsa's woodblock carving school will carve the Tripitaka.", "At 3 p.m., there was also a demonstration of carving woodblocks the traditional way."], "sentences": [{"text": "경상남도 합천에 해인사라는 절이 있어요.", "translation": "There is a temple called Haeinsa in Hapcheon, South Gyeongsang Province.", "vocab": [{"ko": "경상남도", "en": "South Gyeongsang Province"}, {"ko": "합천", "en": "Hapcheon (a county)"}, {"ko": "해인사", "en": "Haeinsa (a Buddhist temple)"}, {"ko": "절", "en": "Buddhist temple"}], "analysis": [{"type": "grammar", "label": "N(이)라는 N", "exp": "'An N called …': 해인사 + 라는 + 절 = 'a temple called Haeinsa'. 라는 follows a vowel, 이라는 a consonant.", "example_in_sentence": "해인사라는 절"}, {"type": "grammar", "label": "N에 N이/가 있다", "exp": "'There is N in (a place)': 합천에 … 절이 있어요 'there is a temple in Hapcheon'.", "example_in_sentence": "절이 있어요"}]}, {"text": "해인사에는 팔만대장경이 있어요.", "translation": "Haeinsa is home to the Tripitaka Koreana (Palman Daejanggyeong).", "vocab": [{"ko": "팔만대장경", "en": "the Tripitaka Koreana (about 80,000 Buddhist woodblocks)"}], "analysis": [{"type": "grammar", "label": "에는 (place + topic)", "exp": "에 'at' + 는 (topic): 해인사에는 'at Haeinsa, (there is) …'.", "example_in_sentence": "해인사에는"}]}, {"text": "팔만대장경은 불교 경전을 새긴 나무판이에요.", "translation": "The Tripitaka Koreana is a set of woodblocks carved with Buddhist scriptures.", "vocab": [{"ko": "불교", "en": "Buddhism"}, {"ko": "경전", "en": "scripture"}, {"ko": "새기다", "en": "to carve; to engrave"}, {"ko": "나무판", "en": "wooden board; woodblock"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (past modifier)", "exp": "Past modifier for verbs: 새기다 → 새긴 나무판 'woodblocks that (people) carved'.", "example_in_sentence": "새긴 나무판"}, {"type": "grammar", "label": "~이에요/예요", "exp": "'Is / are': 나무판 + 이에요. 이에요 follows a consonant, 예요 a vowel.", "example_in_sentence": "나무판이에요"}]}, {"text": "13세기 고려 시대에 만들어졌어요.", "translation": "They were made in the 13th century, during the Goryeo period.", "vocab": [{"ko": "세기", "en": "century"}, {"ko": "고려", "en": "Goryeo (Korean kingdom, 918–1392)"}, {"ko": "시대", "en": "period; era"}, {"ko": "만들어지다", "en": "to be made"}], "analysis": [{"type": "grammar", "label": "~아/어지다 (passive)", "exp": "Makes a verb passive: 만들다 'to make' → 만들어지다 'to be made' → 만들어졌어요 'were made'.", "example_in_sentence": "만들어졌어요"}, {"type": "grammar", "label": "N에 (time)", "exp": "에 after a time word means 'in / at': 시대에 'in the … period'.", "example_in_sentence": "시대에"}]}, {"text": "나무판은 약 8만 개예요.", "translation": "There are about 80,000 woodblocks.", "vocab": [{"ko": "약", "en": "about; approximately"}, {"ko": "만", "en": "ten thousand"}, {"ko": "개", "en": "counter for things; piece"}], "analysis": [{"type": "expression", "label": "number + 개", "exp": "개 counts things: 8만 개 '80,000 (pieces)'. 만 = 10,000, so 8만 = 80,000.", "example_in_sentence": "8만 개"}, {"type": "grammar", "label": "~이에요/예요", "exp": "개 ends in a vowel, so it takes 예요: 개예요.", "example_in_sentence": "개예요"}]}, {"text": "팔만대장경은 유네스코 유산이기도 해요.", "translation": "The Tripitaka Koreana is also UNESCO-listed heritage.", "vocab": [{"ko": "유네스코", "en": "UNESCO"}, {"ko": "유산", "en": "heritage"}], "analysis": [{"type": "grammar", "label": "~기도 하다", "exp": "'Is also …': 유산이다 → 유산이기도 해요 'is also a heritage item'.", "example_in_sentence": "유산이기도 해요"}]}, {"text": "10월 29일 오후 2시, 해인사에서 고불식이 열렸어요.", "translation": "At 2 p.m. on October 29, a gobulsik ceremony was held at Haeinsa.", "vocab": [{"ko": "오후", "en": "afternoon; p.m."}, {"ko": "시", "en": "o'clock"}, {"ko": "고불식", "en": "gobulsik (a Buddhist ceremony announcing a big undertaking to the Buddha)"}, {"ko": "열리다", "en": "to be held"}], "analysis": [{"type": "grammar", "label": "~에서 (place of action)", "exp": "Marks where something happens: 해인사 + 에서 = 'at Haeinsa'.", "example_in_sentence": "해인사에서"}, {"type": "grammar", "label": "~았/었어요", "exp": "Polite past ending: 열리다 → 열렸어요 'was held' (리 + 었 → 렸).", "example_in_sentence": "열렸어요"}]}, {"text": "팔만대장경을 새 나무판에 다시 새기는 일을 시작하는 행사였어요.", "translation": "It was an event to start the work of carving the Tripitaka Koreana onto new woodblocks again.", "vocab": [{"ko": "새", "en": "new"}, {"ko": "다시", "en": "again"}, {"ko": "시작하다", "en": "to start"}, {"ko": "행사", "en": "event"}], "analysis": [{"type": "grammar", "label": "~는 (verb modifier)", "exp": "Present modifier for verbs: 새기다 → 새기는 일 'the work of carving'; 시작하다 → 시작하는 행사 'an event that starts (it)'.", "example_in_sentence": "새기는 일"}, {"type": "grammar", "label": "~에 (target)", "exp": "에 marks where something goes: 새 나무판에 새기다 'to carve onto new woodblocks'.", "example_in_sentence": "나무판에"}, {"type": "grammar", "label": "~였어요/이었어요", "exp": "Past of 예요/이에요: 행사 ends in a vowel → 행사였어요 'was an event'.", "example_in_sentence": "행사였어요"}]}, {"text": "고불식은 큰일을 시작할 때 부처님께 알리는 불교 의식이에요.", "translation": "A gobulsik is a Buddhist ceremony that tells the Buddha when a big undertaking begins.", "vocab": [{"ko": "큰일", "en": "a big task; an important undertaking"}, {"ko": "부처님", "en": "the Buddha"}, {"ko": "알리다", "en": "to tell; to inform"}, {"ko": "의식", "en": "ceremony; rite"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 때", "exp": "'When …': 시작하다 → 시작할 때 'when (they) start'.", "example_in_sentence": "시작할 때"}, {"type": "grammar", "label": "께 (honorific 에게)", "exp": "Honorific form of 에게 'to', used for someone respected: 부처님께 'to the Buddha'.", "example_in_sentence": "부처님께"}, {"type": "grammar", "label": "~는 (verb modifier)", "exp": "알리다 → 알리는 의식 'a ceremony that tells (the Buddha)'.", "example_in_sentence": "알리는 불교 의식"}]}, {"text": "행사의 주제는 '다시 새기는 대장경, 인류를 향하다'였어요.", "translation": "The theme of the event was 'The Tripitaka Carved Anew, Heading Toward Humanity.'", "vocab": [{"ko": "주제", "en": "theme"}, {"ko": "대장경", "en": "Tripitaka (the Buddhist canon)"}, {"ko": "인류", "en": "humanity"}, {"ko": "향하다", "en": "to head toward; to face"}], "analysis": [{"type": "grammar", "label": "의 (possessive)", "exp": "Links two nouns, 'of': 행사의 주제 'the theme of the event'.", "example_in_sentence": "행사의 주제"}, {"type": "grammar", "label": "~였어요/이었어요", "exp": "After a quoted title that ends in a vowel (향하다), 였어요 means 'was': '…향하다'였어요.", "example_in_sentence": "향하다'였어요"}]}, {"text": "앞으로 스님과 해인사 판각학교 졸업생 약 100명이 대장경을 새길 거예요.", "translation": "From now on, about 100 monks and graduates of Haeinsa's woodblock carving school will carve the Tripitaka.", "vocab": [{"ko": "앞으로", "en": "from now on; in the future"}, {"ko": "스님", "en": "Buddhist monk"}, {"ko": "판각학교", "en": "woodblock carving school"}, {"ko": "졸업생", "en": "graduate"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 거예요", "exp": "Future: 새기다 → 새길 거예요 'will carve'.", "example_in_sentence": "새길 거예요"}, {"type": "grammar", "label": "~와/과 (and)", "exp": "Joins nouns, 'and': 스님과 졸업생 'monks and graduates'. 과 follows a consonant, 와 a vowel.", "example_in_sentence": "스님과"}, {"type": "expression", "label": "number + 명", "exp": "명 counts people: 100명 '100 people'.", "example_in_sentence": "100명이"}]}, {"text": "오후 3시에는 전통 방식으로 나무판을 새기는 모습을 보여 주는 시간도 있었어요.", "translation": "At 3 p.m., there was also a demonstration of carving woodblocks the traditional way.", "vocab": [{"ko": "전통", "en": "tradition"}, {"ko": "방식", "en": "way; method"}, {"ko": "모습", "en": "sight; scene"}, {"ko": "보여 주다", "en": "to show"}], "analysis": [{"type": "grammar", "label": "~(으)로 (means)", "exp": "'In (a way)': 방식 + 으로 = 'in the traditional way'.", "example_in_sentence": "전통 방식으로"}, {"type": "grammar", "label": "~아/어 주다", "exp": "Doing something for others: 보이다 'to show' + 어 주다 → 보여 주다 'to show (people)'.", "example_in_sentence": "보여 주는"}, {"type": "grammar", "label": "N도", "exp": "'Also': 시간 + 도 = 'there was also a time (for …)'.", "example_in_sentence": "시간도"}, {"type": "grammar", "label": "~았/었어요", "exp": "Polite past ending: 있다 → 있었어요 'there was'.", "example_in_sentence": "있었어요"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mwhaeinsa29c' and md5(translation) = 'fde97a2f5c415445ea5734ad143b4998';
update public.article_cache set translation = $t${"texts": ["Have you ever stood in line for more than an hour to buy the latest trendy dessert? You finally get one and post it on social media, only to find people already talking about a different dessert. Among Koreans in their 20s and 30s, worn out by trends that never stop changing, a new word is spreading: 'JOMO'.", "JOMO is short for 'Joy of Missing Out'. It is the exact opposite of 'FOMO', the anxious feeling that you alone might miss out on what everyone else is doing.", "Trends really do change at a breathless pace these days. Just look at desserts: after the Dubai chewy cookie, nicknamed 'dujjonku', snacks such as butter rice cake and pizza seolgi became hits one after another. Something similar is happening with exercise. Some young people enjoy running but say they don't bother joining 'running crews', where lots of people run together in a pack.", "Experts name the money and time it takes to keep up with fast-changing trends, along with social media fatigue, as the reasons. Recently, 'missing-out practice' ideas such as 'listen to the radio instead of streaming shows' and 'cook for yourself instead of ordering delivery' have also been shared on social media.", "That doesn't mean JOMO rejects every trend. The idea is to choose by your own standards, not at other people's pace. So this weekend, instead of lining up outside a trendy dessert shop, why not have a good long rest at home?"], "sentences": [{"text": "새로 유행하는 디저트를 사려고 한 시간 넘게 줄을 서 본 적이 있나요?", "translation": "Have you ever stood in line for more than an hour to buy the latest trendy dessert?", "vocab": [{"ko": "유행하다", "en": "to be in fashion; to be trendy"}, {"ko": "디저트", "en": "dessert"}, {"ko": "줄을 서다", "en": "to stand in line"}, {"ko": "넘다", "en": "to be over; to exceed"}], "analysis": [{"type": "grammar", "label": "~려고 / ~으려고 (in order to)", "exp": "Shows purpose: 사다 → 사려고 'in order to buy'. After a consonant stem it is 으려고: 먹다 → 먹으려고.", "example_in_sentence": "사려고"}, {"type": "grammar", "label": "~본 적이 있나요? (Have you ever …?)", "exp": "V-아/어 본 적이 있다 means 'have (ever) done'. 서다 → 서 본 적이 있나요? 'Have you ever stood (in line)?'", "example_in_sentence": "서 본 적이 있나요"}, {"type": "grammar", "label": "~는 (verb modifier)", "exp": "Turns a verb into a noun modifier: 유행하다 → 유행하는 디저트 'a dessert that is in fashion'.", "example_in_sentence": "유행하는 디저트"}]}, {"text": "겨우 사서 SNS에 올렸더니, 사람들은 벌써 다른 디저트 이야기를 하고 있습니다.", "translation": "You finally get one and post it on social media, only to find people already talking about a different dessert.", "vocab": [{"ko": "겨우", "en": "finally; barely (after a lot of effort)"}, {"ko": "올리다", "en": "to post; to upload"}, {"ko": "벌써", "en": "already"}, {"ko": "다르다", "en": "to be different"}], "analysis": [{"type": "grammar", "label": "~서 (and then)", "exp": "Links two actions in order: 사다 → 사서 'buy and then …'. The full form is ~아/어서.", "example_in_sentence": "사서"}, {"type": "grammar", "label": "~더니 (did … and found that)", "exp": "After doing something, you notice a result: 올리다 → 올렸더니 'when I posted it, (I found that) …'.", "example_in_sentence": "올렸더니"}, {"type": "grammar", "label": "~고 있습니다 (be …ing)", "exp": "An action in progress: 하다 → 하고 있습니다 'are talking (about)'.", "example_in_sentence": "하고 있습니다"}]}, {"text": "이렇게 끝없이 바뀌는 유행에 지친 2030 세대 사이에서 요즘 '조모(JOMO)'라는 말이 퍼지고 있습니다.", "translation": "Among Koreans in their 20s and 30s, worn out by trends that never stop changing, a word is spreading these days: 'JOMO'.", "vocab": [{"ko": "끝없이", "en": "endlessly"}, {"ko": "바뀌다", "en": "to change"}, {"ko": "지치다", "en": "to be worn out; to be tired (of)"}, {"ko": "세대", "en": "generation (2030 세대 = people in their 20s and 30s)"}, {"ko": "퍼지다", "en": "to spread"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (past modifier)", "exp": "With verbs, ㄴ/은 shows a finished action or the state it left: 지치다 → 지친 2030 세대 'people in their 20s and 30s who are worn out'.", "example_in_sentence": "지친 2030 세대"}, {"type": "expression", "label": "N 사이에서", "exp": "'Among N': 2030 세대 사이에서 'among people in their 20s and 30s'.", "example_in_sentence": "세대 사이에서"}, {"type": "grammar", "label": "~라는 / ~이라는 (called …)", "exp": "Names something: '조모(JOMO)' + 라는 말 'the word JOMO'. After a consonant it is 이라는.", "example_in_sentence": "'조모(JOMO)'라는 말"}]}, {"text": "조모는 'Joy of Missing Out'의 줄임말로, '놓치는 즐거움'이라는 뜻입니다.", "translation": "JOMO is short for 'Joy of Missing Out', meaning 'the pleasure of missing out'.", "vocab": [{"ko": "줄임말", "en": "abbreviation; shortened word"}, {"ko": "놓치다", "en": "to miss (a chance, a trend)"}, {"ko": "즐거움", "en": "joy; pleasure"}, {"ko": "뜻", "en": "meaning"}], "analysis": [{"type": "grammar", "label": "~로 (being …, and)", "exp": "Links a definition to more information in writing: 줄임말 + 로 'being an abbreviation, (it means) …'. After a consonant other than ㄹ it is 으로.", "example_in_sentence": "줄임말로"}, {"type": "grammar", "label": "~(이)라는 뜻입니다 (it means …)", "exp": "Explains a meaning: '놓치는 즐거움' + 이라는 뜻입니다 'it means \"the joy of missing out\"'.", "example_in_sentence": "'놓치는 즐거움'이라는 뜻입니다"}]}, {"text": "남들이 다 하는 것을 나만 놓칠까 봐 불안해하는 '포모(FOMO)'와 정반대의 태도입니다.", "translation": "It is the exact opposite of 'FOMO', the anxious feeling that you alone might miss out on what everyone else is doing.", "vocab": [{"ko": "남", "en": "other people; others"}, {"ko": "불안해하다", "en": "to feel anxious"}, {"ko": "정반대", "en": "the exact opposite"}, {"ko": "태도", "en": "attitude"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ까 봐 (worried that …)", "exp": "Shows a worry about what might happen: 놓치다 → 놓칠까 봐 '(worried) that I might miss out'.", "example_in_sentence": "놓칠까 봐"}, {"type": "grammar", "label": "N만 (only)", "exp": "'Only N': 나 + 만 = 'only me; I alone'.", "example_in_sentence": "나만"}, {"type": "expression", "label": "N와/과 정반대", "exp": "'The exact opposite of N': '포모(FOMO)'와 정반대 'the exact opposite of FOMO'.", "example_in_sentence": "'포모(FOMO)'와 정반대"}]}, {"text": "실제로 요즘 유행은 숨 가쁘게 바뀝니다.", "translation": "In fact, trends these days change at a breathless pace.", "vocab": [{"ko": "실제로", "en": "actually; in fact"}, {"ko": "요즘", "en": "these days"}, {"ko": "숨 가쁘다", "en": "to be out of breath; breathless"}, {"ko": "바뀌다", "en": "to change"}], "analysis": [{"type": "grammar", "label": "~게 (adverb)", "exp": "Turns an adjective into an adverb: 숨 가쁘다 → 숨 가쁘게 'breathlessly; at a breathless pace'.", "example_in_sentence": "숨 가쁘게"}, {"type": "grammar", "label": "~ㅂ니다 (formal polite)", "exp": "Formal polite present ending used in news: 바뀌다 → 바뀝니다 'change'.", "example_in_sentence": "바뀝니다"}]}, {"text": "디저트만 봐도 '두쫀쿠'로 불린 두바이 쫀득 쿠키에 이어 버터떡, 피자설기 같은 간식이 차례로 인기를 끌었습니다.", "translation": "Just look at desserts: after the Dubai chewy cookie, nicknamed 'dujjonku', snacks such as butter rice cake and pizza seolgi became hits one after another.", "vocab": [{"ko": "쫀득하다", "en": "to be chewy"}, {"ko": "간식", "en": "snack"}, {"ko": "차례로", "en": "one after another; in turn"}, {"ko": "인기를 끌다", "en": "to become popular; to be a hit"}], "analysis": [{"type": "grammar", "label": "~만 봐도 (just looking at …)", "exp": "Gives one quick example that proves the point: 디저트만 봐도 'just look at desserts (and you can see)'.", "example_in_sentence": "디저트만 봐도"}, {"type": "grammar", "label": "~로 불린 (called …)", "exp": "불리다 'to be called' + ㄴ: '두쫀쿠'로 불린 쿠키 'the cookie (that was) called dujjonku'.", "example_in_sentence": "'두쫀쿠'로 불린"}, {"type": "grammar", "label": "~에 이어 (following …)", "exp": "'After N, (came) …': 쿠키에 이어 'following the cookie'.", "example_in_sentence": "쿠키에 이어"}, {"type": "expression", "label": "N 같은 N", "exp": "'N such as …': 버터떡, 피자설기 같은 간식 'snacks such as butter rice cake and pizza seolgi'.", "example_in_sentence": "피자설기 같은 간식"}]}, {"text": "운동에서도 비슷한 모습이 보입니다.", "translation": "Something similar is happening with exercise.", "vocab": [{"ko": "운동", "en": "exercise; working out"}, {"ko": "비슷하다", "en": "to be similar"}, {"ko": "모습", "en": "look; scene; picture"}, {"ko": "보이다", "en": "to be seen; to show"}], "analysis": [{"type": "grammar", "label": "~에서도 (in … too)", "exp": "에서 'in' + 도 'also': 운동에서도 'in exercise too'.", "example_in_sentence": "운동에서도"}, {"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Turns an adjective into a noun modifier: 비슷하다 → 비슷한 모습 'a similar picture'.", "example_in_sentence": "비슷한 모습"}]}, {"text": "달리기는 즐기지만 여럿이 우르르 함께 뛰는 '러닝크루'에는 굳이 들어가지 않는다는 젊은이들도 있습니다.", "translation": "Some young people enjoy running but say they don't bother joining 'running crews', where lots of people run together in a pack.", "vocab": [{"ko": "달리기", "en": "running"}, {"ko": "즐기다", "en": "to enjoy"}, {"ko": "우르르", "en": "in a crowd; all together (a group rushing at once)"}, {"ko": "굳이", "en": "bother to; go out of one's way to"}, {"ko": "젊은이", "en": "young person"}], "analysis": [{"type": "grammar", "label": "~지만 (but)", "exp": "'… but': 즐기다 → 즐기지만 'enjoy (running), but …'.", "example_in_sentence": "즐기지만"}, {"type": "expression", "label": "굳이 ~지 않다", "exp": "'Not bother to …': 굳이 들어가지 않는다 '(they) don't bother joining'.", "example_in_sentence": "굳이 들어가지 않는다는"}, {"type": "grammar", "label": "~는다는 (who say that …)", "exp": "Reported speech used as a modifier: 들어가지 않는다 + 는 젊은이들 'young people who say they don't join'.", "example_in_sentence": "않는다는 젊은이들"}]}, {"text": "전문가들은 빠르게 바뀌는 유행을 따라가는 데 드는 돈과 시간, 그리고 SNS 피로감을 그 이유로 꼽습니다.", "translation": "Experts name the money and time it takes to keep up with fast-changing trends, along with social media fatigue, as the reasons.", "vocab": [{"ko": "전문가", "en": "expert"}, {"ko": "따라가다", "en": "to follow; to keep up with"}, {"ko": "들다", "en": "to cost; to take (money or time)"}, {"ko": "피로감", "en": "fatigue; a feeling of tiredness"}, {"ko": "꼽다", "en": "to name; to pick (as)"}], "analysis": [{"type": "grammar", "label": "~는 데 드는 (it takes … to)", "exp": "N이 들다 means 'to cost / take N'. 따라가는 데 드는 돈 'the money it takes to keep up'. 들다 drops its ㄹ before 는: 드는.", "example_in_sentence": "따라가는 데 드는"}, {"type": "grammar", "label": "~로 꼽습니다 (name … as)", "exp": "A을/를 B(으)로 꼽다 'to name A as B': SNS 피로감을 그 이유로 꼽습니다 'name social media fatigue as the reason'.", "example_in_sentence": "이유로 꼽습니다"}]}, {"text": "최근 SNS에서는 'OTT 대신 라디오 듣기', '배달 음식 대신 직접 요리하기' 같은 '놓치는 연습'이 공유되기도 했습니다.", "translation": "Recently, 'missing-out practice' ideas such as 'listen to the radio instead of streaming shows' and 'cook for yourself instead of ordering delivery' have also been shared on social media.", "vocab": [{"ko": "최근", "en": "recently"}, {"ko": "대신", "en": "instead (of)"}, {"ko": "배달 음식", "en": "delivery food"}, {"ko": "직접", "en": "oneself; in person"}, {"ko": "공유되다", "en": "to be shared"}], "analysis": [{"type": "expression", "label": "N 대신", "exp": "'Instead of N': OTT 대신 라디오 듣기 'listening to the radio instead of streaming (OTT) services'.", "example_in_sentence": "OTT 대신"}, {"type": "grammar", "label": "~기 (noun form)", "exp": "Turns a verb into a noun, like '-ing': 듣다 → 듣기 'listening', 요리하다 → 요리하기 'cooking'.", "example_in_sentence": "요리하기"}, {"type": "grammar", "label": "~기도 했습니다 (also …)", "exp": "Adds that something also happened: 공유되다 → 공유되기도 했습니다 'were also shared'.", "example_in_sentence": "공유되기도 했습니다"}]}, {"text": "그렇다고 조모가 모든 유행을 거부하는 것은 아닙니다.", "translation": "That doesn't mean JOMO rejects every trend.", "vocab": [{"ko": "그렇다고", "en": "that doesn't mean; but that's not to say"}, {"ko": "모든", "en": "every; all"}, {"ko": "거부하다", "en": "to reject; to refuse"}], "analysis": [{"type": "expression", "label": "그렇다고", "exp": "'That doesn't mean …': warns the reader not to jump to a conclusion.", "example_in_sentence": "그렇다고"}, {"type": "grammar", "label": "~는 것은 아닙니다 (it's not that …)", "exp": "Denies a possible idea: 거부하다 → 거부하는 것은 아닙니다 'it does not (mean it) rejects'.", "example_in_sentence": "거부하는 것은 아닙니다"}]}, {"text": "남들의 속도가 아니라 내 기준으로 고르겠다는 것입니다.", "translation": "The idea is to choose by your own standards, not at other people's pace.", "vocab": [{"ko": "속도", "en": "speed; pace"}, {"ko": "기준", "en": "standard; yardstick"}, {"ko": "고르다", "en": "to choose; to pick"}], "analysis": [{"type": "grammar", "label": "~가 아니라 (not … but)", "exp": "'Not A but B': 남들의 속도가 아니라 내 기준으로 'not at other people's pace but by my own standards'.", "example_in_sentence": "속도가 아니라"}, {"type": "grammar", "label": "~(으)로 (by)", "exp": "Shows the basis or way: 기준 + 으로 'by (my) standards'.", "example_in_sentence": "기준으로"}, {"type": "grammar", "label": "~겠다는 것입니다 (the point is that … will)", "exp": "Explains someone's intention: 고르다 → 고르겠다는 것입니다 'the point is that (they) will choose'.", "example_in_sentence": "고르겠다는 것입니다"}]}, {"text": "이번 주말, 유행하는 디저트 가게 앞에 줄을 서는 대신 집에서 푹 쉬어 보는 건 어떨까요?", "translation": "So this weekend, instead of lining up outside a trendy dessert shop, why not have a good long rest at home?", "vocab": [{"ko": "주말", "en": "weekend"}, {"ko": "가게", "en": "shop; store"}, {"ko": "푹", "en": "deeply; well (of rest or sleep)"}, {"ko": "쉬다", "en": "to rest"}], "analysis": [{"type": "grammar", "label": "~는 대신 (instead of …ing)", "exp": "줄을 서다 → 줄을 서는 대신 'instead of standing in line'.", "example_in_sentence": "서는 대신"}, {"type": "grammar", "label": "~아/어 보는 건 어떨까요? (Why not try …?)", "exp": "A soft suggestion: 쉬다 → 쉬어 보는 건 어떨까요? 'How about trying to rest?' (건 = 것은).", "example_in_sentence": "쉬어 보는 건 어떨까요"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mwjomotrnd30' and md5(translation) = '4ce8220b39d807318a1663c2fd3293a6';
update public.article_cache set translation = $t${"texts": ["Small snakes live in Southeast Asia. When they are in danger, they escape in a very special way: they roll their bodies like a wheel.", "Scientists studied these snakes. The study came out on October 19, 2026, in a science journal called Current Biology.", "These snakes roll very fast. At top speed they cover about 3.7 meters per second, about four times faster than when they crawl.", "While a snake rolls, its head does not move much; only its body rolls. After rolling, the snake often hides under a nearby object.", "Here is what scientists think: rolling may confuse animals that hunt snakes, and it may also leave less of the snake's scent on the ground."], "sentences": [{"text": "동남아시아에 작은 뱀이 살아요.", "translation": "Small snakes live in Southeast Asia.", "vocab": [{"ko": "동남아시아", "en": "Southeast Asia"}, {"ko": "작다", "en": "to be small"}, {"ko": "뱀", "en": "snake"}, {"ko": "살다", "en": "to live"}], "analysis": [{"type": "grammar", "label": "~에 (place)", "exp": "에 marks the place where something lives or is: 동남아시아 + 에 = 'in Southeast Asia'.", "example_in_sentence": "동남아시아에"}, {"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Turns an adjective into a noun modifier: 작다 → 작은 뱀 'a small snake'.", "example_in_sentence": "작은 뱀"}, {"type": "grammar", "label": "~아/어요", "exp": "Polite present ending: 살다 → 살아요 'lives'. The stem 살 has the vowel ㅏ, so it takes 아요.", "example_in_sentence": "살아요"}]}, {"text": "이 뱀은 위험할 때 아주 특별한 방법으로 도망가요.", "translation": "When it is in danger, this snake runs away in a very special way.", "vocab": [{"ko": "위험하다", "en": "to be dangerous"}, {"ko": "특별하다", "en": "to be special"}, {"ko": "방법", "en": "way; method"}, {"ko": "도망가다", "en": "to run away; to escape"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 때", "exp": "'When …': 위험하다 → 위험할 때 'when (it is) in danger'.", "example_in_sentence": "위험할 때"}, {"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Turns an adjective into a noun modifier: 특별하다 → 특별한 방법 'a special way'.", "example_in_sentence": "특별한 방법"}, {"type": "grammar", "label": "~(으)로 (means)", "exp": "'By / in (a way)': 방법 + 으로 = 'in a way'. 으로 follows a consonant, 로 a vowel.", "example_in_sentence": "방법으로"}]}, {"text": "몸을 바퀴처럼 굴려요.", "translation": "It rolls its body like a wheel.", "vocab": [{"ko": "몸", "en": "body"}, {"ko": "바퀴", "en": "wheel"}, {"ko": "굴리다", "en": "to roll (something)"}], "analysis": [{"type": "grammar", "label": "N처럼", "exp": "'Like N': 바퀴 + 처럼 = 'like a wheel'.", "example_in_sentence": "바퀴처럼"}, {"type": "grammar", "label": "~을/를 (object)", "exp": "Object particle: 몸 + 을 shows what is rolled (its body). 을 follows a consonant, 를 a vowel.", "example_in_sentence": "몸을"}, {"type": "grammar", "label": "~아/어요", "exp": "Polite present ending: 굴리다 → 굴려요 'rolls' (리 + 어요 → 려요).", "example_in_sentence": "굴려요"}]}, {"text": "과학자들이 이 뱀을 연구했어요.", "translation": "Scientists studied this snake.", "vocab": [{"ko": "과학자", "en": "scientist"}, {"ko": "연구하다", "en": "to study; to research"}], "analysis": [{"type": "grammar", "label": "~들 (plural)", "exp": "Plural marker for nouns: 과학자 → 과학자들 'scientists'.", "example_in_sentence": "과학자들이"}, {"type": "grammar", "label": "~았/었어요", "exp": "Polite past ending. 하다 verbs become 했어요: 연구하다 → 연구했어요 'studied'.", "example_in_sentence": "연구했어요"}]}, {"text": "이 연구는 2026년 10월 19일에 '커런트 바이올로지'라는 과학 잡지에 나왔어요.", "translation": "The study came out on October 19, 2026, in a science journal called Current Biology.", "vocab": [{"ko": "연구", "en": "study; research"}, {"ko": "과학 잡지", "en": "science journal"}, {"ko": "나오다", "en": "to come out; to be published"}], "analysis": [{"type": "grammar", "label": "N에 (time)", "exp": "에 after a date or time means 'on / at': 19일에 'on the 19th'.", "example_in_sentence": "19일에"}, {"type": "grammar", "label": "N(이)라는 N", "exp": "'An N called …': '커런트 바이올로지' + 라는 + 과학 잡지 = 'a science journal called Current Biology'. 라는 follows a vowel, 이라는 a consonant.", "example_in_sentence": "'커런트 바이올로지'라는 과학 잡지"}, {"type": "grammar", "label": "~았/었어요", "exp": "Polite past ending: 나오다 → 나왔어요 'came out' (오 + 았 → 왔).", "example_in_sentence": "나왔어요"}]}, {"text": "이 뱀은 아주 빨리 굴러요.", "translation": "This snake rolls very fast.", "vocab": [{"ko": "아주", "en": "very"}, {"ko": "빨리", "en": "fast; quickly"}, {"ko": "구르다", "en": "to roll"}], "analysis": [{"type": "grammar", "label": "르 irregular", "exp": "Verbs ending in 르 add an extra ㄹ before 아/어: 구르다 → 굴러요 'rolls'.", "example_in_sentence": "굴러요"}]}, {"text": "가장 빠를 때는 1초에 약 3.7미터를 가요.", "translation": "At its fastest, it goes about 3.7 meters per second.", "vocab": [{"ko": "가장", "en": "most"}, {"ko": "빠르다", "en": "to be fast"}, {"ko": "초", "en": "second (of time)"}, {"ko": "약", "en": "about; approximately"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 때", "exp": "'When …': 빠르다 → 빠를 때 'when (it is) fastest'. 는 adds focus: 'at the times when …'.", "example_in_sentence": "빠를 때는"}, {"type": "grammar", "label": "N에 (per)", "exp": "에 after a unit of time can mean 'per': 1초에 'per second'.", "example_in_sentence": "1초에"}, {"type": "expression", "label": "가장 + adjective", "exp": "'The most …': 가장 빠르다 'to be the fastest'.", "example_in_sentence": "가장 빠를"}]}, {"text": "기어갈 때보다 약 네 배 빨라요.", "translation": "That is about four times faster than when it crawls.", "vocab": [{"ko": "기어가다", "en": "to crawl"}, {"ko": "배", "en": "times (as much); -fold"}, {"ko": "빠르다", "en": "to be fast"}], "analysis": [{"type": "grammar", "label": "~보다 (comparison)", "exp": "'Than': 기어갈 때 + 보다 = 'than when it crawls'.", "example_in_sentence": "기어갈 때보다"}, {"type": "expression", "label": "number + 배", "exp": "'… times (as much)': 네 배 빨라요 'four times faster'.", "example_in_sentence": "네 배"}, {"type": "grammar", "label": "르 irregular", "exp": "빠르다 → 빨라요 'is fast': the 르 stem becomes 빨ㄹ before 아요.", "example_in_sentence": "빨라요"}]}, {"text": "뱀이 구를 때 머리는 별로 안 움직여요.", "translation": "When the snake rolls, its head does not move much.", "vocab": [{"ko": "구르다", "en": "to roll"}, {"ko": "머리", "en": "head"}, {"ko": "별로", "en": "(not) very; (not) much"}, {"ko": "움직이다", "en": "to move"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 때", "exp": "'When …': 구르다 → 구를 때 'when it rolls'.", "example_in_sentence": "구를 때"}, {"type": "grammar", "label": "안 + verb", "exp": "안 before a verb makes it negative: 움직여요 → 안 움직여요 'does not move'.", "example_in_sentence": "안 움직여요"}, {"type": "expression", "label": "별로 안 ~", "exp": "'Not very / not much': 별로 is used with a negative. 별로 안 움직여요 'does not move much'.", "example_in_sentence": "별로 안 움직여요"}]}, {"text": "몸만 굴러요.", "translation": "Only its body rolls.", "vocab": [{"ko": "몸", "en": "body"}, {"ko": "구르다", "en": "to roll"}], "analysis": [{"type": "grammar", "label": "N만", "exp": "'Only N': 몸 + 만 = 'only the body'.", "example_in_sentence": "몸만"}]}, {"text": "그리고 뱀은 구른 다음에 가까운 물건 밑에 자주 숨어요.", "translation": "And after rolling, the snake often hides under a nearby object.", "vocab": [{"ko": "가깝다", "en": "to be near; to be close"}, {"ko": "물건", "en": "thing; object"}, {"ko": "자주", "en": "often"}, {"ko": "숨다", "en": "to hide"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ 다음에", "exp": "'After doing …': 구르다 → 구른 다음에 'after rolling'.", "example_in_sentence": "구른 다음에"}, {"type": "grammar", "label": "ㅂ irregular", "exp": "Adjectives ending in ㅂ change ㅂ to 우 before 은: 가깝다 → 가까운 물건 'a nearby object'.", "example_in_sentence": "가까운 물건"}, {"type": "expression", "label": "N 밑에", "exp": "'Under N': 물건 밑에 'under an object'. 밑 means 'the space below'.", "example_in_sentence": "물건 밑에"}]}, {"text": "과학자들은 이렇게 생각해요.", "translation": "Here is what scientists think.", "vocab": [{"ko": "이렇게", "en": "like this; this way"}, {"ko": "생각하다", "en": "to think"}], "analysis": [{"type": "grammar", "label": "~아/어요", "exp": "Polite present ending. 하다 verbs become 해요: 생각하다 → 생각해요 'think'.", "example_in_sentence": "생각해요"}]}, {"text": "구르면 뱀을 잡아먹는 동물이 헷갈릴 수 있어요.", "translation": "When it rolls, animals that eat snakes may get confused.", "vocab": [{"ko": "잡아먹다", "en": "to catch and eat; to prey on"}, {"ko": "동물", "en": "animal"}, {"ko": "헷갈리다", "en": "to be confused"}], "analysis": [{"type": "grammar", "label": "~(으)면", "exp": "'If / when': 구르다 → 구르면 'if (it) rolls'.", "example_in_sentence": "구르면"}, {"type": "grammar", "label": "~는 (verb modifier)", "exp": "Present modifier for verbs: 잡아먹다 → 잡아먹는 동물 'animals that eat (snakes)'.", "example_in_sentence": "잡아먹는 동물"}, {"type": "grammar", "label": "~(으)ㄹ 수 있다 (possibility)", "exp": "'May': 헷갈리다 → 헷갈릴 수 있어요 'may get confused'.", "example_in_sentence": "헷갈릴 수 있어요"}]}, {"text": "그리고 땅에 냄새도 덜 남을 수 있어요.", "translation": "And less of its scent may be left on the ground.", "vocab": [{"ko": "땅", "en": "ground"}, {"ko": "냄새", "en": "smell; scent"}, {"ko": "덜", "en": "less"}, {"ko": "남다", "en": "to be left; to remain"}], "analysis": [{"type": "grammar", "label": "N도", "exp": "'Also / too': 냄새 + 도 'its smell, too'.", "example_in_sentence": "냄새도"}, {"type": "grammar", "label": "~(으)ㄹ 수 있다 (possibility)", "exp": "'May': 남다 → 남을 수 있어요 'may be left'. 을 follows a consonant stem.", "example_in_sentence": "남을 수 있어요"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mwsnake29rol' and md5(translation) = '259983faa4c15384d1ee10e68f910655';
update public.article_cache set translation = $t${"texts": ["In Korea, there is a day when office workers go to work late and even planes stop for a while. What day could it be? It's Suneung day!", "The Suneung is the big exam students take to get into university. This year's Suneung is on Thursday, November 19. About 550,000 people will take the test.", "Test takers have to be inside the exam site by 8:10 in the morning, so a traffic jam that morning would be a disaster. The government asks public offices and companies, \"Please push your start time back to 10 a.m. or later.\" Students who look likely to be late sometimes even ride to the exam site in a police car.", "At 1:10 p.m., the English listening test begins. During this time, planes neither take off nor land, because plane noise must not disturb the test.", "On the morning of the exam, younger students cheer loudly for their seniors in front of the exam sites. They also give them yeot (Korean taffy) or chapssal-tteok (sticky rice cakes). Yeot and chapssal-tteok are sticky, so they stick well. In Korean, 붙다 ('to stick') also means 'to pass an exam'. So these gifts are really a cheer that says, 'Make sure you pass!'"], "sentences": [{"text": "한국에는 회사원들이 늦게 출근하고, 비행기도 잠깐 멈추는 날이 있어요.", "translation": "In Korea, there is a day when office workers go to work late and even planes stop for a while.", "vocab": [{"ko": "회사원", "en": "office worker"}, {"ko": "출근하다", "en": "to go to work"}, {"ko": "비행기", "en": "airplane"}, {"ko": "잠깐", "en": "for a moment; briefly"}, {"ko": "멈추다", "en": "to stop"}], "analysis": [{"type": "grammar", "label": "~고 (and)", "exp": "Links two actions: 출근하다 → 출근하고 'go to work, and …'.", "example_in_sentence": "출근하고"}, {"type": "grammar", "label": "N도 (also; even)", "exp": "도 means 'also' or 'even': 비행기 + 도 = 'even planes'.", "example_in_sentence": "비행기도"}, {"type": "grammar", "label": "~는 (verb modifier)", "exp": "Turns a verb into a noun modifier: 멈추다 → 멈추는 날 'a day when (planes) stop'.", "example_in_sentence": "멈추는 날"}]}, {"text": "무슨 날일까요?", "translation": "What day could it be?", "vocab": [{"ko": "무슨", "en": "what (kind of)"}, {"ko": "날", "en": "day"}], "analysis": [{"type": "grammar", "label": "~(이)ㄹ까요? (I wonder …?)", "exp": "Asks a question you are wondering about: 날이다 → 날일까요? 'What day could it be?'", "example_in_sentence": "날일까요"}]}, {"text": "바로 '수능' 날이에요.", "translation": "It's Suneung day!", "vocab": [{"ko": "바로", "en": "exactly; none other than"}, {"ko": "수능", "en": "the Suneung (Korea's college entrance exam)"}], "analysis": [{"type": "grammar", "label": "~이에요 (to be)", "exp": "Polite 'is': after a consonant use 이에요 (날이에요), after a vowel use 예요.", "example_in_sentence": "날이에요"}]}, {"text": "수능은 대학교에 들어가기 위해 보는 큰 시험이에요.", "translation": "The Suneung is the big exam students take to get into university.", "vocab": [{"ko": "대학교", "en": "university"}, {"ko": "들어가다", "en": "to enter; to get into"}, {"ko": "시험을 보다", "en": "to take an exam"}, {"ko": "크다", "en": "to be big"}], "analysis": [{"type": "grammar", "label": "~기 위해 (in order to)", "exp": "Shows purpose: 들어가다 → 들어가기 위해 'in order to get into'.", "example_in_sentence": "들어가기 위해"}, {"type": "grammar", "label": "~는 (verb modifier)", "exp": "보다 → 보는 시험 'an exam (that people) take'.", "example_in_sentence": "보는"}, {"type": "grammar", "label": "~(으)ㄴ (adjective modifier)", "exp": "Turns an adjective into a noun modifier: 크다 → 큰 시험 'a big exam'.", "example_in_sentence": "큰 시험"}]}, {"text": "올해 수능은 11월 19일 목요일이에요.", "translation": "This year's Suneung is on Thursday, November 19.", "vocab": [{"ko": "올해", "en": "this year"}, {"ko": "목요일", "en": "Thursday"}], "analysis": [{"type": "grammar", "label": "~은/는 (topic)", "exp": "Marks the topic: 수능 + 은 'as for the Suneung'. 은 after a consonant, 는 after a vowel.", "example_in_sentence": "수능은"}, {"type": "expression", "label": "N월 N일", "exp": "Dates go month first, then day: 11월 19일 'November 19'.", "example_in_sentence": "11월 19일"}, {"type": "grammar", "label": "~이에요 (to be)", "exp": "Polite 'is': 목요일 + 이에요 '(it) is Thursday'.", "example_in_sentence": "목요일이에요"}]}, {"text": "약 55만 명이 시험을 봐요.", "translation": "About 550,000 people will take the test.", "vocab": [{"ko": "약", "en": "about; approximately"}, {"ko": "만", "en": "ten thousand"}, {"ko": "명", "en": "counter for people"}], "analysis": [{"type": "expression", "label": "만 (10,000)", "exp": "Korean counts big numbers in units of 만 (10,000): 55만 = 550,000.", "example_in_sentence": "55만 명"}, {"type": "grammar", "label": "~이/가 (subject)", "exp": "Subject particle: 명 + 이. 이 after a consonant, 가 after a vowel.", "example_in_sentence": "명이"}]}, {"text": "수험생들은 아침 8시 10분까지 시험장에 들어가야 해요.", "translation": "Test takers have to be inside the exam site by 8:10 in the morning.", "vocab": [{"ko": "수험생", "en": "test taker"}, {"ko": "아침", "en": "morning"}, {"ko": "시험장", "en": "exam site; test venue"}], "analysis": [{"type": "expression", "label": "N시 N분", "exp": "Telling the time: 시 'o'clock' + 분 'minutes'. 8시 10분 = 8:10.", "example_in_sentence": "8시 10분"}, {"type": "grammar", "label": "~까지 (by; until)", "exp": "'By (a time)': 10분 + 까지 'by (8:)10'.", "example_in_sentence": "10분까지"}, {"type": "grammar", "label": "~야 해요 (have to)", "exp": "Shows something you must do: 들어가다 → 들어가야 해요 'have to go in'.", "example_in_sentence": "들어가야 해요"}]}, {"text": "그래서 아침에 길이 막히면 큰일이에요.", "translation": "So a traffic jam that morning would be a disaster.", "vocab": [{"ko": "그래서", "en": "so; that's why"}, {"ko": "길", "en": "road"}, {"ko": "막히다", "en": "to be jammed (traffic); to be blocked"}, {"ko": "큰일", "en": "big trouble; a disaster"}], "analysis": [{"type": "grammar", "label": "~면 (if)", "exp": "'If …': 막히다 → 막히면 'if (the road) is jammed'. After a consonant stem it is 으면: 먹다 → 먹으면.", "example_in_sentence": "막히면"}, {"type": "expression", "label": "큰일이에요", "exp": "큰일이다 'it's big trouble': used when something would be a disaster.", "example_in_sentence": "큰일이에요"}]}, {"text": "정부는 공공 기관과 회사에 \"출근 시간을 오전 10시 이후로 늦춰 주세요.\"라고 부탁해요.", "translation": "The government asks public offices and companies, \"Please push your start time back to 10 a.m. or later.\"", "vocab": [{"ko": "정부", "en": "government"}, {"ko": "공공 기관", "en": "public office; public institution"}, {"ko": "이후", "en": "after; later than"}, {"ko": "늦추다", "en": "to push back; to delay"}, {"ko": "부탁하다", "en": "to ask (a favor)"}], "analysis": [{"type": "grammar", "label": "N과/와 (and)", "exp": "Joins two nouns: 공공 기관 + 과 회사 'public offices and companies'. 과 after a consonant, 와 after a vowel.", "example_in_sentence": "공공 기관과 회사"}, {"type": "grammar", "label": "~주세요 (please …)", "exp": "A polite request: 늦추다 → 늦춰 주세요 'please push (it) back'.", "example_in_sentence": "늦춰 주세요"}, {"type": "grammar", "label": "~라고 (quoting)", "exp": "Comes after a direct quote: \"…주세요.\" + 라고 부탁해요 'asks, \"Please …\"'.", "example_in_sentence": "라고 부탁해요"}]}, {"text": "늦을 것 같은 학생은 경찰차를 타고 시험장에 가기도 해요.", "translation": "Students who look likely to be late sometimes even ride to the exam site in a police car.", "vocab": [{"ko": "늦다", "en": "to be late"}, {"ko": "학생", "en": "student"}, {"ko": "경찰차", "en": "police car"}, {"ko": "타다", "en": "to ride; to take (a vehicle)"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 것 같은 (likely to …)", "exp": "Guessing: 늦다 → 늦을 것 같은 학생 'a student who looks likely to be late'.", "example_in_sentence": "늦을 것 같은"}, {"type": "grammar", "label": "~고 (and then)", "exp": "Links two actions in order: 타다 → 타고 'ride, and (go) …'.", "example_in_sentence": "타고"}, {"type": "grammar", "label": "~기도 해요 (sometimes also)", "exp": "Shows something that also happens sometimes: 가다 → 가기도 해요 'sometimes go'.", "example_in_sentence": "가기도 해요"}]}, {"text": "오후 1시 10분에는 영어 듣기 시험이 시작돼요.", "translation": "At 1:10 p.m., the English listening test begins.", "vocab": [{"ko": "오후", "en": "afternoon; p.m."}, {"ko": "영어", "en": "English"}, {"ko": "듣기", "en": "listening"}, {"ko": "시작되다", "en": "to begin; to start"}], "analysis": [{"type": "grammar", "label": "~에는 (at …)", "exp": "에 'at (a time)' + 는 (topic): 1시 10분에는 'at 1:10'.", "example_in_sentence": "10분에는"}, {"type": "expression", "label": "시작돼요", "exp": "시작되다 'to begin' + 어요 → 시작되어요, usually shortened to 시작돼요.", "example_in_sentence": "시작돼요"}]}, {"text": "이때는 비행기가 뜨지도 내리지도 않아요.", "translation": "During this time, planes neither take off nor land.", "vocab": [{"ko": "이때", "en": "at this time"}, {"ko": "뜨다", "en": "to take off (a plane); to rise"}, {"ko": "내리다", "en": "to land; to come down"}], "analysis": [{"type": "grammar", "label": "~지도 … ~지도 않아요 (neither … nor)", "exp": "뜨다 → 뜨지도, 내리다 → 내리지도 + 않아요 'neither take off nor land'.", "example_in_sentence": "뜨지도 내리지도 않아요"}]}, {"text": "비행기 소리가 시험을 방해하면 안 되기 때문이에요.", "translation": "That's because plane noise must not disturb the test.", "vocab": [{"ko": "소리", "en": "sound; noise"}, {"ko": "방해하다", "en": "to disturb; to get in the way of"}], "analysis": [{"type": "grammar", "label": "~면 안 되다 / 안 되기 (must not)", "exp": "Says something is not allowed: 방해하다 → 방해하면 안 되다 'must not disturb'.", "example_in_sentence": "방해하면 안 되기"}, {"type": "grammar", "label": "~기 때문이에요 (it's because …)", "exp": "Gives the reason: 안 되다 → 안 되기 때문이에요 'it's because (it) must not'.", "example_in_sentence": "되기 때문이에요"}]}, {"text": "시험 날 아침에는 시험장 앞에서 후배들이 큰 소리로 선배들을 응원해요.", "translation": "On the morning of the exam, younger students cheer loudly for their seniors in front of the exam sites.", "vocab": [{"ko": "앞", "en": "front"}, {"ko": "후배", "en": "junior (younger student at the same school)"}, {"ko": "선배", "en": "senior (older student at the same school)"}, {"ko": "응원하다", "en": "to cheer (for)"}], "analysis": [{"type": "grammar", "label": "~에서 (place of action)", "exp": "Marks where an action happens: 앞 + 에서 'in front of'.", "example_in_sentence": "앞에서"}, {"type": "grammar", "label": "~로 (with)", "exp": "Shows the way something is done: 큰 소리 + 로 'with a loud voice; loudly'.", "example_in_sentence": "큰 소리로"}, {"type": "grammar", "label": "~들 (plural)", "exp": "Plural marker for people: 후배 → 후배들 'juniors'.", "example_in_sentence": "후배들이"}]}, {"text": "엿이나 찹쌀떡도 선물해요.", "translation": "They also give them yeot (Korean taffy) or chapssal-tteok (sticky rice cakes).", "vocab": [{"ko": "엿", "en": "yeot (Korean taffy)"}, {"ko": "찹쌀떡", "en": "chapssal-tteok (sticky rice cake)"}, {"ko": "선물하다", "en": "to give as a gift"}], "analysis": [{"type": "grammar", "label": "~이나 (or)", "exp": "'Or': 엿 + 이나 'yeot or …'. 이나 after a consonant, 나 after a vowel.", "example_in_sentence": "엿이나"}, {"type": "grammar", "label": "N도 (also)", "exp": "찹쌀떡 + 도 'chapssal-tteok too'.", "example_in_sentence": "찹쌀떡도"}]}, {"text": "엿과 찹쌀떡은 끈적끈적해서 잘 붙어요.", "translation": "Yeot and chapssal-tteok are sticky, so they stick well.", "vocab": [{"ko": "끈적끈적하다", "en": "to be sticky"}, {"ko": "잘", "en": "well"}, {"ko": "붙다", "en": "to stick; (of an exam) to pass"}], "analysis": [{"type": "grammar", "label": "~해서 (so; because)", "exp": "하다 words take 해서 for a reason: 끈적끈적하다 → 끈적끈적해서 'because they are sticky'.", "example_in_sentence": "끈적끈적해서"}]}, {"text": "한국어에서 '붙다'는 '시험에 합격하다'라는 뜻도 있어요.", "translation": "In Korean, 붙다 ('to stick') also means 'to pass an exam'.", "vocab": [{"ko": "한국어", "en": "Korean (language)"}, {"ko": "합격하다", "en": "to pass (an exam)"}, {"ko": "뜻", "en": "meaning"}], "analysis": [{"type": "grammar", "label": "~라는 (that says …)", "exp": "Comes after a quoted word: '시험에 합격하다' + 라는 뜻 'the meaning \"to pass an exam\"'.", "example_in_sentence": "'시험에 합격하다'라는 뜻"}, {"type": "grammar", "label": "~도 있어요 (also has)", "exp": "도 'also' + 있어요: 뜻도 있어요 'it also has the meaning'.", "example_in_sentence": "뜻도 있어요"}]}, {"text": "그러니까 이 선물은 '꼭 붙으세요!'라는 응원이에요.", "translation": "So these gifts are really a cheer that says, 'Make sure you pass!'", "vocab": [{"ko": "그러니까", "en": "so; in other words"}, {"ko": "선물", "en": "gift; present"}, {"ko": "꼭", "en": "surely; be sure to"}, {"ko": "응원", "en": "cheering; support"}], "analysis": [{"type": "expression", "label": "그러니까", "exp": "'So; in other words': sums up what was just explained.", "example_in_sentence": "그러니까"}, {"type": "grammar", "label": "~으세요 (please …)", "exp": "A polite request or wish: 붙다 → 붙으세요 'please stick (= pass)!'. After a vowel stem it is 세요: 가세요.", "example_in_sentence": "붙으세요"}, {"type": "grammar", "label": "~라는 (that says …)", "exp": "Comes after a quote: '꼭 붙으세요!' + 라는 응원 'a cheer that says \"Make sure you pass!\"'.", "example_in_sentence": "'꼭 붙으세요!'라는 응원"}]}], "version": "s6"}$t$, qa_at = now()
 where article_id = 'mwsuneung30d' and md5(translation) = '4ea5b696592e74ad3131bf131ca7ce6f';
